// Define the record structure
typedef struct {
    long offset;
    int key;
    double value;
} Record;

// Define the hash table for looking up records by their key
typedef struct {
    int size;
    Record** table;
} HashTable;

// Function to dynamically allocate memory for and initialize an array of 'Record' structures
void init_records(int num_records, int offset_min, int offset_max, int key_min, int key_max, double value_min, double value_max) {
    // Allocate memory for the array of records
    Record* records = (Record*)malloc(num_records * sizeof(Record));

    // Initialize the hash table
    HashTable* hash_table = (HashTable*)malloc(sizeof(HashTable));
    hash_table->size = num_records;
    hash_table->table = (Record**)malloc(num_records * sizeof(Record*));

    // Initialize the records and hash table
    for (int i = 0; i < num_records; i++) {
        records[i].offset = offset_min + rand() % (offset_max - offset_min);
        records[i].key = key_min + rand() % (key_max - key_min);
        records[i].value = value_min + ((double)rand() / RAND_MAX) * (value_max - value_min);

        hash_table->table[i] = &records[i];
    }
}

// Function to deallocate memory for the array of 'Record' structures and the hash table
void free_records(Record* records, HashTable* hash_table) {
    // Deallocate memory for the array of records
    free(records);

    // Deallocate memory for the hash table
    free(hash_table->table);
    free(hash_table);
}

// Function to log memory allocation and deallocation events
void log_memory_event(char* event, void* ptr) {
    printf("%s: %p\n", event, ptr);
}
```
