#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

void process_csv(char* input_file, char* output_file, char* aggregation_criteria, int max_rows) {
    // Open the input file for reading
    FILE* in = fopen(input_file, "r");
    if (in == NULL) {
        printf("Error: unable to open input file %s\n", input_file);
        return;
    }

    // Open the output file for writing
    FILE* out = fopen(output_file, "w");
    if (out == NULL) {
        printf("Error: unable to open output file %s\n", output_file);
        fclose(in);
        return;
    }

    // Read the header row from the input file
    char* line = malloc(1024 * sizeof(char));
    if (fgets(line, 1024, in) == NULL) {
        printf("Error: unable to read header row\n");
        fclose(in);
        fclose(out);
        return;
    }

    // Parse the aggregation criteria from the command-line argument
    char* aggregation_criteria = strtok(aggregation_criteria, ",");
    if (aggregation_criteria == NULL) {
        printf("Error: unable to parse aggregation criteria\n");
        fclose(in);
        fclose(out);
        return;
    }

    // Initialize the aggregated statistics
    int num_rows = 0;
    double sum = 0.0;
    double min = INFINITY;
    double max = -INFINITY;
    double mean = 0.0;
    double stddev = 0.0;

    // Process the input file line by line
    while (fgets(line, 1024, in) != NULL && num_rows < max_rows) {
        // Parse the current row
        char* field = strtok(line, ",");
        int amount = atoi(field);
        if (amount < min) {
            min = amount;
        }
        if (amount > max) {
            max = amount;
        }
        sum += amount;
        num_rows++;
    }

    // Calculate the mean and standard deviation
    mean = sum / num_rows;
    stddev = sqrt((sum - mean) * (sum - mean) / (num_rows - 1));

    // Output the aggregated statistics to the output file
    fprintf(out, "Aggregated Statistics\n");
    fprintf(out, "-------------------\n");
    fprintf(out, "Minimum: %d\n", min);
    fprintf(out, "Maximum: %d\n", max);
    fprintf(out, "Mean: %.2f\n", mean);
    fprintf(out, "Standard Deviation: %.2f\n", stddev);

    // Close the input and output files
    fclose(in);
    fclose(out);
}
