    public void modifyConfig() throws Exception {
        // Read the file content
        String fileContent = readFileContent();

        // Replace placeholders with values from the dictionary
        for (String placeholder : placeholders) {
            if (!parameters.containsKey(placeholder)) {
                throw new IllegalArgumentException("Missing value for placeholder: " + placeholder);
            }
            fileContent = fileContent.replaceAll(placeholder, parameters.get(placeholder));
        }

        // Encrypt the password using a specified encryption algorithm
        String encryptedPassword = encryptPassword(parameters.get("password"));
        fileContent = fileContent.replaceAll("\\$password", encryptedPassword);

        // Write the modified file content back to disk
        Files.writeString(Paths.get(filePath), fileContent);
    }

    private String encryptPassword(String password) {
