    public static String getPokemonReport(Pokemon pokemon, Environment environment) {
        // Retrieve the current environmental conditions using an external API
        try {
            URL url = new URL("https://api.example.com/environment");
            HttpURLConnection connection = (HttpURLConnection) url.openConnection();
            connection.setRequestMethod("GET");
            connection.connect();
            int status = connection.getResponseCode();
            if (status == 200) {
                BufferedReader reader = new BufferedReader(new InputStreamReader(connection.getInputStream()));
                String response = reader.readLine();
                JSONObject json = new JSONObject(response);
                environment.setTemperature(json.getString("temperature"));
                environment.setHumidity(json.getString("humidity"));
            } else {
