            }
        } catch (IOException | JSONException e) {
            System.out.println("Error handling network error: " + e.getMessage());
        }

        // Determine the Pokemon's weaknesses and advantages based on its type and current environmental conditions
        String report = getPokemonReport(pokemon);
        if (environment.getTemperature() == "hot") {
            report += ", but may be affected by heat exhaustion";
        } else if (environment.getHumidity() == "high") {
            report += ", but may be affected by dehydration";
        }
        return report;
    }
}
