// Define a structure to hold information about each hash function or cipher
typedef struct {
    char *name;
    void (*hash_func)();
    void (*key_mgmt_func)();
    void (*iv_gen_func)();
    bool supported;
} cryptographic_function_t;

// Define a list of available hash functions or ciphers
static cryptographic_function_t *available_functions = NULL;

// Define a mutex to ensure thread safety when accessing the list
static pthread_mutex_t function_list_lock = PTHREAD_MUTEX_INITIALIZER;

// Load a new cryptographic module and add its functions to the list
void load_cryptographic_module(const char *module_name) {
    // Open the module using dlopen()
    void *handle = dlopen(module_name, RTLD_LAZY);
    if (!handle) {
        printf("Error loading module %s: %s\n", module_name, dlerror());
        return;
    }

    // Get the list of available functions from the module using dlsym()
    void **available_functions_ptr = dlsym(handle, "available_functions");
    if (!available_functions_ptr) {
        printf("Error getting available functions from module %s: %s\n", module_name, dlerror());
        return;
    }

    // Add the new functions to the list
    pthread_mutex_lock(&function_list_lock);
    cryptographic_function_t *new_functions = (cryptographic_function_t *)available_functions_ptr;
    available_functions = realloc(available_functions, sizeof(cryptographic_function_t) * (num_functions + 1));
    memcpy(&available_functions[num_functions], new_functions, sizeof(cryptographic_function_t) * num_functions);
    pthread_mutex_unlock(&function_list_lock);
}

// Unload a cryptographic module and remove its functions from the list
void unload_cryptographic_module(const char *module_name) {
    // Find the module in the list of available modules
    int i;
    for (i = 0; i < num_modules; i++) {
        if (!strcmp(available_modules[i].name, module_name)) {
            break;
        }
    }

    // If the module is found, unload it using dlclose()
    if (i < num_modules) {
        void *handle = available_modules[i].handle;
        dlclose(handle);
        pthread_mutex_lock(&function_list_lock);
        memmove(&available_functions[i], &available_functions[i + 1], sizeof(cryptographic_function_t) * (num_functions - i));
        available_functions = realloc(available_functions, sizeof(cryptographic_function_t) * (num_functions - 1));
        pthread_mutex_unlock(&function_list_lock);
    }
}

// Get a list of all available cryptographic functions and ciphers
void get_available_functions(cryptographic_function_t **functions) {
    // Lock the mutex to ensure thread safety when accessing the list
    pthread_mutex_lock(&function_list_lock);

    // Copy the list of available functions to the output parameter
    *functions = malloc(sizeof(cryptographic_function_t) * num_functions);
    memcpy(*functions, available_functions, sizeof(cryptographic_function_t) * num_functions);

    // Unlock the mutex and return
    pthread_mutex_unlock(&function_list_lock);
}

// Free a list of cryptographic functions and ciphers
void free_available_functions(cryptographic_function_t **functions) {
    // Lock the mutex to ensure thread safety when accessing the list
    pthread_mutex_lock(&function_list_lock);

    // Free the memory allocated for the list of available functions
    free(*functions);
    *functions = NULL;

    // Unlock the mutex and return
    pthread_mutex_unlock(&function_list_lock);
}
```
