#include <stdio.h>

void manage_resource_pool(int max_concurrency) {
  sem_t *sem = sem_open("resource_pool", O_CREAT, 0644, max_concurrency);
  if (sem == SEM_FAILED) {
    perror("Failed to create semaphore");
    return;
  }

  // Initialize the resource pool with the specified maximum number of concurrent accesses allowed
  for (int i = 0; i < max_concurrency; i++) {
    sem_post(sem);
  }

  // Ensure that all resources are properly released after use
  atexit(cleanup);

  // Implement a logging mechanism to track the usage of resources, including the time and duration of each access
  struct timespec start;
  struct timespec end;
  clock_gettime(CLOCK_REALTIME, &start);

  // Handle edge cases such as exceeding the maximum concurrency limit and potential race conditions
  while (1) {
    sem_wait(sem);
    printf("Accessing resource...\n");
    clock_gettime(CLOCK_REALTIME, &end);
    double duration = (double)(end.tv_sec - start.tv_sec) + (double)(end.tv_nsec - start.tv_nsec) / 1000000000;
    printf("Resource accessed for %f seconds\n", duration);
    sem_post(sem);
  }
}

void cleanup() {
  sem_close(sem);
  sem_unlink("resource_pool");
}
