use std::fs;
use std::path::PathBuf;
use std::thread;
use std::sync::{Arc, Mutex};
use std::error::Error;
use std::fmt;

#[derive(Debug)]
struct ParseError {
    message: String,
}

impl fmt::Display for ParseError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "Parse error: {}", self.message)
    }
}

impl Error for ParseError {}

fn parse_file(path: PathBuf) -> Result<String, ParseError> {
    // Validate the file path and ensure it exists
    if !path.exists() || !path.is_file() {
        return Err(ParseError {
            message: format!("File '{}' does not exist or is not a file", path.display()),
        });
    }

    // Determine the grammar to use based on the file extension
    let grammar = match path.extension().and_then(|ext| ext.to_str()) {
        Some("txt") => "text",
        Some("xml") => "xml",
        _ => return Err(ParseError {
            message: format!("Unsupported file extension '{}'", path.extension().unwrap().display()),
        }),
    };

    // Parse the file using the chosen grammar
    let mut parser = match grammar {
        "text" => TextParser::new(path),
        "xml" => XmlParser::new(path),
        _ => unreachable!(),
    };

    // Handle parsing errors and semantic errors
    match parser.parse() {
        Ok(tokens) => {
            let mut llvm_ir = String::new();
            for token in tokens {
                match token {
                    Token::Text(text) => llvm_ir.push_str(&format!("{}", text)),
                    Token::Xml(xml) => llvm_ir.push_str(&format!("{}", xml)),
                }
            }
            Ok(llvm_ir)
        },
        Err(err) => Err(ParseError {
            message: format!("Parsing error: {}", err),
        }),
    }
}

fn generate_llvm_ir(path: PathBuf, grammar: &str) -> Result<String, ParseError> {
    // Validate the file path and ensure it exists
    if !path.exists() || !path.is_file() {
        return Err(ParseError {
            message: format!("File '{}' does not exist or is not a file", path.display()),
        });
    }

    // Determine the grammar to use based on the file extension
    let grammar = match grammar {
        "text" => "text",
        "xml" => "xml",
        _ => return Err(ParseError {
            message: format!("Unsupported grammar '{}'", grammar),
        }),
    };

    // Parse the file using the chosen grammar
    let mut parser = match grammar {
        "text" => TextParser::new(path),
        "xml" => XmlParser::new(path),
        _ => unreachable!(),
    };

    // Handle parsing errors and semantic errors
    match parser.parse() {
        Ok(tokens) => {
            let mut llvm_ir = String::new();
            for token in tokens {
                match token {
                    Token::Text(text) => llvm_ir.push_str(&format!("{}", text)),
                    Token::Xml(xml) => llvm_ir.push_str(&format!("{}", xml)),
                }
            }
            Ok(llvm_ir)
        },
        Err(err) => Err(ParseError {
            message: format!("Parsing error: {}", err),
        }),
    }
}

fn main() -> Result<(), Box<dyn Error>> {
    // Parse the command-line arguments
    let args = std::env::args().collect::<Vec<String>>();
    if args.len() < 3 {
        return Err(Box::new(ParseError {
            message: "Not enough arguments".to_string(),
        }));
    }

    // Determine the file path and grammar to use
    let path = PathBuf::from(&args[1]);
    let grammar = &args[2];

    // Handle parsing errors and semantic errors
    match generate_llvm_ir(path, grammar) {
        Ok(llvm_ir) => println!("{}", llvm_ir),
        Err(err) => eprintln!("Error: {}", err),
    }

    Ok(())
}
