void insert_unique(vector<int>& v, int val1, int val2, int val3) {
    // Find the first occurrence of val2 in the vector
    auto it = find(v.begin(), v.end(), val2);

    // If val2 is found, insert val3 after it
    if (it != v.end()) {
        v.insert(++it, val3);
    } else {
        // If val2 is not found, insert val3 at the end of the vector
        v.push_back(val3);
    }

    // Remove any duplicates from the vector
    unique(v.begin(), v.end());
}
