namespace GameEnvironmentConfiguration
{
    class Program
    {
        static void Main(string[] args)
        {
            // Load configuration from JSON file
            string configFilePath = "config.json";
            string jsonConfig = File.ReadAllText(configFilePath);
            Config config = JsonConvert.DeserializeObject<Config>(jsonConfig);

            // Initialize game environment with configuration settings
            GameEnvironment env = new GameEnvironment();
            env.TileSize = config.TileSize;
            env.WorldDimensions = config.WorldDimensions;
            env.CameraMovementSpeed = config.CameraMovementSpeed;
            env.FrictionCoefficient = config.FrictionCoefficient;

            // Validate configuration settings for consistency and correctness
            if (config.TileSize > config.WorldDimensions)
            {
                Console.WriteLine("Invalid configuration: tile size cannot be larger than world dimensions.");
                return;
            }

            // Handle dynamic updates to configuration settings without requiring a restart
            while (true)
            {
                string input = Console.ReadLine();
                if (input == "quit")
                {
                    break;
                }
                else if (input == "update")
                {
                    // Update configuration settings from JSON file
                    jsonConfig = File.ReadAllText(configFilePath);
                    config = JsonConvert.DeserializeObject<Config>(jsonConfig);

                    // Validate updated configuration settings for consistency and correctness
                    if (config.TileSize > config.WorldDimensions)
                    {
                        Console.WriteLine("Invalid configuration: tile size cannot be larger than world dimensions.");
                        continue;
                    }

                    // Update game environment with updated configuration settings
                    env.TileSize = config.TileSize;
                    env.WorldDimensions = config.WorldDimensions;
                    env.CameraMovementSpeed = config.CameraMovementSpeed;
                    env.FrictionCoefficient = config.FrictionCoefficient;
                }
            }
        }
    }

    class Config
    {
        public int TileSize { get; set; }
        public int WorldDimensions { get; set; }
        public float CameraMovementSpeed { get; set; }
        public float FrictionCoefficient { get; set; }
