async function manageResources(id: string, requestBody: object): Promise<object> {
  const resources = await getResourcesByIds([id]);
  if (resources.length === 0) {
    return { status: 'error', message: `Resource with id ${id} not found` };
  }

  const updatedResources = updateResources(resources, requestBody);
  const affectedCount = await saveUpdatedResources(updatedResources);

  return { status: 'success', message: `Affected resources: ${affectedCount}` };
}

async function bulkDeleteResources(ids: string[]): Promise<object> {
  const resources = await getResourcesByIds(ids);
  if (resources.length === 0) {
    return { status: 'error', message: `No resources found with ids ${ids}` };
  }

  const deletedCount = await deleteResources(resources);

  return { status: 'success', message: `Deleted resources: ${deletedCount}` };
