<?php

function handleUserRequest($_REQUEST) {
    // Validate input data for each field
    $name = validateInputData('name', $_REQUEST['name'], 2, 50);
    $email = validateInputData('email', $_REQUEST['email'], 'email');
    $password = validateInputData('password', $_REQUEST['password'], 8);

    // Check if the email is already in use by another user before creating or updating an account
    $isEmailInUse = checkIfEmailIsInUse($email);
    if ($isEmailInUse) {
        return jsonResponse(400, 'error', "The email address is already in use");
    }

    // Implement rate limiting to prevent abuse
    $rateLimitExceeded = checkRateLimit($_SERVER['REMOTE_ADDR']);
    if ($rateLimitExceeded) {
        return jsonResponse(429, 'error', "Rate limit exceeded");
    }

    // Log all actions performed on user accounts
    logAction($_REQUEST['id'], $_REQUEST['name'], $_SERVER['REMOTE_ADDR']);

    // Use prepared statements to prevent SQL injection when interacting with the database
    $db = new PDO('mysql:host=localhost;dbname=mydatabase', 'username', 'password');
    $stmt = $db->prepare("SELECT * FROM users WHERE id = :id");
    $stmt->bindParam(':id', $_REQUEST['id']);
    $stmt->execute();
    $user = $stmt->fetch(PDO::FETCH_ASSOC);

    // Handle concurrent requests safely, ensuring that updates to the same user account do not interfere with each other
    if ($user) {
        $lock = new Lock($user['id']);
        $lock->acquire();
        try {
            // Update the user account
            $stmt = $db->prepare("UPDATE users SET name = :name, email = :email, password = :password WHERE id = :id");
            $stmt->bindParam(':name', $name);
            $stmt->bindParam(':email', $email);
            $stmt->bindParam(':password', $password);
            $stmt->bindParam(':id', $_REQUEST['id']);
            $stmt->execute();
        } catch (Exception $e) {
            // Handle database connection errors and retry the operation a maximum of three times before failing
            if ($lock->getRetryCount() < 3) {
                $lock->release();
                return handleUserRequest($_REQUEST);
            } else {
                $lock->release();
                throw $e;
            }
        } finally {
            $lock->release();
        }
    } else {
        // Create a new user account
        $stmt = $db->prepare("INSERT INTO users (name, email, password) VALUES (:name, :email, :password)");
        $stmt->bindParam(':name', $name);
        $stmt->bindParam(':email', $email);
        $stmt->bindParam(':password', $password);
        $stmt->execute();
    }

    // Integrate with an external API to send a welcome email upon account creation, using a specific template and personalization variables
    if ($_REQUEST['sub_action'] === 'create') {
        $apiResponse = sendWelcomeEmail($_REQUEST['email'], $_REQUEST['name']);
        if ($apiResponse->status !== 200) {
            return jsonResponse(500, 'error', "Failed to send welcome email");
        }
    }

    // Ensure that the function can be easily extended to support additional user actions in the future
    switch ($_REQUEST['sub_action']) {
        case 'create':
            return jsonResponse(201, 'success', "User created successfully");
        case 'update':
            return jsonResponse(200, 'success', "User updated successfully");
        case 'delete':
            return jsonResponse(204, 'success', "User deleted successfully");
        default:
            return jsonResponse(400, 'error', "Invalid sub_action provided");
    }
}

function validateInputData($fieldName, $value, $minLength = null, $maxLength = null) {
    // Check if the field is empty
    if (empty($value)) {
        return jsonResponse(400, 'error', "The $fieldName field cannot be empty");
    }

    // Check if the field length is within the specified range
    if ($minLength !== null && strlen($value) < $minLength) {
        return jsonResponse(400, 'error', "The $fieldName field must be at least $minLength characters long");
    }
    if ($maxLength !== null && strlen($value) > $maxLength) {
        return jsonResponse(400, 'error', "The $fieldName field cannot exceed $maxLength characters");
    }

    // Return the validated value
    return $value;
}

function checkIfEmailIsInUse($email) {
    // Check if the email is already in use by another user
    $db = new PDO('mysql:host=localhost;dbname=mydatabase', 'username', 'password');
    $stmt = $db->prepare("SELECT * FROM users WHERE email = :email");
    $stmt->bindParam(':email', $email);
    $stmt->execute();
    return $stmt->fetch(PDO::FETCH_ASSOC) !== false;
}

function checkRateLimit($ipAddress) {
    // Check if the rate limit has been exceeded for the current IP address
    $db = new PDO('mysql:host=localhost;dbname=mydatabase', 'username', 'password');
    $stmt = $db->prepare("SELECT COUNT(*) AS count FROM user_requests WHERE ip_address = :ipAddress AND created_at > NOW() - INTERVAL 1 MINUTE");
    $stmt->bindParam(':ipAddress', $ipAddress);
    $stmt->execute();
    return $stmt->fetch(PDO::FETCH_ASSOC)['count'] >= 10;
}

function logAction($userId, $name, $ipAddress) {
    // Log all actions performed on user accounts
    $db = new PDO('mysql:host=localhost;dbname=mydatabase', 'username', 'password');
    $stmt = $db->prepare("INSERT INTO user_actions (user_id, name, ip_address, created_at) VALUES (:userId, :name, :ipAddress, NOW())");
    $stmt->bindParam(':userId', $userId);
    $stmt->bindParam(':name', $name);
    $stmt->bindParam(':ipAddress', $ipAddress);
    $stmt->execute();
}

function sendWelcomeEmail($email, $name) {
    // Integrate with an external API to send a welcome email upon account creation, using a specific template and personalization variables
    $apiResponse = json_decode(file_get_contents("https://example.com/api/v1/send-welcome-email?email=$email&name=$name"));
    return $apiResponse;
}

function jsonResponse($statusCode, $message, $details) {
    // Return a JSON response with the specified status code and message
    header("Content-Type: application/json");
    return json_encode(array('message' => $message, 'details' => $details), JSON_PRETTY_PRINT);
}
