function asyncTraverseDOM(rootElement, filterCallback, paginationThreshold) {
  const matchingElements = [];
  let currentPage = 0;
  let pageSize = 100;

  // Define a recursive function to traverse the DOM tree
  function traverse(element) {
    if (filterCallback(element)) {
      matchingElements.push(element);
    }

    for (let i = 0; i < element.children.length; i++) {
      traverse(element.children[i]);
    }
  }

  // Define a function to paginate the results
  function paginate() {
    const startIndex = currentPage * pageSize;
    const endIndex = Math.min((currentPage + 1) * pageSize, matchingElements.length);
    return matchingElements.slice(startIndex, endIndex);
  }

  // Define a function to handle navigation issues during traversal
  function handleNavigationIssues() {
    try {
      traverse(rootElement);
    } catch (error) {
      console.log("Error occurred during traversal:", error);
    }
  }

  // Call the recursive function to start traversing the DOM tree
  handleNavigationIssues();

  // Return a paginated version of the results if necessary
  return matchingElements.length > paginationThreshold ? paginate() : matchingElements;
}
