public class FileScanner {
    public static int countExecutableDirectories(String[] filePaths) {
        // Create a tree-based data structure to efficiently manage directory hierarchy and file permissions
        Map<String, List<File>> directoryTree = new HashMap<>();

        // Iterate over the input array of file paths
        for (String filePath : filePaths) {
            File file = new File(filePath);

            // If the file is executable, increment the count of executable files in its containing directory
            if (file.canExecute()) {
                String directoryPath = file.getParent();
                List<File> executableFiles = directoryTree.computeIfAbsent(directoryPath, k -> new ArrayList<>());
                executableFiles.add(file);
            }
        }

        // Count the number of unique directories containing executable files
        int count = 0;
        for (List<File> executableFiles : directoryTree.values()) {
            if (!executableFiles.isEmpty()) {
                count++;
            }
        }

        return count;
    }
}
