import java.util.HashMap;
import java.util.Map;

public class ThemeManager {
    private static final int MAX_CACHE_SIZE = 100; // maximum number of themes to cache
    private static final long CACHE_EXPIRATION_TIME = 3600000L; // one hour in milliseconds
    private static final String DEFAULT_THEME_DIRECTORY = "themes"; // default theme directory

    private Map<String, Theme> cache = new HashMap<>(); // map of cached themes
    private long lastCacheCleanupTime = System.currentTimeMillis(); // time of last cache cleanup

    public synchronized void retrieveTheme(String themeName) {
        // check if the theme is still in use and, if not, release its resources and set it to null
        Theme theme = cache.get(themeName);
        if (theme != null && !theme.isInUse()) {
            theme.releaseResources();
            cache.remove(themeName);
        }

        // verify if a default theme directory is configured and, if not, initialize it with a predefined set of themes
        if (!cache.containsKey(DEFAULT_THEME_DIRECTORY)) {
            initDefaultThemes();
        }
    }

    public synchronized void cacheTheme(String themeName) {
        // check if the theme is already cached and, if not, add it to the cache
        Theme theme = cache.get(themeName);
        if (theme == null) {
            theme = new Theme(themeName);
            cache.put(themeName, theme);
        }
    }

    public synchronized void clearCache() {
        // clear the cache and reset the last cache cleanup time
        cache.clear();
        lastCacheCleanupTime = System.currentTimeMillis();
    }

    private void initDefaultThemes() {
        // initialize the default theme directory with a predefined set of themes
        Theme[] themes = new Theme[] {
            new Theme("theme1"),
            new Theme("theme2"),
            new Theme("theme3")
        };
        for (Theme theme : themes) {
            cache.put(DEFAULT_THEME_DIRECTORY, theme);
        }
    }

    private void evictCache() {
        // evict the least recently used theme from the cache if the cache exceeds the specified threshold
        long currentTime = System.currentTimeMillis();
        if (cache.size() > MAX_CACHE_SIZE) {
            Theme leastRecentlyUsedTheme = null;
            for (Map.Entry<String, Theme> entry : cache.entrySet()) {
                if (leastRecentlyUsedTheme == null || entry.getValue().getLastAccessTime() < leastRecentlyUsedTheme.getLastAccessTime()) {
                    leastRecentlyUsedTheme = entry.getValue();
                }
            }
            cache.remove(leastRecentlyUsedTheme.getName());
        }
    }
}
```
