int* readIntegers(int& count) {
  // Initialize the vector to hold the integers
  vector<int> integers;

  // Read each integer from standard input and add it to the vector
  while (cin >> i) {
    integers.push_back(i);
  }

  // Get the size of the vector and allocate memory for the array
  count = integers.size();
  int* arr = new int[count];

  // Copy the elements from the vector to the array
  copy(integers.begin(), integers.end(), arr);

  return arr;
}

// Function to find the largest integer in an array of integers
int findLargestInteger(int* arr, int count) {
  // Initialize the largest integer as the first element in the array
  int largest = arr[0];

  // Iterate over the remaining elements and compare them with the current largest integer
  for (int i = 1; i < count; i++) {
    if (arr[i] > largest) {
      largest = arr[i];
    }
  }

  return largest;
}

