void simulateService(int& count, int* arr) {
  // Initialize the random engine and distribution for generating random delays
  mt19937 rng(chrono::steady_clock::now().time_since_epoch().count());
  uniform_int_distribution<int> delayDistribution(0, 10);

  // Iterate over the array of integers and simulate starting and stopping the service with random delays
  for (int i = 0; i < count; i++) {
    // Start the service with a random delay
    int startDelay = delayDistribution(rng);
    cout << "Starting service with delay: " << startDelay << endl;
    this_thread::sleep_for(chrono::seconds(startDelay));

    // Stop the service with a random delay
    int stopDelay = delayDistribution(rng);
    cout << "Stopping service with delay: " << stopDelay << endl;
    this_thread::sleep_for(chrono::seconds(stopDelay));
  }
}

