  for (int i = 0; i < count; i++) {
    // Start the service with a random delay
    int startDelay = delayDistribution(rng);
    logFile << "Starting service with delay: " << startDelay << endl;
    this_thread::sleep_for(chrono::seconds(startDelay));

    // Stop the service with a random delay
    int stopDelay = delayDistribution(rng);
    logFile << "Stopping service with delay: " << stopDelay << endl;
    this_thread::sleep_for(chrono::seconds(stopDelay));
  }
}

int main() {
