#include <stdlib.h>
#include <string.h>

typedef struct State {
    int label;
    struct State* next;
} State;

typedef struct FSA {
    int num_states;
    State** states;
} FSA;

State* manage_state_list(int* states, int num_states, FSA* fsa, int last_state) {
    // Check for invalid pointers and out-of-bounds access
    if (states == NULL || fsa == NULL || last_state < 0 || last_state >= num_states) {
        return NULL;
    }

    // Allocate a new state list dynamically
    State* new_list = malloc(sizeof(State) * num_states);
    if (new_list == NULL) {
        return NULL;
    }

    // Populate the new state list with states that meet the condition
    int count = 0;
    for (int i = 0; i < num_states; i++) {
        State* current_state = &(fsa->states[i]);
        if (current_state->label == last_state) {
            new_list[count].label = current_state->label;
            new_list[count].next = NULL;
            count++;
        } else {
            for (int j = 0; j < fsa->num_states; j++) {
                State* target_state = &(fsa->states[j]);
                if (target_state->label == current_state->label && target_state->next != NULL) {
                    new_list[count].label = target_state->label;
                    new_list[count].next = target_state->next;
                    count++;
                    break;
                }
            }
        }
    }

    // Ensure that the 'next' pointer of the last state in the current state list points to the newly created state list
    if (last_state < num_states - 1) {
        fsa->states[last_state].next = new_list;
    }

    return new_list;
}
```
