using System;

public class RandomValueGenerator
{
    private int _minIntRange;
    private int _maxIntRange;
    private float _minFloatRange;
    private float _maxFloatRange;

    public RandomValueGenerator(int minIntRange, int maxIntRange)
    {
        if (minIntRange > maxIntRange)
        {
            throw new ArgumentException("Minimum integer range must be less than or equal to maximum integer range.");
        }

        _minIntRange = minIntRange;
        _maxIntRange = maxIntRange;
    }

    public RandomValueGenerator(float minFloatRange, float maxFloatRange)
    {
        if (minFloatRange > maxFloatRange)
        {
            throw new ArgumentException("Minimum floating-point range must be less than or equal to maximum floating-point range.");
        }

        _minFloatRange = minFloatRange;
        _maxFloatRange = maxFloatRange;
    }

    public RandomValueGenerator()
    {
        _minIntRange = 0;
        _maxIntRange = 100;
        _minFloatRange = 0.0f;
        _maxFloatRange = 1.0f;
    }

    public int GenerateRandomInteger(bool inclusive)
    {
        if (inclusive)
        {
            return new Random().Next(_minIntRange, _maxIntRange + 1);
        }
        else
        {
            return new Random().Next(_minIntRange, _maxIntRange);
        }
    }

    public float GenerateRandomFloat(bool inclusive)
    {
        if (inclusive)
        {
            return new Random().NextFloat(_minFloatRange, _maxFloatRange + 1.0f);
        }
        else
        {
            return new Random().NextFloat(_minFloatRange, _maxFloatRange);
        }
    }

    public void ResetRange()
    {
        _minIntRange = 0;
        _maxIntRange = 100;
        _minFloatRange = 0.0f;
        _maxFloatRange = 1.0f;
    }

    public override string ToString()
    {
        return $"RandomValueGenerator: Minimum integer range: {_minIntRange}, Maximum integer range: {_maxIntRange}, Minimum floating-point range: {_minFloatRange}, Maximum floating-point range: {_maxFloatRange}";
    }
}
```
