const reduceAsync = async (arr, initialValue, callback) => {
  // Check if the input is valid
  if (!Array.isArray(arr)) {
    throw new Error("Invalid input: arr must be an array");
  }
  if (typeof initialValue !== "number") {
    throw new Error("Invalid input: initialValue must be a number");
  }
  if (typeof callback !== "function") {
    throw new Error("Invalid input: callback must be a function");
  }

  // Initialize the accumulator and the result array
  let accumulator = initialValue;
  const results = [];

  // Iterate over the array asynchronously, using recursion to handle large datasets
  for (let i = 0; i < arr.length; i++) {
    await new Promise((resolve) => setTimeout(resolve, 0)); // Yield control to other tasks
    accumulator = callback(accumulator, arr[i]);
    results.push(accumulator);
  }

  // Return the final result
  return results;
};
```
