#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <pthread.h>

// Define a structure to represent a resource bundle
typedef struct {
    int num_items;
    char **items;
} ResourceBundle;

// Define a cache for the resource bundles
static pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;
static ResourceBundle *cache = NULL;

// Load a resource bundle from a file and return its number of items
int load_resource_bundle(const char *path) {
    // Check if the bundle is already in the cache
    pthread_mutex_lock(&cache_lock);
    ResourceBundle *bundle = cache;
    while (bundle != NULL && strcmp(bundle->path, path) != 0) {
        bundle = bundle->next;
    }
    if (bundle == NULL) {
        // Load the bundle from disk and add it to the cache
        FILE *file = fopen(path, "r");
        if (file == NULL) {
            pthread_mutex_unlock(&cache_lock);
            return -errno;
        }
        int num_items = 0;
        while (!feof(file)) {
            char *item = malloc(sizeof(char) * MAX_ITEM_LENGTH);
            if (fgets(item, MAX_ITEM_LENGTH, file) == NULL) {
                free(item);
                break;
            }
            num_items++;
        }
        fclose(file);
        bundle = malloc(sizeof(ResourceBundle));
        bundle->num_items = num_items;
        bundle->items = malloc(sizeof(char *) * num_items);
        for (int i = 0; i < num_items; i++) {
            bundle->items[i] = malloc(sizeof(char) * MAX_ITEM_LENGTH);
        }
        // Add the bundle to the cache
        bundle->next = cache;
        cache = bundle;
    }
    pthread_mutex_unlock(&cache_lock);
    return bundle->num_items;
}
```
This code uses a cache to store previously loaded resource bundles, which reduces the number of disk I/O operations required when loading the same bundle multiple times. The `pthread_mutex_t` mutex is used to ensure thread safety during updates to the cache. The function checks for errors and returns appropriate error codes, including handling race conditions when updating the cache.']

