struct tiff_info parseTiffAndEncrypt(const char* file_path, const char* command) {
    // Open the TIFF file and check for errors
    FILE* fp = fopen(file_path, "rb");
    if (fp == NULL) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }

    // Determine the bits per sample and samples per pixel
    int bits_per_sample = 0;
    int samples_per_pixel = 0;
    while (1) {
        char buffer[256];
        if (fgets(buffer, sizeof(buffer), fp) == NULL) {
            break;
        }
        // Check for the "BitsPerSample" tag
        if (strncmp(buffer, "BitsPerSample", 13) == 0) {
            bits_per_sample = atoi(buffer + 14);
        }
        // Check for the "SamplesPerPixel" tag
        if (strncmp(buffer, "SamplesPerPixel", 16) == 0) {
            samples_per_pixel = atoi(buffer + 17);
        }
    }

    // Handle cases where the image has extra samples
    int extra_samples = 0;
    struct {
        int id;
        int type;
    } *extra_samples_info = NULL;
    if (bits_per_sample == 32) {
        extra_samples = 1;
        extra_samples_info = malloc(sizeof(struct {
            int id;
            int type;
        }));
        extra_samples_info->id = 0;
        extra_samples_info->type = 32;
    } else if (bits_per_sample == 64) {
        extra_samples = 2;
        extra_samples_info = malloc(sizeof(struct {
            int id;
            int type;
        }) * 2);
        extra_samples_info[0].id = 0;
        extra_samples_info[0].type = 32;
        extra_samples_info[1].id = 1;
        extra_samples_info[1].type = 32;
    } else {
        // Return an appropriate error message if the bits per sample is not supported
        fprintf(stderr, "Unsupported bits per sample: %d\n", bits_per_sample);
        exit(EXIT_FAILURE);
    }

    // Use OpenSSL to encrypt or decrypt the content of the TIFF file
    if (strcmp(command, "encrypt") == 0) {
        EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
        if (!EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, NULL, NULL)) {
            ERR_print_errors_fp(stderr);
            exit(EXIT_FAILURE);
        }
        // Encrypt the content of the TIFF file
        if (!EVP_EncryptUpdate(ctx, NULL, NULL, fp)) {
            ERR_print_errors_fp(stderr);
            exit(EXIT_FAILURE);
        }
        EVP_CIPHER_CTX_free(ctx);
    } else if (strcmp(command, "decrypt") == 0) {
        EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
        if (!EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, NULL, NULL)) {
            ERR_print_errors_fp(stderr);
            exit(EXIT_FAILURE);
        }
        // Decrypt the content of the TIFF file
        if (!EVP_DecryptUpdate(ctx, NULL, NULL, fp)) {
            ERR_print_errors_fp(stderr);
            exit(EXIT_FAILURE);
        }
        EVP_CIPHER_CTX_free(ctx);
    } else {
        // Return an appropriate error message if the command line option is not recognized
        fprintf(stderr, "Invalid command line option: %s\n", command);
        exit(EXIT_FAILURE);
    }

    // Close the TIFF file and return the struct with the information about the TIFF file
    fclose(fp);
    struct tiff_info info = {bits_per_sample, samples_per_pixel, extra_samples, extra_samples_info};
    return info;
}
```
