char* modify_filename(const char* filename) {
    // Get the length of the input filename
    int len = strlen(filename);

    // Create a new string to store the modified filename
    char* new_filename = malloc(50 * sizeof(char));

    // Copy the input filename into the new string
    strcpy(new_filename, filename);

    // Extract the file type from the end of the filename
    int type_len = 3;
    char* type = &new_filename[len - type_len];

    // Check if the extracted file type is recognized
    if (strcmp(type, ".txt") == 0 || strcmp(type, ".jpg") == 0 || strcmp(type, ".png") == 0) {
        // If the file type is recognized, modify the filename accordingly
        new_filename[len - type_len] = '_';
        new_filename[len - type_len + 1] = '0';
        new_filename[len - type_len + 2] = '0';
        new_filename[len - type_len + 3] = '1';
    } else {
        // If the file type is not recognized, append a new type based on the length of the filename
        if (len < 4) {
            // Handle filenames with no extension by appending a default type .bin
            strcpy(new_filename + len, ".bin");
        } else {
            // Append a sequence of numbers starting from 1 followed by the recognized or newly determined file type
            for (int i = 0; i < len - type_len; i++) {
                new_filename[i] = '0' + (i % 10);
            }
            strcpy(new_filename + len - type_len, ".bin");
        }
    }

    // Ensure the new filename does not exceed a total length of 50 characters
    if (strlen(new_filename) > 50) {
        // Truncate the filename to fit within the specified constraints
        new_filename[49] = '\0';
    }

    return new_filename;
}
