#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <ffmpeg/avcodec.h>
#include <ffmpeg/avformat.h>
#include <ffmpeg/avutil.h>

int convert_video(const char* input_file, const char* output_file, int target_resolution) {
    // Initialize FFmpeg structures
    AVFormatContext *ifmt_ctx = NULL;
    AVCodecContext *decoder = NULL;
    AVCodecContext *encoder = NULL;
    AVFrame *frame = NULL;
    AVPacket packet;
    int ret, i;

    // Open input file and initialize demuxer
    if ((ret = avformat_open_input(&ifmt_ctx, input_file, NULL, NULL)) < 0) {
        fprintf(stderr, "Could not open input file '%s': %s\n", input_file, av_err2str(ret));
        goto end;
    }

    // Find the video stream information
    if ((ret = avformat_find_stream_info(ifmt_ctx, NULL)) < 0) {
        fprintf(stderr, "Failed to find stream information: %s\n", av_err2str(ret));
        goto end;
    }

    // Dump information about file onto standard error
    av_dump_format(ifmt_ctx, 0, input_file, 0);

    // Find the video decoder
    decoder = avcodec_find_decoder(ifmt_ctx->streams[0]->codecpar->codec_id);
    if (!decoder) {
        fprintf(stderr, "Failed to find video decoder\n");
        ret = AVERROR_DECODER_NOT_FOUND;
        goto end;
    }

    // Open the codec for the video stream
    if ((ret = avcodec_open2(ifmt_ctx->streams[0]->codec, decoder, NULL)) < 0) {
        fprintf(stderr, "Failed to open video decoder: %s\n", av_err2str(ret));
        goto end;
    }

    // Find the video encoder
    encoder = avcodec_find_encoder(AV_CODEC_ID_H264);
    if (!encoder) {
        fprintf(stderr, "Failed to find video encoder\n");
        ret = AVERROR_ENCODER_NOT_FOUND;
        goto end;
    }

    // Open the codec for the video stream
    if ((ret = avcodec_open2(ifmt_ctx->streams[0]->codec, encoder, NULL)) < 0) {
        fprintf(stderr, "Failed to open video encoder: %s\n", av_err2str(ret));
        goto end;
    }

    // Allocate memory for the output file
    frame = av_frame_alloc();
    if (!frame) {
        fprintf(stderr, "Failed to allocate video frame\n");
        ret = AVERROR(ENOMEM);
        goto end;
    }

    // Set up the output file
    AVFormatContext *ofmt_ctx = NULL;
    if ((ret = avformat_alloc_output_context2(&ofmt_ctx, NULL, output_file, NULL)) < 0) {
        fprintf(stderr, "Failed to create output context: %s\n", av_err2str(ret));
        goto end;
    }

    // Set up the video encoder
    AVStream *out_stream = avformat_new_stream(ofmt_ctx, encoder);
    if (!out_stream) {
        fprintf(stderr, "Failed to create output stream\n");
        ret = AVERROR(ENOMEM);
        goto end;
    }

    // Set the video codec parameters
    out_stream->codecpar->codec_id = AV_CODEC_ID_H264;
    out_stream->codecpar->codec_type = AVMEDIA_TYPE_VIDEO;
    out_stream->codecpar->width = target_resolution;
    out_stream->codecpar->height = target_resolution;
    out_stream->codecpar->format = AV_PIX_FMT_YUV420P;
    out_stream->codecpar->bit_rate = 400000;
    out_stream->codecpar->gop_size = 12;
    out_stream->codecpar->qmin = 10;
    out_stream->codecpar->qmax = 51;
    out_stream->codecpar->max_b_frames = 1;

    // Set up the video codec context
    if ((ret = avcodec_parameters_to_context(out_stream->codec, out_stream->codecpar)) < 0) {
        fprintf(stderr, "Failed to copy parameters to output codec context: %s\n", av_err2str(ret));
        goto end;
    }

    // Open the output file
    if ((ret = avio_open(&ofmt_ctx->pb, output_file, AVIO_FLAG_WRITE)) < 0) {
        fprintf(stderr, "Failed to open output file: %s\n", av_err2str(ret));
        goto end;
    }

    // Write the stream header
    if ((ret = avformat_write_header(ofmt_ctx, NULL)) < 0) {
        fprintf(stderr, "Failed to write output file header: %s\n", av_err2str(ret));
        goto end;
    }

    // Read packets from the input file and write them to the output file
    while (1) {
        ret = av_read_frame(ifmt_ctx, &packet);
        if (ret < 0)
            break;

        // Check if packet belongs to video stream
        if (packet.stream_index == 0) {
            // Decode the packet and write the decoded frame to the output file
            ret = avcodec_send_packet(ifmt_ctx->streams[0]->codec, &packet);
            if (ret < 0) {
                fprintf(stderr, "Error submitting packet for decoding: %s\n", av_err2str(ret));
                goto end;
            }

            while (ret >= 0) {
                ret = avcodec_receive_frame(ifmt_ctx->streams[0]->codec, frame);
                if (ret == AVERROR(EAGAIN) || ret == AVERROR_EOF)
                    break;
                else if (ret < 0) {
                    fprintf(stderr, "Error decoding video frame: %s\n", av_err2str(ret));
                    goto end;
                }

                // Rescale the frame to the target resolution
                ret = av_frame_get_buffer(frame, 0);
                if (ret < 0) {
                    fprintf(stderr, "Error allocating output buffer: %s\n", av_err2str(ret));
                    goto end;
                }

                ret = av_image_copy(frame->data, frame->linesize, (const uint8_t**)decoder->data, decoder->linesize, AV_PIX_FMT_YUV420P, target_resolution, target_resolution);
                if (ret < 0) {
                    fprintf(stderr, "Error rescaling video frame: %s\n", av_err2str(ret));
                    goto end;
                }

                // Encode the frame and write it to the output file
                ret = avcodec_send_frame(out_stream->codec, frame);
                if (ret < 0) {
                    fprintf(stderr, "Error submitting frame for encoding: %s\n", av_err2str(ret));
                    goto end;
                }

                while (ret >= 0) {
                    ret = avcodec_receive_packet(out_stream->codec, &packet);
                    if (ret == AVERROR(EAGAIN) || ret == AVERROR_EOF)
                        break;
                    else if (ret < 0) {
                        fprintf(stderr, "Error encoding video frame: %s\n", av_err2str(ret));
                        goto end;
                    }

                    ret = av_write_frame(ofmt_ctx, &packet);
                    if (ret < 0) {
                        fprintf(stderr, "Error writing output frame: %s\n", av_err2str(ret));
                        goto end;
                    }
                }
            }
        }

        // Free the packet that was read
        av_packet_unref(&packet);
    }

    // Write the trailer to the output file
    ret = av_write_trailer(ofmt_ctx);
    if (ret < 0) {
        fprintf(stderr, "Error writing output file trailer: %s\n", av_err2str(ret));
        goto end;
    }

    // Clean up
    ret = 0;
end:
    if (ofmt_ctx && !(ofmt_ctx->oformat->flags & AVFMT_NOFILE))
        avio_closep(&ofmt_ctx->pb);
    avcodec_free_context(&encoder);
    avcodec_free_context(&decoder);
    avformat_free_context(ifmt_ctx);
    avformat_free_context(ofmt_ctx);
    av_frame_free(&frame);
    return ret;
}
