import java.io.*;
import java.util.concurrent.TimeUnit;

public class CommandExecutor {
    private static final int TIMEOUT = 60; // seconds
    private static final String LOG_FILE = "command-log.txt";

    public static void main(String[] args) throws Exception {
        if (args.length < 2) {
            System.out.println("Usage: java CommandExecutor <file> <command> [<working directory>]");
            return;
        }

        String file = args[0];
        String command = args[1];
        File workingDirectory = new File(args.length > 2 ? args[2] : ".");

        // Check if the target file exists and is writable
        if (!workingDirectory.exists() || !workingDirectory.isDirectory()) {
            System.out.println("Invalid working directory: " + workingDirectory);
            return;
        }

        File targetFile = new File(workingDirectory, file);
        if (targetFile.exists() && !targetFile.canWrite()) {
            System.out.println("Target file is not writable: " + targetFile);
            return;
        }

        // Delete the target file if it exists
        if (targetFile.exists()) {
            boolean deleted = targetFile.delete();
            if (!deleted) {
                System.out.println("Failed to delete target file: " + targetFile);
                return;
            }
        }

        // Execute the command and read its output and error streams
        Process process = Runtime.getRuntime().exec(command, null, workingDirectory);
        BufferedReader outputReader = new BufferedReader(new InputStreamReader(process.getInputStream()));
        BufferedReader errorReader = new BufferedReader(new InputStreamReader(process.getErrorStream()));

        // Log the execution process
        String logMessage = "Executing command: " + command + "\n";
        logMessage += "Working directory: " + workingDirectory + "\n";
        logMessage += "Output:\n" + outputReader.lines().collect(Collectors.joining("\n"));
        logMessage += "Error:\n" + errorReader.lines().collect(Collectors.joining("\n"));
        System.out.println(logMessage);

        // Handle timeout and retry mechanism
        long startTime = System.currentTimeMillis();
        while (process.isAlive()) {
            if (System.currentTimeMillis() - startTime > TIMEOUT * 1000) {
                process.destroyForcibly();
                break;
            }
            Thread.sleep(500);
        }

        // Close all I/O streams and release system resources
        outputReader.close();
        errorReader.close();
        process.waitFor();
    }
}
