// Define a custom hash map structure for efficient lookup of recently processed tokens
typedef struct {
    int size;
    int capacity;
    char** keys;
    bool* values;
} TokenHashMap;

// Initialize the hash map with an initial capacity of 10
TokenHashMap* init_hash_map(int capacity) {
    TokenHashMap* map = malloc(sizeof(TokenHashMap));
    map->size = 0;
    map->capacity = capacity;
    map->keys = calloc(capacity, sizeof(char*));
    map->values = calloc(capacity, sizeof(bool));
    return map;
}

// Add a new token to the hash map and update its value
void add_token(TokenHashMap* map, char* key, bool value) {
    if (map->size == map->capacity) {
        // Resize the hash map if it's full
        int new_capacity = map->capacity * 2;
        map->keys = realloc(map->keys, new_capacity * sizeof(char*));
        map->values = realloc(map->values, new_capacity * sizeof(bool));
        map->capacity = new_capacity;
    }
    map->keys[map->size] = key;
    map->values[map->size] = value;
    map->size++;
}

