    private const int MAX_LOG_ENTRIES = 100;
    private static readonly object _lock = new object();
    private static readonly Dictionary<string, string> _logEntries = new Dictionary<string, string>();

    public static void LogMessage(string message, string key, string iv, bool condition)
    {
        if (condition)
        {
            var decryptedMessage = DecryptMessage(message, key, iv);
            var logEntry = $"{DateTime.Now:yyyy-MM-dd HH:mm:ss} - {decryptedMessage}";

            lock (_lock)
            {
                _logEntries[logEntry] = decryptedMessage;
                if (_logEntries.Count > MAX_LOG_ENTRIES)
                {
                    _logEntries.Remove(_logEntries.Keys.First());
                }
            }

            // Asynchronous logging to external service
            LogToExternalService(decryptedMessage);
        }
    }

    private static string DecryptMessage(string message, string key, string iv)
    {
        var des = new TripleDESCryptoServiceProvider();
        des.Key = Encoding.UTF8.GetBytes(key);
        des.IV = Encoding.UTF8.GetBytes(iv);

        using (var msDecrypt = new MemoryStream())
        {
            var csDecrypt = new CryptoStream(msDecrypt, des.CreateDecryptor(), CryptoStreamMode.Write);
            byte[] data = Convert.FromBase64String(message);
            csDecrypt.Write(data, 0, data.Length);
            csDecrypt.FlushFinalBlock();
            return Encoding.UTF8.GetString(msDecrypt.ToArray());
        }
    }

    private static void LogToExternalService(string message)
