public static string GetMD5Hash(string input)
{
    // Use a try-catch block to handle potential errors during hashing
    try
    {
        // Create an instance of the MD5 hash algorithm
        using var md5 = MD5.Create();

        // Convert the input string to a byte array
        byte[] inputBytes = Encoding.UTF8.GetBytes(input);

        // Hash the input bytes and return the result as a hexadecimal string
        return BitConverter.ToString(md5.ComputeHash(inputBytes)).Replace("-", "");
    }
    catch (Exception ex)
    {
        // Log any errors that occur during hashing
        Console.WriteLine($"Error occurred while hashing input: {ex.Message}");

        // Return an empty string to indicate failure
        return "";
    }
}
