using System;
using System.Security.Cryptography;
using System.Text;

public static class AESDecryption
{
    public static byte[] Decrypt(byte[] ciphertext, byte[] encryptionKey, byte[] initializationVector, PaddingMode padding)
    {
        // Initialize the AES cipher with the provided key and IV
        using (var aes = new AesCryptoServiceProvider())
        {
            aes.Key = encryptionKey;
            aes.IV = initializationVector;
            aes.Padding = padding;

            // Create a buffer for storing the decrypted data
            var decryptedData = new byte[ciphertext.Length];

            // Decrypt each part of the message separately
            int currentPart = 0;
            while (currentPart < ciphertext.Length)
            {
                try
                {
                    // Decrypt the current part of the message
                    var decryptedPart = aes.CreateDecryptor().TransformFinalBlock(ciphertext, currentPart, ciphertext.Length - currentPart);

                    // Verify the integrity of the decrypted data using HMAC-SHA256
                    var hmac = new HMACSHA256(encryptionKey);
                    var hmacHash = hmac.ComputeHash(decryptedPart);
                    if (!CompareByteArrays(hmacHash, decryptedData))
                    {
                        throw new Exception("Decryption failed: HMAC verification failed");
                    }

                    // Copy the decrypted data to the output buffer
                    Array.Copy(decryptedPart, 0, decryptedData, currentPart, decryptedPart.Length);

                    // Update the current part index and continue decrypting
                    currentPart += decryptedPart.Length;
                }
                catch (Exception e)
                {
                    // If an exception occurs during decryption, reinitialize the AES cipher with a new IV for the next part of the message
                    aes.IV = GetNewIV(initializationVector);
                    currentPart += 16;
                }
            }

            return decryptedData;
        }
    }

    private static byte[] GetNewIV(byte[] initializationVector)
    {
        // Generate a new IV for the next part of the message
        var newIV = new byte[16];
        Random rng = new Random();
        rng.NextBytes(newIV);
        return newIV;
    }

    private static bool CompareByteArrays(byte[] array1, byte[] array2)
    {
        // Compare two byte arrays for equality
        if (array1 == null || array2 == null)
            return false;
        if (array1.Length != array2.Length)
            return false;
        for (int i = 0; i < array1.Length; i++)
        {
            if (array1[i] != array2[i])
                return false;
        }
        return true;
    }
}
