class ResourceBundle {
public:
    // Constructor
    ResourceBundle(const std::string& path) : path_(path) {}

    // Method to load the resource bundle from a file
    void loadFromFile(const std::string& path) {
        // Open the file in binary mode
        std::ifstream file(path, std::ios::binary);

        // Check if the file is open successfully
        if (!file.is_open()) {
            throw std::runtime_error("Failed to open resource bundle file");
        }

        // Read the byte array from the file
        std::vector<char> buffer(std::istreambuf_iterator<char>(file), {});

        // Close the file
        file.close();

        // Deserialize the byte array into an object of a specific class
        try {
            // Create an ObjectInputStream from the byte array
            std::istringstream stream(buffer);
            std::unique_ptr<ObjectInputStream> input = std::make_unique<ObjectInputStream>(stream);

            // Read the object from the input stream
            auto obj = input->readObject();

            // Check if the deserialization was successful
            if (obj == nullptr) {
                throw std::runtime_error("Failed to deserialize resource bundle");
            }

            // Set the object as the current instance of the class
            setInstance(obj);
        } catch (const std::exception& e) {
            // If an exception occurred, throw a runtime error with a meaningful message
            throw std::runtime_error("Failed to load resource bundle: " + std::string(e.what()));
        }
    }

private:
    // Path to the resource file
    const std::string& path_;

    // Current instance of the class
    static std::unique_ptr<ResourceBundle> instance;

    // Method to set the current instance of the class
    void setInstance(const std::unique_ptr<ResourceBundle>& obj) {
        instance = obj;
    }
};
