function uploadFile(url) {
  // Validate input URL
  if (!url || !url.startsWith("http")) {
    throw new Error("Invalid URL provided");
  }

  // Extract file name and type from URL
  const fileName = url.substring(url.lastIndexOf("/") + 1);
  const fileType = fileName.substring(fileName.lastIndexOf(".") + 1).toLowerCase();

  // Validate file type and size
  if (!["jpg", "png", "pdf"].includes(fileType)) {
    throw new Error("Unsupported file type");
  }
  const maxFileSize = 5 * 1024 * 1024; // 5 MB
  const fileSize = parseInt(url.substring(url.lastIndexOf(";") + 1));
  if (fileSize > maxFileSize) {
    throw new Error(`File size exceeds maximum allowed: ${maxFileSize}`);
  }

  // Choose an upload library
  const uploadLib = "Bluebird";

  // Set up upload options
  const uploadOptions = {
    url,
    fileName,
    fileType,
    maxFileSize,
    retryCount: 3,
    rateLimit: 1000, // 1 second
    progressThreshold: 60 * 1000, // 1 minute
    emailNotify: true,
  };

  // Upload file using chosen library
  const uploadResult = await uploadLib.upload(uploadOptions);

  // Log detailed upload status updates to specified log service
  console.log(`Uploaded ${fileName} (${fileType}) with size ${fileSize} bytes`);
  console.log(`Upload result: ${JSON.stringify(uploadResult)}`);

  // Return URL of uploaded file
  return url;
}
