const { spawn } = require('child_process');

function executeShellCommand(command, args) {
  return new Promise((resolve, reject) => {
    const child = spawn(command, args);
    let output = '';
    child.stdout.on('data', (data) => {
      output += data;
    });
    child.stderr.on('data', (data) => {
      console.error(`stderr: ${data}`);
    });
    child.on('close', (code) => {
      if (code !== 0) {
        reject(new Error(`Command exited with code ${code}`));
      } else {
        resolve(output);
      }
    });
  });
}

function executeShellCommandsConcurrently(commands, args) {
  return Promise.all(commands.map((command) => {
    return executeShellCommand(command, args).then((output) => {
      return output;
    }).catch((error) => {
      console.error(`Error executing command: ${error}`);
      return null;
    });
  }));
}

function getMD5Hashes(strings) {
  const commands = strings.map((string) => `md5sum <<< "${string}"`);
  const args = ['-r'];
  return executeShellCommandsConcurrently(commands, args).then((outputs) => {
    return outputs.map((output) => output.split(' ')[0]);
  });
}
