using System;
using System.Security.Cryptography;
using System.Text;

public static byte[] Decrypt(byte[] ciphertext, string encryptionKey, string initializationVector, int padding) {
    // Initialize AES-CBC decryption algorithm with the provided key and IV
    using (Aes aes = new AesCbcDecryptor(encryptionKey, initializationVector)) {
        // Set padding to the specified value
        aes.Padding = padding;

        // Create a buffer for storing the decrypted data
        byte[] plaintextBuffer = new byte[ciphertext.Length];

        // Decrypt the ciphertext in chunks, using a new IV for each part of the message
        int bytesRead = 0;
        while (bytesRead < ciphertext.Length) {
            // Read the next chunk of the ciphertext
            int chunkSize = Math.Min(ciphertext.Length - bytesRead, aes.BlockSize);
            byte[] chunk = new byte[chunkSize];
            Array.Copy(ciphertext, bytesRead, chunk, 0, chunkSize);

            // Decrypt the chunk and append it to the plaintext buffer
            byte[] decryptedChunk = aes.Decrypt(chunk);
            Array.Copy(decryptedChunk, 0, plaintextBuffer, bytesRead, decryptedChunk.Length);

            // Update the number of bytes read
            bytesRead += chunkSize;
        }

        // Verify the integrity of the decrypted data using HMAC-SHA256
        byte[] hmac = new byte[32];
        using (HMACSHA256 hmacSha256 = new HMACSHA256(encryptionKey)) {
            hmacSha256.ComputeHash(plaintextBuffer, 0, plaintextBuffer.Length, hmac);
        }

        // Check if the HMAC matches the expected value
        if (!hmac.SequenceEqual(plaintextBuffer[plaintextBuffer.Length - 32..])) {
            throw new Exception("Decryption failed: HMAC verification failed");
        }

        // Return the decrypted plaintext as a byte array
        return plaintextBuffer;
    }
}
