fn manage_logging_config(path: &str) -> Result<(), String> {
    // Check if the logging configuration file exists and is accessible
    if !Path::new(path).exists() || !Path::new(path).is_file() {
        return Err("Logging configuration file does not exist or is not a file".to_string());
    }

    // Parse the configuration file to ensure it contains valid settings
    let config = Config::from_file(path)?;

    // Update the configuration settings based on user input or environmental variables
    if let Some(level) = env::var("LOGGING_LEVEL") {
        config.set_level(level);
    }

    // Handle any errors gracefully, providing informative messages without crashing the application
    match Config::from_file(path) {
        Ok(config) => Ok(()),
        Err(e) => Err(format!("Error parsing logging configuration file: {}", e)),
    }
}
