import json
from typing import Dict, List, Optional, TypeVar, Union

T = TypeVar('T')

class JSONSerializable:
    """
    A flexible JSON serialization and deserialization framework.
    """

    _registry: Dict[str, Callable[[], T]] = {}

    def to_json(self) -> str:
        """
        Custom serialization logic through a method that can be overridden by subclasses.
        """
        raise NotImplementedError()

    @classmethod
    def from_json(cls, json_str: str) -> T:
        """
        Custom deserialization logic through a method that can be overridden by subclasses.
        """
        raise NotImplementedError()

    @classmethod
    def register_factory(cls, id: str, factory: Callable[[], T]) -> None:
        """
        Add a new factory function to the registry.
        """
        cls._registry[id] = factory

    @classmethod
    def create_instance(cls, id: str) -> T:
        """
        Instantiate a subclass using the factory function associated with a given ID.
        """
        return cls._registry[id]()

    @classmethod
    def serialize(cls, obj: Union[T, List[T], Dict[str, T]]) -> str:
        """
        Serialization of collections of objects, including handling nested JSON structures.
        """
        if isinstance(obj, list):
            return json.dumps([cls.serialize(item) for item in obj])
        elif isinstance(obj, dict):
            return json.dumps({key: cls.serialize(value) for key, value in obj.items()})
        else:
            return json.dumps(obj.to_json())

    @classmethod
    def deserialize(cls, json_str: str) -> Union[T, List[T], Dict[str, T]]:
        """
        Deserialization of JSON objects containing lists, dictionaries, and primitive types (strings, numbers, booleans).
        """
        data = json.loads(json_str)
        if isinstance(data, list):
            return [cls.deserialize(item) for item in data]
        elif isinstance(data, dict):
            return {key: cls.deserialize(value) for key, value in data.items()}
        else:
            return cls.from_json(data)
```
