// Define a record structure to store offset, key, and value
typedef struct {
    long offset;
    int key;
    double value;
} Record;

// Define a hash table data structure to store records
typedef struct {
    size_t capacity; // number of buckets in the hash table
    size_t size; // number of records stored in the hash table
    Record **buckets; // array of pointers to records
} HashTable;

// Initialize a new hash table with a given capacity
HashTable *hash_table_init(size_t capacity) {
    HashTable *ht = malloc(sizeof(HashTable));
    ht->capacity = capacity;
    ht->size = 0;
    ht->buckets = calloc(capacity, sizeof(Record*));
    return ht;
}

// Insert a new record into the hash table
void hash_table_insert(HashTable *ht, Record *record) {
    // Calculate the hash value for the record's key
    size_t index = record->key % ht->capacity;

    // Check if there is already a record with the same key in the bucket
    if (ht->buckets[index] != NULL && ht->buckets[index]->key == record->key) {
        // If so, replace it with the new record
        ht->buckets[index] = record;
    } else {
        // Otherwise, add the new record to the bucket
        ht->buckets[index] = record;
        ht->size++;
    }
}

// Look up a record in the hash table by key
Record *hash_table_lookup(HashTable *ht, int key) {
    // Calculate the hash value for the given key
    size_t index = key % ht->capacity;

    // Check if there is a record with the same key in the bucket
    if (ht->buckets[index] != NULL && ht->buckets[index]->key == key) {
        return ht->buckets[index];
    } else {
        // If not, return NULL
        return NULL;
    }
}

// Remove a record from the hash table by key
void hash_table_remove(HashTable *ht, int key) {
    // Calculate the hash value for the given key
    size_t index = key % ht->capacity;

    // Check if there is a record with the same key in the bucket
    if (ht->buckets[index] != NULL && ht->buckets[index]->key == key) {
        // If so, remove it from the bucket
        ht->buckets[index] = NULL;
        ht->size--;
    }
}

// Free the memory allocated for the hash table
void hash_table_free(HashTable *ht) {
    free(ht->buckets);
    free(ht);
}
```
