    void (*iv_generation_function)(void);
    bool supported;
} cryptographic_function_t;

// Define a list of available cryptographic functions or ciphers
static cryptographic_function_t *cryptographic_functions = NULL;

// Define a mutex to ensure thread safety when accessing the list of cryptographic functions
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Load a cryptographic module dynamically and return a list of pointers to structures containing detailed information about each hash function or cipher
cryptographic_function_t *load_cryptographic_module(const char *module_name) {
    // Open the dynamic library using dlopen()
    void *handle = dlopen(module_name, RTLD_LAZY);
    if (!handle) {
        fprintf(stderr, "Failed to open dynamic library: %s\n", dlerror());
        return NULL;
    }

    // Get the list of available cryptographic functions or ciphers using dlsym()
    void *sym = dlsym(handle, "get_cryptographic_functions");
    if (!sym) {
        fprintf(stderr, "Failed to get symbol: %s\n", dlerror());
        return NULL;
    }

    // Cast the symbol to a function pointer and call it to retrieve the list of cryptographic functions or ciphers
    cryptographic_function_t *(*get_cryptographic_functions)() = sym;
    cryptographic_functions = get_cryptographic_functions();

    // Check for availability of each hash function or cipher at runtime and return only those that are supported on the current system
    int i;
    for (i = 0; i < num_cryptographic_functions; i++) {
        if (!cryptographic_functions[i].supported) {
            cryptographic_functions[i] = NULL;
        }
    }

    // Handle memory allocation and deallocation carefully to prevent leaks or corruption
    void *memory = malloc(sizeof(cryptographic_function_t) * num_cryptographic_functions);
    if (!memory) {
        fprintf(stderr, "Failed to allocate memory\n");
        return NULL;
    }
    memcpy(memory, cryptographic_functions, sizeof(cryptographic_function_t) * num_cryptographic_functions);
    free(cryptographic_functions);
    cryptographic_functions = memory;

    // Ensure thread safety when multiple threads access the list concurrently
    pthread_mutex_lock(&mutex);
    return cryptographic_functions;
}

// Unload a cryptographic module dynamically and free its resources
void unload_cryptographic_module(const char *module_name) {
    // Open the dynamic library using dlopen()
    void *handle = dlopen(module_name, RTLD_LAZY);
    if (!handle) {
        fprintf(stderr, "Failed to open dynamic library: %s\n", dlerror());
        return;
    }

