    }
    memcpy(memory, cryptographic_functions, sizeof(cryptographic_function_t) * num_cryptographic_functions);
    free(cryptographic_functions);
    cryptographic_functions = memory;

    // Ensure thread safety when multiple threads access the list concurrently
    pthread_mutex_lock(&mutex);
    return cryptographic_functions;
}

