#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/aes.h>
#include <openssl/evp.h>
#include <openssl/err.h>

// Custom memory allocator for large-scale data
void* custom_malloc(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        printf("Error: Out of memory\n");
        exit(1);
    }
    return ptr;
}

// Custom memory deallocator for large-scale data
void custom_free(void* ptr) {
    free(ptr);
}

// Function to initialize AES-256-CBC cipher securely using PBKDF2 with HMAC-SHA256
EVP_CIPHER_CTX* init_cipher(const char* password, size_t password_len) {
    // Derive encryption key and initialization vector (IV) using PBKDF2 with HMAC-SHA256
    unsigned char key[32];
    unsigned char iv[16];
    PBKDF2(password, password_len, salt, 10000, key, sizeof(key), EVP_sha256());
    PBKDF2(password, password_len, salt, 10000, iv, sizeof(iv), EVP_sha256());

    // Allocate memory for the cipher context and key/IV
    EVP_CIPHER_CTX* ctx = custom_malloc(sizeof(EVP_CIPHER_CTX));
    unsigned char* key_ptr = custom_malloc(sizeof(key));
    unsigned char* iv_ptr = custom_malloc(sizeof(iv));

    // Initialize the cipher context with the derived key and IV
    EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key_ptr, iv_ptr);

    // Clean up memory allocated for the key and IV
    custom_free(key_ptr);
    custom_free(iv_ptr);

    return ctx;
}

// Function to handle cleanup of the cipher context
void cleanup_cipher(EVP_CIPHER_CTX* ctx) {
    // Disable the cipher and free all associated resources
    EVP_EncryptFinal_ex(ctx, NULL, 0);
    EVP_CIPHER_CTX_free(ctx);
}

// Function to encrypt data using AES-256-CBC cipher securely
int encrypt(const char* password, size_t password_len, const unsigned char* plaintext, size_t plaintext_len, unsigned char* ciphertext) {
    // Initialize the cipher context with the derived key and IV
    EVP_CIPHER_CTX* ctx = init_cipher(password, password_len);

    // Encrypt the plaintext using the cipher context
    int len = 0;
    if (!EVP_EncryptUpdate(ctx, ciphertext, &len, plaintext, plaintext_len)) {
        printf("Error: %s\n", ERR_error_string(ERR_get_error(), NULL));
        cleanup_cipher(ctx);
        return -1;
    }

    // Clean up the cipher context and return the encrypted data
    cleanup_cipher(ctx);
    return len;
}

// Function to decrypt data using AES-256-CBC cipher securely
int decrypt(const char* password, size_t password_len, const unsigned char* ciphertext, size_t ciphertext_len, unsigned char* plaintext) {
    // Initialize the cipher context with the derived key and IV
    EVP_CIPHER_CTX* ctx = init_cipher(password, password_len);

    // Decrypt the ciphertext using the cipher context
    int len = 0;
    if (!EVP_DecryptUpdate(ctx, plaintext, &len, ciphertext, ciphertext_len)) {
        printf("Error: %s\n", ERR_error_string(ERR_get_error(), NULL));
        cleanup_cipher(ctx);
        return -1;
    }

    // Clean up the cipher context and return the decrypted data
    cleanup_cipher(ctx);
    return len;
}

// Function to handle asynchronous cleanup requests from different threads without causing data corruption or memory leaks
void async_cleanup(EVP_CIPHER_CTX* ctx) {
    // Disable the cipher and free all associated resources asynchronously
    EVP_EncryptFinal_ex(ctx, NULL, 0);
    EVP_CIPHER_CTX_free(ctx);
}
```
