using Newtonsoft.Json;

public class DecryptAndVerifyMessage
{
    private static readonly Dictionary<string, string> _tokenFields = new Dictionary<string, string>()
    {
        { "access_token", null },
        { "expires_in", null },
        { "token_type", null },
        { "refresh_token", null }
    };

    public static byte[] DecryptAndVerifyMessage(string message, string accessToken)
    {
        // Parse the JSON string containing the OAuth2 access token response
        var tokenResponse = JsonConvert.DeserializeObject<OAuth2AccessTokenResponse>(message);

        // Verify that all required fields are present and valid
        if (tokenResponse == null || !_tokenFields.Keys.All(f => _tokenFields[f] != null))
        {
            throw new Exception("Invalid OAuth2 access token response");
        }

        // Verify that the token type is 'Bearer' and expires in a positive integer
        if (tokenResponse.TokenType != "Bearer" || tokenResponse.ExpiresIn <= 0)
        {
            throw new Exception("Invalid OAuth2 access token response");
        }

        // Initialize a new AES instance with the IV for each message part
        var iv = Encoding.UTF8.GetBytes(accessToken);
        using (var aes = new AesCbc(iv))
        {
            // Decrypt the message parts and verify their integrity
            foreach (var part in tokenResponse.MessageParts)
            {
                var plaintext = aes.Decrypt(part, out bool success);
                if (!success)
                {
                    throw new Exception("Decryption failed");
                }

                // Log each decryption attempt's success or failure status along with the message ID
                Console.WriteLine($"Decrypted message part {tokenResponse.MessageId}: {Encoding.UTF8.GetString(plaintext)}");
            }
        }

        return tokenResponse.MessageParts;
    }
}

public class OAuth2AccessTokenResponse
{
    public string AccessToken { get; set; }
    public int ExpiresIn { get; set; }
    public string TokenType { get; set; }
    public string RefreshToken { get; set; }
    public List<byte[]> MessageParts { get; set; }
    public string MessageId { get; set; }
}
