char* modify_filename(const char* filename) {
    // Allocate memory for the new filename
    char* new_filename = malloc(51);
    if (new_filename == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for new filename\n");
        return NULL;
    }

    // Copy the original filename to the new filename
    strcpy(new_filename, filename);

    // Extract the file type from the original filename
    char* file_type = strrchr(filename, '.');
    if (file_type == NULL) {
        // If there is no file type, append a default type of ".bin"
        strcat(new_filename, ".bin");
    } else {
        // If the file type is recognized, modify it according to the specifications
        switch (strlen(file_type)) {
            case 3:
                if (strcmp(file_type, ".txt") == 0) {
                    strcat(new_filename, "_001.txt");
                } else if (strcmp(file_type, ".jpg") == 0) {
                    strcat(new_filename, "_001.jpg");
                } else if (strcmp(file_type, ".png") == 0) {
                    strcat(new_filename, "_001.png");
                } else {
                    // If the file type is not recognized, append a new type based on the length of the filename
                    char* new_type = malloc(strlen(file_type) + 4);
                    if (new_type == NULL) {
                        fprintf(stderr, "Error: Failed to allocate memory for new file type\n");
                        return NULL;
                    }
                    sprintf(new_type, "_001.%s", file_type);
                    strcat(new_filename, new_type);
                    free(new_type);
                }
                break;
            default:
                // If the file type is longer than 3 characters, truncate it to ensure consistency
                char* truncated_file_type = malloc(4);
                if (truncated_file_type == NULL) {
                    fprintf(stderr, "Error: Failed to allocate memory for truncated file type\n");
                    return NULL;
                }
                strncpy(truncated_file_type, file_type, 3);
                strcat(new_filename, "_001.");
                strcat(new_filename, truncated_file_type);
                free(truncated_file_type);
        }
    }

    // Ensure that the new filename adheres to the constraint of being exactly 50 characters long
    if (strlen(new_filename) > 49) {
        char* truncated_filename = malloc(50);
        if (truncated_filename == NULL) {
            fprintf(stderr, "Error: Failed to allocate memory for truncated filename\n");
            return NULL;
        }
        strncpy(truncated_filename, new_filename, 49);
        free(new_filename);
        new_filename = truncated_filename;
    }

    // Return the dynamically allocated string containing the new filename
    return new_filename;
}
