#include <stdlib.h>
#include <string.h>
#include <stdio.h>

// Structure to represent a state in the FSA
typedef struct State {
    int id;
    char *label;
    struct State *next;
} State;

// Function to manage dynamic allocation and manipulation of state lists in an FSA
void manageStates(int *states, int numStates, FSA *fsa, int lastState) {
    // Allocate a new state list dynamically
    State **newList = malloc(sizeof(State *) * (numStates + 1));
    if (!newList) {
        printf("Error: Failed to allocate memory for the new state list\n");
        return;
    }

    // Populate the new state list based on FSA transitions
    for (int i = 0; i < numStates; i++) {
        State *state = malloc(sizeof(State));
        if (!state) {
            printf("Error: Failed to allocate memory for a new state\n");
            return;
        }
        state->id = states[i];
        state->label = strdup(fsa->states[i].label);
        state->next = NULL;
        newList[i] = state;
    }

    // Handle errors for invalid pointers and out-of-bounds access
    if (lastState < 0 || lastState >= numStates) {
        printf("Error: Invalid last state index\n");
        return;
    }

    // Optimize memory usage by reusing existing state objects where applicable
    State *current = newList[lastState];
    while (current->next != NULL) {
        if (current->id == current->next->id) {
            // Reuse the existing state object
            current->label = strdup(current->next->label);
            current->next = current->next->next;
        } else {
            // Create a new state object
            State *newState = malloc(sizeof(State));
            if (!newState) {
                printf("Error: Failed to allocate memory for a new state\n");
                return;
            }
            newState->id = current->next->id;
            newState->label = strdup(current->next->label);
            newState->next = NULL;
            current->next = newState;
        }
    }

    // Ensure that the 'next' pointer of the last state in the current state list points to the newly created state list
    if (lastState < numStates - 1) {
        newList[numStates - 1]->next = newList;
    } else {
        fsa->states = newList;
    }
}
