using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;

namespace RandomValueGenerator
{
    public class RandomValueGenerator
    {
        private readonly int _minValue;
        private readonly int _maxValue;
        private readonly bool _inclusive;
        private readonly bool _exclusive;
        private readonly Random _random;

        public RandomValueGenerator(int minValue, int maxValue, bool inclusive = true, bool exclusive = false)
        {
            if (minValue > maxValue)
                throw new ArgumentException("Minimum value must be less than or equal to maximum value.");

            _minValue = minValue;
            _maxValue = maxValue;
            _inclusive = inclusive;
            _exclusive = exclusive;
            _random = new Random();
        }

        public int GenerateRandomInteger()
        {
            return GenerateRandomInteger(null);
        }

        public int GenerateRandomInteger(int? seed)
