                _random = new Random(seed.Value);

            var range = _maxValue - _minValue + 1;
            return _inclusive ? _random.Next(_minValue, _maxValue + 1) : _random.Next(_minValue, _maxValue);
        }

        public float GenerateRandomFloat()
        {
            return GenerateRandomFloat(null);
        }

        public float GenerateRandomFloat(int? seed)
        {
            if (seed.HasValue)
                _random = new Random(seed.Value);

            var range = _maxValue - _minValue + 1;
            return _inclusive ? _random.Next(_minValue, _maxValue + 1) : _random.Next(_minValue, _maxValue);
        }

        public override string ToString()
        {
            return $"RandomValueGenerator: Range = [{_minValue}, {_maxValue}], Seed = {_random.Seed}";
        }
    }
}
