        new_filename = malloc(strlen(filename) + 5);
        sprintf(new_filename, "%s.bin", filename);
    } else {
        // Determine the file type based on the extracted characters
        if (strcmp(file_type, ".txt") == 0 || strcmp(file_type, ".jpg") == 0 || strcmp(file_type, ".png") == 0) {
            new_filename = malloc(strlen(filename) + 5);
            sprintf(new_filename, "%s", filename);
        } else {
            // If the extracted file type is not recognized, determine a new type based on the length of the filename
            if (strlen(filename) > 40) {
                // Truncate the filename to maintain a logical naming convention and avoid name collisions
                new_filename = malloc(40 + 5);
                sprintf(new_filename, "%s", filename);
            } else {
                // Append a sequence of numbers starting from 1 followed by the recognized or newly determined file type
                new_filename = malloc(strlen(filename) + 6);
                sprintf(new_filename, "%s_001%s", filename, file_type);
