// Define the key derivation function using PBKDF2 and SHA-256
int derive_key(const unsigned char* password, size_t password_length, unsigned char* derived_key) {
    // Check if the password is long enough for key derivation
    if (password_length < MINIMUM_PASSWORD_LENGTH) {
        log("Password too short");
        return ERROR_PASSWORD_TOO_SHORT;
    }

    // Initialize the PBKDF2 algorithm with SHA-256 as the hash function
    EVP_PKEY_CTX* pctx = EVP_PKEY_CTX_new_id(EVP_PKEY_HMAC, NULL);
