    EVP_PKEY_CTX_set1_hkdf_key(pctx, password, password_length);
    EVP_PKEY_CTX_set1_hkdf_salt(pctx, NULL, 0);

    // Derive the key using PBKDF2 with SHA-256
    int ret = EVP_PKEY_derive(pctx, derived_key, KEY_SIZE);
    if (ret <= 0) {
        log("Failed to derive key");
        return ERROR_KEY_DERIVATION_FAILED;
    }

    // Clean up the PBKDF2 context
    EVP_PKEY_CTX_free(pctx);

    return 0;
