#include <arpa/inet.h>
#include <unistd.h>
#include <errno.h>

int connect_with_retry(const char* host, int port, int timeout) {
    struct sockaddr_in server_address;
    int socket_descriptor = -1;
    int retry_count = 0;

    while (retry_count < 3) {
        // Create a new socket
        socket_descriptor = socket(AF_INET, SOCK_STREAM, 0);
        if (socket_descriptor == -1) {
            perror("socket");
            return -1;
        }

        // Set the timeout for the socket
        struct timeval tv;
        tv.tv_sec = timeout;
        tv.tv_usec = 0;
        if (setsockopt(socket_descriptor, SOL_SOCKET, SO_RCVTIMEO, &tv, sizeof(tv)) == -1) {
            perror("setsockopt");
            close(socket_descriptor);
            return -1;
        }

        // Connect to the server
        memset(&server_address, 0, sizeof(server_address));
        server_address.sin_family = AF_INET;
        server_address.sin_port = htons(port);
        if (inet_pton(AF_INET, host, &server_address.sin_addr) <= 0) {
            perror("inet_pton");
            close(socket_descriptor);
            return -1;
        }
        if (connect(socket_descriptor, (struct sockaddr*)&server_address, sizeof(server_address)) < 0) {
            perror("connect");
            close(socket_descriptor);
            retry_count++;
            continue;
        } else {
            break;
        }
    }

    if (retry_count == 3) {
        fprintf(stderr, "Failed to connect to server after %d retries\n", retry_count);
        close(socket_descriptor);
        return -1;
    }

    return socket_descriptor;
}
```
This function takes a string parameter `host` and an integer parameter `port`, and an integer parameter `timeout`. It creates a new socket using the `socket()` system call, sets the timeout for the socket using the `setsockopt()` system call, and attempts to connect to the server using the `connect()` system call. If the connection fails due to a timeout, the function retries up to three times before returning an error status. The function also handles resource management carefully to avoid leaks.']

