        char truncated_filename[50];
        memcpy(truncated_filename, filename, 40);
        truncated_filename[40] = '\0';
        filename = truncated_filename;
    }
    // Extract the file extension from the filename.
    char *extension = strrchr(filename, '.');
    if (extension == NULL) {
        // No extension found, append a default type of ".bin".
        extension = ".bin";
    } else {
        // Remove the dot character from the extension.
        extension++;
    }
    size_t extension_len = strlen(extension);
    if (extension_len > 3) {
        // The extension is too long, truncate it to ensure it fits within the specified constraints.
        char truncated_extension[4];
