        truncated_extension[3] = '\0';
        extension = truncated_extension;
    }
    // Check if the file type is recognized.
    struct hash_info *hash_info = NULL;
    for (size_t i = 0; i < sizeof(hash_list) / sizeof(struct hash_info); i++) {
        if (strcmp(extension, hash_list[i].name) == 0) {
            hash_info = &hash_list[i];
            break;
