// Custom memory allocator for managing large-scale data efficiently
struct MemoryAllocator {
    void* (*malloc)(size_t size);
    void (*free)(void* ptr);
};

// Cipher context structure to manage resources
struct CipherContext {
    AES_KEY key;
    unsigned char iv[AES_BLOCK_SIZE];
    EVP_CIPHER_CTX* ctx;
};

// Function to securely initialize an AES-256-CBC cipher using a given password
struct CipherContext* init_cipher(const char* password, struct MemoryAllocator* allocator) {
    // Derive the encryption key and initialization vector (IV) using PBKDF2 with HMAC-SHA256
    unsigned char key[AES_KEY_SIZE];
    unsigned char iv[AES_BLOCK_SIZE];
    PBKDF2(password, strlen(password), key, AES_KEY_SIZE, 10000, HMAC_SHA256);

    // Allocate memory for the key and IV within the function and manage their lifetime carefully
    struct CipherContext* ctx = allocator->malloc(sizeof(struct CipherContext));
    memcpy(ctx->key.key, key, AES_KEY_SIZE);
    memcpy(ctx->iv, iv, AES_BLOCK_SIZE);

