// Define a function to create a new metrics repository
struct MetricsRepository* createMetricsRepository() {
    struct MetricsRepository* repo = malloc(sizeof(struct MetricsRepository));
    if (repo == NULL) {
        return NULL;
    }
    repo->lock = PTHREAD_MUTEX_INITIALIZER;
    repo->numEntries = 0;
    repo->entries = NULL;
    return repo;
}

// Define a function to add a new metric entry to the repository
void addMetricEntry(struct MetricsRepository* repo, char* category, char* name, double value) {
    pthread_mutex_lock(&repo->lock);
    // Check if the category and name already exist in the repository
    int i;
    for (i = 0; i < repo->numEntries; i++) {
        if (strcmp(category, repo->entries[i].category) == 0 && strcmp(name, repo->entries[i].name) == 0) {
            break;
        }
    }
    // If the category and name do not exist in the repository, add a new entry
    if (i == repo->numEntries) {
        struct MetricEntry* newEntry = malloc(sizeof(struct MetricEntry));
        newEntry->category = category;
        newEntry->name = name;
        newEntry->value = value;
        repo->entries = realloc(repo->entries, (repo->numEntries + 1) * sizeof(struct MetricEntry));
        repo->entries[repo->numEntries++] = *newEntry;
    } else {
        // If the category and name already exist in the repository, update the value
        repo->entries[i].value = value;
    }
    pthread_mutex_unlock(&repo->lock);
}

