            break;
        }
    }
    // If the metric entry is not found, return -1
    if (i == repo->numEntries) {
        pthread_mutex_unlock(&repo->lock);
        return -1.0;
    }
    double value = repo->entries[i].value;
    pthread_mutex_unlock(&repo->lock);
    return value;
}

