struct WebServerConfig {
    int maxConcurrentSessions;
};

struct SessionList {
    struct Session* head;
    struct Session* tail;
    int size;
};

struct SessionList* manageSessions(int* sessionIDs, int numSessions, struct WebServerConfig config, int maxAllowedConcurrentSessions) {
    // Create a new session list with the given number of sessions
    struct SessionList* list = malloc(sizeof(struct SessionList));
    if (!list) {
        return NULL;
    }
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;

    // Iterate through the session IDs and create a new session for each one
    for (int i = 0; i < numSessions; i++) {
        struct Session* session = malloc(sizeof(struct Session));
        if (!session) {
            freeSessionList(list);
            return NULL;
        }
        session->id = sessionIDs[i];
        session->next = NULL;

        // Add the new session to the end of the list
        if (list->tail == NULL) {
            list->head = session;
            list->tail = session;
        } else {
            list->tail->next = session;
            list->tail = session;
        }
        list->size++;
    }

    // Update the next pointer of each session to maintain efficient linking
    struct Session* current = list->head;
    while (current != NULL) {
        if (current->next == NULL) {
            break;
        }
        current->next->prev = current;
        current = current->next;
    }

    // Handle session expiration and update the next pointer of each session to maintain efficient linking
    struct Session* expiredSession = list->head;
    while (expiredSession != NULL) {
        if (expiredSession->id < config.maxConcurrentSessions) {
            break;
        }
        struct Session* nextSession = expiredSession->next;
        free(expiredSession);
        list->size--;
        expiredSession = nextSession;
    }

    // Update the next pointer of each session to maintain efficient linking
    current = list->head;
    while (current != NULL) {
        if (current->next == NULL) {
            break;
        }
        current->next->prev = current;
        current = current->next;
    }

    return list;
}

void freeSessionList(struct SessionList* list) {
    struct Session* session = list->head;
    while (session != NULL) {
        struct Session* nextSession = session->next;
        free(session);
        session = nextSession;
    }
    free(list);
}
```
