void process_directory(const char* directory) {
    DIR *dir;
    struct dirent *ent;
    if ((dir = opendir (directory)) != NULL) {
        while ((ent = readdir (dir)) != NULL) {
            const char* filename = ent->d_name;
            if (strcmp(filename, ".") == 0 || strcmp(filename, "..") == 0) continue;
            struct stat st;
            if (stat(filename, &st) == 0 && S_ISREG(st.st_mode)) {
                const char* extension = strrchr(filename, '.');
                if (extension != NULL && strcmp(extension, ".txt") == 0) {
                    // Calculate the hash of the first 1024 bytes of the file
                    unsigned char hash[SHA_DIGEST_LENGTH];
                    SHA_CTX ctx;
                    SHA1_Init(&ctx);
                    int fd = open(filename, O_RDONLY);
                    if (fd >= 0) {
                        unsigned char buffer[1024];
                        while (read(fd, buffer, sizeof(buffer)) > 0) {
                            SHA1_Update(&ctx, buffer, sizeof(buffer));
                        }
                        close(fd);
                    }
                    SHA1_Final(hash, &ctx);

                    // Construct the new file name by appending the hash to the original filename
                    char new_filename[256];
                    snprintf(new_filename, sizeof(new_filename), "%s-%08x.txt", filename, hash[0]);

                    // Rename the file to the new name
                    rename(filename, new_filename);
                }
            }
        }
        closedir (dir);
    } else {
        perror("Failed to open directory");
    }
}
