            numDigits++;
        } else {
            break;
        }
    }
    std::string newFilename = filename.substr(0, filename.length() - numDigits);
    newFilename += str2;

    // Search for the first occurrence of the first additional string argument within the forward list
    auto it = list.begin();
    while (it != list.end()) {
        if (*it == str1) {
            break;
        }
        it++;
    }

    // Insert the second additional string argument right after the first occurrence of the first additional string argument
    if (it != list.end()) {
        it = list.insert_after(it, str2);
    } else {
        list.push_back(str2);
    }
}
