// Function to initialize AES-256-CBC cipher with given password
int init_cipher(const char* password, EVP_CIPHER_CTX* ctx) {
    // Generate random initialization vector (IV)
    unsigned char iv[AES_BLOCK_SIZE];
    RAND_bytes(iv, AES_BLOCK_SIZE);

    // Derive secure encryption key from password using PBKDF2 with HMAC-SHA256
    size_t key_len = 32;
    unsigned char key[key_len];
    PBKDF2_HMAC_SHA256(password, strlen(password), NULL, 0, 10000, key, key_len);

    // Initialize AES-256-CBC cipher with derived key and IV
    EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv);

    // Clean up resources
    OPENSSL_cleanse(key, key_len);
    OPENSSL_free(iv);
}

// Function to clean up resources when the cipher is no longer needed
void cleanup_cipher(EVP_CIPHER_CTX* ctx) {
    // Clean up AES-256-CBC cipher context
    EVP_CIPHER_CTX_cleanup(ctx);
