#include <openssl/rand.h>

// Function to securely initialize an AES-256-CBC cipher with a given password
int init_cipher(const char* password, EVP_CIPHER_CTX* ctx) {
    // Generate a random initialization vector (IV)
    unsigned char iv[AES_BLOCK_SIZE];
    RAND_bytes(iv, AES_BLOCK_SIZE);

    // Derive a secure encryption key from the password using PBKDF2 with HMAC-SHA256
    unsigned char key[32];
    int key_len = 32;
    PBKDF2(password, strlen(password), iv, AES_BLOCK_SIZE, key, key_len, EVP_sha256());

    // Initialize the cipher context with the derived key and IV
    if (!EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) {
        return 0;
    }

    // Handle memory allocation and deallocation for the IV and key securely
    OPENSSL_cleanse(iv, AES_BLOCK_SIZE);
    OPENSSL_cleanse(key, key_len);

    return 1;
}

// Function to clean up resources when the cipher is no longer needed
void cleanup_cipher(EVP_CIPHER_CTX* ctx) {
    // Clean up the cipher context and free any allocated memory
    EVP_CIPHER_CTX_cleanup(ctx);
}

// Function to encrypt data using the AES-256-CBC cipher
int encrypt(const char* password, const unsigned char* plaintext, int plaintext_len, unsigned char* ciphertext) {
    // Initialize the cipher context with the given password
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!init_cipher(password, ctx)) {
        return 0;
    }

    // Encrypt the plaintext using the cipher context
    int len = 0;
    if (!EVP_EncryptUpdate(ctx, ciphertext, &len, plaintext, plaintext_len)) {
        cleanup_cipher(ctx);
        return 0;
    }

    // Clean up the cipher context and free any allocated memory
    cleanup_cipher(ctx);

    return len;
}

// Function to decrypt data using the AES-256-CBC cipher
int decrypt(const char* password, const unsigned char* ciphertext, int ciphertext_len, unsigned char* plaintext) {
    // Initialize the cipher context with the given password
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!init_cipher(password, ctx)) {
        return 0;
    }

    // Decrypt the ciphertext using the cipher context
    int len = 0;
    if (!EVP_DecryptUpdate(ctx, plaintext, &len, ciphertext, ciphertext_len)) {
        cleanup_cipher(ctx);
        return 0;
    }

    // Clean up the cipher context and free any allocated memory
    cleanup_cipher(ctx);

    return len;
}
