public class DatabaseClient {
    private TcpClient _tcpClient;
    private NetworkStream _networkStream;
    private SHA1Managed _sha1;
    private AesCbc _aesCbc;

    public DatabaseClient(string host, int port) {
        _tcpClient = new TcpClient(host, port);
        _networkStream = _tcpClient.GetStream();
        _sha1 = new SHA1Managed();
        _aesCbc = new AesCbc();
    }

    public DataTableReader ExecuteQuery(string query) {
        // Establish connection to database server
        if (!_tcpClient.Connected) {
            _tcpClient.Connect(_host, _port);
        }

        // Send query to database server and retrieve result as DataTableReader object
        byte[] queryBytes = Encoding.UTF8.GetBytes(query);
        byte[] responseBytes = new byte[1024];
        int bytesRead = 0;
        while ((bytesRead = _networkStream.Read(responseBytes, 0, responseBytes.Length)) > 0) {
            // Handle response from database server and return DataTableReader object
            string responseString = Encoding.UTF8.GetString(responseBytes, 0, bytesRead);
            DataTableReader reader = new DataTableReader(responseString);
            return reader;
        }
    }

    public void Dispose() {
        _tcpClient.Close();
        _networkStream.Dispose();
        _sha1.Dispose();
        _aesCbc.Dispose();
    }
}
