// Initialize AES-256-CBC cipher with given password
AES_KEY *init_cipher(const char *password) {
    // Set IV length to 16 bytes and key length to 32 bytes
    const int iv_len = 16;
    const int key_len = 32;

    // Derive encryption key from password using SHA-1 hash function
