using System.Threading;

// Establish connection to database server and execute query
public DataTableReader ExecuteQuery(byte[] input) {
    // Initialize connection pool and SQL command
    SqlConnectionPool pool = new SqlConnectionPool();
    SqlCommand cmd = new SqlCommand("SELECT * FROM table WHERE column = @input", pool.GetConnection());

    // Add parameter for input byte array
    cmd.Parameters.AddWithValue("@input", input);

    // Execute query and retrieve result as DataTableReader
    DataTableReader reader = cmd.ExecuteReader();

    // Handle errors and close connection
    if (reader == null) {
        Console.WriteLine("Error executing query");
        pool.CloseConnection();
        return null;
    } else {
        pool.CloseConnection();
        return reader;
    }
}
