        public void AddRange(int minValue, int maxValue)
        {
            lock (_syncRoot)
            {
                _ranges.Add(new Range(minValue, maxValue));
            }
        }

        public void RemoveRange(int minValue, int maxValue)
        {
            lock (_syncRoot)
            {
                _ranges.RemoveAll(range => range.MinValue == minValue && range.MaxValue == maxValue);
            }
        }

        public IEnumerable<Range> GetRanges()
        {
            lock (_syncRoot)
            {
                return _ranges;
            }
        }

