        {
            lock (_syncRoot)
            {
                if (minValue > maxValue)
                    throw new ArgumentException("Minimum value must be less than or equal to maximum value.");

                var range = GetRange(minValue, maxValue);
                return _random.Next(range.MinValue, range.MaxValue + 1);
            }
        }

        public float GenerateRandomFloat(float minValue, float maxValue)
        {
            lock (_syncRoot)
            {
                if (minValue > maxValue)
                    throw new ArgumentException("Minimum value must be less than or equal to maximum value.");

                var range = GetRange(minValue, maxValue);
                return _random.NextFloat(range.MinValue, range.MaxValue + 1);
            }
