            }
        }

        public void RemoveRangeConcurrent(int minValue, int maxValue)
        {
            lock (_syncRoot)
            {
                _ranges.RemoveAll(range => range.MinValue == minValue && range.MaxValue == maxValue);
            }
        }

        // Integration methods

        public void LogGeneratedRandomValue(int value, int minValue, int maxValue)
        {
            lock (_syncRoot)
            {
                var range = GetRange(minValue, maxValue);
                Console.WriteLine($"Generated random value: {value} within range [{range.MinValue}, {range.MaxValue}]");
            }
        }

        // Configuration methods

        public void SetSeed(int seed)
        {
            lock (_syncRoot)
            {
                _random = new Random(seed);
            }
        }

        // Error handling methods

        private Range GetRange(int minValue, int maxValue)
        {
            if (minValue > maxValue)
                throw new ArgumentException("Minimum value must be less than or equal to maximum value.");

            var range = _ranges.Find(range => range.MinValue == minValue && range.MaxValue == maxValue);
            if (range == null)
                throw new ArgumentException($"Range [{minValue}, {maxValue}] does not exist.");

