    if (secure_decrypt(request, password, salt, iterations, &plaintext)) {
        return ERROR_CRYPTOGRAPHIC_OPERATIONS;
    }

    // Respond with the decrypted message
    printf("%s\n", plaintext);

    // Free the memory allocated for the plaintext
    free(plaintext);

    return 0;
}
