// Define the modular C function suite for AES-256-CBC encryption with password-based key derivation
int aes_encrypt_cbc(const char *password, const unsigned char *plaintext, size_t plaintext_len, unsigned char *ciphertext) {
    // Generate a random initialization vector (IV) for the AES-256-CBC cipher
    unsigned char iv[IV_LEN];
    RAND_bytes(iv, IV_LEN);

    // Derive a 32-byte encryption key from the password using PBKDF2 with HMAC-SHA256
    unsigned char key[32];
    pbkdf2_hmac_sha256(password, NULL, 10000, key);

    // Allocate memory for the AES-256-CBC cipher context
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();

    // Initialize the AES-256-CBC cipher with the derived key and IV
    if (EVP_EncryptInit_ex(ctx, AES_CIPHER, NULL, key, iv) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    // Encrypt the plaintext using the AES-256-CBC cipher
    int len = 0;
    if (EVP_EncryptUpdate(ctx, ciphertext, &len, plaintext, plaintext_len) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    // Generate the authentication tag for the encrypted data using HMAC-SHA256
    unsigned char auth_tag[32];
    if (EVP_EncryptFinal_ex(ctx, ciphertext + len, &len) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    // Free the AES-256-CBC cipher context and return the encrypted data
    EVP_CIPHER_CTX_free(ctx);
    return len + 32;
}

// Define the modular C function suite for AES-256-CBC decryption with password-based key derivation
int aes_decrypt_cbc(const char *password, const unsigned char *ciphertext, size_t ciphertext_len, unsigned char *plaintext) {
    // Verify that the authentication tag is present in the encrypted data
    if (ciphertext_len < 32) {
