    if (EVP_DecryptUpdate(ctx, plaintext, &len, ciphertext + 32, ciphertext_len - 32) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    // Free the AES-256-CBC cipher context and return the decrypted data
    EVP_CIPHER_CTX_free(ctx);
