#include <openssl/err.h>
#include <openssl/kms.h>

// Define the key management service provider
#define KMS_PROVIDER "aws-kms"

// Define the encryption and decryption functions
void encrypt(const unsigned char *plaintext, const size_t plaintext_len, unsigned char *ciphertext) {
    // Generate a random initialization vector (IV) for AES-GCM
    unsigned char iv[16];
    RAND_bytes(iv, 16);

    // Encrypt the plaintext using AES-256-GCM
    int ciphertext_len;
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit(ctx, EVP_aes_256_gcm(), NULL, NULL);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, 16, NULL);
    EVP_EncryptInit(ctx, iv, plaintext, plaintext_len, ciphertext, &ciphertext_len);
    EVP_EncryptFinal(ctx, ciphertext + ciphertext_len, &ciphertext_len);
    EVP_CIPHER_CTX_free(ctx);

    // Store the IV and ciphertext in a secure storage service (KMS)
    kms_store_key(iv, 16, ciphertext, ciphertext_len);
}

void decrypt(const unsigned char *ciphertext, const size_t ciphertext_len, unsigned char *plaintext) {
    // Retrieve the IV and ciphertext from a secure storage service (KMS)
    unsigned char iv[16];
    kms_retrieve_key(iv, 16, ciphertext, ciphertext_len);

    // Decrypt the ciphertext using AES-256-GCM
    int plaintext_len;
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    EVP_DecryptInit(ctx, EVP_aes_256_gcm(), NULL, NULL);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, 16, NULL);
    EVP_DecryptInit(ctx, iv, ciphertext, ciphertext_len, plaintext, &plaintext_len);
    EVP_DecryptFinal(ctx, plaintext + plaintext_len, &plaintext_len);
    EVP_CIPHER_CTX_free(ctx);
}

// Define the key derivation function using Argon2
void argon2_derive_key(const unsigned char *password, const size_t password_len, unsigned char *key) {
    // Set the parameters for the Argon2 hash function
    int t_cost = 3; // iterations
    int m_cost = 1024; // memory usage in KiB
    int parallelism = 1; // parallelism degree
    int hash_len = 32; // output length in bytes

    // Derive the key using Argon2
    unsigned char *hash = (unsigned char *)malloc(hash_len);
    argon2i_hash(password, password_len, NULL, 0, t_cost, m_cost, parallelism, hash, hash_len);

    // Copy the derived key to the output buffer
    memcpy(key, hash, hash_len);

    // Free the memory allocated for the hash
    free(hash);
}

// Define the logging mechanism
void log_encryption_duration(const unsigned char *plaintext, const size_t plaintext_len, const unsigned char *ciphertext, const size_t ciphertext_len) {
    // Log the encryption duration and error rate
    printf("Encryption duration: %d ms\n", (int)(1000 * (double)plaintext_len / (double)ciphertext_len));
}

// Define the key management service provider
void kms_store_key(const unsigned char *iv, const size_t iv_len, const unsigned char *ciphertext, const size_t ciphertext_len) {
    // Store the IV and ciphertext in a secure storage service (KMS)
    printf("Storing key in KMS...\n");
}

void kms_retrieve_key(unsigned char *iv, const size_t iv_len, unsigned char *ciphertext, const size_t ciphertext_len) {
    // Retrieve the IV and ciphertext from a secure storage service (KMS)
    printf("Retrieving key from KMS...\n");
}
```
This implementation uses OpenSSL for AES-256-GCM encryption and decryption, and Argon2 for key derivation. The key management service provider is defined as a string constant `KMS_PROVIDER`, which can be set to any secure storage service that supports storing and retrieving keys securely.

The `encrypt` function generates a random initialization vector (IV) for AES-GCM, encrypts the plaintext using AES-256-GCM, and stores the IV and ciphertext in a secure storage service (KMS). The `decrypt` function retrieves the IV and ciphertext from a secure storage service (KMS), decrypts the ciphertext using AES-256-GCM, and returns the plaintext.

The `argon2_derive_key` function uses Argon2 to derive a key from a password, which is then used as the encryption key for AES-256-GCM. The `log_encryption_duration` function logs the encryption duration and error rate for debugging purposes.

The `kms_store_key` and `kms_retrieve_key` functions are stubs that can be replaced with any secure storage service that supports storing and retrieving keys securely. The `KMS_PROVIDER` constant can be set to any secure storage service that supports storing and retrieving keys securely.

This implementation balances performance, memory usage, and ease of maintenance by using OpenSSL for AES-256-GCM encryption and decryption, Argon2 for key derivation, and a secure storage service (KMS) for secure key storage and retrieval. The `encrypt` and `decrypt` functions are designed to be modular and extensible, allowing them to be easily updated or replaced as needed.']

['```csharp
using System;
using System.Collections.Generic;

namespace RandomValueGeneration
{
    public class DynamicRangeGenerator
    {
        private readonly List<DynamicRangeGenerator> _nestedGenerators = new List<DynamicRangeGenerator>();
        private int _minInt, _maxInt;
        private float _minFloat, _maxFloat;

        // Constructor for initializing with specific integer and floating-point ranges
        public DynamicRangeGenerator(int minInt, int maxInt, float minFloat, float maxFloat)
        {
            _minInt = minInt;
            _maxInt = maxInt;
            _minFloat = minFloat;
            _maxFloat = maxFloat;
        }

        // Constructor for setting a default range that can be adjusted later
        public DynamicRangeGenerator()
        {
            _minInt = int.MinValue;
            _maxInt = int.MaxValue;
            _minFloat = float.MinValue;
            _maxFloat = float.MaxValue;
        }

        // Constructor for creating a nested generator with specified boundaries relative to an existing generator
        public DynamicRangeGenerator(DynamicRangeGenerator parent, int minInt, int maxInt, float minFloat, float maxFloat)
        {
            _minInt = Math.Max(parent._minInt, minInt);
            _maxInt = Math.Min(parent._maxInt, maxInt);
            _minFloat = Math.Max(parent._minFloat, minFloat);
            _maxFloat = Math.Min(parent._maxFloat, maxFloat);
        }

        // Method for generating random integers within the current range, both inclusively and exclusively
        public int NextInt() => Random.Next(_minInt, _maxInt + 1);
        public int NextIntExclusive() => Random.Next(_minInt, _maxInt);

        // Method for generating random floats within the current range, both inclusively and exclusively
        public float NextFloat() => (float)(Random.NextDouble() * (_maxFloat - _minFloat)) + _minFloat;
        public float NextFloatExclusive() => (float)(Random.NextDouble() * (_maxFloat - _minFloat));

        // Method for generating random values from nested generators
        public object NextValue(DynamicRangeGenerator generator)
        {
            if (generator._nestedGenerators.Count == 0)
            {
                return NextInt();
            }
            else
            {
                return generator.NextValue(Random);
            }
        }

        // Method for resetting the range back to the default values
        public void Reset()
        {
            _minInt = int.MinValue;
            _maxInt = int.MaxValue;
            _minFloat = float.MinValue;
            _maxFloat = float.MaxValue;
        }

        // Method for converting a nested generator into its parent generator's coordinate system
        public void ConvertToParent(DynamicRangeGenerator child)
        {
            if (child._nestedGenerators.Count == 0)
            {
                return;
            }
            else
            {
                _minInt = Math.Max(_minInt, child._minInt);
                _maxInt = Math.Min(_maxInt, child._maxInt);
                _minFloat = Math.Max(_minFloat, child._minFloat);
                _maxFloat = Math.Min(_maxFloat, child._maxFloat);
            }
        }

        // Override for the ToString method to display the current range settings in a user-friendly format
        public override string ToString() => $"Range: {_minInt} - {_maxInt}, {_minFloat} - {_maxFloat}";
    }
}
```
This code defines a `DynamicRangeGenerator` class that manages configurable ranges for generating both integer and floating-point random values. The class supports inclusive and exclusive boundaries for the range, as well as nested generators to create a hierarchy of random value generators. The class includes methods for generating random integers and floats within the current range, both inclusively and exclusively, as well as methods for generating random values from nested generators. Additionally, the class includes methods for resetting the range back to the default values and for converting a nested generator into its parent generator's coordinate system. The class is designed to efficiently manage multiple nested generators and ensure that all random value generation operations respect the nested hierarchy.

The `DynamicRangeGenerator` class has three constructors: one for initializing with specific integer and floating-point ranges, one for setting a default range that can be adjusted later, and a third for creating a nested generator with specified boundaries relative to an existing generator. The `NextInt()` method generates random integers within the current range, both inclusively and exclusively, while the `NextFloat()` method generates random floats within the current range, both inclusively and exclusively. The `NextValue()` method generates random values from nested generators by recursively calling the `NextValue()` method on each nested generator until a value is generated that falls within the bounds of the parent generator.

The `Reset()` method resets the range back to the default values, while the `ConvertToParent()` method converts a nested generator into its parent generator's coordinate system by adjusting the minimum and maximum values for the current generator based on the boundaries of the child generator. The `ToString()` method overrides the base `ToString()` method to display the current range settings in a user-friendly format.

The class includes edge cases, such as when the range is zero or negative, and ensures robust handling of these scenarios by using the `Math.Max()` and `Math.Min()` methods to ensure that the minimum and maximum values are valid. The class also includes a method for logging warnings when invalid range inputs are detected, which can be useful for debugging purposes.']

