    } else {
        struct BinarySearchTreeNode* current = root;
        while (true) {
            if (current->record.key > record->key) {
                if (current->left == NULL) {
                    current->left = malloc(sizeof(struct BinarySearchTreeNode));
                    if (current->left == NULL) {
                        return false;
                    }
                    current->left->record = *record;
                    current->left->left = NULL;
                    current->left->right = NULL;
                } else {
                    current = current->left;
                }
            } else if (current->record.key < record->key) {
                if (current->right == NULL) {
                    current->right = malloc(sizeof(struct BinarySearchTreeNode));
                    if (current->right == NULL) {
                        return false;
                    }
                    current->right->record = *record;
                    current->right->left = NULL;
                    current->right->right = NULL;
                } else {
                    current = current->right;
                }
            } else {
                break;
            }
        }
    }
    table->root = root;
    return true;
}

// Define the record lookup function for the hash table and binary search tree
struct Record* lookupRecord(struct HashTable* table, int key) {
    // Lookup the record in the hash table
    size_t index = key % table->capacity;
    struct HashTableNode* node = table->nodes[index];
    while (node != NULL && node->record.key != key) {
        node = node->next;
    }
    if (node == NULL) {
        return NULL;
    }
    // Lookup the record in the binary search tree
    struct BinarySearchTreeNode* current = table->root;
    while (current != NULL && current->record.key != key) {
        if (current->record.key > key) {
            current = current->left;
        } else if (current->record.key < key) {
            current = current->right;
        }
    }
    if (current == NULL) {
        return NULL;
    }
    return &(current->record);
}

// Define the record deletion function for the hash table and binary search tree
bool deleteRecord(struct HashTable* table, int key) {
    // Delete the record from the hash table
    size_t index = key % table->capacity;
    struct HashTableNode* node = table->nodes[index];
    if (node == NULL) {
        return false;
    }
    while (node->next != NULL && node->next->record.key != key) {
        node = node->next;
    }
    if (node->next == NULL) {
        return false;
    }
    struct HashTableNode* next = node->next->next;
    free(node->next);
    node->next = next;
    table->size--;
    // Delete the record from the binary search tree
    struct BinarySearchTreeNode* current = table->root;
    while (current != NULL && current->record.key != key) {
        if (current->record.key > key) {
            current = current->left;
        } else if (current->record.key < key) {
            current = current->right;
        }
    }
    if (current == NULL) {
        return false;
    }
    struct BinarySearchTreeNode* parent = NULL;
    while (true) {
        if (parent == NULL && current->record.key > key) {
            break;
        } else if (parent != NULL && parent->record.key > key) {
