        } else if (current->right != NULL && current->right->record.key == key) {
            struct BinarySearchTreeNode* temp = current->right;
            current->right = temp->left;
            free(temp);
            break;
        }
        parent = current;
        if (parent->record.key > key) {
            current = parent->left;
        } else {
            current = parent->right;
        }
    }
    return true;
}

// Define the memory pool allocator functions
void* allocateMemoryPool(size_t size) {
    struct MemoryPool* pool = malloc(sizeof(struct MemoryPool));
    if (pool == NULL) {
        return NULL;
    }
    pool->data = malloc(size);
    if (pool->data == NULL) {
