    if (ret <= 0) {
        EVP_CIPHER_CTX_free(ctx);
        OPENSSL_free(derivedKey);
        return ERR_CIPHER_INITIALIZATION_FAILED;
    }

    // Set the cache entry for the derived key and IV
    CacheEntry* cacheEntry = &cache[cacheIndex];
    memcpy(cacheEntry->key, derivedKey, KEY_SIZE);
    memcpy(cacheEntry->iv, salt, IV_LENGTH);
    cacheEntry->timestamp = time(NULL);
    cacheIndex = (cacheIndex + 1) % CACHE_SIZE;

    // Free the memory allocated for the derived key and IV
    OPENSSL_free(derivedKey);

    return 0;
}

// Implement the function to deinitialize the cipher
void deinitCipher() {
    EVP_cleanup();
}

// Implement the function to encrypt data using AES-256-CBC
int encryptData(const unsigned char* plaintext, size_t plaintextLen, unsigned char** ciphertext, size_t* ciphertextLen) {
    // Check if the cache is full
    if (cacheIndex == 0 && cache[CACHE_SIZE - 1].timestamp + CACHE_ENTRY_LIFETIME < time(NULL)) {
        return ERR_RESOURCE_EXHAUSTED;
    }

    // Check if the password is long enough to generate a secure key
    if (strlen((const char*)plaintext) < KEY_SIZE) {
        return ERR_PASSWORD_TOO_SHORT;
    }

    // Derive the encryption key from the password using PBKDF2 and SHA-256
    unsigned char salt[KEY_SIZE];
    RAND_bytes(salt, KEY_SIZE);
    EVP_PBE_CIPHER *cipher = EVP_aes_256_cbc();
    int keyLen = EVP_CIPHER_key_length(cipher);
    unsigned char* derivedKey = OPENSSL_malloc(keyLen);
    if (!derivedKey) {
        return ERR_MEMORY_ALLOCATION_FAILED;
    }
    int ret = EVP_BytesToKey(cipher, EVP_sha256(), salt, (unsigned char*)plaintext, strlen((const char*)plaintext), PBKDF2_ITERATIONS, derivedKey, NULL);
    if (ret <= 0) {
        OPENSSL_free(derivedKey);
        return ERR_KEY_DERIVATION_FAILED;
    }

    // Initialize the AES-256-CBC cipher with the derived key and IV
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        OPENSSL_free(derivedKey);
        return ERR_CIPHER_INITIALIZATION_FAILED;
    }
    ret = EVP_EncryptInit_ex(ctx, cipher, NULL, derivedKey, salt);
    if (ret <= 0) {
        EVP_CIPHER_CTX_free(ctx);
        OPENSSL_free(derivedKey);
        return ERR_CIPHER_INITIALIZATION_FAILED;
    }

    // Allocate memory for the ciphertext and set its length to the plaintext length plus the IV length
    *ciphertextLen = plaintextLen + IV_LENGTH;
    *ciphertext = OPENSSL_malloc(*ciphertextLen);
    if (!*ciphertext) {
        EVP_CIPHER_CTX_free(ctx);
        OPENSSL_free(derivedKey);
        return ERR_MEMORY_ALLOCATION_FAILED;
    }

    // Encrypt the plaintext using AES-256-CBC and store the ciphertext in the allocated memory
    ret = EVP_EncryptUpdate(ctx, *ciphertext, plaintextLen, (unsigned char*)plaintext, plaintextLen);
    if (ret <= 0) {
        OPENSSL_free(*ciphertext);
        EVP_CIPHER_CTX_free(ctx);
        OPENSSL_free(derivedKey);
        return ERR_CIPHER_INITIALIZATION_FAILED;
    }

    // Free the memory allocated for the derived key and IV
    OPENSSL_free(derivedKey);

    // Set the cache entry for the derived key and IV
    CacheEntry* cacheEntry = &cache[cacheIndex];
    memcpy(cacheEntry->key, salt, KEY_SIZE);
    memcpy(cacheEntry->iv, *ciphertext, IV_LENGTH);
    cacheEntry->timestamp = time(NULL);
    cacheIndex = (cacheIndex + 1) % CACHE_SIZE;

    return 0;
}

// Implement the function to decrypt data using AES-256-CBC
int decryptData(const unsigned char* ciphertext, size_t ciphertextLen, unsigned char** plaintext, size_t* plaintextLen) {
    // Check if the cache is full
    if (cacheIndex == 0 && cache[CACHE_SIZE - 1].timestamp + CACHE_ENTRY_LIFETIME < time(NULL)) {
        return ERR_RESOURCE_EXHAUSTED;
    }

    // Check if the password is long enough to generate a secure key
    if (strlen((const char*)ciphertext) < KEY_SIZE) {
        return ERR_PASSWORD_TOO_SHORT;
    }

    // Derive the encryption key from the password using PBKDF2 and SHA-256
    unsigned char salt[KEY_SIZE];
    memcpy(salt, ciphertext, KEY_SIZE);
    EVP_PBE_CIPHER *cipher = EVP_aes_256_cbc();
    int keyLen = EVP_CIPHER_key_length(cipher);
    unsigned char* derivedKey = OPENSSL_malloc(keyLen);
    if (!derivedKey) {
        return ERR_MEMORY_ALLOCATION_FAILED;
    }
    int ret = EVP_BytesToKey(cipher, EVP_sha256(), salt, (unsigned char*)ciphertext, ciphertextLen - IV_LENGTH, PBKDF2_ITERATIONS, derivedKey, NULL);
    if (ret <= 0) {
        OPENSSL_free(derivedKey);
        return ERR_KEY_DERIVATION_FAILED;
    }

    // Initialize the AES-256-CBC cipher with the derived key and IV
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        OPENSSL_free(derivedKey);
        return ERR_CIPHER_INITIALIZATION_FAILED;
    }
    ret = EVP_DecryptInit_ex(ctx, cipher, NULL, derivedKey, salt);
    if (ret <= 0) {
        EVP_CIPHER_CTX_free(ctx);
        OPENSSL_free(derivedKey);
        return ERR_CIPHER_INITIALIZATION_FAILED;
    }

    // Allocate memory for the plaintext and set its length to the ciphertext length minus the IV length
    *plaintextLen = ciphertextLen - IV_LENGTH;
    *plaintext = OPENSSL_malloc(*plaintextLen);
    if (!*plaintext) {
        EVP_CIPHER_CTX_free(ctx);
        OPENSSL_free(derivedKey);
        return ERR_MEMORY_ALLOCATION_FAILED;
    }

    // Decrypt the ciphertext using AES-256-CBC and store the plaintext in the allocated memory
    ret = EVP_DecryptUpdate(ctx, *plaintext, *plaintextLen, (unsigned char*)ciphertext + IV_LENGTH, ciphertextLen - IV_LENGTH);
    if (ret <= 0) {
        OPENSSL_free(*plaintext);
        EVP_CIPHER_CTX_free(ctx);
        OPENSSL_free(derivedKey);
        return ERR_CIPHER_INITIALIZATION_FAILED;
    }

    // Free the memory allocated for the derived key and IV
    OPENSSL_free(derivedKey);

    // Set the cache entry for the derived key and IV
    CacheEntry* cacheEntry = &cache[cacheIndex];
    memcpy(cacheEntry->key, salt, KEY_SIZE);
    memcpy(cacheEntry->iv, ciphertext, IV_LENGTH);
    cacheEntry->timestamp = time(NULL);
    cacheIndex = (cacheIndex + 1) % CACHE_SIZE;

    return 0;
}
```
This code implements the AES-256-CBC cipher with a password-based key derivation scheme using PBKDF2 and SHA-256. The function `initCipher` initializes the cipher with a given password, while `deinitCipher` deinitializes it. The functions `encryptData` and `decryptData` encrypt and decrypt data using AES-256-CBC, respectively.

The code checks for the availability of the OpenSSL library at runtime and handles any errors that may occur during initialization or encryption/decryption. It also implements a cache to store frequently used keys and IVs to reduce the need for repeated derivations. The cache is implemented as an array of `CacheEntry` structures, where each structure contains the derived key and IV, along with a timestamp indicating when it was last accessed. The cache is managed using a circular buffer, where the oldest entries are evicted when the cache becomes full.

The code also implements a configuration option to adjust the number of PBKDF2 iterations, which can be set using the `PBKDF2_ITERATIONS` macro. This allows the user to trade off security against computational resources. The default value is 1000 iterations, but it can be changed as needed.

Overall, this code provides a secure and efficient implementation of AES-256-CBC with password-based key derivation using PBKDF2 and SHA-256.']

