#define CIPHER_MODE AES_CBC

// Function to initialize the AES-256-CBC cipher using a given password
int init_cipher(const char* password, unsigned char** key, unsigned char** iv) {
    // Generate a random initialization vector (IV)
    *iv = (unsigned char*)malloc(AES_BLOCK_SIZE);
    if (*iv == NULL) {
        printf("Error: Failed to allocate memory for IV\n");
        return 1;
    }
    RAND_bytes(*iv, AES_BLOCK_SIZE);

    // Derive a 32-byte encryption key from the password using PBKDF2 with HMAC-SHA256
    *key = (unsigned char*)malloc(KEY_SIZE);
    if (*key == NULL) {
        printf("Error: Failed to allocate memory for key\n");
        free(*iv);
        return 1;
    }
    int iterations = 1000;
    PBKDF2_HMAC_SHA256(password, strlen(password), *iv, AES_BLOCK_SIZE, *key, KEY_SIZE, iterations);

    // Initialize the AES-256-CBC cipher using the derived key and IV
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) {
        printf("Error: Failed to create new cipher context\n");
        free(*key);
        free(*iv);
        return 1;
    }
    int ret = EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, *key, *iv);
    if (ret != 1) {
        printf("Error: Failed to initialize cipher context\n");
        EVP_CIPHER_CTX_free(ctx);
        free(*key);
        free(*iv);
        return 1;
    }

    // Set the number of iterations for PBKDF2 to test implementation robustness
    ret = EVP_PBE_set(EVP_aes_256_cbc(), *key, KEY_SIZE, *iv, AES_BLOCK_SIZE, iterations);
    if (ret != 1) {
        printf("Error: Failed to set PBKDF2 parameters\n");
        EVP_CIPHER_CTX_free(ctx);
        free(*key);
        free(*iv);
        return 1;
    }

    // Return the initialized cipher context and derived key and IV
    *cipher = ctx;
    return 0;
}

// Function to handle cleanup, disabling the cipher, and freeing all associated resources
void cleanup_cipher(EVP_CIPHER_CTX* ctx) {
    // Disable the cipher and free any allocated memory
    EVP_CIPHER_CTX_free(ctx);
}
