// Define the AESCipher function suite
void AESCipher(const char* password, const unsigned char* data, size_t data_len) {
    // Initialize the cipher context
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();

    // Generate a random initialization vector (IV)
    unsigned char iv[AES_BLOCK_SIZE];
    RAND_bytes(iv, AES_BLOCK_SIZE);

    // Derive the encryption key from the password using PBKDF2 with HMAC-SHA256
    unsigned char key[32];
    int iterations = 1000;
    PBKDF2_HMAC_SHA256(password, strlen(password), NULL, 0, iterations, key, 32);

    // Set the cipher type and mode
    EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv);

    // Encrypt the data
    int outlen;
    unsigned char *out = (unsigned char *)malloc(data_len + AES_BLOCK_SIZE);
    EVP_EncryptUpdate(ctx, out, &outlen, data, data_len);

    // Securely free the key and IV memory
    OPENSSL_cleanse(key, 32);
    OPENSSL_cleanse(iv, AES_BLOCK_SIZE);

    // Disable the cipher and free all associated resources
    EVP_CIPHER_CTX_free(ctx);

    // Return the encrypted data
    return out;
}

// Define a logging function that uses snprintf and va_start/va_end to log messages to the error log if a given condition is met
void log_message(const char* format, ...) {
    va_list args;
    va_start(args, format);
    int len = vsnprintf(NULL, 0, format, args);
    va_end(args);

    if (len > 0) {
        char *buffer = (char *)malloc(len + 1);
        va_start(args, format);
        vsnprintf(buffer, len + 1, format, args);
        va_end(args);

        // Log the message to the error log
        fprintf(stderr, "%s\n", buffer);

        free(buffer);
    }
}
