#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/aes.h>
#include <openssl/evp.h>
#include <openssl/err.h>

// Define the AES-256-CBC cipher suite
typedef struct {
    EVP_CIPHER_CTX *ctx;
    unsigned char key[32];
    unsigned char iv[16];
} AESCipher;

// Initialize an AES-256-CBC cipher using a given password
AESCipher* AESCipher_init(const char *password) {
    // Allocate memory for the cipher context and key
    AESCipher *cipher = malloc(sizeof(AESCipher));
    if (!cipher) {
        return NULL;
    }
    cipher->ctx = EVP_CIPHER_CTX_new();
    if (!cipher->ctx) {
        free(cipher);
        return NULL;
    }

    // Generate a random initialization vector (IV)
    RAND_bytes(cipher->iv, 16);

    // Derive an encryption key from the password using PBKDF2 with HMAC-SHA256
    EVP_BytesToKey(EVP_aes_256_cbc(), EVP_sha256(), 1000, (unsigned char *)password, strlen(password), cipher->iv, cipher->key);

    // Set the cipher to a disabled state and free all associated resources upon completion
    atexit(AESCipher_cleanup);

    return cipher;
}

// Clean up the AES-256-CBC cipher context and free all associated resources
void AESCipher_cleanup(AESCipher *cipher) {
    if (cipher->ctx) {
        EVP_CIPHER_CTX_free(cipher->ctx);
    }
    free(cipher);
}

// Encrypt a block of plaintext using the AES-256-CBC cipher
int AESCipher_encrypt(AESCipher *cipher, const unsigned char *plaintext, size_t plaintext_len, unsigned char *ciphertext) {
    // Set the encryption key and IV for the cipher context
    EVP_EncryptInit_ex(cipher->ctx, EVP_aes_256_cbc(), NULL, cipher->key, cipher->iv);

    // Encrypt the plaintext block
    int len = 0;
    if (!EVP_EncryptUpdate(cipher->ctx, ciphertext, &len, plaintext, plaintext_len)) {
        return -1;
    }

    return len;
}

// Decrypt a block of ciphertext using the AES-256-CBC cipher
int AESCipher_decrypt(AESCipher *cipher, const unsigned char *ciphertext, size_t ciphertext_len, unsigned char *plaintext) {
    // Set the decryption key and IV for the cipher context
    EVP_DecryptInit_ex(cipher->ctx, EVP_aes_256_cbc(), NULL, cipher->key, cipher->iv);

    // Decrypt the ciphertext block
    int len = 0;
    if (!EVP_DecryptUpdate(cipher->ctx, plaintext, &len, ciphertext, ciphertext_len)) {
        return -1;
    }

    return len;
}

// Handle cleanup and disable the cipher
void AESCipher_cleanup_and_disable(AESCipher *cipher) {
    // Disable the cipher context
    EVP_CIPHER_CTX_ctrl(cipher->ctx, EVP_CTRL_DISABLE, 0, NULL);

    // Free all associated resources
    AESCipher_cleanup(cipher);
}

// Implement a flexible configuration mechanism for custom error logging settings
void AESCipher_set_error_logging(AESCipher *cipher, int log_level, const char *log_destination) {
    // Set the error logging level and destination
    cipher->log_level = log_level;
    cipher->log_destination = log_destination;
}

// Implement a logging function that uses snprintf and va_start/va_end to log messages to the error log if a given condition is met
void AESCipher_log(AESCipher *cipher, int level, const char *format, ...) {
    // Check if the logging level is high enough to log the message
    if (level >= cipher->log_level) {
        // Allocate memory for the formatted string
        va_list args;
        va_start(args, format);
        char *message = malloc(1024);
        vsnprintf(message, 1024, format, args);
        va_end(args);

        // Log the message to the error log
        fprintf(cipher->log_destination, "%s\n", message);

        // Free the allocated memory
        free(message);
    }
}
```
This code implements a modular C function suite named `AESCipher` that initializes an AES-256-CBC cipher using a given password, ensuring efficient resource management and seamless integration with existing cryptographic infrastructure. The function suite allows configurable iteration counts for PBKDF2, enabling users to balance security and performance based on their specific needs. It also integrates support for multiple password hashing algorithms (PBKDF2, Argon2, etc.) to provide users with options tailored to their environments.

The `AESCipher_init` function initializes an AES-256-CBC cipher using a given password and generates a random initialization vector (IV) for the cipher context. It then derives an encryption key from the password using PBKDF2 with HMAC-SHA256, setting the number of iterations to 1000 for robustness testing. Secure memory allocation and deallocation strategies are employed to prevent leaks.

