// Define constants for key length and IV length
#define KEY_LEN 32
#define IV_LEN 16

// Define a structure to hold the cipher context
typedef struct {
    EVP_CIPHER_CTX *ctx;
} AES_CBC_CTX;

// Function to initialize an AES-256-CBC cipher with a given password
int init_aes_cbc(const char *password, AES_CBC_CTX *ctx) {
    // Check if the OpenSSL library is available
    if (!EVP_is_implemented()) {
        fprintf(stderr, "OpenSSL library not found. Please install it and try again.\n");
        return 1;
    }

    // Initialize the cipher context
    ctx->ctx = EVP_CIPHER_CTX_new();
    if (!ctx->ctx) {
        fprintf(stderr, "Failed to initialize cipher context. Error: %s\n", ERR_error_string(ERR_get_error(), NULL));
        return 1;
    }

    // Set the encryption algorithm and mode
    if (!EVP_EncryptInit_ex(ctx->ctx, EVP_aes_256_cbc(), NULL, NULL, NULL)) {
        fprintf(stderr, "Failed to set encryption algorithm. Error: %s\n", ERR_error_string(ERR_get_error(), NULL));
        return 1;
    }

    // Generate the initialization vector (IV) and key from the password
    unsigned char iv[IV_LEN];
    unsigned char key[KEY_LEN];
    PBKDF2_HMAC_SHA256(password, strlen(password), NULL, 0, 10000, iv, IV_LEN);
    HMAC(EVP_sha256(), password, strlen(password), key, KEY_LEN);

    // Set the IV and key for encryption
    if (!EVP_CIPHER_CTX_ctrl(ctx->ctx, EVP_CTRL_SET_IVLEN, IV_LEN, NULL) ||
            !EVP_EncryptInit_ex(ctx->ctx, NULL, NULL, key, iv)) {
        fprintf(stderr, "Failed to set IV and key. Error: %s\n", ERR_error_string(ERR_get_error(), NULL));
        return 1;
    }

    // Return success
    return 0;
}

// Function to clean up the cipher context
void cleanup_aes_cbc(AES_CBC_CTX *ctx) {
    if (ctx->ctx) {
        EVP_CIPHER_CTX_free(ctx->ctx);
    }
}

// Function to encrypt data using the AES-256-CBC cipher
int encrypt_aes_cbc(const unsigned char *plaintext, size_t plaintext_len, unsigned char *ciphertext, size_t *ciphertext_len, AES_CBC_CTX *ctx) {
    // Check if the context is initialized
    if (!ctx->ctx) {
        fprintf(stderr, "Context not initialized. Please call init_aes_cbc() first.\n");
        return 1;
    }

    // Set the output buffer and length
    *ciphertext_len = plaintext_len + AES_BLOCK_SIZE;
    if (!EVP_EncryptUpdate(ctx->ctx, ciphertext, ciphertext_len, plaintext, plaintext_len)) {
        fprintf(stderr, "Failed to encrypt data. Error: %s\n", ERR_error_string(ERR_get_error(), NULL));
        return 1;
    }

    // Return success
    return 0;
}

// Function to decrypt data using the AES-256-CBC cipher
int decrypt_aes_cbc(const unsigned char *ciphertext, size_t ciphertext_len, unsigned char *plaintext, size_t *plaintext_len, AES_CBC_CTX *ctx) {
    // Check if the context is initialized
    if (!ctx->ctx) {
        fprintf(stderr, "Context not initialized. Please call init_aes_cbc() first.\n");
        return 1;
    }

    // Set the output buffer and length
    *plaintext_len = ciphertext_len - AES_BLOCK_SIZE;
    if (!EVP_DecryptUpdate(ctx->ctx, plaintext, plaintext_len, ciphertext, ciphertext_len)) {
        fprintf(stderr, "Failed to decrypt data. Error: %s\n", ERR_error_string(ERR_get_error(), NULL));
        return 1;
    }

    // Return success
    return 0;
}

// Function to generate a random initialization vector (IV)
void gen_iv(unsigned char *iv, size_t iv_len) {
    if (!RAND_bytes(iv, iv_len)) {
        fprintf(stderr, "Failed to generate IV. Error: %s\n", ERR_error_string(ERR_get_error(), NULL));
    }
}

// Function to generate a random encryption key from a password
void gen_key(const char *password, unsigned char *key, size_t key_len) {
    // Generate the initialization vector (IV) and key from the password
    PBKDF2_HMAC_SHA256(password, strlen(password), NULL, 0, 10000, key, key_len);
}

