using System;
using System.Security.Cryptography;
using System.IO;

public static class AESGCMStreamProcessor
{
    public static void Process(Stream inputStream, Stream outputStream, bool encrypt)
    {
        // Initialize the AES-GCM algorithm with a random key and IV
        using (var aes = new AesGcm(new byte[16], new byte[12]))
        {
            // Set the encryption/decryption mode based on the input parameter
            if (encrypt)
                aes.Mode = CipherMode.Encrypt;
            else
                aes.Mode = CipherMode.Decrypt;

            // Initialize the key and IV for the AES-GCM algorithm
            aes.Initialize();

            // Create a buffer to read/write data in chunks
            var buffer = new byte[1024];

            // Loop until the end of the input stream is reached
            while (true)
            {
                // Read a chunk of data from the input stream
                int bytesRead = inputStream.Read(buffer, 0, buffer.Length);

                if (bytesRead == 0)
                    break;

                // Encrypt/decrypt the data using AES-GCM
                var ciphertext = aes.ProcessBytes(buffer, 0, bytesRead);

                // Write the encrypted/decrypted data to the output stream
                outputStream.Write(ciphertext, 0, ciphertext.Length);
            }
        }
    }
}
