        files[i].path = argv[i];
        files[i].lines = 0;
        files[i].words = 0;
        if (strcmp(argv[i], OPTION_CS) == 0) {
            files[i].words = 0;
        }
    }

    // Create threads to process each file concurrently
    pthread_t *threads = malloc(sizeof(pthread_t) * argc);
    if (threads == NULL) {
        handle_error("Failed to allocate memory for thread information");
        return 1;
    }
    for (i = 0; i < argc; i++) {
        pthread_create(&threads[i], NULL, process_files, &files[i]);
    }

    // Join threads and update progress indicator
    int total_lines = 0;
    int total_words = 0;
    for (i = 0; i < argc; i++) {
        pthread_join(threads[i], NULL);
        total_lines += files[i].lines;
        if (strcmp(argv[i], OPTION_CS) == 0) {
            total_words += files[i].words;
        }
    }
    free(threads);

    // Print results and clean up
    printf("Total lines: %d\n", total_lines);
    if (strcmp(argv[1], OPTION_CS) == 0) {
        printf("Total words: %d\n", total_words);
    }
    free(files);
    return 0;
}

// Parse command-line arguments and handle errors
int parse_args(int argc, char **argv) {
    // Check for invalid options
    if (argc < 2) {
        print_usage(argv[0]);
        return 0;
    }
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], OPTION_HELP) == 0 || strcmp(argv[i], OPTION_MANPAGE) == 0 || strcmp(argv[i], OPTION_CS) == 0 || strcmp(argv[i], OPTION_O) == 0) {
            continue;
        } else if (strncmp(argv[i], "-", 1) == 0) {
            handle_error("Invalid option");
            return 0;
        }
    }

    // Check for missing options
    int required_options = 0;
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], OPTION_CS) == 0 || strcmp(argv[i], OPTION_O) == 0) {
            required_options++;
        }
    }
    if (required_options > 1) {
        handle_error("Multiple options are not allowed");
        return 0;
    } else if (required_options == 0) {
        handle_error("Missing option");
        return 0;
    }

    // Check for invalid file paths
    for (int i = 1; i < argc; i++) {
        struct stat st;
        if (stat(argv[i], &st) == -1) {
            handle_error("Failed to access file");
            return 0;
        }
    }

    // Check for invalid redirection options
    if (strcmp(argv[argc-1], OPTION_O) == 0) {
        if (stat(argv[argc-2], &st) == -1) {
            handle_error("Failed to access output file");
            return 0;
        }
    }

    // Return success
    return 1;
}

// Process each input file concurrently
void* process_files(void *arg) {
    struct file_info *file = (struct file_info *) arg;
    FILE *fp = fopen(file->path, "r");
    if (fp == NULL) {
        handle_error("Failed to open file");
        return NULL;
    }

    // Count lines and words in each line (if -cs flag is set)
    int lines = 0;
    int words = 0;
    char *line = NULL;
    size_t len = 0;
    ssize_t read;
    while ((read = getline(&line, &len, fp)) != -1) {
        lines++;
        if (strcmp(argv[1], OPTION_CS) == 0) {
            char *token = strtok(line, " ");
            while (token != NULL) {
                words++;
                token = strtok(NULL, " ");
            }
        }
    }
    file->lines = lines;
    if (strcmp(argv[1], OPTION_CS) == 0) {
        file->words = words;
    }

    // Close file and return
    fclose(fp);
    free(line);
    return NULL;
}

// Print usage information
void print_usage(char *progname) {
    printf("Usage: %s [options] <file1> [<file2> ...]\n", progname);
    printf("\n");
    printf("Options:\n");
    printf("  -h, --help\t\tPrint usage information and exit\n");
    printf("  -m, --manpage\t\tPrint man page and exit\n");
    printf("  -cs, --count-words\tCount words in each line (implies -c)\n");
    printf("  -o <file>, --output=<file>\tRedirect output to a file\n");
}

// Print man page
void print_manpage() {
    printf("NAME\n");
    printf("\t%s - Process multiple input files\n", argv[0]);
    printf("\n");
    printf("SYNOPSIS\n");
    printf("\t%s [options] <file1> [<file2> ...]\n", argv[0]);
    printf("\n");
    printf("DESCRIPTION\n");
    printf("\tThis program processes multiple input files, each potentially originating from different sources such as network shares, cloud storage, or local directories.\n");
    printf("\tThe program provides detailed usage information and supports optional command-line options to enhance functionality.\n");
    printf("\n");
    printf("OPTIONS\n");
    printf("\t%s\tPrint usage information and exit\n", OPTION_HELP);
    printf("\t%s\tPrint man page and exit\n", OPTION_MANPAGE);
    printf("\t%s\tCount words in each line (implies -c)\n", OPTION_CS);
    printf("\t%s <file>\tRedirect output to a file\n", OPTION_O);
}

// Handle errors gracefully
void handle_error(const char *msg) {
    fprintf(stderr, "%s: %s\n", argv[0], msg);
}
