using namespace std;

// Define a struct to represent a single transaction record
struct Transaction {
    string id;
    string date;
    double amount;
    string merchant;
    string category;
};

// Define a struct to represent a summarized report
struct Report {
    map<string, int> categories;
    map<string, double> amounts;
    set<string> merchants;
    chrono::time_point<chrono::system_clock> startTime;
    chrono::time_point<chrono::system_clock> endTime;
};

// Define a class to manage the processing of transaction data
class TransactionProcessor {
public:
    // Constructor that takes in the configuration file and external data sources
    TransactionProcessor(const string& configFile, const vector<string>& dataSources) : configFile_(configFile), dataSources_(dataSources) {}

    // Function to process a single transaction record
    void processTransaction(const Transaction& transaction) {
        // Check if the transaction is valid and should be processed
        if (isValidTransaction(transaction)) {
            // Apply any necessary transformations to the transaction data
            transformTransaction(transaction);

            // Add the transformed transaction to the report
            addToReport(transaction);
        }
    }

    // Function to generate a summarized report based on the processed transactions
    Report generateReport() {
        // Initialize the report with the start time and end time
        Report report;
        report.startTime = chrono::system_clock::now();
        report.endTime = chrono::system_clock::now();

        // Iterate over the processed transactions and add them to the report
        for (const auto& transaction : transactions_) {
            addToReport(transaction, report);
        }

        return report;
    }

private:
    // Configuration file containing the aggregation criteria
    string configFile_;

    // Vector of external data sources to fetch and integrate into the processing pipeline
    vector<string> dataSources_;

    // Map of processed transactions, keyed by transaction ID
    map<string, Transaction> transactions_;

    // Mutex for protecting the transactions_ map during parallel processing
    mutex transactionsMutex_;

    // Condition variable to signal when a new transaction is available for processing
    condition_variable newTransactionAvailable_;

    // Function to check if a transaction should be processed based on the user-defined criteria
    bool isValidTransaction(const Transaction& transaction) {
        // Load the configuration file and extract the aggregation criteria
        auto config = loadConfigFile();
        auto categories = config["categories"];
        auto amounts = config["amounts"];
        auto merchants = config["merchants"];

        // Check if the transaction matches any of the user-defined criteria
        return (categories.find(transaction.category) != categories.end()) &&
               (amounts.find(transaction.amount) != amounts.end()) &&
               (merchants.find(transaction.merchant) != merchants.end());
    }

    // Function to apply any necessary transformations to the transaction data
    void transformTransaction(const Transaction& transaction) {
        // Load the configuration file and extract the transformation rules
        auto config = loadConfigFile();
        auto rules = config["rules"];

        // Apply each transformation rule to the transaction data
        for (const auto& rule : rules) {
            applyRule(rule, transaction);
        }
    }

    // Function to add a transformed transaction to the report
    void addToReport(const Transaction& transaction, Report& report) {
        // Increment the category and amount totals in the report
        report.categories[transaction.category]++;
        report.amounts[transaction.amount] += transaction.amount;

        // Add the merchant to the set of merchants in the report
        report.merchants.insert(transaction.merchant);
    }

    // Function to load the configuration file and extract the aggregation criteria
    map<string, vector<string>> loadConfigFile() {
        // Load the configuration file into a string stream
        ifstream configStream(configFile_);
        stringstream configBuffer;
        configBuffer << configStream.rdbuf();

        // Parse the configuration file and extract the aggregation criteria
        map<string, vector<string>> config;
        for (const auto& line : configBuffer) {
            if (line.find("categories") != string::npos) {
                config["categories"] = parseCategories(line);
            } else if (line.find("amounts") != string::npos) {
                config["amounts"] = parseAmounts(line);
            } else if (line.find("merchants") != string::npos) {
                config["merchants"] = parseMerchants(line);
            } else if (line.find("rules") != string::npos) {
                config["rules"] = parseRules(line);
            }
        }

        return config;
    }

    // Function to parse the categories from the configuration file
    vector<string> parseCategories(const string& line) {
        // Split the line on commas and trim whitespace from each category
        auto categories = split(line, ",");
        for (auto& category : categories) {
            trim(category);
        }

        return categories;
    }

    // Function to parse the amounts from the configuration file
    vector<double> parseAmounts(const string& line) {
        // Split the line on commas and convert each amount to a double
        auto amounts = split(line, ",");
        for (auto& amount : amounts) {
            amount = stod(amount);
        }

        return amounts;
    }

    // Function to parse the merchants from the configuration file
    vector<string> parseMerchants(const string& line) {
        // Split the line on commas and trim whitespace from each merchant
        auto merchants = split(line, ",");
        for (auto& merchant : merchants) {
            trim(merchant);
        }

        return merchants;
    }

    // Function to parse the rules from the configuration file
    vector<string> parseRules(const string& line) {
        // Split the line on commas and trim whitespace from each rule
        auto rules = split(line, ",");
        for (auto& rule : rules) {
            trim(rule);
        }

        return rules;
    }

    // Function to apply a transformation rule to a transaction
    void applyRule(const string& rule, Transaction& transaction) {
        // Check if the rule is a category mapping
        if (rule.find(":") != string::npos) {
            auto mapping = split(rule, ":");
            transaction.category = mapping[1];
        } else if (rule.find("=") != string::npos) {
            // Check if the rule is an amount mapping
            auto mapping = split(rule, "=");
            transaction.amount = stod(mapping[1]);
        } else if (rule.find("+") != string::npos) {
            // Check if the rule is a merchant addition
            auto addition = split(rule, "+");
            transaction.merchant += addition[1];
        }
    }

    // Function to split a string on a delimiter and trim whitespace from each part
    vector<string> split(const string& str, const string& delim) {
        auto parts = split(str, delim);
        for (auto& part : parts) {
            trim(part);
        }

        return parts;
    }

    // Function to trim whitespace from a string
    void trim(string& str) {
        str.erase(remove_if(str.begin(), str.end(), isspace), str.end());
    }
};
