using System;
using System.Collections.Generic;
using System.Threading;

namespace DynamicValueGenerator
{
    public class DynamicValueGenerator
    {
        private readonly object _lock = new object();
        private readonly Dictionary<int, Range> _ranges = new Dictionary<int, Range>();
        private int _seed;

        public DynamicValueGenerator()
        {
            _seed = Environment.TickCount;
        }

        public void AddRange(int minValue, int maxValue)
        {
            lock (_lock)
            {
                if (minValue > maxValue)
                    throw new ArgumentException("Min value must be less than or equal to max value.");

                _ranges.Add(minValue, new Range(minValue, maxValue));
            }
        }

        public void RemoveRange(int minValue)
        {
            lock (_lock)
            {
                if (!_ranges.ContainsKey(minValue))
                    throw new ArgumentException("Min value not found.");

                _ranges.Remove(minValue);
            }
        }

        public int GetRandomInteger(int minValue, int maxValue)
        {
            lock (_lock)
            {
                if (minValue > maxValue)
                    throw new ArgumentException("Min value must be less than or equal to max value.");

                var range = _ranges.GetValueOrDefault(minValue);
                if (range == null)
                    return minValue;

                var random = new Random(_seed++);
                return random.Next(range.MinValue, range.MaxValue + 1);
            }
        }

        public float GetRandomFloat(float minValue, float maxValue)
        {
            lock (_lock)
            {
                if (minValue > maxValue)
                    throw new ArgumentException("Min value must be less than or equal to max value.");

                var range = _ranges.GetValueOrDefault(minValue);
                if (range == null)
                    return minValue;

                var random = new Random(_seed++);
                return (float)(random.NextDouble() * (maxValue - minValue)) + minValue;
            }
        }

        public void ExportRanges(string filePath)
        {
            lock (_lock)
            {
                using var writer = new StreamWriter(filePath);
                foreach (var range in _ranges.Values)
                {
                    writer.WriteLine($"{range.MinValue} {range.MaxValue}");
                }
            }
        }

        public void LoadConfiguration(string filePath)
        {
            lock (_lock)
            {
                using var reader = new StreamReader(filePath);
                while (!reader.EndOfStream)
                {
                    var line = reader.ReadLine();
                    if (line == null)
                        continue;

                    var values = line.Split(' ');
                    if (values.Length != 2)
                        throw new FormatException("Invalid range format.");

                    int minValue, maxValue;
                    if (!int.TryParse(values[0], out minValue))
                        throw new FormatException("Min value must be an integer.");

                    if (!int.TryParse(values[1], out maxValue))
                        throw new FormatException("Max value must be an integer.");

                    AddRange(minValue, maxValue);
                }
            }
        }

        public void SetSeed(int seed)
        {
            lock (_lock)
            {
                _seed = seed;
            }
        }

        private class Range
        {
            public int MinValue { get; set; }
            public int MaxValue { get; set; }

            public Range(int minValue, int maxValue)
            {
                MinValue = minValue;
                MaxValue = maxValue;
            }
        }
    }
}
