#include <stdlib.h>
#include <string.h>
#include <openssl/aes.h>
#include <openssl/evp.h>
#include <openssl/hmac.h>
#include <openssl/pbkdf2.h>

// Define the cipher parameters
#define AES_KEY_SIZE 32
#define AES_BLOCK_SIZE 16
#define IV_LENGTH 16

// Define the password-based encryption key derivation function
int pbkdf2_hmac_sha256(const char* password, const char* salt, int iterations, unsigned char* key) {
    // Initialize the HMAC context
    HMAC_CTX ctx;
    HMAC_Init(&ctx, password, strlen(password), EVP_sha256());

    // Derive the encryption key from the password using PBKDF2 with HMAC-SHA256
    int ret = PBKDF2_HMAC_SHA256(salt, strlen(salt), iterations, AES_KEY_SIZE, &ctx, key);
    if (ret != 1) {
        printf("Error: PBKDF2_HMAC_SHA256 failed\n");
        return -1;
    }

    // Clean up the HMAC context
    HMAC_CTX_cleanup(&ctx);

    return 0;
}

// Define the AES-256-CBC cipher initialization function
int aes_cbc_init(const char* password, const unsigned char* iv) {
    // Allocate memory for the encryption key and IV
    unsigned char* key = malloc(AES_KEY_SIZE);
    if (key == NULL) {
        printf("Error: failed to allocate memory for encryption key\n");
        return -1;
    }
    unsigned char* iv_ptr = malloc(IV_LENGTH);
    if (iv_ptr == NULL) {
        printf("Error: failed to allocate memory for IV\n");
        free(key);
        return -1;
    }

    // Derive the encryption key from the password using PBKDF2 with HMAC-SHA256
    if (pbkdf2_hmac_sha256(password, NULL, 1000, key) != 0) {
        printf("Error: failed to derive encryption key\n");
        free(key);
        free(iv_ptr);
        return -1;
    }

    // Initialize the AES-256-CBC cipher with the derived key and IV
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) {
        printf("Error: failed to create new cipher context\n");
        free(key);
        free(iv_ptr);
        return -1;
    }
    int ret = EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv_ptr);
    if (ret != 1) {
        printf("Error: failed to initialize AES-256-CBC cipher\n");
        EVP_CIPHER_CTX_free(ctx);
        free(key);
        free(iv_ptr);
        return -1;
    }

    // Set the encryption key and IV for future use
    aes_cbc_key = key;
    aes_cbc_iv = iv_ptr;

    return 0;
}

// Define the AES-256-CBC cipher cleanup function
int aes_cbc_cleanup() {
    // Free the encryption key and IV memory
    free(aes_cbc_key);
    free(aes_cbc_iv);

    return 0;
}

// Define the AES-256-CBC cipher encryption function
int aes_cbc_encrypt(const unsigned char* plaintext, int plaintext_len, unsigned char* ciphertext) {
    // Initialize the AES-256-CBC cipher with the derived key and IV
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) {
        printf("Error: failed to create new cipher context\n");
        return -1;
    }
    int ret = EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, aes_cbc_key, aes_cbc_iv);
    if (ret != 1) {
        printf("Error: failed to initialize AES-256-CBC cipher\n");
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    // Encrypt the plaintext using the AES-256-CBC cipher
    int len = 0;
    ret = EVP_EncryptUpdate(ctx, ciphertext, &len, plaintext, plaintext_len);
    if (ret != 1) {
        printf("Error: failed to encrypt plaintext\n");
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    // Clean up the cipher context
    EVP_CIPHER_CTX_free(ctx);

    return len;
}

// Define the AES-256-CBC cipher decryption function
int aes_cbc_decrypt(const unsigned char* ciphertext, int ciphertext_len, unsigned char* plaintext) {
    // Initialize the AES-256-CBC cipher with the derived key and IV
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) {
        printf("Error: failed to create new cipher context\n");
        return -1;
    }
    int ret = EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, aes_cbc_key, aes_cbc_iv);
    if (ret != 1) {
        printf("Error: failed to initialize AES-256-CBC cipher\n");
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    // Decrypt the ciphertext using the AES-256-CBC cipher
    int len = 0;
    ret = EVP_DecryptUpdate(ctx, plaintext, &len, ciphertext, ciphertext_len);
    if (ret != 1) {
        printf("Error: failed to decrypt ciphertext\n");
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    // Clean up the cipher context
    EVP_CIPHER_CTX_free(ctx);

    return len;
}
