using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;

namespace ValueGenerator
{
    public class ValueGenerator
    {
        private int minValue;
        private int maxValue;

        public ValueGenerator(int minValue, int maxValue)
        {
            this.minValue = minValue;
            this.maxValue = maxValue;
        }

        public float GenerateRandomFloat()
        {
            return (float)(this.minValue + (this.maxValue - this.minValue) * new Random().NextDouble());
        }

        public int GenerateRandomInt()
        {
            return this.minValue + (int)(new Random().NextDouble() * (this.maxValue - this.minValue));
        }

        public double GenerateRandomDouble()
        {
            return this.minValue + (double)(new Random().NextDouble() * (this.maxValue - this.minValue));
        }

        public override string ToString()
        {
            return $"Range[{this.minValue}, {this.maxValue})";
        }

        public float GenerateSeededRandomFloat(int seed)
        {
            var random = new Random(seed);
            return (float)(this.minValue + (this.maxValue - this.minValue) * random.NextDouble());
        }

        public int GenerateSeededRandomInt(int seed)
        {
            var random = new Random(seed);
            return this.minValue + (int)(random.NextDouble() * (this.maxValue - this.minValue));
        }

        public T GenerateRandomValue<T>() where T : struct, IComparable, IFormattable, IConvertible, IComparable<T>, IEquatable<T>
        {
            if (typeof(T) == typeof(int))
            {
                return (T)(object)GenerateRandomInt();
            }
            else if (typeof(T) == typeof(float))
            {
                return (T)(object)GenerateRandomFloat();
            }
            else if (typeof(T) == typeof(double))
            {
                return (T)(object)GenerateRandomDouble();
            }
            else
            {
                throw new NotSupportedException($"The type {typeof(T).Name} is not supported.");
            }
        }

        public static void ResetRandomGenerator()
        {
            Random random = new Random();
            random.NextDouble();
        }
    }
}
