#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <stdbool.h>
#include <openssl/md5.h>

struct Session {
    char* id;
    struct Session* next;
};

struct SessionList {
    struct Session* head;
    int size;
};

struct WebServerConfig {
    int maxConcurrentSessions;
    bool maintenanceMode;
};

struct SessionList* createSessionList(char** sessionIds, int numSessions, struct WebServerConfig config) {
    // Calculate the total number of sessions to be created
    int totalNumSessions = 0;
    for (int i = 0; i < numSessions; i++) {
        if (!config.maintenanceMode || !strcmp(sessionIds[i], "admin")) {
            totalNumSessions++;
        }
    }

    // Allocate memory for the session list and initialize it
    struct SessionList* list = malloc(sizeof(struct SessionList));
    if (!list) {
        return NULL;
    }
    list->head = NULL;
    list->size = 0;

    // Create a new session for each ID in the array
    for (int i = 0; i < numSessions; i++) {
        char* id = sessionIds[i];
        if (!config.maintenanceMode || !strcmp(id, "admin")) {
            struct Session* session = malloc(sizeof(struct Session));
            if (!session) {
                freeSessionList(list);
                return NULL;
            }
            session->id = id;
            session->next = list->head;
            list->head = session;
            list->size++;
        }
    }

    // Update the next pointer of each session to maintain concurrency
    struct Session* current = list->head;
    while (current) {
        if (current->next) {
            current->next->prev = current;
        }
        current = current->next;
    }

    // Handle session expiration and calculate MD5 hashes
    struct Session* current = list->head;
    while (current) {
        if (!config.maintenanceMode || !strcmp(current->id, "admin")) {
            char md5Hash[MD5_DIGEST_LENGTH];
            MD5((unsigned char*)current->id, strlen(current->id), (unsigned char*)md5Hash);
            current->id = malloc(sizeof(char) * (MD5_DIGEST_LENGTH + 1));
            if (!current->id) {
                freeSessionList(list);
                return NULL;
            }
            strcpy(current->id, md5Hash);
        }
        current = current->next;
    }

    // Update the session list to maintain maximum allowed concurrency
    while (list->size > config.maxConcurrentSessions) {
        struct Session* lastSession = list->head;
        while (lastSession->next) {
            lastSession = lastSession->next;
        }
        free(lastSession->id);
        lastSession->id = NULL;
        list->size--;
    }

    // Log session creation and expiration events
    struct Session* current = list->head;
    while (current) {
        if (!config.maintenanceMode || !strcmp(current->id, "admin")) {
            printf("Session created: %s\n", current->id);
        } else {
            printf("Session expired: %s\n", current->id);
        }
        current = current->next;
    }

    // Gracefully degrade when resources are exhausted
    if (list->size > config.maxConcurrentSessions) {
        struct Session* lastSession = list->head;
        while (lastSession->next) {
            lastSession = lastSession->next;
        }
        free(lastSession->id);
        lastSession->id = NULL;
        list->size--;
    }

    return list;
}

void freeSessionList(struct SessionList* list) {
    struct Session* current = list->head;
    while (current) {
        struct Session* next = current->next;
        free(current);
        current = next;
    }
    free(list);
}
