int handleVideoStream(const char* url, struct video_metadata* metadata) {
    // Open the video stream
    int fd = open(url, O_RDONLY);
    if (fd < 0) {
        perror("Failed to open video stream");
        return -1;
    }

    // Determine the video format
    struct stat st;
    if (fstat(fd, &st) < 0) {
        perror("Failed to determine video format");
        close(fd);
        return -1;
    }

    // Initialize FFmpeg structures for metadata extraction and compression
    AVFormatContext* fmt_ctx = NULL;
    AVCodecContext* codec_ctx = NULL;
    AVPacket packet;
    int ret = 0;

    // Extract metadata from the video stream
    if (avformat_open_input(&fmt_ctx, url, NULL, NULL) < 0) {
        perror("Failed to open input");
        goto end;
    }
    if (avformat_find_stream_info(fmt_ctx, NULL) < 0) {
        perror("Failed to find stream info");
        goto end;
    }
    for (int i = 0; i < fmt_ctx->nb_streams; i++) {
        if (fmt_ctx->streams[i]->codecpar->codec_type == AVMEDIA_TYPE_VIDEO) {
            codec_ctx = fmt_ctx->streams[i]->codec;
            break;
        }
    }
    if (!codec_ctx) {
        perror("Failed to find video stream");
        goto end;
    }
    metadata->frame_rate = codec_ctx->framerate.num / codec_ctx->framerate.den;
    metadata->resolution_width = codec_ctx->width;
    metadata->resolution_height = codec_ctx->height;
    metadata->pixel_format = codec_ctx->pix_fmt;

    // Compress the video stream if requested
    if (strcmp(url, "-c") == 0) {
        AVCodec* codec = avcodec_find_encoder(AV_CODEC_ID_H264);
        if (!codec) {
            perror("Failed to find H.264 encoder");
            goto end;
        }
        AVFrame* frame = av_frame_alloc();
        if (!frame) {
            perror("Failed to allocate video frame");
            goto end;
        }
        AVPacket compressed_packet;
        av_init_packet(&compressed_packet);
        while (av_read_frame(fmt_ctx, &packet) >= 0) {
            if (packet.stream_index == fmt_ctx->streams[i]->id) {
                frame->data[0] = packet.data;
                frame->linesize[0] = packet.size;
                int compressed_size = avcodec_encode_video2(codec_ctx, &compressed_packet, frame, NULL);
                if (compressed_size < 0) {
                    perror("Failed to compress video stream");
                    goto end;
                }
                // TODO: handle reencoding options and resolution/frame rate changes
            }
        }
        av_free(frame);
        close(fd);
        return compressed_packet.data;
    }

end:
    if (fmt_ctx) {
        avformat_close_input(&fmt_ctx);
    }
    close(fd);
    return -1;
}
```
