void manage_cell_info(NR_CELL_INFO_PDU_T* pdu, int m) {
    // Allocate memory for the array of structures
    NR_CELL_INFO_PDU_T* cell_info = (NR_CELL_INFO_PDU_T*)malloc(m * sizeof(NR_CELL_INFO_PDU_T));
    if (!cell_info) {
        // Handle allocation failure
        printf("Error: Failed to allocate memory for cell information\n");
        return;
    }

    // Initialize the array of structures with default values
    for (int i = 0; i < m; i++) {
        cell_info[i].cell_id = -1;
        cell_info[i].pci = -1;
        cell_info[i].rsrp = -1.0f;
    }

    // Iterate over the input PDUs and add them to the array of structures
    for (int i = 0; i < m; i++) {
        if (pdu[i].cell_id == -1 || pdu[i].pci == -1) {
            // Skip invalid PDUs
            continue;
        }

        bool duplicate_found = false;
        for (int j = 0; j < i; j++) {
            if (cell_info[j].cell_id == pdu[i].cell_id) {
                // Found a duplicate cell ID, log an error message and continue processing the remaining PDUs
                printf("Error: Duplicate cell ID found in input PDU\n");
                duplicate_found = true;
                break;
            }
        }

        if (duplicate_found) {
            continue;
        }

        // Add the current PDU to the array of structures
        cell_info[i].cell_id = pdu[i].cell_id;
        cell_info[i].pci = pdu[i].pci;
        cell_info[i].rsrp = pdu[i].rsrp;
    }

    // Print the contents of the array of structures to a file
    FILE* fp = fopen("cell_info.txt", "w");
    if (!fp) {
        printf("Error: Failed to open file for writing\n");
        return;
    }

    for (int i = 0; i < m; i++) {
        fprintf(fp, "%d %d %f\n", cell_info[i].cell_id, cell_info[i].pci, cell_info[i].rsrp);
    }

    fclose(fp);
}
