void manage_cell_info(NR_CELL_INFO_PDU_T* arr, int m) {
    // Initialize variables for tracking duplicates and memory usage
    int num_duplicates = 0;
    size_t mem_usage = 0;

    // Iterate over the array of measurements
    for (int i = 0; i < m; i++) {
        // Check if the current measurement is a duplicate
        bool is_duplicate = false;
        for (int j = 0; j < i; j++) {
            if (arr[i].cell_id == arr[j].cell_id) {
                is_duplicate = true;
                break;
            }
        }

        // If the measurement is a duplicate, log an error message and continue processing
        if (is_duplicate) {
            printf("Duplicate cell ID detected: %d\n", arr[i].cell_id);
            num_duplicates++;
            continue;
        }

        // Validate that the PCI is unique within the array
        for (int j = 0; j < i; j++) {
            if (arr[i].pci == arr[j].pci) {
                printf("Duplicate PCI detected: %d\n", arr[i].pci);
                num_duplicates++;
                break;
            }
        }

        // Ensure that the RSRP measurement is valid
        if (arr[i].rsrp < 0 || arr[i].rsrp > 140) {
            printf("Invalid RSRP measurement: %f\n", arr[i].rsrp);
            num_duplicates++;
            continue;
        }

        // Update the memory usage and continue processing
        mem_usage += sizeof(NR_CELL_INFO_PDU_T);
    }

    // Print a summary of the duplicates found
    printf("Number of duplicates: %d\n", num_duplicates);
    printf("Memory usage: %zu bytes\n", mem_usage);
}

// Define a function to convert RSRP measurements from dBm to linear scale (mW)
float rsrp_to_linear(float rsrp) {
    return powf(10, rsrp / 10);
}

// Define a function to convert RSRP measurements from linear scale (mW) to dBm
float rsrp_to_dbm(float rsrp) {
    return 10 * log10f(rsrp);
}

// Define a function to print the contents of the cellular network measurements to a file
void print_cell_info(NR_CELL_INFO_PDU_T* arr, int m, const char* filename) {
    // Open the output file in append mode
    FILE* fp = fopen(filename, "a");
    if (fp == NULL) {
        printf("Error opening file %s\n", filename);
        return;
    }

    // Iterate over the array of measurements and print each one to the file
    for (int i = 0; i < m; i++) {
        fprintf(fp, "%d,%d,%f\n", arr[i].cell_id, arr[i].pci, rsrp_to_linear(arr[i].rsrp));
    }

    // Close the output file
    fclose(fp);
}
