// Function to initialize an AES-256-CBC cipher with a given password
int init_aes_cbc(const char* password, unsigned char* iv) {
    // Check if the OpenSSL library is available and compatible
    if (!EVP_is_implemented()) {
        fprintf(stderr, "OpenSSL library not found or incompatible\n");
        return -1;
    }

    // Derive the encryption key from the password using PBKDF2
    unsigned char* key = NULL;
    int key_len = 0;
    if (pbkdf2(password, strlen(password), iv, AES_IV_SIZE, &key, &key_len, PBKDF2_ITERATIONS) != 1) {
        fprintf(stderr, "Error deriving encryption key from password\n");
        return -1;
    }

    // Initialize the AES-256-CBC cipher with the derived key and IV
    EVP_CIPHER_CTX* ctx = NULL;
    if ((ctx = EVP_CIPHER_CTX_new()) == NULL) {
        fprintf(stderr, "Error creating AES-256-CBC cipher context\n");
        return -1;
    }
    if (EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv) != 1) {
        fprintf(stderr, "Error initializing AES-256-CBC cipher\n");
        return -1;
    }

    // Free memory allocated for the derived key and IV
    OPENSSL_free(key);
    OPENSSL_cleanse(iv, AES_IV_SIZE);

    return 0;
}
