// Define the function to initialize the AES-256-CBC cipher with a given password
int init_aes_cbc(const char* password, size_t password_len) {
  // Check if the OpenSSL library is loaded
  if (!EVP_is_implemented()) {
    fprintf(stderr, MISSING_DEPENDENCIES);
    return -1;
  }

  // Generate a random initialization vector (IV) for AES-256-CBC
  unsigned char iv[AES_BLOCK_SIZE];
  RAND_bytes(iv, AES_BLOCK_SIZE);

  // Derive the key from the password using PBKDF2 with SHA-512
  unsigned char key[EVP_MAX_KEY_LENGTH];
  size_t key_len = EVP_MAX_KEY_LENGTH;
  if (KDF_FUNCTION(password, password_len, NULL, 0, iv, AES_BLOCK_SIZE, key, &key_len) != 1) {
    fprintf(stderr, "Error deriving key from password\n");
    return -1;
  }

  // Initialize the AES-256-CBC cipher with the derived key and IV
  EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
  if (EVP_EncryptInit_ex(ctx, CIPHER, NULL, key, iv) != 1) {
    fprintf(stderr, "Error initializing AES-256-CBC cipher\n");
    EVP_CIPHER_CTX_free(ctx);
    return -1;
  }

  // Set the key and IV for future use
  memcpy(key_, key, key_len);
  memcpy(iv_, iv, AES_BLOCK_SIZE);

  // Free the cipher context
  EVP_CIPHER_CTX_free(ctx);

  return 0;
}

// Define the function to encrypt data using the AES-256-CBC cipher
int encrypt(const unsigned char* plaintext, size_t plaintext_len, unsigned char* ciphertext) {
  // Check if the key and IV are set
  if (key_ == NULL || iv_ == NULL) {
    fprintf(stderr, "Error: Key and IV not set\n");
    return -1;
  }

  // Initialize the AES-256-CBC cipher with the key and IV
  EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
  if (EVP_EncryptInit_ex(ctx, CIPHER, NULL, key_, iv_) != 1) {
    fprintf(stderr, "Error initializing AES-256-CBC cipher\n");
    EVP_CIPHER_CTX_free(ctx);
    return -1;
  }

  // Encrypt the plaintext using the AES-256-CBC cipher
  int len = 0;
  if (EVP_EncryptUpdate(ctx, ciphertext, &len, plaintext, plaintext_len) != 1) {
    fprintf(stderr, "Error encrypting data\n");
    EVP_CIPHER_CTX_free(ctx);
    return -1;
  }

  // Set the output length of the ciphertext
  *ciphertext_len = len;

  // Free the cipher context
  EVP_CIPHER_CTX_free(ctx);

  return 0;
}

// Define the function to decrypt data using the AES-256-CBC cipher
int decrypt(const unsigned char* ciphertext, size_t ciphertext_len, unsigned char* plaintext) {
  // Check if the key and IV are set
  if (key_ == NULL || iv_ == NULL) {
    fprintf(stderr, "Error: Key and IV not set\n");
    return -1;
  }

  // Initialize the AES-256-CBC cipher with the key and IV
  EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
  if (EVP_DecryptInit_ex(ctx, CIPHER, NULL, key_, iv_) != 1) {
    fprintf(stderr, "Error initializing AES-256-CBC cipher\n");
    EVP_CIPHER_CTX_free(ctx);
    return -1;
  }

  // Decrypt the ciphertext using the AES-256-CBC cipher
  int len = 0;
  if (EVP_DecryptUpdate(ctx, plaintext, &len, ciphertext, ciphertext_len) != 1) {
    fprintf(stderr, "Error decrypting data\n");
    EVP_CIPHER_CTX_free(ctx);
    return -1;
  }

  // Set the output length of the plaintext
  *plaintext_len = len;

  // Free the cipher context
  EVP_CIPHER_CTX_free(ctx);

  return 0;
}
