#include <arpa/inet.h>
#include <openssl/ssl.h>
#include <openssl/err.h>
#include <pthread.h>

// Define the configuration parameters for the WebSocket server
#define PORT 8080
#define BACKLOG 10
#define MAX_CONNECTIONS 1000
#define CERTIFICATE_PATH "certificate.crt"
#define KEY_PATH "private.key"
#define CA_CERTIFICATE_PATH "ca-certificate.crt"
#define TLS_VERSION TLSv1_2
#define CLIENT_AUTHENTICATION 0
#define OAUTH_TOKEN_PATH "oauth-token.txt"

// Define the data structures for the WebSocket connections
typedef struct {
    int socket;
    SSL *ssl;
} connection_t;

typedef struct {
    char *hostname;
    int port;
} address_t;

// Define the functions for handling WebSocket connections
void handle_connection(connection_t *conn);
void handle_error(connection_t *conn, const char *message);
void handle_close(connection_t *conn);

// Define the function for initializing the WebSocket server
int initialize_server() {
    // Load the library for handling WebSocket connections (libwebsockets)
    if (!SSL_library_init()) {
        printf("Error: Failed to load libwebsockets library\n");
        return 1;
    }

    // Initialize the SSL context with the given configuration parameters
    SSL_CTX *ctx = SSL_CTX_new(TLSv1_2_client_method());
    if (!ctx) {
        printf("Error: Failed to create SSL context\n");
        return 1;
    }

    // Load the TLS/SSL certificates and private key
    if (SSL_CTX_use_certificate_file(ctx, CERTIFICATE_PATH, SSL_FILETYPE_PEM) <= 0 ||
            SSL_CTX_use_PrivateKey_file(ctx, KEY_PATH, SSL_FILETYPE_PEM) <= 0) {
        printf("Error: Failed to load TLS/SSL certificates and private key\n");
        return 1;
    }

    // Load the CA certificate for client authentication
    if (SSL_CTX_load_verify_locations(ctx, CA_CERTIFICATE_PATH, NULL) <= 0) {
        printf("Error: Failed to load CA certificate for client authentication\n");
        return 1;
    }

    // Set the TLS/SSL version and client authentication options
    SSL_CTX_set_options(ctx, SSL_OP_NO_TLSv1 | SSL_OP_NO_TLSv1_1 | SSL_OP_NO_COMPRESSION | SSL_OP_CIPHER_SERVER_PREFERENCE);
    if (CLIENT_AUTHENTICATION) {
        SSL_CTX_set_verify(ctx, SSL_VERIFY_PEER | SSL_VERIFY_FAIL_IF_NO_PEER_CERT, NULL);
    } else {
        SSL_CTX_set_verify(ctx, SSL_VERIFY_NONE, NULL);
    }

    // Create the socket for the WebSocket server and bind it to the given port
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
        printf("Error: Failed to create socket\n");
        return 1;
    }

    struct sockaddr_in server_address;
    memset(&server_address, 0, sizeof(server_address));
    server_address.sin_family = AF_INET;
    server_address.sin_port = htons(PORT);
    server_address.sin_addr.s_addr = INADDR_ANY;

    if (bind(sock, (struct sockaddr *)&server_address, sizeof(server_address)) < 0) {
        printf("Error: Failed to bind socket\n");
        return 1;
    }

    // Listen for incoming connections and create a new thread for each one
    if (listen(sock, BACKLOG) < 0) {
        printf("Error: Failed to listen for incoming connections\n");
        return 1;
    }

    pthread_t threads[MAX_CONNECTIONS];
    connection_t connections[MAX_CONNECTIONS];

    int i = 0;
    while (i < MAX_CONNECTIONS) {
        struct sockaddr_in client_address;
        socklen_t address_length = sizeof(client_address);
        connections[i].socket = accept(sock, (struct sockaddr *)&client_address, &address_length);
        if (connections[i].socket < 0) {
            printf("Error: Failed to accept incoming connection\n");
            return 1;
        }

        connections[i].ssl = SSL_new(ctx);
        SSL_set_fd(connections[i].ssl, connections[i].socket);

        if (SSL_accept(connections[i].ssl) <= 0) {
            handle_error(&connections[i], "Failed to establish TLS/SSL connection");
            return 1;
        }

        pthread_create(&threads[i], NULL, handle_connection, &connections[i]);
        i++;
    }

    // Clean up the SSL context and socket
    SSL_CTX_free(ctx);
    close(sock);

    return 0;
}

// Define the function for handling WebSocket connections in a separate thread
void *handle_connection(connection_t *conn) {
    // Handle incoming messages from the client and send responses back to the client
    while (1) {
        char buffer[4096];
        int bytes = SSL_read(conn->ssl, buffer, sizeof(buffer));
        if (bytes <= 0) {
            handle_error(conn, "Failed to read from socket");
            break;
        }

        // Process the incoming message and send a response back to the client
        char *response = process_message(buffer);
        int bytes_written = SSL_write(conn->ssl, response, strlen(response));
        if (bytes_written <= 0) {
            handle_error(conn, "Failed to write to socket");
            break;
        }
    }

    // Close the connection and clean up the resources
    SSL_free(conn->ssl);
    close(conn->socket);
    return NULL;
}

// Define the function for handling errors in WebSocket connections
void handle_error(connection_t *conn, const char *message) {
    printf("Error: %s\n", message);
    SSL_free(conn->ssl);
    close(conn->socket);
}

// Define the function for handling closing of WebSocket connections
void handle_close(connection_t *conn) {
    // Close the connection and clean up the resources
    SSL_free(conn->ssl);
    close(conn->socket);
}
