// Custom memory pool allocator for efficient memory management
struct MemoryPool {
    void* data;
    size_t size;
};

// Hash table and binary search tree for optimal insertion and lookup operations
struct Record {
    long offset;
    int key;
    double value;
};

// Logging system to monitor memory allocation and deallocation events
struct Logger {
