#include <openssl/pem.h>
#include <openssl/err.h>

// Define the supported signing algorithms
enum SigningAlgorithm {
    RS256,
    PS256,
    ES256,
    HS256
};

// Define the standard claims that must be present in a JWT token
struct Claim {
    char *iss;
    char *sub;
    char *aud;
    long exp;
    long nbf;
    char *jti;
};

// Define the function to parse and validate a JWT token
int parse_and_validate_token(const char *token, enum SigningAlgorithm algorithm) {
    // Initialize variables
    int status = 0;
    struct Claim claims;
    RSA *rsa_key = NULL;
    EVP_PKEY *pkey = NULL;
    BIO *bio = NULL;
    JWT *jwt = NULL;

    // Parse the token using a secure and efficient JSON parsing library
    jwt = jwt_decode(token, algorithm);
    if (jwt == NULL) {
        status = -1;
        goto cleanup;
    }

    // Extract the claims from the JWT token
    claims.iss = jwt->claims.iss;
    claims.sub = jwt->claims.sub;
    claims.aud = jwt->claims.aud;
    claims.exp = jwt->claims.exp;
    claims.nbf = jwt->claims.nbf;
    claims.jti = jwt->claims.jti;

    // Verify the signature of the JWT token using the RSA-PSS algorithm with SHA-256
    rsa_key = EVP_PKEY_get1_RSA(pkey);
    if (rsa_key == NULL) {
        status = -1;
        goto cleanup;
    }
    if (!EVP_VerifyInit_ex(rsa_key, algorithm)) {
        status = -1;
        goto cleanup;
    }
    if (!EVP_VerifyUpdate(rsa_key, token, strlen(token))) {
        status = -1;
        goto cleanup;
    }
    if (!EVP_VerifyFinal(rsa_key, signature)) {
        status = -1;
        goto cleanup;
    }

    // Clean up resources
cleanup:
    if (jwt != NULL) {
        jwt_free(jwt);
    }
    if (rsa_key != NULL) {
        RSA_free(rsa_key);
    }
    if (pkey != NULL) {
        EVP_PKEY_free(pkey);
    }
    if (bio != NULL) {
        BIO_free(bio);
    }

    // Return the status of the token validation
    return status;
}
```
