void decrypt_message(const unsigned char *ciphertext, const size_t ciphertext_len, const unsigned char *key, const size_t key_len, const unsigned char *iv, const size_t iv_len) {
    // Initialize AES cipher with the provided encryption key and initialization vector (IV)
    AES_KEY aes_key;
    AES_set_decrypt_key(key, key_len * 8, &aes_key);
    AES_cbc_encrypt(ciphertext, ciphertext, ciphertext_len, &aes_key, iv, AES_DECRYPT);

    // Initialize HMAC-SHA256 with the provided encryption key and initialization vector (IV)
    HMAC_CTX *hmac = HMAC_CTX_new();
    HMAC_Init_ex(hmac, key, key_len, EVP_sha256(), NULL);
    HMAC_Update(hmac, ciphertext, ciphertext_len);
    unsigned char hmac_result[SHA256_DIGEST_LENGTH];
    HMAC_Final(hmac, hmac_result, NULL);
    HMAC_CTX_free(hmac);

    // Check if the HMAC-SHA256 result matches the expected value
    if (memcmp(hmac_result, ciphertext + ciphertext_len - SHA256_DIGEST_LENGTH, SHA256_DIGEST_LENGTH) != 0) {
        // If the HMAC-SHA256 result does not match, reinitialize the AES cipher with a new IV for each part of the message
        unsigned char new_iv[AES_BLOCK_SIZE];
        RAND_bytes(new_iv, AES_BLOCK_SIZE);
        AES_cbc_encrypt(ciphertext, ciphertext, ciphertext_len, &aes_key, new_iv, AES_DECRYPT);
    }

    // Log each decryption attempt, including success or failure, along with the corresponding message ID
    char log_message[256];
    snprintf(log_message, 256, "Decrypted message %d: %s", message_id, ciphertext);
    va_list args;
    va_start(args, log_message);
    vfprintf(stderr, log_message, args);
