void validate_payloads() {
    // Lock the mutex to prevent race conditions
    pthread_mutex_lock(&event_list_lock);

    // Iterate over the events list and validate each payload
    for (int i = 0; i < events.size(); i++) {
        EventRecord record = events[i];
        bool valid = check_payload_integrity(record.timestamp, record.event_type);
        if (!valid) {
            // Log the incident to a separate file for auditing purposes
            FILE* log_file = fopen("event_logs.txt", "a");
            fprintf(log_file, "%ld,%d,%s,checksum_error\n", record.timestamp, record.event_type, record.unique_id);
            fclose(log_file);
        }
    }

    // Unlock the mutex
    pthread_mutex_unlock(&event_list_lock);
}

// Define a function to handle any unexpected timestamps or checksum errors gracefully without crashing the program
void handle_incidents() {
    // Lock the mutex to prevent race conditions
    pthread_mutex_lock(&event_list_lock);

    // Iterate over the events list and handle any incidents
    for (int i = 0; i < events.size(); i++) {
        EventRecord record = events[i];
        if (!record.payload_integrity) {
            // Log the incident to a separate file for auditing purposes
            FILE* log_file = fopen("event_logs.txt", "a");
            fprintf(log_file, "%ld,%d,%s,checksum_error\n", record.timestamp, record.event_type, record.unique_id);
            fclose(log_file);
        } else if (record.timestamp < 0) {
            // Log the incident to a separate file for auditing purposes
            FILE* log_file = fopen("event_logs.txt", "a");
