// Define a function to process events in batches, allowing for batch processing of multiple events at once
void process_batch(int batch_size) {
    // Lock the mutex to prevent race conditions
    pthread_mutex_lock(&event_list_lock);

    // Get the last element of the events list
    EventRecord record = events.back();

    // Create a new array to store the batch of events
    EventRecord* batch = (EventRecord*) malloc(sizeof(EventRecord) * batch_size);

    // Iterate over the events list and fill the batch with up to batch_size events
    int i = 0;
    while (i < batch_size && i < num_events) {
        EventRecord record = events[i];
        batch[i] = record;
        i++;
    }

    // Unlock the mutex
    pthread_mutex_unlock(&event_list_lock);
}

