using namespace std;

// Network Interface Configuration structure
struct NIC {
    string macAddress;
    string ipAddress;
    string subnetMask;
};

// Mersenne Twister algorithm for generating random MAC addresses
class NetworkRandomGenerator {
public:
    NetworkRandomGenerator() {}
    ~NetworkRandomGenerator() {}

    static std::random_device rd;
    static std::mt19937 mt;
};

// C function to dynamically allocate and return a new MAC address
std::string generateNewMACAddress() {
    // Generate a random number between 0 and 255 for each octet of the MAC address
    int octet1 = NetworkRandomGenerator::mt() % 256;
    int octet2 = NetworkRandomGenerator::mt() % 256;
    int octet3 = NetworkRandomGenerator::mt() % 256;
    int octet4 = NetworkRandomGenerator::mt() % 256;
    int octet5 = NetworkRandomGenerator::mt() % 256;
    int octet6 = NetworkRandomGenerator::mt() % 256;

    // Format the MAC address as a string
    std::string macAddress = std::to_string(octet1) + ":" + std::to_string(octet2) + ":" + std::to_string(octet3) + ":" + std::to_string(octet4) + ":" + std::to_string(octet5) + ":" + std::to_string(octet6);

    // Check if the MAC address is unique within the network segment
    bool unique = true;
    for (int i = 0; i < macAddresses.size(); i++) {
        if (macAddress == macAddresses[i]) {
            unique = false;
            break;
        }
    }

    // If the MAC address is not unique, generate a new one and check again
    while (!unique) {
        octet1 = NetworkRandomGenerator::mt() % 256;
        octet2 = NetworkRandomGenerator::mt() % 256;
        octet3 = NetworkRandomGenerator::mt() % 256;
        octet4 = NetworkRandomGenerator::mt() % 256;
        octet5 = NetworkRandomGenerator::mt() % 256;
        octet6 = NetworkRandomGenerator::mt() % 256;
        macAddress = std::to_string(octet1) + ":" + std::to_string(octet2) + ":" + std::to_string(octet3) + ":" + std::to_string(octet4) + ":" + std::to_string(octet5) + ":" + std::to_string(octet6);
        unique = true;
        for (int i = 0; i < macAddresses.size(); i++) {
            if (macAddress == macAddresses[i]) {
                unique = false;
                break;
            }
        }
    }

    // Add the new MAC address to the list of known addresses
    macAddresses.push_back(macAddress);

    return macAddress;
}

// Java method to serialize a state object to a file using an ObjectOutputStream
void saveStateToFile(const std::string& filename, const std::vector<NIC>& nicList) {
    // Open the output stream for writing
    ofstream outStream(filename);

    // Write the number of NICs to the file
    outStream << nicList.size() << endl;

    // Write each NIC structure to the file
    for (int i = 0; i < nicList.size(); i++) {
        outStream << nicList[i].macAddress << " " << nicList[i].ipAddress << " " << nicList[i].subnetMask << endl;
    }

    // Close the output stream
    outStream.close();
}

// C function to manage a dynamically allocated array of NetworkPerformanceMetrics structures
void manageNetworkPerformanceMetrics(std::vector<NetworkPerformanceMetrics>& metrics, int N) {
    // Check if the input is valid
    if (N <= 0) {
        return;
    }

    // Initialize the array of NetworkPerformanceMetrics structures
    metrics.resize(N);

    // Fill the array with random data
    for (int i = 0; i < N; i++) {
        metrics[i].bandwidthUsage = NetworkRandomGenerator::mt() % 1000;
        metrics[i].packetLoss = NetworkRandomGenerator::mt() % 1000;
        metrics[i].latency = NetworkRandomGenerator::mt() % 1000;
    }
}

// C function to convert bits per second to kilobits per second
double convertBitsPerSecondToKilobitsPerSecond(double bitsPerSecond) {
    return bitsPerSecond / 1000.0;
}

// C function to visualize the performance metrics through both console-based and graphical interfaces
void visualizeNetworkPerformanceMetrics(const std::vector<NetworkPerformanceMetrics>& metrics, int N) {
    // Print the performance metrics to the console
    for (int i = 0; i < N; i++) {
        cout << "Bandwidth usage: " << convertBitsPerSecondToKilobitsPerSecond(metrics[i].bandwidthUsage) << " kbps" << endl;
        cout << "Packet loss: " << metrics[i].packetLoss << "%" << endl;
        cout << "Latency: " << metrics[i].latency << " ms" << endl;
    }
}
