            time_t currentTime = time(NULL);

            // Calculate the session duration for the current log entry
            long sessionDuration = currentTime - currentLogID;

            // Check if the session duration is less than 30 days
            if (sessionDuration < 2592000) {
                // Update the latest log entry's ID and index
                latestLog[0] = currentLogID;
                latestLog[1] = i;
            }
