    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, "http://example.com/test-configurations");
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, body);
        CURLcode res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            fprintf(stderr, "Error exporting test configurations: %s\n", curl_easy_strerror(res));
            return 0;
        }
    } else {
        fprintf(stderr, "Error initializing HTTP client\n");
        return 0;
    }

    // Clean up the HTTP request headers and body
    curl_slist_free_all(headers);
    free(body);

    // Return success if the POST request was successful
    return 1;
}
