            printf("Duplicate cell ID found in structure %d. Continuing to process remaining structures...\n", i);
            continue;
        }

        // Convert RSRP measurements from dBm to linear scale (mW) if necessary
        if (arr[i].rsrp < 0) {
            arr[i].rsrp = pow(10, arr[i].rsrp / 10);
        }
    }

    // Print the contents of the structures to a specified file
    FILE* fp = fopen("cell_info.txt", "w");
    if (fp == NULL) {
        printf("Error: unable to open file for writing\n");
        return;
    }

    for (i = 0; i < m; i++) {
        fprintf(fp, "%d %d %.2f\n", arr[i].cell_id, arr[i].pci, arr[i].rsrp);
    }

    fclose(fp);
}
