    vector<NFAPI_CRC_INDICATION_PDU_T> generateRandomNumbers(size_t numRxUeInformation, size_t numCrcIndicationRel8Tags) {
        // Initialize AES-256-CBC cipher with given password
        AutoSeededRandomPool prng;
        CTR_Mode<AES>::Encryption aesEncryptor(prng, 256);

        // Generate random initialization vector (IV) and securely derive encryption key from password using PBKDF2 with HMAC-SHA256
        SecByteBlock iv(aesEncryptor.OptimalBlockSize());
        prng.GenerateBlock(iv, iv.size());
        SecByteBlock key(32);
        PBKDF2_HMAC<SHA256> pbkdf2;
        pbkdf2.DeriveKey(key, 32, 0, password_, password_.length(), iv, aesEncryptor.OptimalBlockSize());

        // Utilize Mersenne Twister algorithm to generate random numbers
        MersenneTwisterRNG rng;
        vector<NFAPI_CRC_INDICATION_PDU_T> randomNumbers(numRxUeInformation);
        for (size_t i = 0; i < numRxUeInformation; ++i) {
            randomNumbers[i].rxUeInformation.rnti = rng.GenerateWord32();
            randomNumbers[i].crcIndicationRel8Tag.crcFlag = rng.GenerateWord32() % 2;
        }

        // Encrypt random numbers using AES-256-CBC cipher
        CTR_Mode<AES>::Encryption aesEncryptor(key, iv);
        for (size_t i = 0; i < numRxUeInformation; ++i) {
            SecByteBlock plaintext(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            memcpy(plaintext.data(), &randomNumbers[i], sizeof(NFAPI_CRC_INDICATION_PDU_T));
            SecByteBlock ciphertext(aesEncryptor.OptimalBlockSize());
            aesEncryptor.ProcessData(ciphertext, plaintext);
            memcpy(&randomNumbers[i], ciphertext.data(), sizeof(NFAPI_CRC_INDICATION_PDU_T));
        }

        // Populate list of NFAPI_CRC_INDICATION_PDU_T structures with encrypted random numbers
        vector<NFAPI_CRC_INDICATION_PDU_T> encryptedRandomNumbers(numRxUeInformation);
        for (size_t i = 0; i < numRxUeInformation; ++i) {
            encryptedRandomNumbers[i] = randomNumbers[i];
        }

        // Generate additional CRC_INDICATION_REL8_TAG structures with randomly set CRCFLAG
        vector<CRC_INDICATION_REL8_TAG> crcIndicationRel8Tags(numCrcIndicationRel8Tags);
        for (size_t i = 0; i < numCrcIndicationRel8Tags; ++i) {
            crcIndicationRel8Tags[i].crcFlag = rng.GenerateWord32() % 2;
        }

        // Combine encrypted random numbers and CRC_INDICATION_REL8_TAG structures into a single list
        vector<NFAPI_CRC_INDICATION_PDU_T> combinedList(numRxUeInformation + numCrcIndicationRel8Tags);
        for (size_t i = 0; i < numRxUeInformation; ++i) {
            combinedList[i] = encryptedRandomNumbers[i];
        }
        for (size_t i = 0; i < numCrcIndicationRel8Tags; ++i) {
            combinedList[numRxUeInformation + i] = crcIndicationRel8Tags[i];
        }

        return combinedList;
    }

private:
    string password_;
};
