// LogEntry structure to store log metadata and message
typedef struct {
    int id;
    time_t startTime;
    char* message;
    bool valid;
} LogEntry;

// Array of LogEntry structures to store all logs
LogEntry* logEntries = NULL;
int numLogs = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to add a new log entry to the array
void addLog(int id, time_t startTime, char* message) {
    // Lock the mutex to prevent concurrent writes
    pthread_mutex_lock(&mutex);

    // Allocate memory for the new LogEntry structure
    LogEntry* newEntry = (LogEntry*)malloc(sizeof(LogEntry));
    newEntry->id = id;
    newEntry->startTime = startTime;
    newEntry->message = message;
    newEntry->valid = true;

    // Add the new entry to the array of log entries
    logEntries[numLogs++] = newEntry;

    // Unlock the mutex and return
    pthread_mutex_unlock(&mutex);
}

// Function to get the latest log entry's ID and index
void getLatestLog(int* id, int* index) {
    // Lock the mutex to prevent concurrent reads
    pthread_mutex_lock(&mutex);

    // Get the latest log entry from the array of log entries
    LogEntry* latestEntry = &logEntries[numLogs - 1];

    // Unlock the mutex and return the ID and index
    *id = latestEntry->id;
    *index = numLogs - 1;
    pthread_mutex_unlock(&mutex);
}

// Function to filter out logs older than 30 days based on current system time
void filterOldLogs() {
    // Lock the mutex to prevent concurrent writes
    pthread_mutex_lock(&mutex);

    // Get the current system time in seconds
    time_t now = time(NULL);

    // Iterate through the array of log entries and filter out logs older than 30 days
    for (int i = numLogs - 1; i >= 0; i--) {
        LogEntry* entry = &logEntries[i];
        if ((now - entry->startTime) / (24 * 60 * 60) > 30) {
            // Free the memory for the filtered log entry
            free(entry);

            // Shift all remaining log entries to fill the gap
            for (int j = i; j < numLogs - 1; j++) {
                logEntries[j] = logEntries[j + 1];
            }

            // Decrement the number of logs by one
            numLogs--;
        }
    }

    // Unlock the mutex and return
    pthread_mutex_unlock(&mutex);
}

