import java.util.*;
import java.security.*;

public class RandomValueGenerator {
    private KickstartConfig config;
    private Map<String, Range> ranges = new HashMap<>();
    private SecureRandom random;

    public RandomValueGenerator(KickstartConfig config) {
        this.config = config;
        this.random = new SecureRandom();
    }

    public void addRange(String name, int min, int max) {
        ranges.put(name, new Range(min, max));
    }

    public void removeRange(String name) {
        ranges.remove(name);
    }

    public int generateInteger(String rangeName) {
        return generateInteger(rangeName, false);
    }

    public int generateInteger(String rangeName, boolean exclusive) {
        Range range = ranges.get(rangeName);
        if (range == null) {
            throw new IllegalArgumentException("Range not found: " + rangeName);
        }
        return random.nextInt(range.max - range.min + 1) + range.min;
    }

    public float generateFloat(String rangeName) {
        return generateFloat(rangeName, false);
    }

    public float generateFloat(String rangeName, boolean exclusive) {
        Range range = ranges.get(rangeName);
        if (range == null) {
            throw new IllegalArgumentException("Range not found: " + rangeName);
        }
        return random.nextFloat() * (range.max - range.min) + range.min;
    }

    public void replacePlaceholders(Map<String, String> parameters) {
        config.replacePlaceholders(parameters);
    }

    public void appendEncryptedPassword(String password) {
        config.appendEncryptedPassword(password);
    }

    private class Range {
        int min;
