void insert_string(vector<string>& vec, const string& str1, const string& str2) {
    // Check if str1 is already in the vector
    auto it = find(vec.begin(), vec.end(), str1);
    if (it != vec.end()) {
        // Insert str2 after str1
        vec.insert(++it, str2);
    } else {
        // Insert str2 at the end of the vector
        vec.push_back(str2);
    }

    // Remove duplicates from the vector
    vec.erase(unique(vec.begin(), vec.end()), vec.end());
}
