    // Constructor
    SandeshClient(const string& ip, const string& port) : io_service(), resolver(io_service), socket(io_service), proxy_sessions() {
        this->ip = ip;
        this->port = port;
    }

    // Destructor
    ~SandeshClient() {
        for (auto& session : proxy_sessions) {
            session.second->close();
        }
    }

    // Connect to the Sandesh server
    void connect() {
        boost::asio::ip::tcp::resolver::query query(boost::asio::ip::tcp::v4(), ip, port);
        resolver.async_resolve(query, [this](const boost::system::error_code& ec, boost::asio::ip::tcp::resolver::iterator it) {
            if (!ec) {
                socket.async_connect(*it, [this](const boost::system::error_code& ec) {
                    if (!ec) {
                        // Start the proxy sessions
                        startProxySessions();
                    } else {
                        cout << "Error connecting to Sandesh server: " << ec.message() << endl;
                    }
                });
            } else {
                cout << "Error resolving Sandesh server address: " << ec.message() << endl;
            }
        });
    }

    // Start the proxy sessions
    void startProxySessions() {
        for (int i = 0; i < 10; ++i) {
            auto session = make_shared<boost::asio::ip::tcp::socket>(io_service);
            socket.async_accept(session, [this](const boost::system::error_code& ec) {
                if (!ec) {
                    // Handle the incoming request
                    handleRequest(session);
                } else {
                    cout << "Error accepting proxy session: " << ec.message() << endl;
                }
            });
        }
    }

    // Handle the incoming request
    void handleRequest(shared_ptr<boost::asio::ip::tcp::socket> socket) {
        boost::asio::streambuf request;
        boost::asio::async_read_until(socket, request, "\r\n", [this, socket](const boost::system::error_code& ec, size_t bytes_transferred) {
            if (!ec) {
                // Parse the incoming request
                string request_str = boost::asio::buffers_to_string(request.data());
                vector<string> tokens;
                boost::split(tokens, request_str, boost::is_any_of(" "));
                if (tokens[0] == "GET") {
                    // Handle GET requests
                    handleGetRequest(socket, tokens);
                } else if (tokens[0] == "POST") {
                    // Handle POST requests
                    handlePostRequest(socket, tokens);
                } else {
                    // Unsupported request method
                    sendErrorResponse(socket, 405);
                }
            } else {
                cout << "Error reading incoming request: " << ec.message() << endl;
            }
        });
    }

    // Handle GET requests
    void handleGetRequest(shared_ptr<boost::asio::ip::tcp::socket> socket, const vector<string>& tokens) {
        string path = tokens[1];
        if (path == "/") {
            // Send the root page
            sendResponse(socket, 200, "text/html", "<html><body>Hello World!</body></html>");
        } else {
            // Send a 404 response
            sendErrorResponse(socket, 404);
        }
    }

    // Handle POST requests
    void handlePostRequest(shared_ptr<boost::asio::ip::tcp::socket> socket, const vector<string>& tokens) {
        string path = tokens[1];
        if (path == "/") {
            // Send the root page
            sendResponse(socket, 200, "text/html", "<html><body>Hello World!</body></html>");
        } else {
            // Send a 404 response
            sendErrorResponse(socket, 404);
        }
    }

    // Send an error response
    void sendErrorResponse(shared_ptr<boost::asio::ip::tcp::socket> socket, int status) {
        string message = "HTTP/1.1 " + boost::lexical_cast<string>(status) + "\r\n";
        message += "Content-Type: text/html\r\n";
        message += "Connection: close\r\n";
        message += "\r\n";
        socket->async_send(boost::asio::buffer(message), [this, socket](const boost::system::error_code& ec, size_t bytes_transferred) {
            if (!ec) {
                // Close the connection
                socket->close();
            } else {
                cout << "Error sending error response: " << ec.message() << endl;
            }
        });
    }

    // Send a response
    void sendResponse(shared_ptr<boost::asio::ip::tcp::socket> socket, int status, const string& content_type, const string& body) {
        string message = "HTTP/1.1 " + boost::lexical_cast<string>(status) + "\r\n";
        message += "Content-Type: " + content_type + "\r\n";
        message += "Connection: close\r\n";
        message += "Content-Length: " + boost::lexical_cast<string>(body.size()) + "\r\n";
        message += "\r\n";
        message += body;
        socket->async_send(boost::asio::buffer(message), [this, socket](const boost::system::error_code& ec, size_t bytes_transferred) {
            if (!ec) {
                // Close the connection
                socket->close();
            } else {
                cout << "Error sending response: " << ec.message() << endl;
            }
        });
    }

private:
    boost::asio::io_service io_service;
    boost::asio::ip::tcp::resolver resolver;
    boost::asio::ip::tcp::socket socket;
    map<string, shared_ptr<boost::asio::ip::tcp::socket>> proxy_sessions;
};

