namespace RealTimeCommunicationSystem
{
    public class ConfigurationManager
    {
        private const int N = 1000; // Maximum number of PDUs to handle
        private List<NFAPI_CRC_INDICATION_PDU_T> _pduList = new List<NFAPI_CRC_INDICATION_PDU_T>(N);

        public void AddPdu(NFAPI_CRC_INDICATION_PDU_T pdu)
        {
            if (pdu.RX_UE_INFORMATION_TAG == 0 || pdu.RNTI == 0)
            {
                throw new ArgumentException("Invalid PDU", nameof(pdu));
            }

            // Check for duplicates
            foreach (var existingPdu in _pduList)
            {
                if (existingPdu.RX_UE_INFORMATION_TAG == pdu.RX_UE_INFORMATION_TAG && existingPdu.RNTI == pdu.RNTI)
                {
                    throw new ArgumentException("Duplicate PDU", nameof(pdu));
                }
            }

            _pduList.Add(pdu);
        }

        public void RemovePdu(NFAPI_CRC_INDICATION_PDU_T pdu)
        {
            if (pdu.RX_UE_INFORMATION_TAG == 0 || pdu.RNTI == 0)
            {
                throw new ArgumentException("Invalid PDU", nameof(pdu));
            }

            // Check for duplicates
            foreach (var existingPdu in _pduList)
            {
                if (existingPdu.RX_UE_INFORMATION_TAG == pdu.RX_UE_INFORMATION_TAG && existingPdu.RNTI == pdu.RNTI)
                {
                    _pduList.Remove(existingPdu);
                    return;
                }
            }
        }

        public void UpdatePdu(NFAPI_CRC_INDICATION_PDU_T oldPdu, NFAPI_CRC_INDICATION_PDU_T newPdu)
        {
            if (oldPdu.RX_UE_INFORMATION_TAG == 0 || oldPdu.RNTI == 0 || newPdu.RX_UE_INFORMATION_TAG == 0 || newPdu.RNTI == 0)
            {
                throw new ArgumentException("Invalid PDU", nameof(oldPdu));
            }

            // Check for duplicates
            foreach (var existingPdu in _pduList)
            {
                if (existingPdu.RX_UE_INFORMATION_TAG == oldPdu.RX_UE_INFORMATION_TAG && existingPdu.RNTI == oldPdu.RNTI)
                {
                    _pduList[existingPdu] = newPdu;
                    return;
                }
            }
        }

        public void PrintPdus(string filePath)
        {
            if (filePath == null)
            {
                throw new ArgumentNullException(nameof(filePath));
            }

            using (var writer = new StreamWriter(filePath))
            {
                foreach (var pdu in _pduList)
                {
                    writer.WriteLine($"{pdu.RX_UE_INFORMATION_TAG}, {pdu.RNTI}, {pdu.CRC_INDICATION_REL8_TAG}");
                }
            }
        }
    }
}
