const express = require('express');
const app = express();
const bodyParser = require('body-parser');
const cors = require('cors');
const axios = require('axios');

app.use(bodyParser.json());
app.use(cors());

// Define the resources collection
let resources = [];

// Define the update function
function updateResources(req, res) {
  // Get the unique identifier for each resource
  const ids = req.body.ids;

  // Update the resources in the collection
  ids.forEach((id) => {
    const index = resources.findIndex((resource) => resource.id === id);
    if (index !== -1) {
      resources[index] = Object.assign(resources[index], req.body.updates);
    } else {
      // If the resource is not found, add it to the collection
      resources.push({ id: id, ...req.body.updates });
    }
  });

  // Return a detailed status message and the number of affected resources
  res.status(200).json({
    message: `Updated ${ids.length} resource${ids.length > 1 ? 's' : ''}.`,
    affectedResources: ids.length,
  });
}

// Define the delete function
function deleteResources(req, res) {
  // Get the unique identifier for each resource
  const ids = req.body.ids;

  // Delete the resources from the collection
  ids.forEach((id) => {
    const index = resources.findIndex((resource) => resource.id === id);
    if (index !== -1) {
      resources.splice(index, 1);
    }
  });

  // Return a detailed status message and the number of affected resources
  res.status(200).json({
    message: `Deleted ${ids.length} resource${ids.length > 1 ? 's' : ''}.`,
    affectedResources: ids.length,
  });
}

// Define the API endpoint for updating resources
app.put('/resources', updateResources);

// Define the API endpoint for deleting resources
