namespace XMLParser
{
    public class XMLDocument
    {
        private XmlDocument _document;
        private XPathNavigator _navigator;

        public XMLDocument(string xml)
        {
            _document = new XmlDocument();
            _document.LoadXml(xml);
            _navigator = _document.CreateNavigator();
        }

        public XmlElement GetFirstElementByName(string name)
        {
            XPathExpression expression = _navigator.Compile("/" + name);
            XPathNodeIterator iterator = _navigator.Select(expression);
            if (iterator.MoveNext())
            {
                return (XmlElement)iterator.Current;
            }
            else
            {
                return null;
            }
        }

        public List<XmlElement> GetElementsByName(string name)
        {
            XPathExpression expression = _navigator.Compile("/" + name);
            XPathNodeIterator iterator = _navigator.Select(expression);
            List<XmlElement> elements = new List<XmlElement>();
            while (iterator.MoveNext())
            {
                elements.Add((XmlElement)iterator.Current);
            }
            return elements;
        }

        public bool Validate()
        {
            XmlReaderSettings settings = new XmlReaderSettings();
            settings.ValidationType = ValidationType.Schema;
            settings.Schemas.Add(null, "http://www.w3.org/2001/XMLSchema");
            using (XmlReader reader = XmlReader.Create(_document.OuterXml, settings))
            {
                while (reader.Read()) ;
            }
            return !settings.HasErrors;
        }

        public void Parse(string xml)
        {
            _document.LoadXml(xml);
            _navigator = _document.CreateNavigator();
        }

        public string Serialize()
        {
            StringBuilder builder = new StringBuilder();
            using (StringWriter writer = new StringWriter(builder))
            {
                XmlWriterSettings settings = new XmlWriterSettings();
                settings.Indent = true;
                settings.NewLineOnAttributes = false;
                settings.OmitXmlDeclaration = true;
                using (XmlWriter xmlWriter = XmlWriter.Create(writer, settings))
                {
                    _document.WriteTo(xmlWriter);
                }
            }
            return builder.ToString();
        }

        public void SetXPathExpression(string expression)
        {
            _navigator.Compile(expression);
        }

        public XmlElement GetFirstMatchingElement()
        {
            XPathExpression expression = _navigator.Compile(_navigator.NameTable.Add("//*"));
            XPathNodeIterator iterator = _navigator.Select(expression);
            if (iterator.MoveNext())
            {
                return (XmlElement)iterator.Current;
            }
            else
            {
                return null;
            }
        }

        public List<XmlElement> GetMatchingElements()
        {
            XPathExpression expression = _navigator.Compile(_navigator.NameTable.Add("//*"));
            XPathNodeIterator iterator = _navigator.Select(expression);
            List<XmlElement> elements = new List<XmlElement>();
            while (iterator.MoveNext())
            {
                elements.Add((XmlElement)iterator.Current);
            }
            return elements;
        }
    }
}
