function handleUserRequest($_REQUEST) {
    // Validate input data
    $name = validateInputData($_REQUEST['name'], 2, 50);
    $email = validateInputData($_REQUEST['email'], 'email');
    $password = validateInputData($_REQUEST['password'], 8);

    // Check if email is already in use by another user
    $isEmailInUse = checkIfEmailIsInUse($email);
    if ($isEmailInUse) {
        return json_encode([
            'message' => 'error',
            'details' => 'Email is already in use.'
        ]);
    }

    // Implement rate limiting
    $rateLimit = 10;
    $ipAddress = $_SERVER['REMOTE_ADDR'];
    if (checkRateLimit($ipAddress, $rateLimit)) {
        return json_encode([
            'message' => 'error',
            'details' => 'Too many requests. Please try again later.'
        ]);
    }

    // Log all actions performed on user accounts
    logAction($name, $email, $password, $subAction);

    // Use prepared statements to prevent SQL injection
    $db = new PDO('mysql:host=localhost;dbname=mydatabase', 'username', 'password');
    $stmt = $db->prepare("SELECT * FROM users WHERE id = :id");
    $stmt->bindParam(':id', $_REQUEST['id']);
    $stmt->execute();

    // Handle concurrent requests safely
    $lock = new Lock($db);
    $lock->acquire();

    try {
        if ($subAction == 'create') {
            createUserAccount($name, $email, $password);
        } elseif ($subAction == 'update') {
            updateUserAccount($_REQUEST['id'], $name, $email, $password);
        } elseif ($subAction == 'delete') {
            deleteUserAccount($_REQUEST['id']);
        }
    } catch (Exception $e) {
        // Handle database connection errors and retry the operation a maximum of three times before failing
        if ($lock->isLocked()) {
            $lock->release();
        }

        return json_encode([
            'message' => 'error',
            'details' => 'Database error. Please try again later.'
        ]);
    } finally {
        $lock->release();
    }

    // Integrate with an external API to send a welcome email upon account creation
    if ($subAction == 'create') {
        $emailService = new EmailService();
        $emailService->sendWelcomeEmail($name, $email);
    }

    return json_encode([
        'message' => 'success',
        'details' => 'User account updated successfully.'
    ]);
}

