const runTests = (moduleName, testCases) => {
  // Validate module name against whitelist to prevent path traversal attacks
  if (!isValidModuleName(moduleName)) {
    throw new Error(`Invalid module name: ${moduleName}`);
  }

  // Dynamically load the module using require
  const module = require(moduleName);

  // Initialize mocking library and reset blueslip after each test execution
  const blueslip = require('blueslip');
  let blueslipResetCount = 0;

  // Run each test in a separate environment using a sandboxed function to avoid side effects between tests
  const results = [];
  for (const testCase of testCases) {
    const testResult = runTest(testCase, module);
    blueslipResetCount++;
    results.push({
      label: testCase.label,
      passed: testResult.passed,
      errorMessage: testResult.errorMessage,
      blueslipResetCount: blueslipResetCount,
    });
  }

  // Log detailed information to the console
  console.log(`Module: ${moduleName}`);
  console.log(`Test cases: ${testCases.length}`);
  console.log(`Passed tests: ${results.filter(result => result.passed).length}`);
  console.log(`Failed tests: ${results.filter(result => !result.passed).length}`);
  console.log(`Skipped tests: ${results.filter(result => result.skipped).length}`);
  console.log(`Blueslip reset count: ${blueslipResetCount}`);

  // Return results object containing test results and blueslip reset count
  return {
    results,
    blueslipResetCount,
  };
};

