function refreshDialogFields(resourceId, url) {
let fieldNamesToRefresh = ['field1', 'field2', 'field3'];
let dialogFields = document.querySelectorAll('dialog-field');
for (let i = 0; i < dialogFields.length; i++) {
let fieldName = dialogFields[i].getAttribute('name');
if (fieldNamesToRefresh.includes(fieldName)) {
let message = {
type: 'refresh',
resourceId,
url,
fieldName
};
window.parent.postMessage(message, '*');
}
}
