#include <iostream>
#include <string>
#include <vector>
#include <cstdlib>
#include <ctime>
#include <chrono>
#include <fstream>
#include <sstream>
#include <iomanip>
#include <algorithm>

using namespace std;

// Define a structure to store NIC information
struct NetworkInterfaceConfiguration {
    string macAddress;
    string ipAddress;
    string subnetMask;
};

// Define a class for the Mersenne Twister algorithm
class NetworkRandomGenerator {
public:
    NetworkRandomGenerator() {
        // Initialize the random number generator with a seed value
        srand(time(0));
    }

    ~NetworkRandomGenerator() {}

    static int getRandomNumber(int min, int max) {
        return rand() % (max - min + 1) + min;
    }
};

// Define a function to dynamically allocate and return a new MAC address
string generateNewMacAddress() {
    // Use the Mersenne Twister algorithm to generate a random number between 0 and 255
    int randomNumber = NetworkRandomGenerator::getRandomNumber(0, 255);

    // Convert the random number to a hexadecimal string
    stringstream ss;
    ss << std::hex << randomNumber;

    // Return the MAC address as a string
    return "00:11:22:" + ss.str() + ":33:44";
}

// Define a function to handle errors gracefully and retry up to three times upon conflict detection
string generateNewMacAddressWithRetry(int maxRetries) {
    int retries = 0;
    string macAddress;

    while (retries < maxRetries) {
        try {
            // Generate a new MAC address using the Mersenne Twister algorithm
            macAddress = generateNewMacAddress();

            // Check if the generated MAC address is unique within the network segment
            if (!isMacAddressUnique(macAddress)) {
                // If not, retry up to three times
                retries++;
                continue;
            } else {
                // If yes, return the generated MAC address
                return macAddress;
            }
        } catch (const exception& e) {
            // Catch any exceptions and retry up to three times
            retries++;
            continue;
        }
    }

    // If all retries fail, return an empty string
    return "";
}

// Define a function to check if a MAC address is unique within the network segment
bool isMacAddressUnique(string macAddress) {
    // Check if the generated MAC address is already in use
    for (auto nic : nics) {
        if (nic.macAddress == macAddress) {
            return false;
        }
    }

    // If not, return true
    return true;
}

// Define a function to serialize a state object to a file using an ObjectOutputStream
void serializeStateObject(string filename, NetworkInterfaceConfiguration nic) {
    try {
        // Open the output file in binary mode
        ofstream outfile(filename, ios::binary);

        // Write the NIC information to the file
        outfile.write((char*)&nic, sizeof(NetworkInterfaceConfiguration));

        // Close the output file
        outfile.close();
    } catch (const exception& e) {
        // Catch any exceptions and print an error message
        cerr << "Error serializing state object: " << e.what() << endl;
    }
}

// Define a function to deserialize a state object from a file using an ObjectInputStream
NetworkInterfaceConfiguration deserializeStateObject(string filename) {
    NetworkInterfaceConfiguration nic;

    try {
        // Open the input file in binary mode
        ifstream infile(filename, ios::binary);

        // Read the NIC information from the file
        infile.read((char*)&nic, sizeof(NetworkInterfaceConfiguration));

        // Close the input file
        infile.close();
    } catch (const exception& e) {
        // Catch any exceptions and print an error message
        cerr << "Error deserializing state object: " << e.what() << endl;
    }

    return nic;
}

// Define a function to create and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
vector<NFAPI_CRC_INDICATION_PDU_T> createAndPopulateCrcIndicationPduList(int numElements) {
    vector<NFAPI_CRC_INDICATION_PDU_T> pduList;

    for (int i = 0; i < numElements; i++) {
        NFAPI_CRC_INDICATION_PDU_T pdu;

        // Set the RX_UE_INFORMATION_TAG and RNTI fields randomly
        pdu.rxUeInformationTag = NetworkRandomGenerator::getRandomNumber(0, 255);
        pdu.rnti = NetworkRandomGenerator::getRandomNumber(0, 65535);

        // Set the CRC_INDICATION_REL8_TAG field randomly
        pdu.crcIndicationRel8Tag = NetworkRandomGenerator::getRandomNumber(0, 255);

        // Add the PDU to the list
        pduList.push_back(pdu);
    }

    return pduList;
}

// Define a function to handle up to N performance metrics, ensuring proper memory management, error handling for allocation failures, and validating the uniqueness of timestamp values
void handlePerformanceMetrics(vector<NFAPI_CRC_INDICATION_PDU_T> pduList) {
    // Create a vector to store the unique timestamps
    vector<int64_t> timestamps;

    // Iterate over the PDU list and extract the timestamps
    for (auto pdu : pduList) {
        int64_t timestamp = pdu.timestamp;

        // Check if the timestamp is unique
        if (!contains(timestamps, timestamp)) {
            // If yes, add it to the vector
            timestamps.push_back(timestamp);
        } else {
            // If not, print an error message and continue
            cerr << "Duplicate timestamp detected: " << timestamp << endl;
        }
    }
}

// Define a function to support multiple output formats for bandwidth data, allowing conversion between bits per second and kilobits per second
void convertBandwidthData(vector<NFAPI_CRC_INDICATION_PDU_T> pduList) {
    // Iterate over the PDU list and convert the bandwidth data to kilobits per second
    for (auto pdu : pduList) {
        int64_t bandwidth = pdu.bandwidth;

        // Convert the bandwidth from bits per second to kilobits per second
        bandwidth /= 1024;

        // Print the converted bandwidth value
        cout << "Bandwidth: " << bandwidth << " kbps" << endl;
    }
}

