        performanceMetricValues[timestamp] = performanceMetrics;
    }

    // Iterate over the hash table and print the performance metric values for each timestamp
    for (auto it : performanceMetricValues) {
        int64_t timestamp = it.first;
        vector<int64_t> performanceMetrics = it.second;

        // Print the performance metric values for the current timestamp
        cout << "Timestamp: " << timestamp << endl;
        for (auto pm : performanceMetrics) {
            cout << "\t" << pm << endl;
        }
    }
}
