function asyncTraverseDOM(rootElement, filterCallback, paginationThreshold = 1000, apiUrl) {
  const filteredElements = [];
  let currentPage = 0;
  let totalPages = 0;
  let isPaginating = false;
  let isFetchingMetadata = false;
  let recentlyUpdatedElements = new Set();

  // Define a function to fetch metadata for each element
  const fetchMetadata = async (element) => {
    if (!isFetchingMetadata) {
      isFetchingMetadata = true;
      try {
        const response = await fetch(apiUrl + '/metadata/' + element.id);
        const data = await response.json();
        return data;
      } catch (error) {
        console.error('Error fetching metadata:', error);
      } finally {
        isFetchingMetadata = false;
      }
    }
  };

  // Define a function to filter elements based on dynamic conditions
  const filterElements = async (elements, pageNumber) => {
    if (!isPaginating) {
      isPaginating = true;
      try {
        const filteredPage = await Promise.all(
          elements.map((element) => {
            return new Promise((resolve, reject) => {
              filterCallback(element, (result) => {
                if (result) {
                  resolve(element);
                } else {
                  resolve(null);
                }
              });
            });
          })
        );
        return filteredPage;
      } catch (error) {
        console.error('Error filtering elements:', error);
      } finally {
        isPaginating = false;
      }
    }
  };

  // Define a function to paginate the filtered elements
  const paginateElements = async (filteredElements, pageNumber) => {
    if (!isPaginating) {
      isPaginating = true;
      try {
        const startIndex = pageNumber * paginationThreshold;
        const endIndex = Math.min(startIndex + paginationThreshold, filteredElements.length);
        return filteredElements.slice(startIndex, endIndex);
      } catch (error) {
        console.error('Error paginating elements:', error);
      } finally {
        isPaginating = false;
      }
    }
  };

  // Define a function to export the filtered elements in different formats
  const exportElements = async (filteredElements, format) => {
    if (!isFetchingMetadata) {
      isFetchingMetadata = true;
      try {
        switch (format) {
          case 'json':
            return JSON.stringify(filteredElements);
          case 'csv':
            const csvRows = filteredElements.map((element) => {
              return Object.values(element).join(',');
            });
            return csvRows.join('\n');
        }
      } catch (error) {
        console.error('Error exporting elements:', error);
      } finally {
        isFetchingMetadata = false;
      }
    }
  };

  // Define a function to handle real-time updates and optimize re-filtering
  const handleUpdates = async (element) => {
    if (!isPaginating && !isFetchingMetadata) {
      isPaginating = true;
