import java.util.HashMap;
import java.util.LinkedList;
import java.util.Map;
import java.util.Queue;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantLock;

public class ThemeCache {
    private static final int DEFAULT_CACHE_SIZE = 10;
    private static final int MIN_CACHE_SIZE = 5;
    private static final int MAX_CACHE_SIZE = 20;
    private static final int EVICTION_THRESHOLD = 80;
    private static final String DEFAULT_THEME_DIRECTORY = "themes";

    private Map<String, Theme> cache;
    private Queue<String> lruQueue;
    private Lock lock;

    public ThemeCache() {
        this.cache = new ConcurrentHashMap<>();
        this.lruQueue = new LinkedList<>();
        this.lock = new ReentrantLock();
    }

    public void init(String themeDirectory) {
        // Initialize the cache with the default theme directory
        this.themeDirectory = themeDirectory;
        this.cache = new ConcurrentHashMap<>();
        this.lruQueue = new LinkedList<>();
        this.lock = new ReentrantLock();
    }

    public void updateCache(String themeName, Theme theme) {
        // Update the cache with the latest theme packs from a remote server
        lock.lock();
        try {
            if (cache.containsKey(themeName)) {
                cache.put(themeName, theme);
            } else {
                cache.put(themeName, theme);
                lruQueue.add(themeName);
            }
        } finally {
            lock.unlock();
        }
    }

    public Theme getTheme(String themeName) {
        // Retrieve a theme from the cache based on its name
        lock.lock();
        try {
            if (cache.containsKey(themeName)) {
                lruQueue.remove(themeName);
                lruQueue.add(themeName);
                return cache.get(themeName);
            } else {
                return null;
            }
        } finally {
            lock.unlock();
        }
    }

    public void evictCache() {
        // Evict the least recently used theme from the cache if it exceeds the eviction threshold
        lock.lock();
        try {
            if (cache.size() > EVICTION_THRESHOLD) {
                String lruThemeName = lruQueue.poll();
                cache.remove(lruThemeName);
            }
        } finally {
            lock.unlock();
        }
    }

    public void updateLRUCache() {
        // Update the LRU queue with the latest theme usage information
        lock.lock();
        try {
            for (String themeName : cache.keySet()) {
                if (!lruQueue.contains(themeName)) {
                    lruQueue.add(themeName);
                }
            }
        } finally {
            lock.unlock();
        }
    }
}
```
This code implements a least recently used (LRU) cache eviction policy for managing theme caching in a mobile application. The `ThemeCache` class maintains a map of themes and their corresponding bitmaps, as well as an LRU queue to track the most frequently used themes. When a new theme is requested, it is added to the cache if it does not already exist, and its usage information is updated in the LRU queue. If the cache exceeds a specified threshold, the least recently used theme is evicted from the cache. The `updateCache` method updates the cache with the latest theme packs from a remote server, while the `getTheme` method retrieves a theme from the cache based on its name. The `evictCache` method evicts the least recently used theme from the cache if it exceeds the eviction threshold. The `updateLRUCache` method updates the LRU queue with the latest theme usage information.

The code also includes configuration options for adjusting the cache size based on current device memory constraints and prioritizing certain themes over others based on user preferences. The default cache size is set to 10, but it can be adjusted to a minimum of 5 and a maximum of 20. The eviction threshold is set to 80%, but it can be adjusted to prioritize certain themes over others based on user preferences.

The code uses a `ConcurrentHashMap` for the cache, which allows multiple concurrent requests to access the cache without conflicts. It also uses a `ReentrantLock` to ensure thread safety during theme retrieval and caching operations.']

