public class ServiceConfigurationManager {
    private static final int MAX_SERVICE_START_DELAY = 10000; // 10 seconds
    private static final String DEFAULT_MESSAGING_SYSTEM_ENDPOINT = "http://localhost:8080";

    private List<ServiceConfiguration> configurations;

    public ServiceConfigurationManager() {
        this.configurations = new CopyOnWriteArrayList<>();
    }

    public void addConfiguration(int serviceStartDelay, String serviceStopMessage, String messagingSystemEndpoint) {
        if (serviceStartDelay < 0 || serviceStartDelay > MAX_SERVICE_START_DELAY) {
            throw new IllegalArgumentException("Service start delay must be between 0 and " + MAX_SERVICE_START_DELAY);
        }

        if (!isValidMessagingSystemEndpoint(messagingSystemEndpoint)) {
            throw new IllegalArgumentException("Invalid messaging system endpoint");
        }

        ServiceConfiguration configuration = new ServiceConfiguration(serviceStartDelay, serviceStopMessage, messagingSystemEndpoint);
        configurations.add(configuration);
    }

    public void removeConfiguration(int serviceStartDelay) {
        if (serviceStartDelay < 0 || serviceStartDelay > MAX_SERVICE_START_DELAY) {
            throw new IllegalArgumentException("Service start delay must be between 0 and " + MAX_SERVICE_START_DELAY);
        }

        configurations.removeIf(configuration -> configuration.getServiceStartDelay() == serviceStartDelay);
    }

    public void startService(int serviceStartDelay) {
        if (serviceStartDelay < 0 || serviceStartDelay > MAX_SERVICE_START_DELAY) {
            throw new IllegalArgumentException("Service start delay must be between 0 and " + MAX_SERVICE_START_DELAY);
        }

        ServiceConfiguration configuration = configurations.stream()
                .filter(configuration -> configuration.getServiceStartDelay() == serviceStartDelay)
                .findFirst()
                .orElseThrow(() -> new IllegalArgumentException("No configuration found for service start delay " + serviceStartDelay));

        // Start the service and log a message to the messaging system endpoint
        System.out.println("Starting service with start delay " + serviceStartDelay);
        try {
            Thread.sleep(configuration.getServiceStartDelay());
        } catch (InterruptedException e) {
            e.printStackTrace();
        }
        logMessageToMessagingSystemEndpoint(configuration.getServiceStopMessage(), configuration.getMessagingSystemEndpoint());
    }

    public void stopService(int serviceStartDelay) {
        if (serviceStartDelay < 0 || serviceStartDelay > MAX_SERVICE_START_DELAY) {
            throw new IllegalArgumentException("Service start delay must be between 0 and " + MAX_SERVICE_START_DELAY);
        }

        ServiceConfiguration configuration = configurations.stream()
                .filter(configuration -> configuration.getServiceStartDelay() == serviceStartDelay)
                .findFirst()
                .orElseThrow(() -> new IllegalArgumentException("No configuration found for service start delay " + serviceStartDelay));

        // Stop the service and log a message to the messaging system endpoint
        System.out.println("Stopping service with start delay " + serviceStartDelay);
        try {
            Thread.sleep(configuration.getServiceStopMessage());
        } catch (InterruptedException e) {
            e.printStackTrace();
        }
        logMessageToMessagingSystemEndpoint(configuration.getServiceStopMessage(), configuration.getMessagingSystemEndpoint());
    }

    private boolean isValidMessagingSystemEndpoint(String messagingSystemEndpoint) {
        // TODO: Implement a more robust validation for the messaging system endpoint
        return true;
    }

    private void logMessageToMessagingSystemEndpoint(String message, String messagingSystemEndpoint) {
        // TODO: Implement a more efficient way of logging messages to the messaging system endpoint
        System.out.println("Logging message " + message + " to messaging system endpoint " + messagingSystemEndpoint);
    }
}
```
