use std::env;
use std::error::Error;
use std::process;

use tokio::net::TcpStream;
use tokio::prelude::*;
use tokio::time::{sleep, Duration};

struct HttpClient {
    client: reqwest::Client,
}

impl HttpClient {
    fn new() -> Self {
        let mut builder = reqwest::Client::builder();
        builder.danger_accept_invalid_certs(true);
        Self {
            client: builder.build().unwrap(),
        }
    }

    async fn get(&self, url: &str) -> Result<String, Box<dyn Error>> {
        let mut response = self.client.get(url).send().await?;
        let status = response.status();
        if !status.is_success() {
            return Err(format!("Request failed with status: {}", status).into());
        }
        Ok(response.text().await?)
    }

    async fn post(&self, url: &str, body: &[u8]) -> Result<String, Box<dyn Error>> {
        let mut response = self.client.post(url).body(body).send().await?;
        let status = response.status();
        if !status.is_success() {
            return Err(format!("Request failed with status: {}", status).into());
        }
        Ok(response.text().await?)
    }
}

struct RequestBuilder {
    url: String,
    headers: Vec<(String, String)>,
    body: Option<Vec<u8>>,
}

impl RequestBuilder {
    fn new(url: &str) -> Self {
        Self {
            url: url.to_string(),
            headers: vec![],
            body: None,
        }
    }

    fn add_header(&mut self, name: &str, value: &str) -> &mut Self {
        self.headers.push((name.to_string(), value.to_string()));
        self
    }

    fn set_body(&mut self, body: Vec<u8>) -> &mut Self {
        self.body = Some(body);
        self
    }

    async fn send(&self) -> Result<String, Box<dyn Error>> {
        let mut client = HttpClient::new();
        for (name, value) in self.headers.iter() {
            client = client.add_header(name, value);
        }
        match &self.body {
            Some(body) => client.post(&self.url, body).await?,
            None => client.get(&self.url).await?,
        };
        Ok("".to_string())
    }
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn Error>> {
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 {
        eprintln!("Usage: {} URL", args[0]);
        process::exit(1);
    }
    let url = &args[1];
    let request_builder = RequestBuilder::new(url).add_header("Content-Type", "application/json");
    match request_builder.send().await {
        Ok(response) => println!("Response: {}", response),
        Err(e) => eprintln!("Error: {}", e),
    }
    Ok(())
}
