};

// Octree class
class Octree {
 public:
  // Constructor
  Octree(int size) : size_(size), root_(nullptr) {}

  // Destructor
  ~Octree() { delete root_; }

  // Getter method for the size of the octree
  int getSize() const { return size_; }

  // Setter method for the size of the octree
  void setSize(int size) { size_ = size; }

  // Add a simulation entity to the octree
  void addEntity(int x, int y, int z, int attribute) {
    // Create a new node if necessary
    if (root_ == nullptr) {
      root_ = new OctreeNode(0, x, y, z);
    }

    // Find the appropriate child node for the entity
    OctreeNode* current = root_;
    while (current->getNumChildren() > 0) {
      int index = getChildIndex(x, y, z, current->getLevel());
      current = current->getChild(index);
    }

    // Add the entity to the child node
    OctreeNode* newNode = new OctreeNode(current->getLevel() + 1, x, y, z);
    newNode->setAttribute(attribute);
    current->addChild(newNode);
  }

  // Remove a simulation entity from the octree
  void removeEntity(int x, int y, int z) {
    // Find the appropriate child node for the entity
    OctreeNode* current = root_;
    while (current->getNumChildren() > 0) {
      int index = getChildIndex(x, y, z, current->getLevel());
      current = current->getChild(index);
    }

    // Remove the entity from the child node
    if (current->getAttribute() == x && current->getY() == y && current->getZ() == z) {
      current->setAttribute(-1);
    }
  }

  // Update a simulation entity in the octree
  void updateEntity(int x, int y, int z, int attribute) {
    // Find the appropriate child node for the entity
    OctreeNode* current = root_;
    while (current->getNumChildren() > 0) {
      int index = getChildIndex(x, y, z, current->getLevel());
      current = current->getChild(index);
    }

    // Update the entity in the child node
    if (current->getAttribute() == x && current->getY() == y && current->getZ() == z) {
      current->setAttribute(attribute);
    }
  }

  // Query the octree for entities within a given range
  std::vector<int> queryEntities(int x, int y, int z, int radius) {
    // Create a vector to store the results
    std::vector<int> results;

    // Find the appropriate child node for the query
    OctreeNode* current = root_;
    while (current->getNumChildren() > 0) {
      int index = getChildIndex(x, y, z, current->getLevel());
      current = current->getChild(index);
    }

    // Query the child node for entities within the given range
    queryEntitiesRecursive(current, x, y, z, radius, results);

    return results;
  }

 private:
  // Size of the octree
  int size_;

  // Root node of the octree
  OctreeNode* root_;

  // Get the index of the child node for a given coordinate and level
  int getChildIndex(int x, int y, int z, int level) {
    return (x >> (level * 3)) & 7;
  }

  // Recursive method to query entities within a given range
  void queryEntitiesRecursive(OctreeNode* node, int x, int y, int z, int radius, std::vector<int>& results) {
    // Check if the current node is within the given range
    if (node->getX() >= x - radius && node->getX() <= x + radius &&
        node->getY() >= y - radius && node->getY() <= y + radius &&
        node->getZ() >= z - radius && node->getZ() <= z + radius) {
      // Add the entity to the results vector
      results.push_back(node->getAttribute());
    }

    // Recursively query child nodes within the given range
    for (int i = 0; i < node->getNumChildren(); ++i) {
      OctreeNode* child = node->getChild(i);
      queryEntitiesRecursive(child, x, y, z, radius, results);
    }
  }
};
