pthread_mutex_t g_recommendation_cache_lock = PTHREAD_MUTEX_INITIALIZER;
semaphore_t g_recommendation_cache_semaphore = SEMAPHORE_INITIALIZER;

// Define the function to manage the real-time recommendation engine
void manage_recommendation_engine(struct User *user) {
    // Acquire the lock on the global recommendation cache
    pthread_mutex_lock(&g_recommendation_cache_lock);

    // Check if the user is already in the interaction window
    struct InteractionWindow *window = g_recommendation_cache.window;
    size_t i;
    for (i = 0; i < window->count; ++i) {
        if (window->users[i].user_id == user->user_id) {
            break;
        }
    }

    // If the user is not in the interaction window, add them
    if (i == window->count) {
        if (window->count < window->capacity) {
            window->users[window->count++] = *user;
        } else {
            // If the interaction window is full, remove the oldest user
            struct User *oldest_user = &window->users[0];
            size_t j;
            for (j = 1; j < window->capacity; ++j) {
                if (window->users[j].timestamp < oldest_user->timestamp) {
                    oldest_user = &window->users[j];
                }
            }
            *oldest_user = *user;
        }
    } else {
        // If the user is already in the interaction window, update their item ID and timestamp
        window->users[i].item_id = user->item_id;
        window->users[i].timestamp = user->timestamp;
    }

    // Check if the interaction window has expired
    time_t current_time = time(NULL);
    if (current_time - window->start_time > 300) {
        // If the interaction window has expired, reset it and update the highest engagement score
        struct InteractionWindow new_window;
        new_window.users = malloc(sizeof(struct User) * 5);
        new_window.capacity = 5;
        new_window.count = 0;
        new_window.start_time = current_time;
        new_window.end_time = current_time + 300;
        g_recommendation_cache.window = &new_window;
        g_recommendation_cache.highest_engagement_score = 0;
    }

    // Release the lock on the global recommendation cache
    pthread_mutex_unlock(&g_recommendation_cache_lock);
}

// Define the function to calculate the engagement score for a user in the current interaction window
int calculate_engagement_score(struct User *user) {
    // Calculate the total number of unique items interacted with by the user within the 5-minute window
    struct InteractionWindow *window = g_recommendation_cache.window;
    size_t i;
    int unique_items = 0;
    for (i = 0; i < window->count; ++i) {
        if (window->users[i].user_id == user->user_id) {
            break;
        }
    }
    size_t j;
    for (j = i + 1; j < window->count; ++j) {
        if (window->users[j].user_id == user->user_id && window->users[j].item_id != window->users[i].item_id) {
            unique_items++;
        }
    }

    // Calculate the engagement score based on the total number of unique items interacted with
    int engagement_score = 0;
    if (unique_items > 50) {
        engagement_score = 100 - (unique_items - 50);
    } else {
        engagement_score = 100 - unique_items;
    }

