}

// Define the function to update the global recommendation cache and metrics
void update_recommendation_cache(struct User *user) {
    // Acquire the lock on the global recommendation cache
    pthread_mutex_lock(&g_recommendation_cache_lock);

    // Update the highest engagement score and corresponding session ID if necessary
    int engagement_score = calculate_engagement_score(user);
    if (engagement_score > g_recommendation_cache.highest_engagement_score) {
        g_recommendation_cache.highest_engagement_score = engagement_score;
        g_recommendation_cache.session_id = user->session_id;
    }

    // Release the lock on the global recommendation cache
    pthread_mutex_unlock(&g_recommendation_cache_lock);
}

// Define the function to handle concurrent updates efficiently without data races or stale recommendations
void handle_concurrent_updates(struct User *user) {
    // Acquire the lock on the global recommendation cache
    pthread_mutex_lock(&g_recommendation_cache_lock);

    // Update the interaction window and highest engagement score if necessary
    update_recommendation_cache(user);

