        // If the event is outside the reset interval, use a more complex recency index calculation that takes into account user activity patterns over the past month
        double decay_rate = 0.95; // Adjust this value to control the rate at which the recency index decays over time
        int num_days = (time_diff - RESET_INTERVAL) / (24 * 3600);
        for (int i = 0; i < num_days; i++) {
            recency_index += decay_rate * pow(decay_rate, i);
