        list[i]->crc_indication.crc_flag = rand() % 2;
        list[i]->hash = NULL;
    }

    // Compute the MD5 hash of the provided string for each CRC indication
    for (int i = 0; i < num_indications; i++) {
        char *hash = md5(string);
        if (hash == NULL) {
