// Define the structure to store transaction data
typedef struct {
    int age;
    int num_transactions;
    double weighted_sum;
} Transaction;

// Define a function to parse a line from the log file and store it in a Transaction structure
Transaction* parse_transaction(char* line) {
    // Allocate memory for the transaction structure
    Transaction* transaction = malloc(sizeof(Transaction));
    if (transaction == NULL) {
        printf("Error: Failed to allocate memory for transaction\n");
        return NULL;
    }

    // Parse the line and store the fields in the transaction structure
    char* token = strtok(line, ",");
    while (token != NULL) {
        if (strcmp(token, "age") == 0) {
            transaction->age = atoi(strtok(NULL, ","));
        } else if (strcmp(token, "num_transactions") == 0) {
            transaction->num_transactions = atoi(strtok(NULL, ","));
        } else if (strcmp(token, "weighted_sum") == 0) {
            transaction->weighted_sum = atof(strtok(NULL, ","));
        }
        token = strtok(NULL, ",");
    }

    return transaction;
}

// Define a function to filter transactions based on the specified criteria
void filter_transactions(Transaction* transactions, int num_transactions) {
    // Initialize the set of metrics and the maximum weighted sum
    double max_weighted_sum = 0.0;
    int max_transaction_id = -1;
    int num_valid_transactions = 0;

    // Iterate over each transaction and filter based on the specified criteria
    for (int i = 0; i < num_transactions; i++) {
        Transaction* transaction = transactions + i;
        if (transaction->age >= 18 && transaction->num_transactions <= 3 && transaction->weighted_sum > max_weighted_sum) {
            max_weighted_sum = transaction->weighted_sum;
            max_transaction_id = i;
        }
    }

    // Print the maximum weighted sum and corresponding transaction ID
    printf("Maximum weighted sum: %f\n", max_weighted_sum);
    printf("Corresponding transaction ID: %d\n", max_transaction_id);
}

// Define a function to calculate the average of the last two numerical values in the age and weighted sum fields
void calculate_average(Transaction* transaction) {
    // Calculate the average of the last two numerical values in the age field
    int num_ages = 0;
    double total_age = 0.0;
    for (int i = 1; i < 3; i++) {
        if (transaction->age[i] != '\0') {
            num_ages++;
            total_age += transaction->age[i];
        }
    }
    double average_age = num_ages > 0 ? total_age / num_ages : 0.0;

    // Calculate the average of the last two numerical values in the weighted sum field
    int num_weighted_sums = 0;
    double total_weighted_sum = 0.0;
    for (int i = 1; i < 3; i++) {
        if (transaction->weighted_sum[i] != '\0') {
            num_weighted_sums++;
            total_weighted_sum += transaction->weighted_sum[i];
        }
    }
    double average_weighted_sum = num_weighted_sums > 0 ? total_weighted_sum / num_weighted_sums : 0.0;

    // Print the calculated averages
    printf("Average age: %f\n", average_age);
    printf("Average weighted sum: %f\n", average_weighted_sum);
}

// Define a function to print each transaction's processed fields in a comma-separated format
void print_transaction(Transaction* transaction) {
    // Print the transaction ID and age
    printf("%d,", transaction->age);

    // Print the number of transactions in the past 3 seconds
    printf("%d,", transaction->num_transactions);

    // Print the weighted sum
    printf("%f,", transaction->weighted_sum);

    // Print the calculated average of the last two numerical values in the age and weighted sum fields
    calculate_average(transaction);
}

// Define a function to handle file I/O operations and error handling
void handle_file_io(FILE* file, char* filename) {
    // Check if the file can be read
    if (file == NULL) {
        printf("Error: Failed to open file %s\n", filename);
        return;
    }

    // Read each line from the file and parse it into a Transaction structure
    char* line = malloc(sizeof(char) * 1024);
    while (fgets(line, 1024, file) != NULL) {
        Transaction* transaction = parse_transaction(line);
        if (transaction == NULL) {
            printf("Error: Failed to parse transaction\n");
            continue;
        }

        // Filter transactions based on the specified criteria
        filter_transactions(transaction, 1);

        // Print each transaction's processed fields in a comma-separated format
        print_transaction(transaction);
    }

    // Free dynamically allocated memory
    free(line);
}

// Define a function to integrate with an external system that expects the output in a specific JSON format
void generate_json(Transaction* transactions, int num_transactions) {
    // Allocate memory for the JSON output buffer
    char* json = malloc(sizeof(char) * 1024);
    if (json == NULL) {
        printf("Error: Failed to allocate memory for JSON output\n");
        return;
    }

    // Iterate over each transaction and generate the JSON output
    for (int i = 0; i < num_transactions; i++) {
        Transaction* transaction = transactions + i;
        sprintf(json, "{\"age\": %d, \"num_transactions\": %d, \"weighted_sum\": %f}", transaction->age, transaction->num_transactions, transaction->weighted_sum);
    }

    // Print the JSON output
    printf("%s\n", json);

    // Free dynamically allocated memory
    free(json);
}

int main() {
    // Define the input file name and open it for reading
    char* filename = "transactions.log";
    FILE* file = fopen(filename, "r");

    // Handle file I/O operations and error handling
    handle_file_io(file, filename);

    // Generate the JSON output
    generate_json(transactions, num_transactions);

    return 0;
}
