#define MAX_CRC_INDICATIONS 10000
#define MEMORY_POOL_SIZE (MAX_CRC_INDICATIONS * sizeof(NFAPI_CRC_INDICATION_PDU_T))

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rx_ue_information_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
    uint32_t crcflag;
    char* hash;
} NFAPI_CRC_INDICATION_PDU_T;

void generate_crc_indications(char* string) {
    // Create a custom memory pool to manage resources efficiently
    void* memory_pool = malloc(MEMORY_POOL_SIZE);
    if (!memory_pool) {
        printf("Error: Failed to allocate memory for CRC indications\n");
        return;
    }

    // Initialize the list of CRC indications
    NFAPI_CRC_INDICATION_PDU_T* crc_indications = (NFAPI_CRC_INDICATION_PDU_T*)memory_pool;
    size_t num_crc_indications = 0;

    // Compute the MD5 hash of the provided string and store it in each structure
    while (num_crc_indications < MAX_CRC_INDICATIONS) {
        NFAPI_CRC_INDICATION_PDU_T* crc_indication = &crc_indications[num_crc_indications];
        crc_indication->rx_ue_information_tag = RX_UE_INFORMATION_TAG;
        crc_indication->rnti = rand();
        crc_indication->crc_indication_rel8_tag = CRC_INDICATION_REL8_TAG;
        crc_indication->crcflag = rand() % 2;
        crc_indication->hash = md5(string);
        num_crc_indications++;
    }

    // Free the memory pool when it is no longer needed
    free(memory_pool);
}
