        array->capacity *= 2;
        array->data = (LTE_PHY_RX_FRAME_T*)realloc(array->data, sizeof(LTE_PHY_RX_FRAME_T) * array->capacity);
        assert(array->data != NULL);
    }

    // Add the new frame to the end of the array
    array->data[array->size++] = frame;
}

