        frames->capacity = new_capacity;
    }

    // Insert the new frame into the array
    size_t index = frames->count++;
    LTE_PHY_RX_FRAME_T *frame = &(frames->frames[index]);
    frame->dl_ccch = dl_ccch;
    frame->rrc_cnas = rrc_cnas;
    frame->payload = payload;

    // Release the mutex to allow other threads to access the array
    pthread_mutex_unlock(&mutex);
}

// Delete a frame from the dynamic array
void delete_frame(LTE_PHY_RX_FRAMES_T *frames, size_t index) {
    // Acquire the mutex to protect the array from concurrent access
    pthread_mutex_lock(&mutex);

    // Check if the specified index is valid
    if (index >= frames->count) {
        // Release the mutex and return
        pthread_mutex_unlock(&mutex);
        return;
    }

    // Delete the frame from the array
    LTE_PHY_RX_FRAME_T *frame = &(frames->frames[index]);
    free(frame->dl_ccch);
    free(frame->rrc_cnas);
    free(frame->payload);
    frames->count--;

    // Shift the remaining frames down to fill the gap
    for (size_t i = index; i < frames->count; i++) {
        LTE_PHY_RX_FRAME_T *src = &(frames->frames[i + 1]);
        LTE_PHY_RX_FRAME_T *dst = &(frames->frames[i]);
        dst->dl_ccch = src->dl_ccch;
        dst->rrc_cnas = src->rrc_cnas;
        dst->payload = src->payload;
    }

    // Release the mutex to allow other threads to access the array
    pthread_mutex_unlock(&mutex);
}

// Resize the dynamic array while minimizing performance impact during resizing operations
void resize_frames(LTE_PHY_RX_FRAMES_T *frames, size_t new_capacity) {
    // Acquire the mutex to protect the array from concurrent access
    pthread_mutex_lock(&mutex);

    // Check if the new capacity is smaller than the current capacity
    if (new_capacity < frames->capacity) {
        // Release the mutex and return
        pthread_mutex_unlock(&mutex);
        return;
    }

    // Reallocate the array with the new capacity
    LTE_PHY_RX_FRAME_T **new_frames = realloc(frames->frames, new_capacity * sizeof(LTE_PHY_RX_FRAME_T*));
    if (new_frames == NULL) {
        // Handle memory allocation failure
        pthread_mutex_unlock(&mutex);
        return;
    }
    frames->frames = new_frames;
    frames->capacity = new_capacity;

    // Release the mutex to allow other threads to access the array
    pthread_mutex_unlock(&mutex);
}

