    pduList = malloc(len * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (pduList == NULL) {
        fprintf(stderr, "Failed to allocate memory for PDU list\n");
        goto error;
    }

    // Iterate over the nodes in the nodeset and populate the PDUs
    for (i = 0; i < len; ++i) {
        xmlNodePtr node = xmlXPathNodeSetItem(nodeset, i);
        NFAPI_CRC_INDICATION_PDU_T *pdu = &pduList[i];

        // Set the RX_UE_INFORMATION_TAG and RNTI fields
        pdu->RX_UE_INFORMATION_TAG = (char *)node->name;
        pdu->RNTI = atoi((const char *)xmlGetProp(node, "RNTI"));

        // Set the CRC_INDICATION_REL8_TAG field
        xmlNodePtr rel8Node = xmlChildElement(node, "CRC_INDICATION_REL8");
        if (rel8Node != NULL) {
            pdu->CRC_INDICATION_REL8_TAG = (char *)rel8Node->name;
        } else {
            fprintf(stderr, "Failed to find CRC_INDICATION_REL8 node\n");
            goto error;
        }

        // Set the CRCFLAG field
        xmlNodePtr crcFlagNode = xmlChildElement(rel8Node, "CRCFLAG");
        if (crcFlagNode != NULL) {
            pdu->CRCFLAG = atoi((const char *)xmlGetProp(crcFlagNode, "CRCFLAG"));
        } else {
            fprintf(stderr, "Failed to find CRCFLAG node\n");
            goto error;
        }

        // Compute the MD5 hash of the RX_UE_INFORMATION node
        xmlNodePtr rxUeInfoNode = xmlChildElement(node, "RX_UE_INFORMATION");
        if (rxUeInfoNode != NULL) {
            unsigned char md5Hash[MD5_DIGEST_LENGTH];
            MD5_CTX ctx;
            MD5_Init(&ctx);
            MD5_Update(&ctx, xmlGetProp(rxUeInfoNode, "RNTI"), strlen((const char *)xmlGetProp(rxUeInfoNode, "RNTI")));
            MD5_Final(md5Hash, &ctx);
            memcpy(pdu->MD5Hash, md5Hash, MD5_DIGEST_LENGTH);
        } else {
            fprintf(stderr, "Failed to find RX_UE_INFORMATION node\n");
            goto error;
        }
    }

error:
    // Free the XPath context and nodeset
