    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
    unsigned char md5[MD5_DIGEST_LENGTH];
} NFAPI_CRC_INDICATION_PDU_T;

void parse_and_generate_crc_indications(const xmlChar *xml, size_t len) {
    // Initialize the memory pool allocator
    xmlMemSetup();

    // Create an XPath context for parsing the XML document
    xmlXPathContextPtr xpathCtx = xmlXPathNewContext(NULL);

    // Set up the XPath expression for selecting the relevant nodes in the XML document
    const char *xpathExpr = "/nfapi/crc-indication-rel8";
    xmlXPathObjectPtr xpathObj = xmlXPathEvalExpression(xpathExpr, xpathCtx);

    // Iterate over the selected nodes and create a list of NFAPI_CRC_INDICATION_PDU_T structures
    size_t numNodes = xpathObj->nodesetval->nodeNr;
    NFAPI_CRC_INDICATION_PDU_T *crcIndications = malloc(numNodes * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    for (size_t i = 0; i < numNodes; i++) {
        xmlNodePtr node = xpathObj->nodesetval->nodeTab[i];

        // Parse the relevant nodes within the current node and populate the NFAPI_CRC_INDICATION_PDU_T structure
        RX_UE_INFORMATION_TAG rxUeInformationTag;
        RNTI rnti;
        CRC_INDICATION_REL8_TAG crcIndicationRel8Tag;
        xmlNodePtr node1 = xmlChildElement(node, "rx-ue-information");
        xmlNodePtr node2 = xmlChildElement(node1, "rnti");
        xmlNodePtr node3 = xmlChildElement(node2, "crc-indication-rel8");
        xmlNodePtr node4 = xmlChildElement(node3, "crci");
        xmlNodePtr node5 = xmlChildElement(node4, "crc-flag");
        xmlNodePtr node6 = xmlChildElement(node5, "random");
        sscanf(xmlGetProp(node1, "tag"), "%d", &rxUeInformationTag);
        sscanf(xmlGetProp(node2, "tag"), "%d", &rnti);
        sscanf(xmlGetProp(node3, "tag"), "%d", &crcIndicationRel8Tag);
        sscanf(xmlGetProp(node4, "tag"), "%d", &crci);
        sscanf(xmlGetProp(node5, "tag"), "%d", &crcFlag);
        sscanf(xmlGetProp(node6, "tag"), "%d", &random);

        // Compute the MD5 hash of the current node's content and store it in the NFAPI_CRC_INDICATION_PDU_T structure
        xmlChar *content = xmlNodeGetContent(node);
        unsigned char md5[MD5_DIGEST_LENGTH];
        MD5((unsigned char *)content, strlen(content), md5);
        crcIndications[i].md5 = md5;

        // Free the memory allocated for the current node's content
        xmlFree(content);
    }

    // Clean up the XPath context and return the list of NFAPI_CRC_INDICATION_PDU_T structures
    xmlXPathFreeObject(xpathObj);
    xmlXPathFreeContext(xpathCtx);
    return crcIndications;
}
