// Caching mechanism for frequently accessed XML nodes
struct NodeCache {
    char* node;
    int hash;
};

// Random value generator class
class RandomValueGenerator {
private:
    int seed;
    int min;
    int max;

public:
    // Constructor with inclusive boundaries
    RandomValueGenerator(int min, int max) {
        this->min = min;
        this->max = max;
        this->seed = time(NULL);
    }

    // Overloaded method for generating random integers
    int generateRandomInt() {
        return rand_r(&this->seed) % (this->max - this->min + 1) + this->min;
    }

    // Overloaded method for generating random floats
    float generateRandomFloat() {
        return ((float)rand_r(&this->seed)) / RAND_MAX * (this->max - this->min) + this->min;
    }

    // Method for setting a custom seed
    void setSeed(int seed) {
        this->seed = seed;
    }
};

// Function to parse and generate CRC indications
NFAPI_CRC_INDICATION_PDU_T* parse_and_generate_crc_indications(char* xml, int len) {
    // Initialize the list of CRC indications
    NFAPI_CRC_INDICATION_PDU_T* crc_indications = NULL;

    // Create a cache for frequently accessed XML nodes
    struct NodeCache* node_cache = (struct NodeCache*)malloc(sizeof(struct NodeCache) * len);
    memset(node_cache, 0, sizeof(struct NodeCache) * len);

    // Initialize the random value generator with inclusive boundaries
    RandomValueGenerator rvg(1, 256);

    // Iterate through each XML node and generate CRC indications
    for (int i = 0; i < len; i++) {
        char* node = xml + i * sizeof(char);
        int hash = md5_hash(node, strlen(node));

        // Check if the node is already in the cache
        bool found = false;
        for (int j = 0; j < len; j++) {
            if (node_cache[j].hash == hash) {
                found = true;
                break;
            }
        }

        // If the node is not in the cache, add it to the list and compute its MD5 hash
        if (!found) {
            crc_indications = (NFAPI_CRC_INDICATION_PDU_T*)realloc(crc_indications, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (i + 1));
            NFAPI_CRC_INDICATION_PDU_T* crc_indication = &crc_indications[i];

            // Parse the XML node using XPath
            char* rx_ue_information_tag = xpath_query(node, "//RX_UE_INFORMATION_TAG");
            if (rx_ue_information_tag) {
                crc_indication->rx_ue_information_tag = strdup(rx_ue_information_tag);
            } else {
                // Handle exception gracefully
                printf("Error parsing XML node: %s\n", node);
                continue;
            }

            char* rnti = xpath_query(node, "//RNTI");
            if (rnti) {
                crc_indication->rnti = strdup(rnti);
            } else {
                // Handle exception gracefully
                printf("Error parsing XML node: %s\n", node);
                continue;
            }

            char* crc_indication_rel8_tag = xpath_query(node, "//CRC_INDICATION_REL8_TAG");
            if (crc_indication_rel8_tag) {
                crc_indication->crc_indication_rel8_tag = strdup(crc_indication_rel8_tag);
            } else {
                // Handle exception gracefully
                printf("Error parsing XML node: %s\n", node);
                continue;
            }

            // Generate a random CRCFLAG value within the specified range
            crc_indication->crcflag = rvg.generateRandomInt();

            // Add the node to the cache
            node_cache[i].node = node;
            node_cache[i].hash = hash;
        }
    }

    // Free the cache and return the list of CRC indications
    free(node_cache);
    return crc_indications;
}
