// Define NAS message structure
typedef struct {
    uint8_t opcode;
    uint16_t length;
    uint8_t* data;
} NAS_MESSAGE_T;

// Define NAS summary report structure
typedef struct {
    uint32_t message_count;
    uint32_t average_size;
    bool error_occured;
} NAS_SUMMARY_REPORT_T;

int process_nas_messages(NAS_MESSAGE_T** messages, int message_count) {
    // Initialize summary report array
    NAS_SUMMARY_REPORT_T* reports = (NAS_SUMMARY_REPORT_T*)malloc(sizeof(NAS_SUMMARY_REPORT_T) * 256);
    if (!reports) {
        // Log error and return -1 on memory allocation failure
        printf("Error: Failed to allocate memory for NAS summary reports\n");
        return -1;
    }

    // Iterate over messages and categorize them based on opcode
    for (int i = 0; i < message_count; i++) {
        NAS_MESSAGE_T* message = messages[i];
        uint8_t opcode = message->opcode;

        // Update summary report for current opcode
        reports[opcode].message_count++;
        reports[opcode].average_size += message->length;

        // Check for error occurrences and log them
        if (message->error_occured) {
            printf("Error: NAS message with opcode %d encountered an error\n", opcode);
            reports[opcode].error_occured = true;
        }
    }

    // Detect and log unusual message patterns that might indicate protocol anomalies
    for (int i = 0; i < 256; i++) {
        if (reports[i].message_count > 10 && reports[i].average_size > 100) {
            printf("Warning: Unusual NAS message pattern detected with opcode %d\n", i);
        }
    }

    // Return summary report array
    return reports;
}
