    RealTimeMonitoringSystem* monitoring_system;

public:
    RandomSequenceGenerator(size_t cache_capacity, size_t distributed_cache_capacity) {
        cache = (SequenceCache*)malloc(sizeof(SequenceCache));
        cache->sequences = (RandomSequence**)malloc(sizeof(RandomSequence*) * cache_capacity);
        cache->capacity = cache_capacity;
        cache->count = 0;

        distributed_cache = (DistributedSequenceCache*)malloc(sizeof(DistributedSequenceCache));
        distributed_cache->sequences = (RandomSequence**)malloc(sizeof(RandomSequence*) * distributed_cache_capacity);
        distributed_cache->capacity = distributed_cache_capacity;
        distributed_cache->count = 0;

        monitoring_system = (RealTimeMonitoringSystem*)malloc(sizeof(RealTimeMonitoringSystem));
    }

