    RandomSequence* generateSequence(size_t length, const char* characters) {
        // Check if the requested sequence is already in the cache
        for (size_t i = 0; i < cache->count; i++) {
            if (cache->sequences[i]->length == length && strcmp(cache->sequences[i]->sequence, characters) == 0) {
                return cache->sequences[i];
            }
        }

        // If the requested sequence is not in the cache, generate a new one
        RandomSequence* sequence = (RandomSequence*)malloc(sizeof(RandomSequence));
        sequence->sequence = (char*)malloc(length + 1);
        sequence->length = length;

        for (size_t i = 0; i < length; i++) {
            size_t index = rand() % strlen(characters);
            sequence->sequence[i] = characters[index];
        }
        sequence->sequence[length] = '\0';

        // Add the generated sequence to the cache
        if (cache->count < cache->capacity) {
            cache->sequences[cache->count++] = sequence;
        } else {
            // If the cache is full, evict the least recently used sequence
            size_t lru_index = 0;
            for (size_t i = 1; i < cache->count; i++) {
                if (cache->sequences[i]->last_accessed < cache->sequences[lru_index]->last_accessed) {
