#include <stdio.h>
#include <openssl/sha.h>

typedef struct {
    char *source_ip;
    char *dest_ip;
    int protocol;
    unsigned long sequence_number;
    unsigned char hash[SHA256_DIGEST_LENGTH];
} packet_metadata;

packet_metadata process_packet_metadata(char *packet, char *string) {
    packet_metadata metadata = {NULL};

    // Extract and validate metadata fields from the packet header
    metadata.source_ip = (char *)packet + 12;
    metadata.dest_ip = (char *)packet + 16;
    metadata.protocol = *(int *)(packet + 20);
    metadata.sequence_number = *(unsigned long *)(packet + 24);

    // Compute SHA-256 hash of the provided string parameter
    unsigned char hash[SHA256_DIGEST_LENGTH];
    SHA256_CTX ctx;
    SHA256_Init(&ctx);
    SHA256_Update(&ctx, string, strlen(string));
    SHA256_Final(hash, &ctx);

    // Store the hash within the metadata structure
    memcpy(metadata.hash, hash, SHA256_DIGEST_LENGTH);

    return metadata;
}
```
