struct MemoryPool {
    struct Node *head;
};

struct Node {
    void *data;
    struct Node *next;
};

void initMemoryPool(struct MemoryPool *pool) {
    pool->head = NULL;
}

void *allocate(struct MemoryPool *pool, size_t size) {
    struct Node *node = malloc(sizeof(struct Node));
    node->data = malloc(size);
    node->next = pool->head;
    pool->head = node;
    return node->data;
