#include <stdlib.h>
#include <string.h>
#include <openssl/sha.h>
#include <pthread.h>

// Custom memory pool for managing dynamic allocations
struct MemoryPool {
    void* data;
    size_t size;
};

// Packet metadata structure
struct Metadata {
    char* sourceIP;
    char* destIP;
    int protocolType;
    unsigned long sequenceNumber;
    unsigned char hash[SHA256_DIGEST_LENGTH];
};

// Process a packet by extracting and validating metadata fields
void processPacketMetadata(const void* packet, size_t length) {
    // Allocate memory for the metadata structure on the heap
    struct Metadata* metadata = malloc(sizeof(struct Metadata));
    if (!metadata) {
        printf("Error: Failed to allocate memory for metadata\n");
        return;
    }

    // Extract and validate metadata fields from the packet header
    const char* sourceIP = (const char*)packet + 12;
    const char* destIP = (const char*)packet + 16;
    int protocolType = *(const int*)packet;
    unsigned long sequenceNumber = *(const unsigned long*)packet;
    const char* stringParam = "This is a test string";

    // Compute SHA-256 hash of the provided string parameter asynchronously
    pthread_t thread;
    if (pthread_create(&thread, NULL, computeHash, stringParam)) {
        printf("Error: Failed to create thread for hash computation\n");
        free(metadata);
        return;
    }

    // Wait for the hash computation to complete
    void* result = NULL;
    pthread_join(thread, &result);
    if (!result) {
        printf("Error: Failed to compute hash\n");
        free(metadata);
        return;
    }

    // Copy the computed hash into the metadata structure
    memcpy(metadata->hash, result, SHA256_DIGEST_LENGTH);

    // Free the memory allocated for the hash computation result
    free(result);

    // Populate the rest of the metadata structure with extracted values
    metadata->sourceIP = sourceIP;
    metadata->destIP = destIP;
    metadata->protocolType = protocolType;
    metadata->sequenceNumber = sequenceNumber;

    // Log the packet processing time for performance analysis
    struct timespec start, end;
    clock_gettime(CLOCK_MONOTONIC, &start);

    // Process the packet using the extracted metadata
    processPacket(metadata);

    clock_gettime(CLOCK_MONOTONIC, &end);
    printf("Processing time: %ld ns\n", (end.tv_sec - start.tv_sec) * 1000000000 + end.tv_nsec - start.tv_nsec);

    // Free the memory allocated for the metadata structure
    free(metadata);
}

// Custom hash computation function using OpenSSL
void* computeHash(const void* string) {
    unsigned char* result = malloc(SHA256_DIGEST_LENGTH);
    if (!result) {
        printf("Error: Failed to allocate memory for hash computation\n");
        return NULL;
    }

    SHA256((const unsigned char*)string, strlen(string), result);

    return result;
}

// Process a packet using the extracted metadata
void processPacket(struct Metadata* metadata) {
    // Implement packet processing logic here
    printf("Processing packet with source IP %s and destination IP %s\n", metadata->sourceIP, metadata->destIP);
}
