        messages[i] = message;
    }

    // Process the NAS messages concurrently
    pthread_t* threads = (pthread_t*)malloc(sizeof(pthread_t) * message_count);
    if (!threads) {
        printf("Failed to allocate memory for %d thread handles\n", message_count);
        return 1;
    }
    for (int i = 0; i < message_count; i++) {
        pthread_create(&threads[i], NULL, process_nas_messages, messages + i);
