        NAS_SUMMARY_REPORT_T* report = reports + i;
        printf("NAS message type %d: count=%d, average size=%lu, error count=%d\n", i, report->count, report->average_size / report->count, report->error_count);
    }

    // Free the NAS messages and summary reports
    for (int i = 0; i < message_count; i++) {
        free(messages[i]);
    }
