// Define the function to process and analyze transactions
TRANSACTION_REPORT_T* batch_process_and_analyze_transactions(TRANSACTION_T** transactions, int transaction_count, size_t report_size) {
    // Initialize the report buffer
    TRANSACTION_REPORT_T* reports = (TRANSACTION_REPORT_T*)malloc(report_size * sizeof(TRANSACTION_REPORT_T));
    if (!reports) {
        return NULL;
    }

    // Initialize the transaction processing semaphore
    sem_t* transaction_sem = sem_open("transaction_sem", O_CREAT, 0644, 1);
    if (transaction_sem == SEM_FAILED) {
        free(reports);
        return NULL;
    }

    // Initialize the thread pool for concurrent transaction processing
    pthread_t* threads = (pthread_t*)malloc(sizeof(pthread_t) * transaction_count);
    if (!threads) {
        sem_close(transaction_sem);
        free(reports);
        return NULL;
    }

    // Initialize the thread pool for concurrent transaction processing
    pthread_attr_t* attr = (pthread_attr_t*)malloc(sizeof(pthread_attr_t));
    if (!attr) {
        sem_close(transaction_sem);
        free(threads);
        free(reports);
        return NULL;
    }

    // Set the thread attributes for the transaction processing threads
    pthread_attr_init(attr);
    pthread_attr_setdetachstate(attr, PTHREAD_CREATE_JOINABLE);

    // Create a thread for each transaction to process
    for (int i = 0; i < transaction_count; i++) {
        TRANSACTION_T* transaction = transactions[i];
        pthread_create(&threads[i], attr, process_transaction, (void*)transaction);
    }

    // Wait for all threads to complete
    for (int i = 0; i < transaction_count; i++) {
        pthread_join(threads[i], NULL);
    }

    // Close the transaction processing semaphore
    sem_close(transaction_sem);

    // Free the thread pool and attributes
    free(attr);
    free(threads);

    return reports;
}

// Define the function to process a single transaction
void* process_transaction(void* arg) {
    TRANSACTION_T* transaction = (TRANSACTION_T*)arg;

    // Acquire the transaction processing semaphore
    if (sem_wait(transaction_sem) == -1) {
        return NULL;
    }

    // Process the transaction and analyze its type
    int transaction_type = transaction->transaction_type;
    float amount = transaction->amount;
    char* transaction_type_str = "Unknown";
    switch (transaction_type) {
        case 1:
            transaction_type_str = "Credit";
            break;
        case 2:
            transaction_type_str = "Debit";
            break;
        default:
            break;
    }

    // Update the report for this transaction type
    TRANSACTION_REPORT_T* report = (TRANSACTION_REPORT_T*)malloc(sizeof(TRANSACTION_REPORT_T));
    if (!report) {
        sem_post(transaction_sem);
        return NULL;
    }
    report->transaction_count = 1;
    report->total_amount = amount;
    report->transaction_type = transaction_type_str;

    // Release the transaction processing semaphore
    sem_post(transaction_sem);

    return (void*)report;
}
