    int transaction_type;
    float amount;
} TRANSACTION_T;

// Define the transaction types
#define TRANSACTION_TYPE_DEPOSIT 0
#define TRANSACTION_TYPE_WITHDRAWAL 1
#define TRANSACTION_TYPE_TRANSFER 2

// Define the transaction categories
#define TRANSACTION_CATEGORY_DEPOSITS 0
#define TRANSACTION_CATEGORY_WITHDRAWALS 1
#define TRANSACTION_CATEGORY_TRANSFERS 2

