    int category;
    float total_amount;
    int frequency;
} TRANSACTION_ANALYSIS_T;

// Define the transaction processing function
void batch_process_and_analyze_transactions(TRANSACTION_T *transactions, int num_transactions) {
    // Initialize the transaction analysis structure
    TRANSACTION_ANALYSIS_T *transaction_analysis = (TRANSACTION_ANALYSIS_T *)malloc(sizeof(TRANSACTION_ANALYSIS_T) * 3);
    memset(transaction_analysis, 0, sizeof(TRANSACTION_ANALYSIS_T) * 3);

    // Initialize the semaphore for concurrent access to shared resources
    sem_t *sem = sem_open("/batch_process_and_analyze_transactions", O_CREAT, 0644, 1);

    // Process each transaction in parallel
    #pragma omp parallel for schedule(dynamic)
    for (int i = 0; i < num_transactions; i++) {
        TRANSACTION_T *transaction = &transactions[i];

        // Acquire the semaphore to prevent concurrent access to shared resources
        sem_wait(sem);

        // Analyze the transaction type and category
        int transaction_type = transaction->transaction_type;
        int transaction_category = 0;
        if (transaction_type == TRANSACTION_TYPE_DEPOSIT) {
            transaction_category = TRANSACTION_CATEGORY_DEPOSITS;
        } else if (transaction_type == TRANSACTION_TYPE_WITHDRAWAL) {
            transaction_category = TRANSACTION_CATEGORY_WITHDRAWALS;
        } else if (transaction_type == TRANSACTION_TYPE_TRANSFER) {
            transaction_category = TRANSACTION_CATEGORY_TRANSFERS;
        }

        // Update the transaction analysis structure
        transaction_analysis[transaction_category].total_amount += transaction->amount;
        transaction_analysis[transaction_category].frequency++;

        // Release the semaphore to allow other threads to access shared resources
        sem_post(sem);
    }

    // Close the semaphore
    sem_close(sem);

    // Print the transaction analysis results
    printf("Transaction Analysis Results:\n");
    for (int i = 0; i < 3; i++) {
        TRANSACTION_ANALYSIS_T *analysis = &transaction_analysis[i];
        printf("Category: %d\n", i);
        printf("Total Amount: %.2f\n", analysis->total_amount);
        printf("Frequency: %d\n", analysis->frequency);
    }

    // Clean up the transaction analysis structure
    free(transaction_analysis);
}
