// Define the function to generate and populate a list of CRC indications
void generate_crc_indications(char* string, int num_structures) {
    // Allocate memory for the list of structures on the heap
    NFAPI_CRC_INDICATION_PDU_T* crc_indications = (NFAPI_CRC_INDICATION_PDU_T*)malloc(num_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Initialize the list of structures with random values for RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG
    srand(time(NULL));
    for (int i = 0; i < num_structures; i++) {
        crc_indications[i].rx_ue_information_tag = rand() % 65535;
        crc_indications[i].rnti = rand() % 4294967295;
        crc_indications[i].crc_indication_rel8_tag = rand() % 255;
    }

    // Compute the MD5 hash of the provided string and store it in each structure
    for (int i = 0; i < num_structures; i++) {
