                sleep(pow(2, attempt));
                if (validate_crc_indication(crc_indications[i])) {
                    break;
                }
                attempt++;
            }
            // If all attempts fail, free the allocated memory and return
            if (attempt > 3) {
                for (int i = 0; i < num_structures; i++) {
                    free(crc_indications[i].md5_hash);
                }
                free(crc_indications);
                return;
            }
        }
    }

    // Limit the rate at which new structures are added to the list to prevent overload
    int num_structures_created = 0;
    while (num_structures_created < num_structures) {
        if (get_heap_usage() <= 50) {
            crc_indications[num_structures_created].md5_hash = malloc(16);
            MD5((unsigned char*)string, strlen(string), crc_indications[num_structures_created].md5_hash);
            num_structures_created++;
        } else {
            sleep(1);
        }
    }

    // Monitor memory usage and pause structure creation if necessary
    while (get_heap_usage() >= 50) {
        sleep(60);
    }

    // Log detailed metrics about structure generation and hash computation
