parsed_data_t* parse_and_generate_crc_indications(const xmlChar *xml, size_t len) {
    // Create an XPath context for the XML document
    xmlXPathContextPtr xpathCtx = xmlXPathNewContext(xml);
    if (xpathCtx == NULL) {
        fprintf(stderr, "Failed to create XPath context\n");
        return NULL;
    }

    // Set the namespace for the XML document
    xmlXPathRegisterNs(xpathCtx, BAD_CAST "nfapi", BAD_CAST "http://www.nfapi.org/schema/nfapi/3.0/nfapiConfig.xsd");

    // Define the XPath expression for the RX UE information tag
    xmlChar *rxUeInfoExpr = BAD_CAST "/nfapi:nfapiConfig/nfapi:rfInterface/nfapi:rfInterfaces/nfapi:rfInterface/nfapi:rxUEInformation";

    // Define the XPath expression for the RNTI tag
    xmlChar *rntiExpr = BAD_CAST "./nfapi:rnti";

    // Define the XPath expression for the CRC indication rel8 tag
    xmlChar *crcIndRel8Expr = BAD_CAST "./nfapi:crcIndication/nfapi:crcIndicationRel8";

    // Define the XPath expression for the CRCFLAG tag
    xmlChar *crcFlagExpr = BAD_CAST "./nfapi:crcIndication/nfapi:crcIndicationRel8/nfapi:crcFlag";

    // Create a list to store the parsed data
    parsed_data_t *parsedDataList = NULL;

    // Iterate over each RX UE information tag in the XML document
    xmlNodePtr rxUeInfoNode = xpathCtx->node;
    while (rxUeInfoNode != NULL) {
        // Get the RNTI value for the current node
        xmlChar *rntiValue = xmlGetProp(rxUeInfoNode, rntiExpr);

        // Get the CRC indication rel8 tag for the current node
        xmlNodePtr crcIndRel8Node = xmlXPathNodeEval(rxUeInfoNode, crcIndRel8Expr, xpathCtx);

        // Get the CRCFLAG value for the current node
        xmlChar *crcFlagValue = xmlGetProp(crcIndRel8Node, crcFlagExpr);

        // Create a new structure to store the parsed data
        parsed_data_t *parsedData = malloc(sizeof(parsed_data_t));
        if (parsedData == NULL) {
            fprintf(stderr, "Failed to allocate memory for parsed data\n");
            return NULL;
        }

        // Initialize the structure with the parsed data
        parsedData->pdu.rxUeInformation = rxUeInfoNode;
        parsedData->pdu.rnti = atoi(rntiValue);
        parsedData->pdu.crcIndicationRel8.crcFlag = atoi(crcFlagValue);

        // Compute the MD5 hash of the current node's content
        xmlChar *nodeContent = xmlNodeGetContent(rxUeInfoNode);
        unsigned char md5Hash[MD5_DIGEST_LENGTH];
        MD5((unsigned char *)nodeContent, strlen(nodeContent), md5Hash);
        parsedData->hash = malloc(sizeof(char) * (MD5_DIGEST_LENGTH * 2 + 1));
        if (parsedData->hash == NULL) {
            fprintf(stderr, "Failed to allocate memory for hash\n");
            return NULL;
        }
        sprintf(parsedData->hash, "%02x%02x%02x%02x%02x%02x%02x%02x%02x%02x%02x%02x%02x%02x%02x%02x",
                md5Hash[0], md5Hash[1], md5Hash[2], md5Hash[3], md5Hash[4], md5Hash[5], md5Hash[6], md5Hash[7],
                md5Hash[8], md5Hash[9], md5Hash[10], md5Hash[11], md5Hash[12], md5Hash[13], md5Hash[14], md5Hash[15]);

        // Add the structure to the list of parsed data
        parsedDataList = realloc(parsedDataList, sizeof(parsed_data_t) * (numParsedData + 1));
        if (parsedDataList == NULL) {
            fprintf(stderr, "Failed to allocate memory for parsed data list\n");
            return NULL;
        }
        parsedDataList[numParsedData++] = *parsedData;

        // Free the memory allocated for the node content and hash
        free(nodeContent);
        free(parsedData->hash);
    }

    // Free the XPath context
    xmlXPathFreeContext(xpathCtx);

    return parsedDataList;
}
