// Define a function to update the database table with a new status, last modified IP address, and last modified date for a given clinic ID
function updateDatabase($clinicId, $status, $lastModifiedIpAddress, $lastModifiedDate) {
    // Establish a secure connection to the database
    $conn = mysqli_connect("localhost", "my_user", "my_password", "my_db");

    // Check for errors in establishing the connection
    if (mysqli_connect_errno()) {
        echo "Failed to connect to MySQL: " . mysqli_connect_error();
    }

    // Prepare an SQL query to update the table with the new status and last modified date
    $query = "UPDATE clinic SET status = ?, last_modified_ip_address = ?, last_modified_date = ? WHERE clinic_id = ?";

    // Execute the query with the given parameters
    $stmt = mysqli_prepare($conn, $query);
    mysqli_stmt_bind_param($stmt, "sssi", $status, $lastModifiedIpAddress, $lastModifiedDate, $clinicId);
    mysqli_stmt_execute($stmt);

    // Handle any potential errors gracefully
    if (mysqli_error($conn)) {
        echo "Error updating database: " . mysqli_error($conn);
    }

    // Return a success message if the update is successful
    return "Update successful.";
}
