        return false;
    }

    // Add the new connection to the pool
    $db_pool[] = $db;

    // Return the new connection
    return $db;
}

// Function to close a connection from the pool
function close_connection($db) {
    global $db_pool;

    // Check if the connection is in the pool
    foreach ($db_pool as $key => $value) {
        if ($value === $db) {
            unset($db_pool[$key]);
            break;
        }
    }
}
