typedef struct {
    int count;
    NFAPI_RRC_CU_UP_PDU_T *list;
} NFAPI_RRC_CU_UP_PDU_LIST_T;

// Define a mutex to protect the list of NFAPI_RRC_CU_UP_PDU_T structures from concurrent access
pthread_mutex_t nfapi_rrc_cu_up_pdu_list_mutex = PTHREAD_MUTEX_INITIALIZER;

// Define a function to add an NFAPI_RRC_CU_UP_PDU_T structure to the list
void nfapi_rrc_cu_up_pdu_add(NFAPI_RRC_CU_UP_PDU_T *pdu) {
    pthread_mutex_lock(&nfapi_rrc_cu_up_pdu_list_mutex);
    NFAPI_RRC_CU_UP_PDU_LIST_T *list = (NFAPI_RRC_CU_UP_PDU_LIST_T *)malloc(sizeof(NFAPI_RRC_CU_UP_PDU_LIST_T));
    list->count++;
    list->list = (NFAPI_RRC_CU_UP_PDU_T *)realloc(list->list, sizeof(NFAPI_RRC_CU_UP_PDU_T) * list->count);
    memcpy(&list->list[list->count - 1], pdu, sizeof(NFAPI_RRC_CU_UP_PDU_T));
    pthread_mutex_unlock(&nfapi_rrc_cu_up_pdu_list_mutex);
}

// Define a function to remove an NFAPI_RRC_CU_UP_PDU_T structure from the list
void nfapi_rrc_cu_up_pdu_remove(NFAPI_RRC_CU_UP_PDU_T *pdu) {
    pthread_mutex_lock(&nfapi_rrc_cu_up_pdu_list_mutex);
    NFAPI_RRC_CU_UP_PDU_LIST_T *list = (NFAPI_RRC_CU_UP_PDU_LIST_T *)malloc(sizeof(NFAPI_RRC_CU_UP_PDU_LIST_T));
    for (int i = 0; i < list->count; i++) {
        if (memcmp(&list->list[i], pdu, sizeof(NFAPI_RRC_CU_UP_PDU_T)) == 0) {
            memcpy(&list->list[i], &list->list[list->count - 1], sizeof(NFAPI_RRC_CU_UP_PDU_T));
            list->count--;
            break;
        }
    }
    pthread_mutex_unlock(&nfapi_rrc_cu_up_pdu_list_mutex);
}

// Define a function to retrieve an NFAPI_RRC_CU_UP_PDU_T structure from the list by its ID
NFAPI_RRC_CU_UP_PDU_T *nfapi_rrc_cu_up_pdu_get(int id) {
    pthread_mutex_lock(&nfapi_rrc_cu_up_pdu_list_mutex);
    NFAPI_RRC_CU_UP_PDU_LIST_T *list = (NFAPI_RRC_CU_UP_PDU_LIST_T *)malloc(sizeof(NFAPI_RRC_CU_UP_PDU_LIST_T));
    for (int i = 0; i < list->count; i++) {
        if (list->list[i].id == id) {
            return &list->list[i];
        }
    }
    pthread_mutex_unlock(&nfapi_rrc_cu_up_pdu_list_mutex);
    return NULL;
}
