#define MAX_STRUCTURES 100
#define MIN_DELAY 1000 // milliseconds
#define MAX_DELAY 30000 // milliseconds
#define LOG_FILENAME "crc_indications.log"
#define LOG_ROTATION_INTERVAL 86400 // seconds (24 hours)
#define MEMORY_LIMIT 50 // percentage of available memory

typedef struct {
    uint16_t rx_ue_information_tag;
    uint32_t rnti;
    uint8_t crc_indication_rel8_tag;
    bool crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

void generate_crc_indications(char *string) {
    // Initialize variables
    int i, j;
    uint16_t rx_ue_information_tag = 0;
    uint32_t rnti = 0;
    uint8_t crc_indication_rel8_tag = 0;
    bool crcflag = false;
    char *hash_string = NULL;
    unsigned char hash[MD5_DIGEST_LENGTH];
    struct timespec start, end;
    double elapsed;
    int log_fd = -1;
    int log_file_size = 0;
    int log_rotation_count = 0;
    bool memory_exceeded = false;
    bool validation_failed = false;
    NFAPI_CRC_INDICATION_PDU_T *crc_indications[MAX_STRUCTURES];

    // Generate random RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG values
    srand(time(NULL));
    for (i = 0; i < MAX_STRUCTURES; i++) {
        rx_ue_information_tag = rand() % 65535 + 1;
        rnti = rand() % 4294967295 + 1;
        crc_indication_rel8_tag = rand() % 255 + 1;
        crcflag = (rand() % 2) ? true : false;
        crc_indications[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!crc_indications[i]) {
            perror("malloc");
            exit(EXIT_FAILURE);
        }
        crc_indications[i]->rx_ue_information_tag = rx_ue_information_tag;
        crc_indications[i]->rnti = rnti;
        crc_indications[i]->crc_indication_rel8_tag = crc_indication_rel8_tag;
        crc_indications[i]->crcflag = crcflag;
    }

    // Calculate MD5 hash of provided string parameter
    hash_string = malloc(strlen(string) + 1);
    if (!hash_string) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }
    strcpy(hash_string, string);
    MD5((unsigned char *)hash_string, strlen(hash_string), hash);

    // Validate generated CRC indications against network settings
    for (i = 0; i < MAX_STRUCTURES; i++) {
        if (!validate_crc_indication(crc_indications[i], hash)) {
            validation_failed = true;
            break;
        }
    }

    // Retry validation up to three times with exponentially increasing delays between attempts
    int retry_count = 0;
    while (validation_failed && retry_count < 3) {
        sleep(pow(2, retry_count));
        for (i = 0; i < MAX_STRUCTURES; i++) {
            if (!validate_crc_indication(crc_indications[i], hash)) {
                validation_failed = true;
                break;
            }
        }
        retry_count++;
    }

    // Fail gracefully if validation fails after all retries
    if (validation_failed) {
        fprintf(stderr, "Validation failed for generated CRC indications\n");
        exit(EXIT_FAILURE);
    }

    // Monitor memory usage and pause structure creation if necessary
    struct rusage usage;
    getrusage(RUSAGE_SELF, &usage);
    if (usage.ru_maxrss > MEMORY_LIMIT * 1024) {
        fprintf(stderr, "Memory limit exceeded\n");
        memory_exceeded = true;
    }

    // Log detailed metrics about structure generation and hash computation
    log_fd = open(LOG_FILENAME, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd == -1) {
        perror("open");
        exit(EXIT_FAILURE);
    }
    clock_gettime(CLOCK_REALTIME, &start);
    for (i = 0; i < MAX_STRUCTURES; i++) {
        fprintf(log_fd, "%ld.%09ld %d %u %u %u %u\n", start.tv_sec, start.tv_nsec, i + 1, crc_indications[i]->rx_ue_information_tag, crc_indications[i]->rnti, crc_indications[i]->crc_indication_rel8_tag, crc_indications[i]->crcflag);
        log_file_size += strlen(hash_string) + 1;
    }
    clock_gettime(CLOCK_REALTIME, &end);
    elapsed = (double)(end.tv_sec - start.tv_sec) + (double)(end.tv_nsec - start.tv_nsec) / 1000000000;
    fprintf(log_fd, "Elapsed time: %.3lf seconds\n", elapsed);
    close(log_fd);

    // Rotate log files daily and archive old logs for at least one month
    struct statvfs fs_stats;
    if (statvfs("/", &fs_stats) == -1) {
        perror("statvfs");
        exit(EXIT_FAILURE);
    }
    log_rotation_count = log_file_size / (fs_stats.f_bsize * fs_stats.f_frsize);
    if (log_rotation_count > LOG_ROTATION_INTERVAL) {
        char archive_filename[256];
        snprintf(archive_filename, sizeof(archive_filename), "%s.%d", LOG_FILENAME, log_rotation_count);
        rename(LOG_FILENAME, archive_filename);
    }

    // Free memory dynamically allocated for CRC indications and hash string
    for (i = 0; i < MAX_STRUCTURES; i++) {
        free(crc_indications[i]);
    }
    free(hash_string);
}

