#include <openssl/aes.h>
#include <openssl/evp.h>
#include <openssl/sha.h>

// Function to initialize an AES-256-CBC cipher with a given password
EVP_CIPHER_CTX* init_cipher(const char* password) {
    // Create a new EVP_CIPHER_CTX structure
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();

    // Set the cipher type and mode
    EVP_CipherInit(ctx, EVP_aes_256_cbc(), NULL, NULL, 1);

    // Generate a random initialization vector (IV)
    unsigned char iv[16];
    RAND_bytes(iv, sizeof(iv));

    // Set the IV length to 16 bytes
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_SET_IVLEN, sizeof(iv), NULL);

    // Set the key length to 32 bytes
    unsigned char key[32];
    SHA1(password, strlen(password), key);

    // Set the encryption key
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_SET_KEY, sizeof(key), key);

    // Enable the cipher
    EVP_CipherInit(ctx, NULL, NULL, NULL, 1);

    return ctx;
}
