    EVP_CIPHER_CTX_set_iv_length(ctx, 16);
    EVP_EncryptInit_ex(ctx, NULL, NULL, password, strlen(password));
    return ctx;
}

void cleanup_aes_cbc(void* ctx) {
    // Disable AES-256-CBC cipher when no longer needed
    EVP_CIPHER_CTX_free((EVP_CIPHER_CTX*)ctx);
}

nfapi_crc_indication_pdu_t* generate_crc_indication(const char* password) {
    // Generate and populate NFAPI_CRC_INDICATION_PDU_T structure with valid RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG
    nfapi_crc_indication_pdu_t* pdu = (nfapi_crc_indication_pdu_t*)malloc(sizeof(nfapi_crc_indication_pdu_t));
    pdu->rx_ue_information_tag = 0x1;
    pdu->rnti = 0x1234;
    pdu->crc_indication_rel8_tag = 0x2;
    pdu->crcflag = true;

    // Calculate MD5 hash of provided string parameter and store it within the structure
    unsigned char md5[MD5_DIGEST_LENGTH];
    MD5((unsigned char*)password, strlen(password), md5);
    memcpy(pdu->md5, md5, MD5_DIGEST_LENGTH);

    return pdu;
}
