        _httpClient = new HttpClient();
        _databaseUrl = databaseUrl;
    }

    public async Task<DataTableReader> ExecuteQueryAsync(byte[] query, CancellationToken cancellationToken = default) {
        // Establish connection to the database server
        using var httpResponseMessage = await _httpClient.PostAsync(_databaseUrl, new ByteArrayContent(query), cancellationToken);

        // Handle failed database operations with retry logic
        if (!httpResponseMessage.IsSuccessStatusCode) {
            int attempt = 0;
            while (attempt < 3 && !httpResponseMessage.IsSuccessStatusCode) {
                await Task.Delay(Math.Pow(2, attempt++));
                httpResponseMessage = await _httpClient.PostAsync(_databaseUrl, new ByteArrayContent(query), cancellationToken);
            }
        }

        // Handle response from the database server and retrieve result as DataTableReader object
        if (httpResponseMessage.IsSuccessStatusCode) {
            var responseStream = await httpResponseMessage.Content.ReadAsStreamAsync();
            return new DataTableReader(responseStream);
        } else {
            throw new Exception("Failed to execute query");
        }
    }
}
