void update_database(int clinic_id, int status, char *last_modified_ip, time_t last_modified_date) {
    // Create a connection pool to the database
    CONNECTION_POOL *pool = create_connection_pool();
    if (!pool) {
        printf("Error: Failed to create connection pool\n");
        return;
    }

    // Get a connection from the pool
    MYSQL *conn = get_connection(pool);
    if (!conn) {
        printf("Error: Failed to get connection from pool\n");
        destroy_connection_pool(pool);
        return;
