    if (mysql_query(conn, query)) {
        printf("Error: Failed to update database table\n");
        destroy_connection_pool(pool);
        return;
    }

    // Close the connection to the database
    mysql_close(conn);

    // Destroy the connection pool
    destroy_connection_pool(pool);
}

// Function to create a connection pool to the database
CONNECTION_POOL* create_connection_pool() {
    // Allocate memory for the connection pool
    CONNECTION_POOL *pool = (CONNECTION_POOL*)malloc(sizeof(CONNECTION_POOL));
    if (!pool) {
        printf("Error: Failed to allocate memory for connection pool\n");
        return NULL;
    }

    // Initialize the number of connections in the pool
    pool->num_connections = 0;

    // Allocate memory for the array of connections
    pool->connections = (MYSQL**)malloc(sizeof(MYSQL*) * MAX_CONNECTIONS);
    if (!pool->connections) {
        printf("Error: Failed to allocate memory for connection array\n");
        free(pool);
        return NULL;
    }

    // Initialize the connections in the pool
    for (int i = 0; i < MAX_CONNECTIONS; i++) {
        pool->connections[i] = mysql_init(NULL);
        if (!pool->connections[i]) {
            printf("Error: Failed to initialize connection\n");
            free(pool->connections);
            free(pool);
            return NULL;
        }
    }

    // Return the connection pool
    return pool;
}

// Function to get a connection from the connection pool
MYSQL* get_connection(CONNECTION_POOL *pool) {
    // Check if there are any available connections in the pool
    for (int i = 0; i < MAX_CONNECTIONS; i++) {
        if (!pool->connections[i]) {
            continue;
        }

        // Return an available connection from the pool
        return pool->connections[i];
    }

    // If no connections are available, create a new one and add it to the pool
    MYSQL *conn = mysql_init(NULL);
    if (!conn) {
        printf("Error: Failed to initialize connection\n");
        return NULL;
    }

    // Add the new connection to the pool
    for (int i = 0; i < MAX_CONNECTIONS; i++) {
        if (!pool->connections[i]) {
            pool->connections[i] = conn;
            return conn;
        }
    }

    // If no connections are available, destroy the new connection and return NULL
    mysql_close(conn);
    return NULL;
}

// Function to destroy a connection pool
void destroy_connection_pool(CONNECTION_POOL *pool) {
    // Check if the pool is valid
    if (!pool) {
        return;
    }

    // Close and free all connections in the pool
    for (int i = 0; i < MAX_CONNECTIONS; i++) {
        if (pool->connections[i]) {
            mysql_close(pool->connections[i]);
            free(pool->connections[i]);
        }
    }

    // Free the array of connections
    free(pool->connections);

    // Free the connection pool structure
    free(pool);
}
