    for (int i = 0; i < n; i++) {
        list[i].rx_ue_information_tag = rand() % 1000;
        list[i].rnti = rand() % 1000000;
        list[i].crc_indication_rel8_tag = rand() % 1000;
        list[i].crcflag = rand() % 2;
    }

    return list;
}

// Process a batch of strings and return their respective MD5 hashes in a list
void process_strings(char **strings, int n) {
    // Allocate memory for the output list
    unsigned char *hashes = (unsigned char *)malloc(sizeof(unsigned char) * n * 16);
    if (hashes == NULL) {
        printf("Error: unable to allocate memory for hashes\n");
        return;
    }

    // Process each string in the batch
    for (int i = 0; i < n; i++) {
        unsigned char *hash = get_hash(strings[i]);
        if (hash == NULL) {
            printf("Error: unable to calculate hash for string %d\n", i);
            return;
        }
        memcpy(&hashes[i * 16], hash, 16);
    }

    // Free the memory for the input strings
    for (int i = 0; i < n; i++) {
        free(strings[i]);
    }

    // Return the list of hashes
    return hashes;
}

// Update a database table with a new status, last modified IP address, and last modified date for a given clinic ID
void update_database(int clinic_id, int status, char *last_modified_ip, time_t last_modified_date) {
    // Open the database connection pool
    pthread_mutex_lock(&connection_pool_mutex);
    if (connection_pool == NULL) {
        printf("Error: unable to open database connection\n");
        return;
    }

    // Update the database table with the new status, last modified IP address, and last modified date for the given clinic ID
    char *query = "UPDATE clinics SET status = ?, last_modified_ip = ?, last_modified_date = ? WHERE clinic_id = ?";
    int result = sqlite3_exec(connection_pool, query, NULL, NULL, &error);
    if (result != SQLITE_OK) {
        printf("Error: unable to update database table\n");
        return;
    }

    // Close the database connection pool
    pthread_mutex_unlock(&connection_pool_mutex);
}

