                              SCORE_WEIGHT_POPULARITY * num_unique_items / 50 +
                              SCORE_WEIGHT_ENGAGEMENT * interaction_window.engagement_score;

    // Update the cache and interaction window structures
    cache_entry_t *cache_entry = malloc(sizeof(cache_entry_t));
