    cache.entries[cache.size++] = cache_entry;

    interaction_window.engagement_score += engagement_score;

    // Update the database table with a new status, last modified IP address, and last modified date for the given clinic ID
    int retries = 0;
    while (retries < MAX_RETRIES) {
        try {
            // Connect to the database using a connection pool
            connection_pool_t *connection_pool = get_connection_pool();
            pthread_mutex_lock(&connection_pool->locks[user_id % CONNECTION_POOL_SIZE]);
            while (connection_pool->num_free_connections == 0) {
                pthread_cond_wait(&connection_pool->conditions[user_id % CONNECTION_POOL_SIZE], &connection_pool->locks[user_id % CONNECTION_POOL_SIZE]);
            }
            connection_pool_entry_t *connection = connection_pool->connections[user_id % CONNECTION_POOL_SIZE];

            // Update the database table with a new status, last modified IP address, and last modified date for the given clinic ID
            char query[1024];
            sprintf(query, "UPDATE recommendation_engine SET status = 'active', last_modified_ip = '%s', last_modified_date = NOW() WHERE user_id = %d AND session_id = %d AND item_id = '%s'", inet_ntoa(connection->addr.sin_addr), user_id, session_id, item_id);
            if (mysql_query(connection->conn, query)) {
                printf("Error updating database table: %s\n", mysql_error(connection->conn));
                return ERROR_DATABASE_ERROR;
            }

            // Release the connection back to the pool
            pthread_mutex_unlock(&connection_pool->locks[user_id % CONNECTION_POOL_SIZE]);
            pthread_cond_signal(&connection_pool->conditions[user_id % CONNECTION_POOL_SIZE]);
        } catch (const std::exception &e) {
            printf("Error updating database table: %s\n", e.what());
            return ERROR_DATABASE_ERROR;
        }
    }

    // Return the highest engagement score and the corresponding session ID from the current 5-minute window
    int max_engagement_score = -1;
    int max_session_id = -1;
    for (int i = 0; i < cache.size; i++) {
        if (cache.entries[i]->engagement_score > max_engagement_score) {
            max_engagement_score = cache.entries[i]->engagement_score;
            max_session_id = cache.entries[i]->session_id;
        }
    }
    return max_session_id;
}
