// Add a user interaction to the sliding window and cache
void add_interaction(window_t* window, int user_id, int session_id, int item_id, time_t timestamp, char* metadata) {
    // Check if the sliding window is full
    if (window->size == window->capacity) {
        // Remove the oldest interaction from the cache
        remove_interaction(cache, user_id, session_id, item_id, timestamp, metadata);

        // Add the new interaction to the sliding window and cache
        add_interaction(window, user_id, session_id, item_id, timestamp, metadata);
    } else {
