void remove_interaction(cache_t* cache, int user_id, int session_id, int item_id, time_t timestamp, char* metadata) {
    // Find the index of the interaction in the cache
    int index = -1;
    for (int i = 0; i < cache->size; i++) {
        if (cache->interactions[i].user_id == user_id && cache->interactions[i].session_id == session_id && cache->interactions[i].item_id == item_id && cache->interactions[i].timestamp == timestamp) {
            index = i;
            break;
        }
    }

    // Remove the interaction from the sliding window and cache
    if (index != -1) {
        for (int i = index; i < cache->size - 1; i++) {
            cache->interactions[i].user_id = cache->interactions[i + 1].user_id;
            cache->interactions[i].session_id = cache->interactions[i + 1].session_id;
            cache->interactions[i].item_id = cache->interactions[i + 1].item_id;
            cache->interactions[i].timestamp = cache->interactions[i + 1].timestamp;
            strcpy(cache->interactions[i].metadata, cache->interactions[i + 1].metadata);
        }
        cache->size--;
    }
}

// Evaluate the engagement scores for the current 5-minute window
void evaluate_scores(window_t* window, cache_t* cache, engagement_t* scores) {
    // Initialize the engagement scores and corresponding session IDs
    scores[0].score = 0;
    scores[0].session_id = -1;

    // Iterate over the user interactions in the sliding window
    for (int i = 0; i < window->size; i++) {
        // Find the corresponding interaction in the cache
        int index = -1;
        for (int j = 0; j < cache->size; j++) {
            if (cache->interactions[j].user_id == window->interactions[i].user_id && cache->interactions[j].session_id == window->interactions[i].session_id && cache->interactions[j].item_id == window->interactions[i].item_id && cache->interactions[j].timestamp == window->interactions[i].timestamp) {
                index = j;
                break;
            }
        }

        // If the interaction is not found in the cache, add it to the cache and update the engagement scores
        if (index == -1) {
            add_interaction(cache, window->interactions[i].user_id, window->interactions[i].session_id, window->interactions[i].item_id, window->interactions[i].timestamp, window->interactions[i].metadata);
            update_scores(window, cache, scores);
        } else {
            // Update the engagement scores for the corresponding interaction in the cache
            update_scores(cache, index, scores);
        }
    }
}

// Update the engagement scores for a given interaction in the cache
void update_scores(cache_t* cache, int index, engagement_t* scores) {
    // Initialize the engagement score and corresponding session ID
    scores[0].score = 0;
    scores[0].session_id = -1;

    // Iterate over the user interactions in the sliding window
    for (int i = 0; i < cache->size; i++) {
        // If the interaction is not found in the cache, add it to the cache and update the engagement scores
        if (cache->interactions[i].user_id == cache->interactions[index].user_id && cache->interactions[i].session_id == cache->interactions[index].session_id && cache->interactions[i].item_id == cache->interactions[index].item_id && cache->interactions[i].timestamp == cache->interactions[index].timestamp) {
            scores[0].score += 1;
            scores[0].session_id = cache->interactions[i].session_id;
        }
    }
}
