int generate_crc_indications(NFAPI_CRC_INDICATION_PDU_T *pdu, char *password, struct connection *conn, void (*callback)(void)) {
    // Check if the password is empty or NULL
    if (password == NULL || strlen(password) == 0) {
        return -1;
    }

    // Check if the connection has a title set
    if (conn->title == NULL) {
        return -2;
    }

