// Define the MD5 hashing function for computing hash values
void md5Hash(const string& input, unsigned char* output) {
    MD5_CTX ctx;
    MD5Init(&ctx);
    MD5Update(&ctx, (unsigned char*)input.c_str(), input.size());
    MD5Final(output, &ctx);
}

