    // Check if the heap usage is above the maximum allowed percentage
    if (getHeapUsage() > MAX_HEAP_USAGE) {
        // Pause structure creation until the heap usage drops below the minimum required percentage
        while (getHeapUsage() > MIN_HEAP_USAGE) {
            this_thread::sleep_for(chrono::milliseconds(100));
        }
    }

    // Validate the CRC indication against the network's current settings
    NetworkConfigurationAPI networkConfig;
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (networkConfig.validateCrcIndication(crcIndication)) {
