}

// Define the function for logging metrics about structure generation and hash computation
void logMetrics() {
    // Get the current timestamp
    time_t now = time(nullptr);

    // Open the log file in append mode
    ofstream logFile;
    logFile.open(LOG_FILE_NAME, ios::app);

    // Log the current timestamp and structure count
    logFile << "Timestamp: " << now << endl;
    logFile << "Structure Count: " << processingQueue.size() << endl;

    // Iterate over the processing queue and compute the MD5 hash of each string parameter
    for (const auto& crcIndication : processingQueue) {
        unsigned char md5Hash[MD5_DIGEST_LENGTH];
        md5Hash(crcIndication.stringParameter, md5Hash);

        // Log the MD5 hash value for each string parameter
        logFile << "String Parameter: " << crcIndication.stringParameter << endl;
        logFile << "MD5 Hash Value: ";
        for (int i = 0; i < MD5_DIGEST_LENGTH; i++) {
            logFile << setw(2) << setfill('0') << hex << (int)md5Hash[i];
        }
        logFile << endl;
    }

    // Close the log file
    logFile.close();
}

// Define the function for rotating log files daily and archiving old logs
void rotateLogFiles() {
    while (true) {
        // Get the current timestamp
        time_t now = time(nullptr);

        // Open the log file in append mode
        ofstream logFile;
        logFile.open(LOG_FILE_NAME, ios::app);

        // Rotate the log file if it has reached the rotation interval
        if (difftime(now, logFile.tellg()) >= LOG_ROTATION_INTERVAL) {
            // Close the log file and rename it with a timestamp suffix
            logFile.close();
            string newFileName = LOG_FILE_NAME + "." + to_string(now);
            rename(LOG_FILE_NAME, newFileName);
        }
    }
}

