                return 0;
            case 'h':
                print_usage();
                return 0;
        }
    }

    if (optind < argc) {
        input_file = argv[optind];
    } else {
        printf("No input file specified. Please provide an input file.\n");
        return 1;
    }

    // Read input file and process lines
    char *buffer = NULL;
    int buffer_size = read_input_file(input_file, &buffer);
    if (buffer_size < 0) {
        printf("Error reading input file. Please check the file path and permissions.\n");
        return 1;
    }

    file_stats stats;
    int result = process_lines(buffer, buffer_size, &stats);
    if (result < 0) {
        printf("Error processing lines. Please check the input file and try again.\n");
        return 1;
    }

    // Write output to file or console
    if (strcmp(output_file, DEFAULT_OUTPUT_FILE) != 0) {
        result = write_output_file(output_file, buffer);
        if (result < 0) {
            printf("Error writing output file. Please check the file path and permissions.\n");
            return 1;
        }
    } else {
        printf("%s", buffer);
    }

