void print_usage() {
    printf("Usage: %s [OPTION]... [INPUT FILE]\n\nOptions:\n\t-c, --count-words\tCount the number of words in each line and print a summary at the end.\n\t-o, --output-file\tRedirect output to a specified file instead of the console.\n\t-m, --manpage\tDisplay comprehensive documentation.\n\t-h, --help\tPrint usage information and exit.", argv[0]);
}

void print_manpage() {
    printf(MANPAGE_HEADER, argv[0], argv[0]);
    printf("NAME\n\t%s - A program that parses command line arguments and provides detailed usage information if no input file is specified.\n\nSYNOPSIS\n\t%s [OPTION]... [INPUT FILE]\n\nDESCRIPTION\n\tThis program accepts an optional input file and processes it line by line, counting the number of lines and printing a summary at the end. It also supports the following features:\n\t* Support for optional --manpage option to display comprehensive documentation.\n\t* Support for -cs option to count the number of words in each line and print a summary at the end.\n\t* Support for -o output_file option to redirect the output to a specified file instead of the console.\n\t* Implement a progress indicator that shows the percentage of lines processed during the input file processing.\n\t* Ensure the program handles large files efficiently by reading them in chunks rather than loading the entire file into memory.\n\t* Include error handling for invalid command line arguments, missing required options, and I/O errors.\n\t* Design the program to be robust against concurrent access from multiple threads when multiple files are being processed simultaneously.\n\t* Optimize the program to minimize memory usage and CPU time, especially when dealing with very large files.\n\nOPTIONS\n\t-c, --count-words\tCount the number of words in each line and print a summary at the end.\n\t-o, --output-file\tRedirect output to a specified file instead of the console.\n\t-m, --manpage\tDisplay comprehensive documentation.\n\t-h, --help\tPrint usage information and exit.", argv[0], argv[0]);
    printf(MANPAGE_FOOTER);
}

int read_input_file(char *filename, char **buffer) {
    int fd = open(filename, O_RDONLY);
    if (fd < 0) {
        return -1;
    }

    struct stat file_info;
    if (fstat(fd, &file_info) < 0) {
        close(fd);
        return -1;
    }

    *buffer = malloc(file_info.st_size + 1);
    if (*buffer == NULL) {
        close(fd);
        return -1;
    }

    ssize_t bytes_read = read(fd, *buffer, file_info.st_size);
    if (bytes_read < 0) {
        free(*buffer);
        close(fd);
        return -1;
    }

    (*buffer)[bytes_read] = '\0';
    close(fd);
    return bytes_read;
}

int write_output_file(char *filename, char *buffer) {
    int fd = open(filename, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) {
        return -1;
    }

    ssize_t bytes_written = write(fd, buffer, strlen(buffer));
    if (bytes_written < 0) {
        close(fd);
        return -1;
    }

    close(fd);
    return bytes_written;
}

int count_words(char *line) {
    int word_count = 0;
    char *token = strtok(line, " ");
    while (token != NULL) {
        word_count++;
        token = strtok(NULL, " ");
    }
    return word_count;
}

int process_lines(char *buffer, int buffer_size, file_stats *stats) {
    char *line = buffer;
    while (line < buffer + buffer_size) {
        // Count words in each line and update stats
        int word_count = count_words(line);
        stats->word_count += word_count;
        stats->line_count++;

        // Print progress indicator
        printf("Processing %d%%...\n", (int)((stats->line_count / (double)buffer_size) * 100));

        // Move to next line
        line += strlen(line);
        if (*line == '\n') {
            line++;
        }
    }
    return 0;
}

void print_summary(file_stats stats) {
    printf("Summary:\n\tLines: %d\n\tWords: %d\n", stats.line_count, stats.word_count);
}
