typedef struct NFAPI_CRC_INDICATION_PDU_T {
    uint8_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint32_t CRC_INDICATION_REL8_TAG;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

void generate_crc_indication_pdu(char *filepath, int line_count, int word_count) {
    // Allocate memory for the list of structures on the heap
    NFAPI_CRC_INDICATION_PDU_T *struct_list = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * line_count);

    // Initialize the list of structures with default values
    for (int i = 0; i < line_count; i++) {
        struct_list[i].RX_UE_INFORMATION_TAG = 0x01;
        struct_list[i].RNTI = 0x0000;
        struct_list[i].CRC_INDICATION_REL8_TAG = 0x00000000;
        struct_list[i].CRCFLAG = 0x01;
    }

    // Compute the MD5 hash of each line in the file
    for (int i = 0; i < line_count; i++) {
        char *line = NULL;
        size_t len = 0;
        ssize_t read;

        FILE *file = fopen(filepath, "r");
        if (file == NULL) {
            perror("fopen");
            exit(EXIT_FAILURE);
        }

        while ((read = getline(&line, &len, file)) != -1) {
            // Compute the MD5 hash of the line using OpenSSL library functions
            unsigned char md5[MD5_DIGEST_LENGTH];
            MD5((unsigned char *)line, strlen(line), md5);

            // Set the CRC_INDICATION_REL8_TAG field in the structure with the hash value
            struct_list[i].CRC_INDICATION_REL8_TAG = *(uint32_t *)md5;
        }

        fclose(file);
    }

    // Free the allocated memory for the list of structures
    free(struct_list);
}

