// Function to parse the contents of a configuration file and extract key-value pairs
void parse_configuration_file(char *filename) {
    // Initialize variables for parsing the configuration file
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("Error opening configuration file");
        return;
    }
    char line[1024];
    while (fgets(line, 1024, fp) != NULL) {
        // Check if the line is a comment or empty
        if (line[0] == '#' || line[0] == '\n') {
            continue;
        }
        // Extract the section name and key-value pair from the line
        char *section_name = strtok(line, "=");
        char *key = strtok(NULL, "=");
        char *value = strtok(NULL, "\n");
        if (section_name == NULL || key == NULL || value == NULL) {
            fprintf(stderr, "Error: invalid configuration file format\n");
            continue;
        }
        // Validate the integrity of each entry using HMAC-SHA256 for authenticity and integrity
        unsigned char checksum[SHA256_DIGEST_LENGTH];
        HMAC(EVP_sha256(), "secret", strlen("secret"), (unsigned char *)value, strlen(value), checksum, NULL);
        if (memcmp(checksum, value + strlen(value) - SHA256_DIGEST_LENGTH, SHA256_DIGEST_LENGTH) != 0) {
            fprintf(stderr, "Error: invalid checksum for configuration entry\n");
            continue;
        }
        // Generate and populate a list of ConfigurationEntry structures
        ConfigurationEntry *entry = malloc(sizeof(ConfigurationEntry));
        if (entry == NULL) {
            perror("Error allocating memory for ConfigurationEntry structure");
            return;
        }
        entry->section_name = strdup(section_name);
        entry->key = strdup(key);
        entry->value = strdup(value);
        memcpy(entry->checksum, checksum, SHA256_DIGEST_LENGTH);
        // Add the ConfigurationEntry structure to the list of entries
    }
}

