void init_nfapi_rrc_pdu_list(char *mac_addr) {
    // Allocate memory for the list on the heap
    nfapi_rrc_pdu_t **list = malloc(sizeof(nfapi_rrc_pdu_t *) * 10);
    if (list == NULL) {
        printf("Error: Failed to allocate memory for NFAPI RRC PDU list\n");
        return;
    }

    // Compute the SHA-256 hash of the MAC address string
