    if (mac_hash == NULL) {
        printf("Error: Failed to compute SHA-256 hash for MAC address\n");
        free(list);
        return;
    }

    // Initialize the list with a single structure containing the MAC PDU, AMSDU info, and SN info
    nfapi_rrc_pdu_t *init_struct = malloc(sizeof(nfapi_rrc_pdu_t));
    if (init_struct == NULL) {
        printf("Error: Failed to allocate memory for initial NFAPI RRC PDU structure\n");
        free(list);
        return;
    }
    init_struct->mac_pdu = malloc(sizeof(MAC_PDU));
    if (init_struct->mac_pdu == NULL) {
        printf("Error: Failed to allocate memory for MAC PDU\n");
        free(list);
        return;
