        free(list);
        return;
    }
    list[0] = init_struct;

    // Set the MAC address hash in the initial structure
    memcpy(init_struct->mac_pdu->mac_addr, mac_hash, 32);

    // Free the memory for the SHA-256 hash and set it to NULL
    free(mac_hash);
    mac_hash = NULL;

    // Initialize the list size and current index
    int list_size = 1;
    int curr_index = 0;

    // Loop until the list is no longer needed
    while (list_size > 0) {
        // Increment the current index and check for overflow
        if (curr_index >= list_size) {
            curr_index = 0;
        }

        // Get the next structure in the list
        nfapi_rrc_pdu_t *struct_ptr = list[curr_index];

        // Compute the SHA-256 hash of the MAC address string for the current structure
        unsigned char *hash = compute_sha256(struct_ptr->mac_pdu->mac_addr);
        if (hash == NULL) {
            printf("Error: Failed to compute SHA-256 hash for MAC address\n");
            free(list);
            return;
        }

        // Set the MAC address hash in the current structure
        memcpy(struct_ptr->mac_pdu->mac_addr, hash, 32);

        // Free the memory for the SHA-256 hash and set it to NULL
        free(hash);
        hash = NULL;

        // Increment the current index and check for overflow
        curr_index++;

        // If the list size has not been exceeded, add a new structure to the list
        if (curr_index < list_size) {
            nfapi_rrc_pdu_t *new_struct = malloc(sizeof(nfapi_rrc_pdu_t));
            if (new_struct == NULL) {
                printf("Error: Failed to allocate memory for new NFAPI RRC PDU structure\n");
                free(list);
                return;
            }
            list[curr_index] = new_struct;
        }
    }

    // Free the memory for the list and set it to NULL
    free(list);
    list = NULL;
