// Define the function to compute the SHA-256 hash of a provided MAC address string
unsigned char *compute_sha256(char *mac_addr) {
    // Initialize the SHA-256 context
    EVP_MD_CTX *ctx = EVP_MD_CTX_new();
    if (ctx == NULL) {
        printf("Error: Failed to initialize SHA-256 context\n");
        return NULL;
    }

    // Set the hash type and data for the SHA-256 computation
    EVP_MD *md = EVP_get_digestbyname("SHA256");
    if (md == NULL) {
        printf("Error: Failed to get SHA-256 digest\n");
        EVP_MD_CTX_free(ctx);
        return NULL;
    }
    unsigned char *data = (unsigned char *)mac_addr;
    int data_len = strlen(mac_addr);

    // Compute the SHA-256 hash of the MAC address string
    if (!EVP_DigestInit_ex(ctx, md, NULL) || !EVP_DigestUpdate(ctx, data, data_len) || !EVP_DigestFinal_ex(ctx, NULL, 0)) {
        printf("Error: Failed to compute SHA-256 hash for MAC address\n");
        EVP_MD_CTX_free(ctx);
        return NULL;
    }

    // Allocate memory for the SHA-256 hash and set it to NULL
    unsigned char *hash = malloc(32);
    if (hash == NULL) {
        printf("Error: Failed to allocate memory for SHA-256 hash\n");
        EVP_MD_CTX_free(ctx);
        return NULL;
    }

    // Set the SHA-256 hash in the output buffer and free the context
    int hash_len = 32;
    if (!EVP_DigestFinal_ex(ctx, hash, &hash_len)) {
        printf("Error: Failed to finalize SHA-256 hash computation\n");
        EVP_MD_CTX_free(ctx);
        return NULL;
    }
    EVP_MD_CTX_free(ctx);

    // Return the SHA-256 hash
    return hash;
}

