int resolve_hostname(char *hostname) {
    // Initialize the DNS resolver context
    struct addrinfo hints, *res;
    memset(&hints, 0, sizeof(struct addrinfo));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;
    int status = getaddrinfo(hostname, NULL, &hints, &res);
    if (status != 0) {
        printf("Error: Failed to resolve hostname\n");
        return -1;
    }

    // Get the IP address from the DNS resolver context and free it
    struct in_addr *ip = (struct in_addr *)res->ai_addr;
    char ip_str[INET_ADDRSTRLEN];
    inet_ntop(AF_INET, &ip->s_addr, ip_str, INET_ADDRSTRLEN);
    freeaddrinfo(res);

    // Return the IP address as a `u_char` array
    u_char *ip_array = (u_char *)malloc(4);
    if (ip_array == NULL) {
        printf("Error: Failed to allocate memory for IP address\n");
        return -1;
    }
    memcpy(ip_array, ip_str, 4);
    return ip_array;
}
