// Define the structure for RX_UE_INFORMATION_TAG
typedef struct {
    int rnti;
    char crc_indication_rel8_tag[10];
} NFAPI_CRC_INDICATION_PDU_T;

// Define the function to dynamically allocate memory for an array of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* allocate_array(int n) {
    // Check if the input is valid
    if (n <= 0) {
        return NULL;
    }

    // Allocate memory for the array of structures
    NFAPI_CRC_INDICATION_PDU_T* arr = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * n);
    if (arr == NULL) {
        return NULL;
    }

    // Initialize each structure in the array
    for (int i = 0; i < n; i++) {
        arr[i].rnti = -1;
        strcpy(arr[i].crc_indication_rel8_tag, "");
    }

    return arr;
}

// Define the function to validate the integrity of an RX_UE_INFORMATION_TAG structure
int validate_rx_ue_information_tag(NFAPI_CRC_INDICATION_PDU_T* tag) {
    // Check if the RNTI value is within the valid range of 0 to 65535
    if (tag->rnti < 0 || tag->rnti > 65535) {
        return 0;
    }

    // Check if the RX_UE_INFORMATION_TAG is correctly formed
    if (strlen(tag->crc_indication_rel8_tag) != 10) {
        return 0;
    }

    return 1;
}

// Define the function to populate an array of NFAPI_CRC_INDICATION_PDU_T structures with user input
void populate_array(NFAPI_CRC_INDICATION_PDU_T* arr, int n) {
    // Read a list of M integers from standard input, where M is less than or equal to N
    int m;
    scanf("%d", &m);

    // Check if the input is valid
    if (m <= 0 || m > n) {
        return;
    }

    // Populate the array with the integers read from standard input
    for (int i = 0; i < m; i++) {
        int num;
        scanf("%d", &num);
        arr[i].rnti = num;
        sprintf(arr[i].crc_indication_rel8_tag, "%d", num);
    }
}

// Define the function to find and print the largest integer in an array of integers
void find_largest_integer(int* arr, int n) {
    // Check if the input is valid
    if (n <= 0) {
        return;
    }

    // Find the largest integer in the array
    int largest = arr[0];
    for (int i = 1; i < n; i++) {
        if (arr[i] > largest) {
            largest = arr[i];
        }
    }

    // Print the largest integer
    printf("%d\n", largest);
}

// Define the main function to demonstrate the use of the above functions
int main() {
    // Read the number of structures to allocate from standard input
    int n;
    scanf("%d", &n);

    // Allocate memory for the array of structures
    NFAPI_CRC_INDICATION_PDU_T* arr = allocate_array(n);
    if (arr == NULL) {
        return 1;
    }

    // Populate the array with user input
    populate_array(arr, n);

    // Validate each structure in the array
    for (int i = 0; i < n; i++) {
        if (!validate_rx_ue_information_tag(&arr[i])) {
            printf("Invalid RX_UE_INFORMATION_TAG at index %d\n", i);
            continue;
        }
    }

    // Find and print the largest integer in the array
    find_largest_integer(arr, n);

    // Free the allocated memory
    free(arr);

    return 0;
}
