#include <stdlib.h>
#include <string.h>
#include <stdio.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* allocate_crc_indication_pdu(int num_structures) {
    // Check if the number of structures is valid
    if (num_structures <= 0) {
        return NULL;
    }

    // Allocate memory for the array of structures
    NFAPI_CRC_INDICATION_PDU_T* pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * num_structures);
    if (pdu == NULL) {
        printf("Error: Failed to allocate memory for CRC indication PDU\n");
        return NULL;
    }

    // Initialize each structure with a valid RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG
    for (int i = 0; i < num_structures; i++) {
        pdu[i].RX_UE_INFORMATION_TAG = 1;
        pdu[i].RNTI = 2;
        pdu[i].CRC_INDICATION_REL8_TAG = 3;
    }

    // Return the allocated memory
    return pdu;
}

void free_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (pdu != NULL) {
        free(pdu);
    }
