['```c++
#include <iostream>
#include <vector>
#include <random>
#include <chrono>
#include <thread>
#include <mutex>

using namespace std;

struct NFAPI_CRC_INDICATION_PDU_T {
    uint16_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
};

struct DynamicRangeGenerator {
    int min, max;
    bool inclusive;

    DynamicRangeGenerator(int min, int max, bool inclusive) : min(min), max(max), inclusive(inclusive) {}

    int generate() {
        if (inclusive) {
            return rand() % (max - min + 1) + min;
        } else {
            return rand() % (max - min) + min + 1;
        }
    }
};

class RandomNFAPackageGenerator {
private:
    vector<NFAPI_CRC_INDICATION_PDU_T> nfaPduList;
    DynamicRangeGenerator rxUeInformationTagRange, rntiRange, crcIndicationRel8TagRange;
    int maxInstancesPerSecond = 0;
    chrono::time_point<chrono::system_clock> lastResetTime;
    mutex instanceCounterMutex;
    atomic<int> instancesCount;

public:
    RandomNFAPackageGenerator(DynamicRangeGenerator rxUeInformationTagRange, DynamicRangeGenerator rntiRange, DynamicRangeGenerator crcIndicationRel8TagRange) :
        rxUeInformationTagRange(rxUeInformationTagRange), rntiRange(rntiRange), crcIndicationRel8TagRange(crcIndicationRel8TagRange) {}

    RandomNFAPackageGenerator(int minRxUeInformationTag, int maxRxUeInformationTag, bool inclusiveRxUeInformationTag, int minRnti, int maxRnti, bool inclusiveRnti, int minCrcIndicationRel8Tag, int maxCrcIndicationRel8Tag, bool inclusiveCrcIndicationRel8Tag) :
        rxUeInformationTagRange(minRxUeInformationTag, maxRxUeInformationTag, inclusiveRxUeInformationTag), rntiRange(minRnti, maxRnti, inclusiveRnti), crcIndicationRel8TagRange(minCrcIndicationRel8Tag, maxCrcIndicationRel8Tag, inclusiveCrcIndicationRel8Tag) {}

    RandomNFAPackageGenerator() : rxUeInformationTagRange(0, 65535, true), rntiRange(0, 4294967295, true), crcIndicationRel8TagRange(0, 255, true) {}

    void SetMaxInstancesPerSecond(int maxInstancesPerSecond) {
        this->maxInstancesPerSecond = maxInstancesPerSecond;
    }

    int GetInstancesCount() {
        return instancesCount.load();
    }

    void ResetInstanceCounter() {
        lastResetTime = chrono::system_clock::now();
        instancesCount = 0;
    }

    vector<NFAPI_CRC_INDICATION_PDU_T> GenerateRandomNFAPackageList(int numInstances) {
        vector<NFAPI_CRC_INDICATION_PDU_T> nfaPduList;
        for (int i = 0; i < numInstances; i++) {
            NFAPI_CRC_INDICATION_PDU_T nfaPdu;
            nfaPdu.RX_UE_INFORMATION_TAG = rxUeInformationTagRange.generate();
            nfaPdu.RNTI = rntiRange.generate();
            nfaPdu.CRC_INDICATION_REL8_TAG = crcIndicationRel8TagRange.generate();
            nfaPduList.push_back(nfaPdu);
        }
        return nfaPduList;
    }

    void PopulateRandomNFAPackageList(int numInstances) {
        lock_guard<mutex> lock(instanceCounterMutex);
        if (maxInstancesPerSecond > 0 && instancesCount >= maxInstancesPerSecond) {
            cerr << "Maximum number of instances per second exceeded. Skipping population." << endl;
            return;
        }
        nfaPduList = GenerateRandomNFAPackageList(numInstances);
        instancesCount++;
    }

    void ResetRange() {
        rxUeInformationTagRange = DynamicRangeGenerator(0, 65535, true);
        rntiRange = DynamicRangeGenerator(0, 4294967295, true);
        crcIndicationRel8TagRange = DynamicRangeGenerator(0, 255, true);
    }

    void SetRxUeInformationTagRange(int min, int max, bool inclusive) {
        rxUeInformationTagRange = DynamicRangeGenerator(min, max, inclusive);
    }

    void SetRntiRange(int min, int max, bool inclusive) {
        rntiRange = DynamicRangeGenerator(min, max, inclusive);
    }

    void SetCrcIndicationRel8TagRange(int min, int max, bool inclusive) {
        crcIndicationRel8TagRange = DynamicRangeGenerator(min, max, inclusive);
    }

    string ToString() {
        return "RX_UE_INFORMATION_TAG range: [" + to_string(rxUeInformationTagRange.min) + ", " + to_string(rxUeInformationTagRange.max) + "], RNTI range: [" + to_string(rntiRange.min) + ", " + to_string(rntiRange.max) + "], CRC_INDICATION_REL8_TAG range: [" + to_string(crcIndicationRel8TagRange.min) + ", " + to_string(crcIndicationRel8TagRange.max) + "]";
    }
};
```
This code defines a `RandomNFAPackageGenerator` class that generates and manages a list of `NFAPI_CRC_INDICATION_PDU_T` structures, each containing valid RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG with randomly set CRCFLAG. The class utilizes a custom random number generator based on `DynamicRangeGenerator` structure to ensure configurable and hierarchical range management for generating random values.

The class has the following methods:

* `SetMaxInstancesPerSecond`: Configures the maximum number of instances of `NFAPI_CRC_INDICATION_PDU_T` that can be generated per second.
* `GetInstancesCount`: Returns the current count of instances generated since the last reset.
* `ResetInstanceCounter`: Resets the instance counter back to zero.
* `GenerateRandomNFAPackageList`: Generates a list of random NFAPI_CRC_INDICATION_PDU_T structures with the specified number of instances.
* `PopulateRandomNFAPackageList`: Populates the internal list of NFAPI_CRC_INDICATION_PDU_T structures with the specified number of instances, ensuring that the maximum number of instances per second is not exceeded.
* `ResetRange`: Resets the range settings to their default values.
