// Define data types for configuration settings
typedef enum {
    INT,
    FLOAT,
    BOOL,
    STRING
} setting_type;

typedef struct {
    char *key;
    void *value;
    setting_type type;
} config_setting;

// Define a linked list for storing configuration settings
typedef struct config_list {
    config_setting *settings;
    int num_settings;
    pthread_mutex_t mutex; // Mutex for thread safety
} config_list;

// Function to add a new setting to the linked list
void add_setting(config_list *list, char *key, void *value, setting_type type) {
    // Allocate memory for the new setting
    config_setting *new_setting = malloc(sizeof(config_setting));
    if (!new_setting) {
        printf("Error: Failed to allocate memory for new setting\n");
        return;
    }

    // Initialize the new setting
    new_setting->key = key;
    new_setting->value = value;
    new_setting->type = type;

    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&list->mutex);

    // Add the new setting to the end of the linked list
    if (list->num_settings == 0) {
        list->settings = new_setting;
    } else {
        config_setting *last_setting = list->settings + (list->num_settings - 1);
        last_setting->next = new_setting;
    }

    // Increment the number of settings and unlock the mutex
    list->num_settings++;
    pthread_mutex_unlock(&list->mutex);
}

// Function to remove a setting from the linked list
void remove_setting(config_list *list, char *key) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&list->mutex);

    // Find the setting with the given key and remove it from the linked list
    config_setting *current = list->settings;
    while (current != NULL) {
        if (strcmp(current->key, key) == 0) {
            if (current == list->settings) {
                list->settings = current->next;
            } else {
                config_setting *prev = current - 1;
                prev->next = current->next;
            }
            free(current);
            break;
        }
        current = current->next;
    }

    // Decrement the number of settings and unlock the mutex
    list->num_settings--;
    pthread_mutex_unlock(&list->mutex);
}

// Function to retrieve a setting from the linked list
void *get_setting(config_list *list, char *key) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&list->mutex);

    // Find the setting with the given key and return its value
    config_setting *current = list->settings;
    while (current != NULL) {
        if (strcmp(current->key, key) == 0) {
            void *value = current->value;
            pthread_mutex_unlock(&list->mutex);
            return value;
        }
        current = current->next;
    }

    // Unlock the mutex and return NULL if the setting is not found
    pthread_mutex_unlock(&list->mutex);
    return NULL;
}

// Function to log a message to a centralized monitoring system
void log_message(char *message, int level) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&list->mutex);

    // Log the message and unlock the mutex
    printf("Logging message: %s (level: %d)\n", message, level);
    pthread_mutex_unlock(&list->mutex);
}

// Function to handle a variable number of settings, ensuring efficient memory usage and proper resource management
void manage_settings(config_list *list) {
