}

// Function to add a new CRC indication to the cache
void add_crc_indication(CACHE_STRUCT_T *cache, uint16_t rx_ue_information_tag, uint32_t rnti) {
    // Check if the cache is full
    if (cache->num_crc_indications >= SIZE_LIMIT) {
        // Evict an entry from the cache using the eviction policy
        switch (EVICTION_POLICY) {
            case "LRU":
                evict_lru(cache);
                break;
            default:
                printf("Invalid eviction policy\n");
                return;
        }
    }

    // Allocate memory for the new CRC indication
