    // Add the new CRC indication to the cache
    cache->crc_indications[cache->num_crc_indications++] = new_crc_indication;
}

// Function to evict an entry from the cache using the LRU policy
void evict_lru(CACHE_STRUCT_T *cache) {
    // Find the least recently used entry in the cache
    size_t lru_index = 0;
    for (size_t i = 1; i < cache->num_crc_indications; i++) {
        if (cache->crc_indications[i]->last_accessed < cache->crc_indications[lru_index]->last_accessed) {
            lru_index = i;
        }
    }

    // Free the memory for the least recently used entry
    free(cache->crc_indications[lru_index]);

    // Remove the least recently used entry from the cache
    memmove(&cache->crc_indications[lru_index], &cache->crc_indications[lru_index + 1], (cache->num_crc_indications - lru_index - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    cache->num_crc_indications--;
}

// Function to update the last accessed time for a CRC indication in the cache
void update_last_accessed(CACHE_STRUCT_T *cache, uint16_t rx_ue_information_tag, uint32_t rnti) {
    // Find the index of the CRC indication in the cache
    size_t index = 0;
    for (size_t i = 0; i < cache->num_crc_indications; i++) {
        if (cache->crc_indications[i]->rx_ue_information_tag == rx_ue_information_tag && cache->crc_indications[i]->rnti == rnti) {
            index = i;
            break;
        }
    }

    // Update the last accessed time for the CRC indication
    if (index < cache->num_crc_indications) {
        cache->crc_indications[index]->last_accessed = time(NULL);
    }
}

// Function to retrieve a CRC indication from the cache
NFAPI_CRC_INDICATION_PDU_T *get_crc_indication(CACHE_STRUCT_T *cache, uint16_t rx_ue_information_tag, uint32_t rnti) {
    // Find the index of the CRC indication in the cache
    size_t index = 0;
    for (size_t i = 0; i < cache->num_crc_indications; i++) {
        if (cache->crc_indications[i]->rx_ue_information_tag == rx_ue_information_tag && cache->crc_indications[i]->rnti == rnti) {
            index = i;
            break;
        }
    }

    // Return the CRC indication if it exists in the cache
    if (index < cache->num_crc_indications) {
        update_last_accessed(cache, rx_ue_information_tag, rnti);
        return cache->crc_indications[index];
    } else {
        return NULL;
    }
}
