    sysinfo(&mem_usage);
    if (mem_usage.totalram * mem_usage.mem_unit > 60 * 1024 * 1024) { // 60% of available memory
        printf("Warning: Memory usage exceeds 60%%. Pausing structure creation until usage drops below 50%%.\n");
        sleep(30); // Pause for 30 seconds
    }

    // Free the list of CRC indications and hashes
    free(crc_indication_list);
    for (i = 0; i < num_structures; i++) {
        free(crc_indication_list[i].hash);
    }
}

