unsigned char *hash_mac_address(char *mac_address) {
    unsigned char *hash = (unsigned char *)malloc(SHA256_DIGEST_LENGTH);
    if (!hash) {
        printf("Error: Failed to allocate memory for hash\n");
        return NULL;
    }
    SHA256((const unsigned char *)mac_address, strlen(mac_address), hash);
    return hash;
}

// Convert a hash to a string representation
char *hash_to_string(unsigned char *hash) {
    char *hash_str = (char *)malloc(SHA256_DIGEST_LENGTH * 2 + 1);
    if (!hash_str) {
        printf("Error: Failed to allocate memory for hash string\n");
        return NULL;
    }
    for (int i = 0; i < SHA256_DIGEST_LENGTH; i++) {
        sprintf(hash_str + i * 2, "%02x", hash[i]);
    }
    return hash_str;
}
