        return NULL;
    }
    list->elements = malloc(capacity * sizeof(MAC_PACKET_T));
    if (!list->elements) {
        free(list);
        return NULL;
    }
    list->capacity = capacity;
    list->count = 0;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

// Add a new MAC packet to the list
void mac_packet_list_add(MAC_PACKET_LIST_T* list, MAC_PACKET_T* packet) {
    pthread_mutex_lock(&list->mutex);
    if (list->count == list->capacity) {
        // Dynamically resize the list if it's full
        size_t new_capacity = list->capacity * 2;
        MAC_PACKET_T* new_elements = realloc(list->elements, new_capacity * sizeof(MAC_PACKET_T));
        if (!new_elements) {
            pthread_mutex_unlock(&list->mutex);
            return;
        }
        list->elements = new_elements;
        list->capacity = new_capacity;
    }
    // Copy the packet data into the list
    memcpy(list->elements + list->count, packet, sizeof(MAC_PACKET_T));
    list->count++;
    pthread_mutex_unlock(&list->mutex);
}

// Remove a MAC packet from the list by its index
void mac_packet_list_remove(MAC_PACKET_LIST_T* list, size_t index) {
    pthread_mutex_lock(&list->mutex);
    if (index >= list->count) {
        // Out of bounds
        pthread_mutex_unlock(&list->mutex);
        return;
    }
    // Shift the elements after the removed element to fill the gap
    memmove(list->elements + index, list->elements + index + 1, (list->count - index - 1) * sizeof(MAC_PACKET_T));
    list->count--;
    pthread_mutex_unlock(&list->mutex);
}

// Get the MAC packet at the given index in the list
MAC_PACKET_T* mac_packet_list_get(MAC_PACKET_LIST_T* list, size_t index) {
    pthread_mutex_lock(&list->mutex);
    if (index >= list->count) {
        // Out of bounds
        pthread_mutex_unlock(&list->mutex);
        return NULL;
    }
    MAC_PACKET_T* packet = list->elements + index;
    pthread_mutex_unlock(&list->mutex);
    return packet;
}

// Free the memory allocated by the list
void mac_packet_list_free(MAC_PACKET_LIST_T* list) {
    free(list->elements);
    pthread_mutex_destroy(&list->mutex);
    free(list);
}
