void init_mac_pdu_array(MAC_PDU_T **pdu_array) {
    // Allocate memory for the array
    *pdu_array = (MAC_PDU_T *)malloc(sizeof(MAC_PDU_T) * MAX_ARRAY_SIZE);
    if (*pdu_array == NULL) {
        printf("Error: Failed to allocate memory for MAC PDU array\n");
        return;
    }

    // Initialize the sequence number generator
    srand(time(NULL));

    // Loop through each element in the array and initialize it
    for (int i = 0; i < MAX_ARRAY_SIZE; i++) {
        (*pdu_array)[i].header.sequence_number = rand() % 1000;
        (*pdu_array)[i].payload.data = NULL;
    }
}

// Function to add a new MAC PDU to the array
void add_mac_pdu(MAC_PDU_T **pdu_array, MAC_HEADER_T header, MAC_PAYLOAD_T payload) {
    // Check if the array is full
    if (MAX_ARRAY_SIZE == (*pdu_array)->size) {
        printf("Error: The MAC PDU array is full\n");
        return;
    }

    // Add the new MAC PDU to the end of the array
    (*pdu_array)[(*pdu_array)->size].header = header;
    (*pdu_array)[(*pdu_array)->size].payload = payload;
    (*pdu_array)->size++;
}

// Function to remove a MAC PDU from the array
void remove_mac_pdu(MAC_PDU_T **pdu_array, int index) {
    // Check if the index is valid
    if (index < 0 || index >= (*pdu_array)->size) {
        printf("Error: Invalid index for MAC PDU\n");
        return;
    }

    // Shift all elements after the specified index to the left
    for (int i = index + 1; i < (*pdu_array)->size; i++) {
        (*pdu_array)[i - 1] = (*pdu_array)[i];
    }

    // Decrement the size of the array
    (*pdu_array)->size--;
}
