// Define the structure for a MAC PDU
typedef struct {
    MAC_HEADER_T header;
    MAC_PAYLOAD_T payload;
} MAC_PDU_T;

// Define the maximum size of the array
#define MAX_ARRAY_SIZE 1024

// Define a lock for thread safety
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Function to initialize and configure the dynamic array
void init_array(MAC_PDU_T **array, int *size) {
    // Allocate memory for the array
    *array = (MAC_PDU_T *)malloc(sizeof(MAC_PDU_T) * MAX_ARRAY_SIZE);
    if (*array == NULL) {
        printf("Error: Failed to allocate memory for the array\n");
        return;
    }

    // Initialize the sequence number generator
    srand(time(NULL));

    // Set the initial size of the array to 0
    *size = 0;
}

// Function to append a new element to the dynamic array
void append_element(MAC_PDU_T **array, int *size) {
    // Acquire the lock for thread safety
    pthread_mutex_lock(&lock);

    // Check if the maximum size of the array has been reached
    if (*size >= MAX_ARRAY_SIZE) {
        printf("Error: Maximum size of the array has been reached\n");
        return;
    }

    // Generate a new sequence number for the PDU
    int seq_num = rand() % 1024;

    // Check if the sequence number is already in use
    while (seq_num == (*array)[*size - 1].header.sequence_number) {
        seq_num = rand() % 1024;
    }

    // Initialize a new MAC PDU with the generated sequence number
    MAC_PDU_T *new_pdu = (MAC_PDU_T *)malloc(sizeof(MAC_PDU_T));
    if (new_pdu == NULL) {
        printf("Error: Failed to allocate memory for the new PDU\n");
        return;
    }
    new_pdu->header.sequence_number = seq_num;

    // Append the new PDU to the array
    (*array)[*size] = *new_pdu;
    *size += 1;

    // Release the lock for thread safety
    pthread_mutex_unlock(&lock);
}

// Function to remove an element from the dynamic array
void remove_element(MAC_PDU_T **array, int *size) {
    // Acquire the lock for thread safety
    pthread_mutex_lock(&lock);

    // Check if the array is empty
    if (*size == 0) {
        printf("Error: The array is empty\n");
        return;
    }

    // Remove the last element from the array
    MAC_PDU_T *removed_pdu = &(*array)[*size - 1];
    (*size)--;

    // Release the lock for thread safety
    pthread_mutex_unlock(&lock);
}

// Function to serialize the dynamic array to a file
void serialize(MAC_PDU_T **array, int size) {
    // Open the output file in binary mode
    FILE *output = fopen("output.bin", "wb");
    if (output == NULL) {
        printf("Error: Failed to open the output file\n");
        return;
    }

    // Write the size of the array to the file
    int written = fwrite(&size, sizeof(int), 1, output);
    if (written != 1) {
        printf("Error: Failed to write the size of the array\n");
        return;
    }

    // Write each element of the array to the file
    for (int i = 0; i < size; i++) {
        written = fwrite(&(*array)[i], sizeof(MAC_PDU_T), 1, output);
        if (written != 1) {
            printf("Error: Failed to write element %d of the array\n", i);
            return;
        }
    }

    // Close the output file
    fclose(output);
}

// Function to deserialize the dynamic array from a file
void deserialize(MAC_PDU_T **array, int *size) {
    // Open the input file in binary mode
    FILE *input = fopen("input.bin", "rb");
    if (input == NULL) {
        printf("Error: Failed to open the input file\n");
        return;
    }

    // Read the size of the array from the file
    int read = fread(size, sizeof(int), 1, input);
    if (read != 1) {
        printf("Error: Failed to read the size of the array\n");
        return;
    }

    // Allocate memory for the array
    *array = (MAC_PDU_T *)malloc(sizeof(MAC_PDU_T) * (*size));
    if (*array == NULL) {
        printf("Error: Failed to allocate memory for the array\n");
        return;
    }

    // Read each element of the array from the file
    for (int i = 0; i < *size; i++) {
        read = fread(&(*array)[i], sizeof(MAC_PDU_T), 1, input);
        if (read != 1) {
            printf("Error: Failed to read element %d of the array\n", i);
            return;
        }
    }

    // Close the input file
    fclose(input);
}
