// Define a struct to represent a TCP segment
typedef struct {
    int sequence_number;
    int acknowledgment_number;
    TCP_HEADER_T tcp_header;
    TCP_SEGMENT_DATA_T tcp_segment_data;
} TCPSegment;

// Define a struct to represent the dynamic list of TCP segments
typedef struct {
    TCPSegment* segments;
    int size;
    int max_size;
    pthread_mutex_t lock;
} TCPSegmentList;

// Initialize the dynamic list with an initial capacity of 10 elements
void initTCPSegmentList(TCPSegmentList* list) {
    list->segments = (TCPSegment*)malloc(sizeof(TCPSegment) * 10);
    list->size = 0;
    list->max_size = 10;
    pthread_mutex_init(&list->lock, NULL);
}

// Append a new TCP segment to the end of the dynamic list
void appendTCPSegment(TCPSegmentList* list, int sequence_number, int acknowledgment_number, TCP_HEADER_T tcp_header, TCP_SEGMENT_DATA_T tcp_segment_data) {
    pthread_mutex_lock(&list->lock);
    if (list->size == list->max_size) {
        // Reallocate the memory for the segments to increase the capacity by 50%
        int new_capacity = list->max_size * 2;
        TCPSegment* new_segments = (TCPSegment*)realloc(list->segments, sizeof(TCPSegment) * new_capacity);
        if (new_segments == NULL) {
            // Handle memory allocation failure gracefully
            pthread_mutex_unlock(&list->lock);
            return;
        }
        list->segments = new_segments;
        list->max_size = new_capacity;
    }
    list->segments[list->size].sequence_number = sequence_number;
    list->segments[list->size].acknowledgment_number = acknowledgment_number;
    list->segments[list->size].tcp_header = tcp_header;
    list->segments[list->size].tcp_segment_data = tcp_segment_data;
    list->size++;
    pthread_mutex_unlock(&list->lock);
}

// Remove the first TCP segment from the dynamic list
void removeTCPSegment(TCPSegmentList* list) {
    pthread_mutex_lock(&list->lock);
    if (list->size == 0) {
