#include <time.h>

#define MAX_CONNECTIONS 50000
#define CONNECTION_METADATA_SIZE 128
#define METADATA_BUFFER_SIZE (MAX_CONNECTIONS * CONNECTION_METADATA_SIZE)
#define BUFFER_SIZE (METADATA_BUFFER_SIZE + sizeof(int))
#define MAX_RETRY 5
#define RETRY_DELAY 1000 // in milliseconds
#define MIN_BACKOFF 2 // in seconds
#define MAX_BACKOFF 30 // in seconds

typedef struct {
    int fd;
    char remote_ip[INET6_ADDRSTRLEN];
    uint16_t port;
    enum connection_status status;
    time_t last_activity;
} connection_metadata_t;

connection_metadata_t *connections = NULL;
int num_connections = 0;
pthread_mutex_t connections_lock = PTHREAD_MUTEX_INITIALIZER;

void handle_error(const char *msg) {
    perror(msg);
    exit(1);
}

void add_connection(int fd, const struct sockaddr *remote_addr, socklen_t addr_len) {
    pthread_mutex_lock(&connections_lock);
    if (num_connections >= MAX_CONNECTIONS) {
        printf("Maximum number of connections reached. Closing connection.\n");
        close(fd);
        return;
    }
    int i = 0;
    for (i = 0; i < num_connections; i++) {
        if (connections[i].status == CONNECTION_CLOSED) {
            break;
        }
    }
    if (i >= num_connections) {
        printf("No available connections. Closing connection.\n");
        close(fd);
        return;
    }
    connections[i].fd = fd;
    memcpy(&connections[i].remote_ip, remote_addr, addr_len);
    connections[i].port = ntohs(((struct sockaddr_in *)remote_addr)->sin_port);
    connections[i].status = CONNECTION_ESTABLISHED;
    connections[i].last_activity = time(NULL);
    num_connections++;
    pthread_mutex_unlock(&connections_lock);
}

void remove_connection(int fd) {
    pthread_mutex_lock(&connections_lock);
    int i;
    for (i = 0; i < num_connections; i++) {
        if (connections[i].fd == fd) {
            connections[i].status = CONNECTION_CLOSED;
            break;
        }
    }
    pthread_mutex_unlock(&connections_lock);
}

void update_connection(int fd, const struct sockaddr *remote_addr, socklen_t addr_len) {
    pthread_mutex_lock(&connections_lock);
    int i;
    for (i = 0; i < num_connections; i++) {
        if (connections[i].fd == fd) {
            memcpy(&connections[i].remote_ip, remote_addr, addr_len);
            connections[i].port = ntohs(((struct sockaddr_in *)remote_addr)->sin_port);
            connections[i].last_activity = time(NULL);
            break;
        }
    }
    pthread_mutex_unlock(&connections_lock);
}

void *connection_handler(void *arg) {
    int fd = (int)(long)arg;
    char buffer[BUFFER_SIZE];
    ssize_t bytes_read;
    while ((bytes_read = read(fd, buffer, BUFFER_SIZE)) > 0) {
        // handle incoming data
    }
    remove_connection(fd);
    return NULL;
}

void *network_monitoring_service() {
    int sock = socket(AF_INET6, SOCK_STREAM, 0);
    if (sock < 0) {
        handle_error("socket");
    }
    struct sockaddr_in6 server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin6_family = AF_INET6;
    server_addr.sin6_port = htons(12345);
    if (bind(sock, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        handle_error("bind");
    }
    if (listen(sock, MAX_CONNECTIONS) < 0) {
        handle_error("listen");
    }
    printf("Network monitoring service started.\n");
    while (1) {
        struct sockaddr_in6 client_addr;
        socklen_t addr_len = sizeof(client_addr);
        int fd = accept(sock, (struct sockaddr *)&client_addr, &addr_len);
        if (fd < 0) {
            handle_error("accept");
        }
        add_connection(fd, (struct sockaddr *)&client_addr, addr_len);
        pthread_t thread;
        if (pthread_create(&thread, NULL, connection_handler, (void *)(long)fd) < 0) {
            handle_error("pthread_create");
        }
    }
}

int main() {
    connections = malloc(sizeof(connection_metadata_t) * MAX_CONNECTIONS);
    if (!connections) {
        handle_error("malloc");
    }
    pthread_mutex_init(&connections_lock, NULL);
    network_monitoring_service();
    return 0;
}
