// Add a new packet to the list
void add_packet(PACKET_LIST_T* list, MAC_PACKET_T* packet) {
    pthread_mutex_lock(&list->mutex);
    if (list->count == list->capacity) {
        // Dynamically resize the list if necessary
        size_t new_capacity = list->capacity * 2;
        MAC_PACKET_T* new_packets = realloc(list->packets, new_capacity);
        if (new_packets == NULL) {
