    pthread_mutex_unlock(&list->mutex);
}

// Remove a packet from the list by its index
void remove_packet(PACKET_LIST_T* list, size_t index) {
    pthread_mutex_lock(&list->mutex);
    if (index >= list->count) {
        // Handle out-of-range index
        pthread_mutex_unlock(&list->mutex);
        return;
