typedef struct {
    // PHY_CHANNEL_STATE_INFO
    int channel;
    float frequency;
} PHY_CHANNEL_STATE_INFO;

typedef struct {
    // PHY_RX_BUFFER_T
    char* buffer;
    size_t size;
} PHY_RX_BUFFER_T;

typedef struct {
    // PHY_RX_STREAM_INFO
    int stream_id;
    float gain;
} PHY_RX_STREAM_INFO;

typedef struct {
    // PHY_RX_CONTEXT_T
    PHY_CHANNEL_STATE_INFO channel_state;
    PHY_RX_BUFFER_T rx_buffer;
    PHY_RX_STREAM_INFO stream_info;
} PHY_RX_CONTEXT_T;

void allocate_rx_contexts(size_t num_contexts) {
    // Allocate memory for the array of PHY_RX_CONTEXT_T structures
    PHY_RX_CONTEXT_T* contexts = (PHY_RX_CONTEXT_T*)malloc(num_contexts * sizeof(PHY_RX_CONTEXT_T));
    if (!contexts) {
        // Handle memory allocation failure
        return;
    }

    // Initialize each structure with a valid PHY_CHANNEL_STATE_INFO, PHY_RX_BUFFER_T, and PHY_RX_STREAM_INFO
    for (size_t i = 0; i < num_contexts; ++i) {
        contexts[i].channel_state.channel = i + 1;
        contexts[i].channel_state.frequency = 2407 + (i * 5);
        contexts[i].rx_buffer.buffer = malloc(1024 * sizeof(char));
        if (!contexts[i].rx_buffer.buffer) {
            // Handle memory allocation failure
            return;
        }
        contexts[i].rx_buffer.size = 1024;
        contexts[i].stream_info.stream_id = i + 1;
        contexts[i].stream_info.gain = 0.5f;
    }

    // Clean up allocated memory upon completion or failure
    atexit(free_rx_contexts);
}

void free_rx_contexts() {
    PHY_RX_CONTEXT_T* contexts = (PHY_RX_CONTEXT_T*)malloc(num_contexts * sizeof(PHY_RX_CONTEXT_T));
    if (!contexts) {
        // Handle memory allocation failure
        return;
    }

    for (size_t i = 0; i < num_contexts; ++i) {
        free(contexts[i].rx_buffer.buffer);
    }
}
