        array[array_size].RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
        array[array_size].RNTI = RNTI;
        array[array_size].CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
        array_size++;
    }
}

