    return &array[index];
}

// Function to purge expired entries from the hash table
void purge_expired_entries() {
    // Iterate over all entries in the hash table
    for (int i = 0; i < HASH_TABLE_SIZE; i++) {
        // Check if the entry is expired
        if (array[i].RNTI == -1) {
            continue;
