import requests
from datetime import datetime
from collections import defaultdict
from typing import Dict, List, Tuple

class CertificateValidator:
    def __init__(self):
        self.graph = defaultdict(list)
        self.crl_services = []
        self.certificate_validity_threshold = 30
        self.processing_time = 0
        self.validation_report = {}

    def add_api(self, api: str):
        """Add an API to the graph"""
        self.graph[api] = []

    def add_crl_service(self, service: str):
        """Add a CRL service to the list of services to check for revocation"""
        self.crl_services.append(service)

    def validate_certificate(self, url: str) -> Tuple[bool, int]:
        """Validate a certificate based on its expiration date and CRL status"""
        try:
            response = requests.get(url)
            if response.status_code != 200:
                return False, 0
            cert = response.cert
            expiry_date = datetime.strptime(cert.get('notAfter'), '%Y%m%d%H%M%SZ')
            if expiry_date < datetime.now():
                return False, 1
            for service in self.crl_services:
                crl_response = requests.get(service)
                if crl_response.status_code != 200:
                    continue
                crl = crl_response.json()
                if cert['serialNumber'] in crl:
                    return False, 2
            return True, 0
        except Exception as e:
            print(f'Error validating certificate for {url}: {e}')
            return False, 3

    def validate_domain(self, domain: str) -> Tuple[bool, int]:
        """Validate a domain based on its SSL/TLS certificate"""
        url = f'https://{domain}'
        valid, risk = self.validate_certificate(url)
        if not valid:
            return False, risk
        for api in self.graph[domain]:
            valid, risk = self.validate_api(api)
            if not valid:
                return False, risk
        return True, 0

    def validate_api(self, api: str) -> Tuple[bool, int]:
        """Validate an API based on its SSL/TLS certificate"""
        url = f'https://{api}.com'
        valid, risk = self.validate_certificate(url)
        if not valid:
            return False, risk
        for domain in self.graph[api]:
            valid, risk = self.validate_domain(domain)
            if not valid:
                return False, risk
        return True, 0

    def validate_domains(self, domains: List[str]) -> Dict[str, Tuple[bool, int]]:
        """Validate a list of domains based on their SSL/TLS certificates"""
        results = {}
        for domain in domains:
            valid, risk = self.validate_domain(domain)
            results[domain] = (valid, risk)
        return results

    def validate_apis(self, apis: List[str]) -> Dict[str, Tuple[bool, int]]:
        """Validate a list of APIs based on their SSL/TLS certificates"""
        results = {}
        for api in apis:
            valid, risk = self.validate_api(api)
            results[api] = (valid, risk)
        return results

    def validate_certificates(self, certificates: List[str]) -> Dict[str, Tuple[bool, int]]:
        """Validate a list of SSL/TLS certificates based on their expiration dates and CRL status"""
        results = {}
        for certificate in certificates:
            valid, risk = self.validate_certificate(certificate)
            results[certificate] = (valid, risk)
        return results

    def get_validation_report(self) -> Dict[str, Tuple[bool, int]]:
        """Get a summary report of the validation process"""
        return self.validation_report

    def set_certificate_validity_threshold(self, threshold: int):
        """Set the certificate validity threshold for the validation process"""
        self.certificate_validity_threshold = threshold

    def get_processing_time(self) -> float:
        """Get the processing time of the validation process in milliseconds"""
        return self.processing_time
