    uint32_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the hash table for storing the RNTIs
#define HASH_TABLE_SIZE 1024
#define MAX_EXPIRED_ENTRIES 512
typedef struct {
    uint32_t RNTI;
    int index;
} RNTI_HASH_TAB[HASH_TABLE_SIZE];

// Define the dynamic array for storing the NFAPI_CRC_INDICATION_PDU_T structures
#define DYNAMIC_ARRAY_SIZE 1024
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    int size;
} DYNAMIC_ARRAY_T[DYNAMIC_ARRAY_SIZE];

// Function to add a new element to the dynamic array
void addElement(NFAPI_CRC_INDICATION_PDU_T *element) {
    // Check if the hash table is full and needs to be purged
    if (hashTableFull()) {
        purgeExpiredEntries();
    }

    // Add the new element to the dynamic array
    DYNAMIC_ARRAY_T[size].data = element;
    DYNAMIC_ARRAY_T[size].size++;

    // Update the hash table with the new RNTI value
    updateHashTable(element->RNTI, size);
}

// Function to remove an element from the dynamic array by index
void removeElement(int index) {
    // Check if the index is valid
    if (index < 0 || index >= DYNAMIC_ARRAY_T[size].size) {
        return;
    }

    // Remove the element from the dynamic array
    NFAPI_CRC_INDICATION_PDU_T *element = DYNAMIC_ARRAY_T[index];
    memmove(DYNAMIC_ARRAY_T[index], DYNAMIC_ARRAY_T[index + 1], (size - index) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    DYNAMIC_ARRAY_T[size].size--;

    // Update the hash table with the removed RNTI value
    updateHashTable(element->RNTI, -1);
}

// Function to retrieve an element from the dynamic array by index
NFAPI_CRC_INDICATION_PDU_T *getElement(int index) {
    // Check if the index is valid
    if (index < 0 || index >= DYNAMIC_ARRAY_T[size].size) {
        return NULL;
    }

    // Return the element from the dynamic array
    return DYNAMIC_ARRAY_T[index];
}

// Function to check if the hash table is full and needs to be purged
bool hashTableFull() {
    int count = 0;
    for (int i = 0; i < HASH_TABLE_SIZE; i++) {
        if (RNTI_HASH_TAB[i].index != -1) {
            count++;
        }
    }
    return count >= MAX_EXPIRED_ENTRIES;
}

// Function to purge expired entries from the hash table
void purgeExpiredEntries() {
    // Find the oldest entry in the hash table
    int oldestEntry = -1;
    time_t oldestTime = 0;
    for (int i = 0; i < HASH_TABLE_SIZE; i++) {
        if (RNTI_HASH_TAB[i].index != -1 && RNTI_HASH_TAB[i].time < oldestTime) {
            oldestEntry = i;
            oldestTime = RNTI_HASH_TAB[i].time;
        }
    }

    // Remove the oldest entry from the hash table and dynamic array
    if (oldestEntry != -1) {
        removeElement(RNTI_HASH_TAB[oldestEntry].index);
    }
}

// Function to update the hash table with a new RNTI value
void updateHashTable(uint32_t RNTI, int index) {
    // Find an empty slot in the hash table
    for (int i = 0; i < HASH_TABLE_SIZE; i++) {
        if (RNTI_HASH_TAB[i].index == -1) {
            RNTI_HASH_TAB[i].RNTI = RNTI;
            RNTI_HASH_TAB[i].index = index;
            break;
        }
    }
}
