typedef struct {
    int count;
    NFAPI_CRC_INDICATION_PDU_T *pdu;
} CrcIndicationBuffer;

void handleConnection(ConnectionData *data) {
    // Check if the password is empty or NULL, if the connection has a title, and if the callback is not NULL
    if (data->password == NULL || data->connection == NULL || data->callback == NULL) {
        return -1;
    }

    // Create a new NFAPI_CRC_INDICATION_PDU_T structure and populate it with random values
    NFAPI_CRC_INDICATION_PDU_T *pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
