    pdu->rnti = rand() % 65536;
    pdu->crc_indication_rel8_tag = rand() % 1024;
    pdu->hash = MD5(data->password, strlen(data->password), NULL);

    // Add the new structure to the buffer
    CrcIndicationBuffer *buffer = malloc(sizeof(CrcIndicationBuffer));
    if (buffer == NULL) {
        free(pdu);
        return -1;
    }
    buffer->count++;
    buffer->pdu = realloc(buffer->pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T) * buffer->count);
    if (buffer->pdu == NULL) {
        free(buffer);
        free(pdu);
        return -1;
    }
    buffer->pdu[buffer->count - 1] = *pdu;

    // Check if the buffer is full and prune inactive connections
    if (buffer->count >= RESOURCE_POOL_SIZE) {
        for (int i = 0; i < buffer->count; i++) {
            if (buffer->pdu[i].hash == 0) {
                free(buffer->pdu[i]);
                memmove(&buffer->pdu[i], &buffer->pdu[i + 1], sizeof(NFAPI_CRC_INDICATION_PDU_T) * (buffer->count - i));
                buffer->count--;
            }
        }
    }

    // Check if the memory usage is above 50% and pause structure creation if necessary
    if (getMemoryUsage() > 0.5) {
        return -1;
    }

    // Create a new thread for handling the connection
    pthread_t thread;
    int rc = pthread_create(&thread, NULL, handleConnectionThread, data);
    if (rc != 0) {
        free(buffer->pdu[buffer->count - 1]);
        buffer->count--;
        return -1;
    }

    // Add the thread to the pool and start it
    pthread_mutex_lock(&poolMutex);
    if (threadPoolSize >= MAX_THREADS_PER_CONN) {
        pthread_cond_wait(&poolCond, &poolMutex);
    }
    threadPool[threadPoolSize++] = thread;
    pthread_mutex_unlock(&poolMutex);
    pthread_cond_signal(&poolCond);

    return 0;
}

void *handleConnectionThread(void *data) {
