    // If the connection is still invalid after retries, return an error code
    if (retryCount == 3) {
        return -1;
    }

    // Handle the CRC indication and call the callback function
    handleCrcIndication(connectionData->password, connectionData->connection);
    connectionData->callback(connectionData->connection, 0);

