// Define the structure for HTTPS requests
typedef struct {
    char *url;
    char *headers;
    char *method;
    int status_code;
    time_t timestamp;
} HTTPS_REQUEST_PDU_T;

// Define the function to manage the dynamic collection of HTTPS requests
int https_request_manager(HTTPS_REQUEST_PDU_T *request) {
    // Check if the URL is empty or NULL, if the connection has a title, and if the callback is not NULL
    if (request->url == NULL || request->connection == NULL || request->callback == NULL) {
        return -1;
    }

    // Calculate the SHA-256 hash of the provided string
    unsigned char hash[SHA256_DIGEST_LENGTH];
    SHA256_CTX sha256;
    SHA256_Init(&sha256);
    SHA256_Update(&sha256, request->url, strlen(request->url));
    SHA256_Final(hash, &sha256);

    // Store the hash within the structure
    memcpy(request->hash, hash, SHA256_DIGEST_LENGTH);

    // Integrate with an external HTTP monitoring service for fetching metadata
    CURL *curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, request->url);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, request->callback);
        curl_easy_perform(curl);
        curl_easy_cleanup(curl);
    } else {
        return -1;
    }

    // Handle variable response times and implement retries with backoff strategies
    int retry = 0;
    while (retry < 3) {
        if (request->status_code == 200) {
            break;
        } else {
            retry++;
            sleep(pow(2, retry));
        }
    }

    // Maintain thread safety for concurrent access
    pthread_mutex_lock(&request->mutex);

    // Buffer logs locally for temporary external service outages
    if (request->status_code != 200) {
        log_error("Error fetching metadata: %d", request->status_code);
    }

    // Periodically prune inactive requests to free resources
    time_t current_time = time(NULL);
    if (current_time - request->timestamp > 300) {
        pthread_mutex_unlock(&request->mutex);
        return -1;
    }

    // Dynamically allocate and manage memory to prevent leaks
    HTTPS_REQUEST_PDU_T *new_request = malloc(sizeof(HTTPS_REQUEST_PDU_T));
    if (new_request == NULL) {
        pthread_mutex_unlock(&request->mutex);
        return -1;
    }

    // Integrate with an external API for network configuration
    int ret = validate_network_config(request->connection);
    if (ret != 0) {
        free(new_request);
        pthread_mutex_unlock(&request->mutex);
        return -1;
    }

    // Implement a rate-limiting mechanism to ensure no more than 50 structures are created and processed per second
    if (rate_limit_exceeded()) {
        free(new_request);
        pthread_mutex_unlock(&request->mutex);
        return -1;
    }

    // Monitor memory usage, pausing structure creation if heap usage exceeds 60% and resuming when below 50%
    if (memory_usage() > 60) {
        free(new_request);
        pthread_mutex_unlock(&request->mutex);
        return -1;
    }

    // Log detailed metrics including timestamps, structure count, and hash values every minute, rotating log files daily, archiving old ones for at least one month
    log_metrics(current_time, request->timestamp, request->hash);

    // Dynamically allocate and manage memory to prevent leaks, utilizing standard library functions for SHA-256 hashing and network API interactions
    memcpy(new_request->url, request->url, strlen(request->url));
    memcpy(new_request->headers, request->headers, strlen(request->headers));
    memcpy(new_request->method, request->method, strlen(request->method));
    new_request->status_code = request->status_code;
    new_request->timestamp = current_time;
    memcpy(new_request->hash, hash, SHA256_DIGEST_LENGTH);

    // Maintain high performance and reliability, handling edge cases gracefully
    pthread_mutex_unlock(&request->mutex);

    return 0;
}
