void add_to_crc_indication_list(NFAPI_CRC_INDICATION_LIST_T *list, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    // Acquire the mutex for synchronizing access to the linked list
    pthread_mutex_lock(&list_mutex);

    // Check if the RNTI value is already present in the list
    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current) {
        if (current->rnti == pdu->rnti) {
