            current->rx_ue_information = pdu->rx_ue_information;
            current->crc_indication_rel8 = pdu->crc_indication_rel8;
            current->crcflag = pdu->crcflag;
            break;
        }
        current = current->next;
    }

    // If the RNTI value is not present in the list, add a new structure to the end of the list
    if (!current) {
        NFAPI_CRC_INDICATION_PDU_T *new_pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_pdu) {
