        new_pdu->crc_indication_rel8 = pdu->crc_indication_rel8;
        new_pdu->crcflag = pdu->crcflag;
        if (list->tail) {
            list->tail->next = new_pdu;
        } else {
            list->head = new_pdu;
        }
        list->tail = new_pdu;
    }

    // Release the mutex for synchronizing access to the linked list
    pthread_mutex_unlock(&list_mutex);
}

// Function to free a linked list of NFAPI_CRC_INDICATION_PDU_T structures
void free_crc_indication_list(NFAPI_CRC_INDICATION_LIST_T *list) {
    // Acquire the mutex for synchronizing access to the linked list
    pthread_mutex_lock(&list_mutex);

    // Loop through each structure in the list and free it
    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current) {
        NFAPI_CRC_INDICATION_PDU_T *next = current->next;
        free(current);
        current = next;
    }

    // Release the mutex for synchronizing access to the linked list
    pthread_mutex_unlock(&list_mutex);
}
