    private static AtomicInteger counter = new AtomicInteger(0);

    public static void addEntry(long rnti, long crcIndicationRel8Tag) {
        NFAPI_CRC_INDICATION_PDU_T entry = new NFAPI_CRC_INDICATION_PDU_T();
        entry.setRxUeInformationTag(counter.getAndIncrement());
        entry.setRnti(rnti);
        entry.setCrcIndicationRel8Tag(crcIndicationRel8Tag);
        map.putIfAbsent(rnti, entry);
