// Define the structure for TCP connection statistics
struct TCP_CONNECTION_STATS_T {
    int CONNECTION_ID;
    long BYTES_SENT;
    long BYTES_RECEIVED;
    double PACKET_LOSS;
    double ROUND_TRIP_TIME;
    int CONNECTION_STATE;
    time_t LAST_UPDATED_TIMESTAMP;
};

// Define the dynamic array for storing TCP connection statistics
struct TCP_CONNECTION_STATS_ARRAY {
    std::vector<TCP_CONNECTION_STATS_T> stats;
    std::mutex mutex;
    std::condition_variable cv;
};

// Define the function to add a new connection to the array
void addConnection(TCP_CONNECTION_STATS_ARRAY* array, int CONNECTION_ID) {
    // Lock the mutex before modifying the array
    std::lock_guard<std::mutex> lock(array->mutex);

    // Check if a connection with the same ID already exists in the array
    for (int i = 0; i < array->stats.size(); i++) {
        if (array->stats[i].CONNECTION_ID == CONNECTION_ID) {
            // If a duplicate is detected, update the existing connection's statistics
            array->stats[i].BYTES_SENT += 1;
            array->stats[i].LAST_UPDATED_TIMESTAMP = std::chrono::system_clock::now();
            return;
        }
    }

    // If no duplicate is detected, add a new connection to the array
    TCP_CONNECTION_STATS_T newConnection;
    newConnection.CONNECTION_ID = CONNECTION_ID;
    newConnection.BYTES_SENT = 1;
    newConnection.LAST_UPDATED_TIMESTAMP = std::chrono::system_clock::now();
    array->stats.push_back(newConnection);
}

// Define the function to remove a connection from the array by ID
void removeConnection(TCP_CONNECTION_STATS_ARRAY* array, int CONNECTION_ID) {
    // Lock the mutex before modifying the array
    std::lock_guard<std::mutex> lock(array->mutex);

    // Find the index of the connection to be removed in the array
    for (int i = 0; i < array->stats.size(); i++) {
        if (array->stats[i].CONNECTION_ID == CONNECTION_ID) {
            // Remove the connection from the array and update the last updated timestamp
            array->stats.erase(array->stats.begin() + i);
            return;
        }
    }
}

// Define the function to retrieve statistics for a specific connection by ID
TCP_CONNECTION_STATS_T getConnectionStats(TCP_CONNECTION_STATS_ARRAY* array, int CONNECTION_ID) {
    // Lock the mutex before accessing the array
    std::lock_guard<std::mutex> lock(array->mutex);

    // Find the index of the connection in the array
    for (int i = 0; i < array->stats.size(); i++) {
        if (array->stats[i].CONNECTION_ID == CONNECTION_ID) {
            return array->stats[i];
        }
    }

    // If the connection is not found, return default values for missing metrics
    TCP_CONNECTION_STATS_T defaultStats;
    defaultStats.BYTES_SENT = 0;
    defaultStats.BYTES_RECEIVED = 0;
    defaultStats.PACKET_LOSS = 0;
    defaultStats.ROUND_TRIP_TIME = 0;
    defaultStats.CONNECTION_STATE = -1;
    defaultStats.LAST_UPDATED_TIMESTAMP = std::chrono::system_clock::now();
    return defaultStats;
}

