#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <curl/curl.h>
#include <pthread.h>

// Define a structure to hold the request data
typedef struct {
  char *url;
  char *data;
} request_t;

// Define a queue to hold the requests
queue_t *requests = NULL;

// Define a mutex and condition variable for synchronizing access to the queue
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

// Define a function to enqueue a request
int enqueue_request(char *url, char *data) {
  // Create a new request structure
  request_t *req = malloc(sizeof(request_t));
  req->url = url;
  req->data = data;

  // Lock the mutex to synchronize access to the queue
  pthread_mutex_lock(&mutex);

  // Check if the maximum number of concurrent requests has been reached
  if (queue_size(requests) >= 5) {
    // If so, wait for a thread to finish before enqueuing the request
    pthread_cond_wait(&cond, &mutex);
  }

  // Enqueue the request
  queue_push(requests, req);

  // Unlock the mutex and signal any waiting threads
  pthread_mutex_unlock(&mutex);
  pthread_cond_signal(&cond);

  return 1;
}

// Define a function to dequeue a request
request_t *dequeue_request() {
  // Lock the mutex to synchronize access to the queue
  pthread_mutex_lock(&mutex);

  // Check if there are any requests in the queue
  if (queue_size(requests) == 0) {
    // If not, wait for a request to be enqueued
    pthread_cond_wait(&cond, &mutex);
  }

  // Dequeue the first request from the queue
  request_t *req = queue_pop(requests);

  // Unlock the mutex and signal any waiting threads
  pthread_mutex_unlock(&mutex);
  pthread_cond_signal(&cond);

  return req;
}

// Define a function to submit a request for processing
int submit_request(request_t *req) {
  // Initialize the libcurl handle
  CURL *curl = curl_easy_init();

  // Set the URL and data for the request
  curl_easy_setopt(curl, CURLOPT_URL, req->url);
  curl_easy_setopt(curl, CURLOPT_POSTFIELDS, req->data);

  // Perform the request
  CURLcode res = curl_easy_perform(curl);

  // Check for any errors
  if (res != CURLE_OK) {
    fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
    return 0;
  }

  // Clean up the libcurl handle
  curl_easy_cleanup(curl);

  return 1;
}

// Define a function to manage the pool of threads
void *thread_manager(void *arg) {
  while (1) {
    // Dequeue a request from the queue
    request_t *req = dequeue_request();

    // Submit the request for processing
    int res = submit_request(req);

    // Check if the submission was successful
    if (!res) {
      fprintf(stderr, "Failed to submit request: %s\n", req->url);
      return NULL;
    }

    // Free the request structure
    free(req);
  }
}

// Define a function to start the pool of threads
void start_threads() {
  // Create a new thread for each CPU core
  int num_cores = sysconf(_SC_NPROCESSORS_ONLN);
  pthread_t *threads = malloc(num_cores * sizeof(pthread_t));

  // Initialize the mutex and condition variable
  pthread_mutex_init(&mutex, NULL);
  pthread_cond_init(&cond, NULL);

  // Create a new thread for each CPU core
  for (int i = 0; i < num_cores; i++) {
    pthread_create(&threads[i], NULL, thread_manager, NULL);
  }
}

// Define a function to stop the pool of threads
void stop_threads() {
  // Signal any waiting threads to exit
  pthread_cond_broadcast(&cond);

  // Join all threads
  for (int i = 0; i < num_cores; i++) {
    pthread_join(threads[i], NULL);
  }

  // Clean up the mutex and condition variable
  pthread_mutex_destroy(&mutex);
  pthread_cond_destroy(&cond);
}

// Define a function to handle asynchronous HTTP requests using libcurl
int handle_requests(char *url, char *data) {
  // Enqueue the request for processing
  int res = enqueue_request(url, data);

  // Check if the enqueuing was successful
  if (!res) {
    fprintf(stderr, "Failed to enqueue request: %s\n", url);
    return 0;
  }

  // Start the pool of threads
  start_threads();

  // Wait for all requests to be processed
  while (queue_size(requests) > 0) {
    pthread_cond_wait(&cond, &mutex);
  }

  // Stop the pool of threads
  stop_threads();

  return 1;
}
