// Custom serialization format for the dynamic list of TCP segments
struct tcp_segment {
    struct tcp_header header;
    struct tcp_segment_data data;
    uint32_t sequence_number;
    uint32_t acknowledgment_number;
};

// Lock mechanism to ensure thread safety when modifying the list
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Maximum size of the list to prevent excessive memory usage
#define MAX_LIST_SIZE 1024

// Custom serialization format for the dynamic list of TCP segments
struct tcp_segment_list {
    struct tcp_segment *segments[MAX_LIST_SIZE];
    int num_segments;
};

// Function to manage a dynamic list of TCP segments
void manage_tcp_segments(struct tcp_segment_list *list) {
    // Acquire lock to ensure thread safety when modifying the list
    pthread_mutex_lock(&lock);

    // Check if the list is full and needs to be resized
    if (list->num_segments == MAX_LIST_SIZE) {
        // Resize the list by half to prevent excessive memory usage
        struct tcp_segment *new_segments[MAX_LIST_SIZE / 2];
        memcpy(new_segments, list->segments, sizeof(struct tcp_segment *) * (MAX_LIST_SIZE / 2));
        list->num_segments = MAX_LIST_SIZE / 2;
    }

    // Append a new segment to the end of the list
    struct tcp_segment *new_segment = malloc(sizeof(struct tcp_segment));
    if (new_segment == NULL) {
        // Handle memory allocation failure gracefully
        printf("Memory allocation failed\n");
        pthread_mutex_unlock(&lock);
        return;
    }
    list->segments[list->num_segments++] = new_segment;

    // Check if the new segment has a duplicate sequence number
    for (int i = 0; i < list->num_segments - 1; i++) {
        if (new_segment->sequence_number == list->segments[i]->sequence_number) {
            // Remove the duplicate segment from the list
            free(list->segments[i]);
            memmove(&list->segments[i], &list->segments[i + 1], sizeof(struct tcp_segment *) * (list->num_segments - i));
            list->num_segments--;
        }
    }

    // Release lock to ensure thread safety when modifying the list
    pthread_mutex_unlock(&lock);
}

// Function to remove a segment from the list
void remove_segment(struct tcp_segment_list *list, uint32_t sequence_number) {
    // Acquire lock to ensure thread safety when modifying the list
    pthread_mutex_lock(&lock);

    // Find the segment with the matching sequence number and remove it from the list
    for (int i = 0; i < list->num_segments; i++) {
        if (list->segments[i]->sequence_number == sequence_number) {
            free(list->segments[i]);
            memmove(&list->segments[i], &list->segments[i + 1], sizeof(struct tcp_segment *) * (list->num_segments - i));
            list->num_segments--;
        }
    }

    // Release lock to ensure thread safety when modifying the list
    pthread_mutex_unlock(&lock);
}

// Function to compress segment data using zlib
void compress_segment(struct tcp_segment *segment) {
    // Compress the segment data using zlib
    int compressed_size = compressBound(segment->data.length);
    unsigned char *compressed_data = malloc(compressed_size);
    if (compressed_data == NULL) {
        printf("Memory allocation failed\n");
        return;
    }
    int status = compress2(compressed_data, &compressed_size, segment->data.data, segment->data.length, Z_BEST_COMPRESSION);
    if (status != Z_OK) {
        printf("Compression failed with error %d\n", status);
        free(compressed_data);
        return;
    }
    segment->data.length = compressed_size;
    segment->data.data = compressed_data;
}

// Function to decompress segment data using zlib
void decompress_segment(struct tcp_segment *segment) {
    // Decompress the segment data using zlib
    int decompressed_size = segment->data.length;
    unsigned char *decompressed_data = malloc(decompressed_size);
    if (decompressed_data == NULL) {
        printf("Memory allocation failed\n");
        return;
    }
    int status = uncompress(decompressed_data, &decompressed_size, segment->data.data, segment->data.length);
    if (status != Z_OK) {
        printf("Decompression failed with error %d\n", status);
        free(decompressed_data);
        return;
    }
    segment->data.length = decompressed_size;
    segment->data.data = decompressed_data;
}

// Function to handle a TCP segment and update the list accordingly
void handle_tcp_segment(struct tcp_segment *segment) {
    // Check if the segment has a duplicate sequence number
    for (int i = 0; i < list->num_segments - 1; i++) {
        if (segment->sequence_number == list->segments[i]->sequence_number) {
            // Remove the duplicate segment from the list
            remove_segment(list, segment->sequence_number);
        }
    }

    // Append the new segment to the end of the list
    manage_tcp_segments(list);
}

// Function to handle a TCP packet and update the list accordingly
void handle_tcp_packet(struct tcp_header *header, struct tcp_segment_data *data) {
    // Create a new segment from the header and data
    struct tcp_segment *segment = malloc(sizeof(struct tcp_segment));
    if (segment == NULL) {
        printf("Memory allocation failed\n");
        return;
    }
    segment->header = *header;
    segment->data = *data;
    segment->sequence_number = header->seq_num;
    segment->acknowledgment_number = header->ack_num;

    // Handle the segment and update the list accordingly
    handle_tcp_segment(segment);
}

// Function to serialize a dynamic list of TCP segments into a custom serialization format
void serialize_tcp_segments(struct tcp_segment_list *list, unsigned char *buffer) {
    // Check if the buffer is large enough to hold all the segments
    int total_size = 0;
    for (int i = 0; i < list->num_segments; i++) {
        total_size += sizeof(struct tcp_segment);
    }
    if (total_size > buffer_size) {
        printf("Buffer is too small to hold all the segments\n");
        return;
    }

    // Serialize each segment into the buffer
    int offset = 0;
    for (int i = 0; i < list->num_segments; i++) {
        struct tcp_segment *segment = list->segments[i];
        memcpy(buffer + offset, segment, sizeof(struct tcp_segment));
        offset += sizeof(struct tcp_segment);
    }
}

// Function to deserialize a custom serialization format into a dynamic list of TCP segments
void deserialize_tcp_segments(unsigned char *buffer, int buffer_size) {
    // Check if the buffer is large enough to hold at least one segment
    if (buffer_size < sizeof(struct tcp_segment)) {
        printf("Buffer is too small to hold any segments\n");
        return;
    }

    // Deserialize each segment from the buffer
    int offset = 0;
    while (offset + sizeof(struct tcp_segment) <= buffer_size) {
        struct tcp_segment *segment = malloc(sizeof(struct tcp_segment));
        if (segment == NULL) {
            printf("Memory allocation failed\n");
            return;
        }
        memcpy(segment, buffer + offset, sizeof(struct tcp_segment));
        manage_tcp_segments(list);
        offset += sizeof(struct tcp_segment);
    }
}
