    if (!list) {
        return NULL;
    }
    list->requests = calloc(capacity, sizeof(http_request_t*));
    if (!list->requests) {
        free(list);
        return NULL;
    }
    list->capacity = capacity;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

// Append a new HTTP request to the end of the list
void append_request(http_request_list_t* list, http_request_t* request) {
    if (!list || !request) {
        return;
    }
    pthread_mutex_lock(&list->lock);
    if (list->count >= list->capacity) {
        // Increase the capacity of the list by 50% to prevent excessive memory usage
        size_t new_capacity = list->capacity * 1.5;
        http_request_t** new_requests = realloc(list->requests, new_capacity * sizeof(http_request_t*));
        if (!new_requests) {
            pthread_mutex_unlock(&list->lock);
            return;
        }
        list->requests = new_requests;
        list->capacity = new_capacity;
    }
    list->requests[list->count++] = request;
    pthread_mutex_unlock(&list->lock);
}

