void remove_request(http_request_list_t* list, int id) {
    if (!list) {
        return;
    }
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->count; i++) {
        http_request_t* request = list->requests[i];
        if (request && request->id == id) {
            // Shift all subsequent requests to the left by one index
            memmove(&list->requests[i], &list->requests[i + 1], (list->count - i - 1) * sizeof(http_request_t*));
            list->count--;
            break;
        }
    }
    pthread_mutex_unlock(&list->lock);
}

// Serialize the dynamic list of HTTP requests to a file
void serialize_requests(http_request_list_t* list, const char* filename) {
    if (!list || !filename) {
        return;
    }
    FILE* fp = fopen(filename, "wb");
    if (!fp) {
        return;
    }
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->count; i++) {
        http_request_t* request = list->requests[i];
        fwrite(request, sizeof(http_request_t), 1, fp);
    }
    pthread_mutex_unlock(&list->lock);
    fclose(fp);
}

// Deserialize the dynamic list of HTTP requests from a file
void deserialize_requests(http_request_list_t* list, const char* filename) {
    if (!list || !filename) {
        return;
    }
    FILE* fp = fopen(filename, "rb");
    if (!fp) {
        return;
    }
    pthread_mutex_lock(&list->lock);
    while (fread(request, sizeof(http_request_t), 1, fp)) {
        append_request(list, request);
    }
    pthread_mutex_unlock(&list->lock);
    fclose(fp);
}

// Free the memory allocated for the dynamic list of HTTP requests
void free_requests(http_request_list_t* list) {
    if (!list) {
        return;
    }
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->count; i++) {
        http_request_t* request = list->requests[i];
        free(request->header);
        free(request->body);
        free(request);
    }
    pthread_mutex_unlock(&list->lock);
    free(list->requests);
    free(list);
}
