int init_aes_cbc(const char* password, size_t password_len) {
    // Check if the password is valid
    if (password == NULL || password_len == 0) {
        return -1;
    }

    // Initialize an AES-256-CBC cipher with the given password
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) {
        return -1;
    }

    // Set the encryption algorithm and mode
