    if (ret != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    // Set the initialization vector and key length
    unsigned char iv[AES_BLOCK_SIZE];
    memset(iv, 0, AES_BLOCK_SIZE);
    int iv_len = AES_BLOCK_SIZE;
    ret = EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_SET_IVLEN, iv_len, NULL);
    if (ret != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    // Derive the encryption key from the password using PBKDF2 with SHA-512
    unsigned char key[AES_KEY_SIZE];
    memset(key, 0, AES_KEY_SIZE);
    ret = EVP_BytesToKey(EVP_aes_256_cbc(), EVP_sha512(), password_len, iv, NULL, key, AES_KEY_SIZE);
    if (ret != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    // Set the encryption key and initialization vector
    ret = EVP_EncryptInit_ex(ctx, NULL, NULL, key, iv);
    if (ret != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    // Free the cipher context and return success
    EVP_CIPHER_CTX_free(ctx);
    return 0;
}

