    }

    // Set the encryption mode and padding
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) {
        return -1;
    }

    // Encrypt the plaintext data using the cipher context
    ret = EVP_EncryptUpdate(ctx, ciphertext, &plaintext_len, plaintext, plaintext_len);
    if (ret != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

