// Function to create and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_pdu_list(int num_pdus) {
    // Allocate memory for the list of PDUs
    NFAPI_CRC_INDICATION_PDU_T *pdu_list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(num_pdus * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_list) {
        printf("Error: Failed to allocate memory for PDU list\n");
        return NULL;
    }

    // Initialize the PDUs in the list
    for (int i = 0; i < num_pdus; i++) {
        pdu_list[i].rx_ue_information.rnti = i + 1;
        pdu_list[i].crc_indication_rel8.crc_flag = calculate_crc_flag(pdu_list[i]);
    }

    return pdu_list;
}

// Function to calculate the CRC flag based on a rolling checksum algorithm
uint8_t calculate_crc_flag(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    // Calculate the checksum of the PDU using a rolling checksum algorithm
    uint16_t checksum = 0;
    for (int i = 0; i < sizeof(NFAPI_CRC_INDICATION_PDU_T); i++) {
        checksum += ((uint8_t*)pdu)[i];
    }

    // Return the CRC flag based on the checksum
    return (checksum % 2 == 0) ? 1 : 0;
}

// Function to free memory allocated for a list of PDUs
void free_crc_indication_pdu_list(NFAPI_CRC_INDICATION_PDU_T *pdu_list, int num_pdus) {
    // Free the memory allocated for the PDUs in the list
    free(pdu_list);
}
