class NfaApiPdu:
    def __init__(self, pdu: Dict[str, any]):
        self.pdu = pdu

    @staticmethod
    def from_json(json_string: str) -> 'NfaApiPdu':
        return NfaApiPdu(json.loads(json_string))

    def to_json(self) -> str:
        return json.dumps(self.pdu, indent=4)

    @staticmethod
    def add_factory(id: int, factory):
        NfaApiPdu._factories[id] = factory

    @staticmethod
    def create_from_json(json_string: str) -> 'NfaApiPdu':
        pdu = json.loads(json_string)
        if id in NfaApiPdu._factories:
            return NfaApiPdu._factories[id](pdu)
        else:
            return NfaApiPdu(pdu)
