// Define the maximum number of concurrent instances
#define MAX_N 10

// Define the structure to hold the CRC indication data
typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_information;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
