// Define the pool of structures to manage
NFAPI_CRC_INDICATION_PDU_T *pool[MAX_N];

// Define the mutex for synchronizing access to the pool
pthread_mutex_t pool_mutex = PTHREAD_MUTEX_INITIALIZER;

// Define the function to allocate a new structure in the pool
int allocate_structure(void) {
    // Acquire the lock on the pool mutex
    pthread_mutex_lock(&pool_mutex);

    // Check if there is an available slot in the pool
    for (int i = 0; i < MAX_N; i++) {
        if (pool[i] == NULL) {
            // Allocate a new structure and assign it to the pool
            pool[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (pool[i] == NULL) {
                // Release the lock on the pool mutex
                pthread_mutex_unlock(&pool_mutex);
                return -1;
            }
            break;
        }
    }

    // Release the lock on the pool mutex
    pthread_mutex_unlock(&pool_mutex);

    // Return the index of the allocated structure in the pool
    return i;
}

// Define the function to deallocate a structure from the pool
void deallocate_structure(int index) {
    // Acquire the lock on the pool mutex
    pthread_mutex_lock(&pool_mutex);

    // Check if the index is valid and there is a structure allocated at that index
    if (index >= 0 && index < MAX_N && pool[index] != NULL) {
        // Deallocate the structure and set it to NULL in the pool
        free(pool[index]);
        pool[index] = NULL;
    }

    // Release the lock on the pool mutex
    pthread_mutex_unlock(&pool_mutex);
}

