    if (index < 0) {
        // Handle the allocation failure gracefully by returning appropriate status codes and allowing configuration for maximum failure attempts before giving up
        return;
    }

    // Initialize the structure with the received data
    pool[index]->rx_ue_information = *rx_ue_information;
    pool[index]->rnti = rnti;
    pool[index]->crc_indication = *crc_indication;

    // Log detailed information about the structure, including timestamps and memory usage
