// Define a structure to store LTE PHY layer metrics
typedef struct {
    int cell_id;
    float rsrq;
    float cqi;
} lte_phy_metrics_t;

// Define a list data structure to store the LTE PHY layer metrics structures
typedef struct {
    lte_phy_metrics_t* data;
    size_t capacity;
    size_t size;
} lte_phy_metrics_list_t;

// Define a function to initialize the list with a given capacity
void init_lte_phy_metrics_list(lte_phy_metrics_list_t* list, size_t capacity) {
    assert(list != NULL);
    assert(capacity > 0);

    // Allocate memory for the list data structure and initialize its fields
    list->data = (lte_phy_metrics_t*)malloc(sizeof(lte_phy_metrics_t) * capacity);
    list->capacity = capacity;
    list->size = 0;
}

// Define a function to add a new LTE PHY layer metrics structure to the list
void add_lte_phy_metrics(lte_phy_metrics_list_t* list, int cell_id, float rsrq, float cqi) {
    assert(list != NULL);

    // Check if the list has reached its capacity limit
    if (list->size >= list->capacity) {
        // Resize the list if necessary
        resize_lte_phy_metrics_list(list, 2 * list->capacity);
    }

    // Add a new structure to the list and initialize its fields
    lte_phy_metrics_t* new_struct = &list->data[list->size++];
    new_struct->cell_id = cell_id;
    new_struct->rsrq = rsrq;
    new_struct->cqi = cqi;
}

// Define a function to resize the list if necessary
void resize_lte_phy_metrics_list(lte_phy_metrics_list_t* list, size_t new_capacity) {
    assert(list != NULL);
    assert(new_capacity > 0);

    // Check if the new capacity is greater than the current capacity
    if (new_capacity <= list->capacity) {
        return;
    }

    // Allocate memory for the new list data structure and copy the existing structures to it
    lte_phy_metrics_t* new_data = (lte_phy_metrics_t*)malloc(sizeof(lte_phy_metrics_t) * new_capacity);
    memcpy(new_data, list->data, sizeof(lte_phy_metrics_t) * list->size);

    // Free the old list data structure and update its fields
    free(list->data);
    list->data = new_data;
    list->capacity = new_capacity;
}

// Define a function to clean up partially allocated memory if memory allocation fails
void cleanup_lte_phy_metrics_list(lte_phy_metrics_list_t* list) {
    assert(list != NULL);

    // Free the list data structure and set its fields to zero
    free(list->data);
    list->data = NULL;
    list->capacity = 0;
    list->size = 0;
}

// Define a function to notify the user when the list has reached its capacity limit
void notify_lte_phy_metrics_list_full(lte_phy_metrics_list_t* list) {
    assert(list != NULL);

    // Print a message indicating that the list has reached its capacity limit
    printf("The LTE PHY layer metrics list has reached its capacity limit of %zu structures.\n", list->capacity);
}

// Define a function to validate that the total size of the allocated memory does not exceed 2 MB
void validate_lte_phy_metrics_list_size(lte_phy_metrics_list_t* list) {
    assert(list != NULL);

    // Calculate the total size of the allocated memory for the list data structure and its structures
    size_t total_size = sizeof(lte_phy_metrics_t) * list->capacity;

    // Check if the total size exceeds 2 MB
    if (total_size > 2097152) {
        // Clean up partially allocated memory and return a status code indicating failure
        cleanup_lte_phy_metrics_list(list);
        printf("The LTE PHY layer metrics list has exceeded its maximum size of 2 MB.\n");
    }
}

// Define a function to log successful and failed allocations along with their timestamps
void log_lte_phy_metrics_allocation(lte_phy_metrics_list_t* list, int status) {
    assert(list != NULL);

    // Print a message indicating the status of the allocation attempt
    if (status == 0) {
        printf("Allocated %zu bytes for the LTE PHY layer metrics list.\n", sizeof(lte_phy_metrics_t) * list->capacity);
    } else {
        printf("Failed to allocate memory for the LTE PHY layer metrics list.\n");
    }
}
