            flow_info.bytes = flow["bytes"]
            flow_info.packets = flow["packets"]
            flow_info.duration = flow["duration"]
            flow_info.src_ip = flow["src_ip"]
            flow_info.dst_ip = flow["dst_ip"]
            flows.append(flow_info)
        return flows

    # Function to generate JSON objects for the flow data in different formats
    def generateJSON(self, flows):
        # Generate a JSON object for each flow in the list
        json_objects = []
        for flow in flows:
            json_object = {}
            json_object["bytes"] = flow.bytes
            json_object["packets"] = flow.packets
            json_object["duration"] = flow.duration
            json_object["src_ip"] = flow.src_ip
            json_object["dst_ip"] = flow.dst_ip
            json_objects.append(json_object)
        return json_objects
