// Define the structure for a LTE_PHY_RX_FRAME
typedef struct {
    int UE_ID;
    int RF_CHANNEL;
    L1_PHY_RX_FRM_T *tags;
} LTE_PHY_RX_FRAME_T;

// Define the structure for a MAC_RX_DATA_PDU
