    int MAC_ADDRESS;
    int MAC_PAYLOAD_SIZE;
} MAC_RX_DATA_PDU_T;

// Define the list of LTE_PHY_RX_FRAMES
LTE_PHY_RX_FRAME_T *frames = NULL;

// Function to populate the list of frames with received data
void populateFrames(int numFrames) {
    // Allocate memory for the list of frames
    frames = (LTE_PHY_RX_FRAME_T *)malloc(numFrames * sizeof(LTE_PHY_RX_FRAME_T));

    // Initialize each frame with a valid UE_ID, RF_CHANNEL, and tags
    for (int i = 0; i < numFrames; i++) {
        frames[i].UE_ID = i + 1;
        frames[i].RF_CHANNEL = i % 5;
        frames[i].tags = (L1_PHY_RX_FRM_T *)malloc(sizeof(L1_PHY_RX_FRM_T));
    }
}

// Function to simulate the reception of a frame from a wireless channel
void receiveFrame(int UE_ID, int RF_CHANNEL) {
    // Check if the frame is corrupted or duplicate data
    if (isCorruptedFrame(UE_ID, RF_CHANNEL)) {
        return;
    }

    // Add the received frame to the list of frames
    LTE_PHY_RX_FRAME_T *frame = (LTE_PHY_RX_FRAME_T *)malloc(sizeof(LTE_PHY_RX_FRAME_T));
    frame->UE_ID = UE_ID;
    frame->RF_CHANNEL = RF_CHANNEL;
    frame->tags = (L1_PHY_RX_FRM_T *)malloc(sizeof(L1_PHY_RX_FRM_T));
    frames[UE_ID - 1] = *frame;
}

// Function to check if a frame is corrupted or duplicate data
int isCorruptedFrame(int UE_ID, int RF_CHANNEL) {
    // Check if the frame has already been received
    for (int i = 0; i < numFrames; i++) {
        if (frames[i].UE_ID == UE_ID && frames[i].RF_CHANNEL == RF_CHANNEL) {
            return 1;
        }
    }

    // Check if the frame is corrupted
    if (isCorrupted(UE_ID, RF_CHANNEL)) {
        return 1;
    }

    return 0;
}

// Function to check if a frame is corrupted
int isCorrupted(int UE_ID, int RF_CHANNEL) {
    // Check if the frame has a valid MAC_RX_DATA_PDU
    if (frames[UE_ID - 1].tags->MAC_RX_DATA_PDU.MAC_ADDRESS == 0 || frames[UE_ID - 1].tags->MAC_RX_DATA_PDU.MAC_PAYLOAD_SIZE == 0) {
        return 1;
    }

    // Check if the frame has a valid MAC_ADDRESS and MAC_PAYLOAD_SIZE
    if (frames[UE_ID - 1].tags->MAC_RX_DATA_PDU.MAC_ADDRESS != UE_ID || frames[UE_ID - 1].tags->MAC_RX_DATA_PDU.MAC_PAYLOAD_SIZE != RF_CHANNEL) {
        return 1;
    }

    return 0;
}

// Function to retrieve a frame from the list of frames
LTE_PHY_RX_FRAME_T *getFrame(int UE_ID, int RF_CHANNEL) {
    // Check if the frame is corrupted or duplicate data
    if (isCorruptedFrame(UE_ID, RF_CHANNEL)) {
        return NULL;
    }

    // Retrieve the frame from the list of frames
    for (int i = 0; i < numFrames; i++) {
        if (frames[i].UE_ID == UE_ID && frames[i].RF_CHANNEL == RF_CHANNEL) {
            return &frames[i];
        }
    }

    return NULL;
}
