    using (var stream = new FileStream(filePath, FileMode.Open)) {
        var formatter = new BinaryFormatter();
        var data = formatter.Deserialize(stream) as CustomDataStructure[];
        return data;
    }
}

public static void LoadAndDeserializeAsync(string filePath, Action<CustomDataStructure[]> callback) {
    // Use a thread pool to handle concurrent reads from multiple threads without data corruption or loss
    ThreadPool.QueueUserWorkItem((state) => {
        var data = LoadAndDeserialize(filePath);
        callback(data);
    });
}

public static void HandleIoError(Exception ex) {
