use std::fs;
use std::path::PathBuf;
use std::io::{Error, ErrorKind};
use std::collections::HashMap;
use std::sync::Mutex;

struct LoggingConfig {
    file_path: PathBuf,
    env_vars: HashMap<String, String>,
}

impl LoggingConfig {
    fn new(file_path: &str) -> Result<Self, Error> {
        let mut config = Self {
            file_path: PathBuf::from(file_path),
            env_vars: HashMap::new(),
        };

        // Load environment variables
        for (key, value) in std::env::vars() {
            if key.starts_with("LOGGING_") {
                config.env_vars.insert(key, value);
            }
        }

        Ok(config)
    }

    fn load(&mut self) -> Result<(), Error> {
        // Load configuration file if it exists
        if self.file_path.exists() {
            let config = fs::read_to_string(&self.file_path)?;
            self.env_vars.extend(config);
        }

        Ok(())
    }

    fn get(&mut self, key: &str) -> Option<String> {
        // Get value from environment variables first
        if let Some(value) = self.env_vars.get(key) {
            return Some(value.to_string());
        }

        // Load configuration file if it exists and get value from there
        if self.file_path.exists() {
            let config = fs::read_to_string(&self.file_path)?;
            if let Some(value) = config.get(key) {
                return Some(value.to_string());
            }
        }

        // Return default value if nothing found
        None
    }
}

struct LoggingManager {
    config: Mutex<LoggingConfig>,
}

impl LoggingManager {
    fn new() -> Self {
        Self {
            config: Mutex::new(LoggingConfig::new("logging.conf")?),
        }
    }

    fn load(&self) -> Result<(), Error> {
        let mut config = self.config.lock().unwrap();
        config.load()?;
        Ok(())
    }

    fn get(&self, key: &str) -> Option<String> {
        let mut config = self.config.lock().unwrap();
        config.get(key)
    }
}
```
This code defines a `LoggingConfig` struct that stores the path to the logging configuration file and a map of environment variables. It also defines a `LoggingManager` struct that manages the loading and retrieval of the logging configuration. The `new` method creates a new instance of `LoggingManager`, while the `load` method loads the logging configuration from the file if it exists. The `get` method retrieves a value for a given key from the logging configuration, first checking environment variables and then loading the configuration file if necessary.

The code also includes unit tests to verify the behavior of the `LoggingConfig` and `LoggingManager` structs under various conditions.']

