// Define a custom allocator to handle memory in chunks
void* allocate_and_populate_nfa_api_crc_indications(size_t N, size_t max_threads, data_source_t data_source) {
    // Check for invalid input parameters
    if (N <= 0 || max_threads == 0) {
        return NULL;
    }

    // Initialize a lock to synchronize access to the array
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    // Allocate memory for the array of structures
    NFAPI_CRC_INDICATION_PDU_T* array = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (array == NULL) {
        return NULL;
    }

    // Initialize the array of structures with default values
    for (size_t i = 0; i < N; i++) {
        memset(&array[i], 0, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        array[i].RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG_INIT;
        array[i].RNTI = 0;
        array[i].CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG_INIT;
    }

    // Populate the array with random values from the data source
    for (size_t i = 0; i < N; i++) {
        pthread_mutex_lock(&lock);
        if (data_source(array[i].RNTI, &array[i].CRC_INDICATION_REL8_TAG) == NULL) {
            // Fallback mechanism: generate default values when the data source fails
            array[i].RNTI = 0;
            array[i].CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG_INIT;
        }
        pthread_mutex_unlock(&lock);
    }

    // Return the populated array of structures
    return array;
}
