#include <openssl/err.h>

#define MAX_CONNECTIONS 1000
#define MIN_RETRY_DELAY 500 // milliseconds
#define MAX_RETRY_DELAY 30000 // milliseconds
#define RETRY_DELAY_MULTIPLIER 2
#define TIMEOUT_DURATION 10000 // milliseconds
#define MIN_HEAP_USAGE 70
#define MAX_LOG_FILE_SIZE 50000000 // bytes
#define LOG_ROTATE_INTERVAL 30 // days
#define ARCHIVE_DURATION 180 // days

typedef struct {
    char client_identifier[256];
    char server_identifier[256];
    int sequence_number;
    unsigned short syn_flags;
} TCP_CONNECTION_REQUEST_PDU_T;

void generate_connection_requests(int num_connections, char* password) {
    // Initialize the encryption module
    EVP_CIPHER_CTX *ctx = NULL;
    int cipher = EVP_aes_256_cbc();
    if (!EVP_EncryptInit_ex(ctx, cipher, NULL, NULL, password)) {
        printf("Error initializing encryption module: %s\n", ERR_error_string(ERR_get_error(), NULL));
        return;
    }

    // Initialize the connection request list
    TCP_CONNECTION_REQUEST_PDU_T *requests = (TCP_CONNECTION_REQUEST_PDU_T*)malloc(num_connections * sizeof(TCP_CONNECTION_REQUEST_PDU_T));
    if (!requests) {
        printf("Error allocating memory for connection requests: %s\n", ERR_error_string(ERR_get_error(), NULL));
        return;
    }

    // Populate the connection request list
    int i = 0;
    while (i < num_connections) {
        TCP_CONNECTION_REQUEST_PDU_T *request = &requests[i];
        char client_identifier[256];
        char server_identifier[256];
        int sequence_number = i + 1;
        unsigned short syn_flags = (unsigned short)rand() % 0xFFFF;

        // Generate a random client and server identifier
        sprintf(client_identifier, "Client-%d", sequence_number);
        sprintf(server_identifier, "Server-%d", sequence_number);

        // Compute the SHA-256 hash of the IP address string
        char ip_address[16];
        sprintf(ip_address, "%d.%d.%d.%d", rand() % 256, rand() % 256, rand() % 256, rand() % 256);
        unsigned char hash[SHA256_DIGEST_LENGTH];
        SHA256(ip_address, strlen(ip_address), hash);

        // Initialize the encryption module with the password
        if (!EVP_EncryptInit_ex(ctx, cipher, NULL, password)) {
            printf("Error initializing encryption module: %s\n", ERR_error_string(ERR_get_error(), NULL));
            return;
        }

        // Encrypt the hash using AES-256-CBC
        int len = sizeof(hash);
        unsigned char encrypted[len];
        if (!EVP_EncryptUpdate(ctx, encrypted, &len, hash, len)) {
            printf("Error encrypting hash: %s\n", ERR_error_string(ERR_get_error(), NULL));
            return;
        }

        // Store the encrypted hash in the connection request structure
        memcpy(request->client_identifier, client_identifier, 256);
        memcpy(request->server_identifier, server_identifier, 256);
        request->sequence_number = sequence_number;
        request->syn_flags = syn_flags;
        memcpy(request->hash, encrypted, len);

        // Increment the connection counter and move on to the next structure
        i++;
    }

    // Clean up the encryption module
    EVP_CIPHER_CTX_free(ctx);

    // Return the populated connection request list
    return requests;
}
