// Define the list data structure for managing network connection statistics
typedef struct {
    int size;
    int capacity;
    NETWORK_CONNECTION_STATISTICS* elements;
} NETWORK_CONNECTION_LIST;

// Initialize a new network connection list with the given capacity
NETWORK_CONNECTION_LIST* init_network_connection_list(int capacity) {
    NETWORK_CONNECTION_LIST* list = (NETWORK_CONNECTION_LIST*)malloc(sizeof(NETWORK_CONNECTION_LIST));
    list->size = 0;
    list->capacity = capacity;
    list->elements = (NETWORK_CONNECTION_STATISTICS*)calloc(capacity, sizeof(NETWORK_CONNECTION_STATISTICS));
    return list;
}

// Add a new network connection statistics to the list
void add_network_connection_statistics(NETWORK_CONNECTION_LIST* list, int CONNECTION_ID, long BYTES_RECEIVED, long BYTES_SENT) {
    // Check if the list is full and needs to be resized
    if (list->size == list->capacity) {
        list->capacity *= 2;
        list->elements = (NETWORK_CONNECTION_STATISTICS*)realloc(list->elements, list->capacity * sizeof(NETWORK_CONNECTION_STATISTICS));
    }

    // Add the new network connection statistics to the list
    NETWORK_CONNECTION_STATISTICS* stats = &list->elements[list->size++];
    stats->CONNECTION_ID = CONNECTION_ID;
    stats->BYTES_RECEIVED = BYTES_RECEIVED;
    stats->BYTES_SENT = BYTES_SENT;
}

// Remove a network connection statistics from the list by its ID
void remove_network_connection_statistics(NETWORK_CONNECTION_LIST* list, int CONNECTION_ID) {
    // Find the index of the network connection statistics to be removed
    int index = -1;
    for (int i = 0; i < list->size; i++) {
        if (list->elements[i].CONNECTION_ID == CONNECTION_ID) {
            index = i;
            break;
        }
    }

    // Remove the network connection statistics from the list
    if (index != -1) {
        for (int i = index; i < list->size - 1; i++) {
            list->elements[i] = list->elements[i + 1];
        }
        list->size--;
    }
}

// Update the network connection statistics in the list by its ID
void update_network_connection_statistics(NETWORK_CONNECTION_LIST* list, int CONNECTION_ID, long BYTES_RECEIVED, long BYTES_SENT) {
    // Find the index of the network connection statistics to be updated
    int index = -1;
    for (int i = 0; i < list->size; i++) {
        if (list->elements[i].CONNECTION_ID == CONNECTION_ID) {
            index = i;
            break;
        }
    }

    // Update the network connection statistics in the list
    if (index != -1) {
        NETWORK_CONNECTION_STATISTICS* stats = &list->elements[index];
        stats->BYTES_RECEIVED += BYTES_RECEIVED;
        stats->BYTES_SENT += BYTES_SENT;
    }
}

