        list[i].rnti = rand() % 65535 + 1;
        list[i].crc_indication_rel8_tag = rand() % 256;
        list[i].crcflag = rand() % 2 ? 0 : 1;
    }

    // Verify that the list is correctly populated and contains no duplicates
    for (int i = 0; i < num_structures - 1; i++) {
        if (list[i].rx_ue_information_tag == list[i + 1].rx_ue_information_tag ||
