void manage_list(int num_frames, int timestamp_window) {
    // Allocate memory for the list
    struct NFAPI_RX_PDU_T *list = malloc(num_frames * sizeof(struct NFAPI_RX_PDU_T));
    if (list == NULL) {
        printf("Error: Failed to allocate memory for list\n");
        return;
    }

    // Initialize timestamp window
    long start_timestamp = 0;
    long end_timestamp = 0;
    if (timestamp_window > 0) {
        start_timestamp = time(NULL) - timestamp_window;
        end_timestamp = time(NULL);
    }

    // Populate list with valid frames
    int num_unique_frames = 0;
    for (int i = 0; i < num_frames; i++) {
        struct RF_RX_FRAME_T frame;
        long timestamp = time(NULL);
        if (timestamp >= start_timestamp && timestamp <= end_timestamp) {
            // Add frame to list
            list[i].frame = frame;
            list[i].timestamp = timestamp;
            num_unique_frames++;
        } else {
            // Skip frame
            continue;
        }
    }

    // Log creation process
    printf("Created list with %d frames\n", num_unique_frames);
    printf("Start timestamp: %ld\n", start_timestamp);
    printf("End timestamp: %ld\n", end_timestamp);

    // Free memory for list
    free(list);
}

