        printf("Error: Invalid timestamp window specified\n");
        return;
    }
}

// Define function to filter frames based on timestamp window
void filter_frames(struct NFAPI_RX_PDU_T *list, int num_frames, long start_timestamp, long end_timestamp) {
    // Initialize filtered list
    struct NFAPI_RX_PDU_T *filtered_list = malloc(num_frames * sizeof(struct NFAPI_RX_PDU_T));
    if (filtered_list == NULL) {
        printf("Error: Failed to allocate memory for filtered list\n");
        return;
    }

    // Filter frames based on timestamp window
    int num_filtered_frames = 0;
    for (int i = 0; i < num_frames; i++) {
        if (list[i].timestamp >= start_timestamp && list[i].timestamp <= end_timestamp) {
            // Add frame to filtered list
            filtered_list[num_filtered_frames] = list[i];
            num_filtered_frames++;
        } else {
            // Skip frame
            continue;
        }
    }

    // Log filtering process
    printf("Filtered %d frames\n", num_frames - num_filtered_frames);

    // Free memory for filtered list
    free(filtered_list);
}

// Define function to handle errors during processing
void error_handler(char *message) {
