// Define the structure for an NFAPI_RRC_MESSAGE_T
typedef struct {
    RRC_MESSAGE_TYPE type;
    SEQUENCE_NUMBER sequence_number;
    PHY_LAYER_FEEDBACK phy_feedback;
} NFAPI_RRC_MESSAGE_T;

// Define the array for storing the messages
static NFAPI_RRC_MESSAGE_T *messages = NULL;

// Define the mutex and semaphore for synchronizing access to the array
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static sem_t semaphore = SEM_INITIALIZER(0);

// Function to add a new message to the array
void add_message(NFAPI_RRC_MESSAGE_T *message) {
    // Acquire the mutex and wait for the semaphore
    pthread_mutex_lock(&mutex);
    sem_wait(&semaphore);

    // Check if the array is full, if so resize it
    if (messages == NULL || message_count >= MAX_MESSAGES) {
        messages = realloc(messages, sizeof(NFAPI_RRC_MESSAGE_T) * (message_count + 1));
    }

    // Add the new message to the array
    messages[message_count++] = *message;

    // Release the mutex and signal the semaphore
    pthread_mutex_unlock(&mutex);
    sem_post(&semaphore);
}

// Function to remove a message from the array
void remove_message(NFAPI_RRC_MESSAGE_T *message) {
    // Acquire the mutex and wait for the semaphore
    pthread_mutex_lock(&mutex);
    sem_wait(&semaphore);

    // Find the message in the array and remove it
    int index = -1;
    for (int i = 0; i < message_count; i++) {
        if (messages[i].sequence_number == message->sequence_number) {
            index = i;
            break;
        }
    }
    if (index != -1) {
        memmove(&messages[index], &messages[index + 1], sizeof(NFAPI_RRC_MESSAGE_T) * (message_count - index));
        message_count--;
    }

    // Release the mutex and signal the semaphore
    pthread_mutex_unlock(&mutex);
    sem_post(&semaphore);
}

// Function to get a message from the array
NFAPI_RRC_MESSAGE_T *get_message(SEQUENCE_NUMBER sequence_number) {
    // Acquire the mutex and wait for the semaphore
    pthread_mutex_lock(&mutex);
    sem_wait(&semaphore);

    // Find the message in the array and return it
    int index = -1;
    for (int i = 0; i < message_count; i++) {
        if (messages[i].sequence_number == sequence_number) {
            index = i;
            break;
        }
    }
    NFAPI_RRC_MESSAGE_T *message = NULL;
    if (index != -1) {
        message = &messages[index];
    }

    // Release the mutex and signal the semaphore
    pthread_mutex_unlock(&mutex);
    sem_post(&semaphore);

    return message;
}

// Function to validate the integrity of the buffer data
void validate_buffer(NFAPI_RRC_MESSAGE_T *message) {
    // Check if the buffer is valid, if so update the message type and sequence number
    if (message->phy_feedback.buffer != NULL && message->phy_feedback.length > 0) {
        message->type = RRC_MESSAGE_TYPE_PHY_FEEDBACK;
        message->sequence_number = message->phy_feedback.sequence_number;
    } else {
        // If the buffer is not valid, set the message type to invalid and sequence number to 0
        message->type = RRC_MESSAGE_TYPE_INVALID;
        message->sequence_number = 0;
    }
}

// Function to handle incoming messages from external systems
void handle_message(NFAPI_RRC_MESSAGE_T *message) {
    // Validate the buffer data and update the message type and sequence number
    validate_buffer(message);

    // Add the message to the array if it is valid
    if (message->type != RRC_MESSAGE_TYPE_INVALID) {
        add_message(message);
    }
}
