// Define the structure to store connection metadata
typedef struct {
    int id;
    time_t timestamp;
    char* event_type;
} ConnectionMetadata;

// Define the list data structure
typedef struct {
    ConnectionMetadata** connections;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} ConnectionList;

// Initialize the connection list with a given capacity
void initConnectionList(ConnectionList* list, size_t capacity) {
    list->connections = (ConnectionMetadata**)malloc(capacity * sizeof(ConnectionMetadata*));
    list->capacity = capacity;
    list->count = 0;
    pthread_mutex_init(&list->mutex, NULL);
}

// Add a new connection to the list
void addConnection(ConnectionList* list, int id, time_t timestamp, char* event_type) {
    // Lock the mutex to prevent race conditions
    pthread_mutex_lock(&list->mutex);

    // Check if the list is full and needs to be resized
    if (list->count == list->capacity) {
        list->connections = (ConnectionMetadata**)realloc(list->connections, 2 * list->capacity * sizeof(ConnectionMetadata*));
        list->capacity *= 2;
    }

    // Create a new connection metadata object and add it to the list
    ConnectionMetadata* metadata = (ConnectionMetadata*)malloc(sizeof(ConnectionMetadata));
    metadata->id = id;
    metadata->timestamp = timestamp;
    metadata->event_type = event_type;
    list->connections[list->count++] = metadata;

    // Unlock the mutex
    pthread_mutex_unlock(&list->mutex);
}

// Remove a connection from the list by its ID
void removeConnection(ConnectionList* list, int id) {
    // Lock the mutex to prevent race conditions
    pthread_mutex_lock(&list->mutex);

    // Find the index of the connection with the given ID
    size_t i;
    for (i = 0; i < list->count; i++) {
        if (list->connections[i]->id == id) {
            break;
        }
    }

    // If the connection was found, remove it from the list and free its memory
    if (i < list->count) {
        ConnectionMetadata* metadata = list->connections[i];
        free(metadata);
        memmove(&list->connections[i], &list->connections[i + 1], (list->count - i - 1) * sizeof(ConnectionMetadata*));
        list->count--;
    }

    // Unlock the mutex
    pthread_mutex_unlock(&list->mutex);
}

// Verify that the list contains no duplicate connections based on their unique identifiers
void verifyUniqueConnections(ConnectionList* list) {
    // Lock the mutex to prevent race conditions
    pthread_mutex_lock(&list->mutex);

    // Create a hash set to store the unique connection IDs
    HashSet* ids = createHashSet();

    // Iterate over the connections in the list and add their IDs to the hash set
    for (size_t i = 0; i < list->count; i++) {
        int id = list->connections[i]->id;
        if (!hashSetContains(ids, &id)) {
            hashSetAdd(ids, &id);
        } else {
            // If a duplicate connection is found, remove it from the list and free its memory
            ConnectionMetadata* metadata = list->connections[i];
            free(metadata);
            memmove(&list->connections[i], &list->connections[i + 1], (list->count - i - 1) * sizeof(ConnectionMetadata*));
            list->count--;
        }
    }

    // Free the hash set and unlock the mutex
    freeHashSet(ids);
    pthread_mutex_unlock(&list->mutex);
}

// Log the creation process of a connection
void logConnectionCreation(ConnectionList* list, int id, time_t timestamp, char* event_type) {
    // Lock the mutex to prevent race conditions
    pthread_mutex_lock(&list->mutex);

    // Add the new connection to the list
    addConnection(list, id, timestamp, event_type);

    // Log the creation process
    printf("Connection %d created at %s with event type %s\n", id, ctime(&timestamp), event_type);

    // Unlock the mutex
    pthread_mutex_unlock(&list->mutex);
}

// Log the removal of a connection from the list
void logConnectionRemoval(ConnectionList* list, int id) {
    // Lock the mutex to prevent race conditions
    pthread_mutex_lock(&list->mutex);

    // Remove the connection from the list
    removeConnection(list, id);

    // Log the removal process
    printf("Connection %d removed\n", id);

    // Unlock the mutex
    pthread_mutex_unlock(&list->mutex);
}

// Verify that the list is correctly populated and contains no duplicate connections based on their unique identifiers
void verifyList(ConnectionList* list) {
    // Lock the mutex to prevent race conditions
    pthread_mutex_lock(&list->mutex);

    // Verify that the list is correctly populated
    if (list->count == 0) {
        printf("The list is empty\n");
    } else {
        // Iterate over the connections in the list and verify that they are unique based on their IDs
        for (size_t i = 0; i < list->count - 1; i++) {
            if (list->connections[i]->id == list->connections[i + 1]->id) {
                printf("Duplicate connection found with ID %d\n", list->connections[i]->id);
            }
        }
    }

    // Unlock the mutex
    pthread_mutex_unlock(&list->mutex);
}

// Free the memory allocated for the list and its connections
void freeConnectionList(ConnectionList* list) {
    // Lock the mutex to prevent race conditions
    pthread_mutex_lock(&list->mutex);

    // Iterate over the connections in the list and free their memory
    for (size_t i = 0; i < list->count; i++) {
        ConnectionMetadata* metadata = list->connections[i];
        free(metadata);
    }

    // Free the memory allocated for the list itself
    free(list->connections);

    // Unlock the mutex
    pthread_mutex_unlock(&list->mutex);
