void addEvent(ConnectionEvent* event) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&lock);

    // Allocate memory for the new event
    ConnectionEvent* new_event = malloc(sizeof(ConnectionEvent));
    if (new_event == NULL) {
        perror("malloc");
        exit(1);
    }

    // Copy the data from the input event to the new event
