}

// Define the function to handle incoming connection events
void handleEvents() {
    // Loop indefinitely until a signal is received to stop the thread
    while (1) {
        // Wait for a new event to be available
        sem_wait(&sem);

        // Lock the mutex to prevent concurrent access
        pthread_mutex_lock(&lock);

        // Check if there are any events in the list
        if (num_events > 0) {
            // Process each event in the list
            size_t i;
            for (i = 0; i < num_events; i++) {
                processEvent(events[i]);
            }
        }

        // Unlock the mutex and signal that all events have been processed
        pthread_mutex_unlock(&lock);
        sem_post(&sem);
    }
}

// Define the function to handle outgoing connection events
