    pthread_mutex_init(&lock, NULL);
    sem_init(&sem, 0, 0);

    // Create a thread to handle incoming connection events
    pthread_t event_handler;
    if (pthread_create(&event_handler, NULL, handleEvents, NULL) != 0) {
