        exit(1);
    }

    // Create a thread to handle outgoing connection events
    pthread_t event_sender;
    if (pthread_create(&event_sender, NULL, sendEvents, NULL) != 0) {
        perror("pthread_create");
        exit(1);
    }

    // Wait for the threads to finish
    pthread_join(event_handler, NULL);
    pthread_join(event_sender, NULL);

    // Clean up the mutex and semaphore
    pthread_mutex_destroy(&lock);
    sem_destroy(&sem);

    return 0;
}
