    if (ptr == NULL) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

// Define the function to handle DNS resolution for a given hostname using standard library functions
int resolve_hostname(const char *hostname, u_char **ip_address) {
    struct addrinfo hints, *res;
    int status;

    // Initialize the hints structure with the desired parameters
    memset(&hints, 0, sizeof(struct addrinfo));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;

    // Perform DNS resolution using getaddrinfo()
    status = getaddrinfo(hostname, NULL, &hints, &res);
    if (status != 0) {
        fprintf(stderr, "DNS resolution failed: %s\n", gai_strerror(status));
        return -1;
    }

    // Return the IP address in a u_char array
    *ip_address = malloc(sizeof(u_char) * 4);
    memcpy(*ip_address, res->ai_addr, sizeof(u_char) * 4);

    return 0;
}

