int handle_error(const char *message) {
    fprintf(stderr, "%s\n", message);
    return -1;
}

// Define the function to compute the SHA-256 hash of a provided MAC address string using standard library functions
void compute_sha256_hash(const char *mac_address, u_char **hash) {
    // Check if the input parameters are valid
    if (mac_address == NULL || hash == NULL) {
        return;
    }

    // Compute the SHA-256 hash of the MAC address string using sha256() function from openssl library
    *hash = malloc(sizeof(u_char) * 32);
    memcpy(*hash, sha256(mac_address, strlen(mac_address), NULL), sizeof(u_char) * 32);
}

