// function to validate CRC indications against network settings and retry up to three times with exponentially increasing delays
bool validate_crc_indication(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    // send the CRC indication to the external API for validation
    bool valid = false;
    int retry_count = 0;
    while (!valid && retry_count < 3) {
        valid = validate_crc_indication_api(pdu);
        if (!valid) {
            // exponential backoff with a minimum and maximum delay
            int delay = pow(2, retry_count) * MIN_RETRY_DELAY;
            if (delay > MAX_RETRY_DELAY) {
                delay = MAX_RETRY_DELAY;
            }
            // sleep for the calculated delay
            usleep(delay);
        }
    }
    return valid;
}

