            string connString = "Data Source=localhost;Initial Catalog=mydatabase;Integrated Security=True";
            SqlConnection conn = new SqlConnection(connString);
            conn.Open();

            // Execute query and retrieve result as DataTableReader object
            string query = "SELECT * FROM mytable";
            SqlCommand cmd = new SqlCommand(query, conn);
            SqlDataAdapter adapter = new SqlDataAdapter(cmd);
            DataSet ds = new DataSet();
            adapter.Fill(ds);
            DataTableReader reader = ds.CreateDataReader();

            // Encrypt data using AES-256-CBC cipher and write to file
            string filename = "encrypted_data.txt";
            FileStream fs = new FileStream(filename, FileMode.Create);
            CryptoStream cs = new CryptoStream(fs, aes.CreateEncryptor(), CryptoStreamMode.Write);
            byte[] buffer = new byte[1024];
            int read;
            while ((read = reader.Read(buffer, 0, buffer.Length)) > 0) {
                cs.Write(buffer, 0, read);
            }
            cs.FlushFinalBlock();
            fs.Close();
        }
    }
}
