// Function to modify the file name based on validation logic
char* modifyFileName(const char* filename) {
    // Initialize variables for tracking modifications and lockout state
    int modificationCount = 0;
    bool isLockedOut = false;
    time_t lastModificationTime = 0;

    // Check if the file name contains enough valid characters to determine the appropriate extension
    if (strlen(filename) < 3) {
        return NULL;
