    // Check if the file type is valid and not already the same as the desired extension
    if (strcmp(fileType, ".txt") && strcmp(fileType, ".log") && strcmp(fileType, ".csv") && strcmp(fileType, ".json")) {
        return NULL;
    }

    // Create a new file name with the desired extension
    char* newFileName = (char*)malloc(strlen(filename) + 5);
    sprintf(newFileName, "%s%s", filename, FILE_EXTENSIONS[fileType]);

    // Check if the modification limit has been exceeded within the lockout period
    time_t currentTime = time(NULL);
    if (modificationCount >= 3 && currentTime - lastModificationTime < LOCKOUT_PERIOD) {
        isLockedOut = true;
    }

    // If the file name has been modified within the lockout period, enter a lockout state
    if (isLockedOut) {
        return NULL;
    }

    // Record the modification attempt in an external logging service
    logModificationAttempt(filename, newFileName);

    // Return the new file name
    return newFileName;
}

