void securelyModifyAndEncrypt(forward_list<string>& list, const string& filename, const string& password, const string& searchString1, const string& insertString2) {
    // Initialize AES-256-CBC cipher with given password
    EVP_CIPHER_CTX* ctx;
    int keylen = 32;
    unsigned char key[keylen];
    SHA1(reinterpret_cast<const unsigned char*>(password.c_str()), password.size(), key);
    if (!EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, NULL)) {
        cerr << "Error initializing AES-256-CBC cipher" << endl;
        return;
    }

    // Set IV length to 16 bytes and key length to 32 bytes
    if (!EVP_CIPHER_CTX_set_iv_length(ctx, 16)) {
        cerr << "Error setting IV length" << endl;
        return;
    }
    if (!EVP_CIPHER_CTX_set_key_length(ctx, keylen)) {
        cerr << "Error setting key length" << endl;
        return;
    }

    // Encrypt modified list of strings using initialized cipher context
    vector<string> encryptedList;
    for (const string& str : list) {
        string encryptedStr = encryptString(str, ctx);
        encryptedList.push_back(encryptedStr);
    }

    // Modify filename by appending digits and replacing extension with new file type
    string modifiedFilename;
    int numDigits = 10;
    for (int i = 0; i < numDigits; ++i) {
        modifiedFilename += to_string(rand() % 10);
    }
    modifiedFilename += ".newFileType";

    // Write encrypted list of strings to file
    ofstream outfile(modifiedFilename, ios::binary);
    for (const string& str : encryptedList) {
        outfile << str;
    }
    outfile.close();
}

string encryptString(const string& str, EVP_CIPHER_CTX* ctx) {
    // Encrypt input string using AES-256-CBC cipher context
    int len = str.size();
    unsigned char in[len];
    memcpy(in, str.c_str(), len);
    unsigned char out[len + AES_BLOCK_SIZE];
    int outLen;
    if (!EVP_EncryptUpdate(ctx, out, &outLen, in, len)) {
        cerr << "Error encrypting string" << endl;
        return "";
    }
    memcpy(in, out, outLen);
    return string(reinterpret_cast<const char*>(in), outLen);
}

void cleanupCipherContext(EVP_CIPHER_CTX* ctx) {
    // Disable AES-256-CBC cipher context when no longer needed
    EVP_CIPHER_CTX_cleanup(ctx);
}
