void securelyModifyAndEncrypt(vector<string>& list, const string& filename, const string& arg1, const string& arg2) {
    // Check if the input parameters are valid
    if (list.empty() || filename.empty() || arg1.empty() || arg2.empty()) {
        cerr << "Invalid input parameters" << endl;
        return;
    }

    // Determine the number of digits to append and the file type to replace the existing extension
    string newFilename = filename + ".enc";

    // Initialize an AES-256-CBC cipher with a given password using the OpenSSL library, employing SHA-256 for key derivation to mitigate cryptographic vulnerabilities
    EVP_CIPHER_CTX* ctx = NULL;
    const EVP_CIPHER* cipher = EVP_aes_256_cbc();
    unsigned char key[32];
    SHA256(reinterpret_cast<const unsigned char*>(arg1.c_str()), arg1.size(), key);
    int keyLen = 32;
    if (!EVP_EncryptInit_ex(ctx, cipher, NULL, key, keyLen)) {
        cerr << "Failed to initialize AES-256-CBC cipher" << endl;
        return;
    }

    // Search for the first occurrence of the first additional string argument within the forward list and modify it accordingly—insert the second additional string argument after finding it or append it to the end if not found
    bool found = false;
    for (auto& str : list) {
        if (str == arg1) {
            found = true;
            break;
        }
    }
    if (!found) {
        cerr << "First additional string argument not found" << endl;
        return;
    }
    size_t pos = list.indexOf(arg1);
    list.insert(pos + 1, arg2);

    // Encrypt the modified list of strings using the AES-256-CBC cipher, ensuring the function modifies the forward list in place without returning anything
    for (auto& str : list) {
        unsigned char* buf = reinterpret_cast<unsigned char*>(str.c_str());
        int len = str.size();
        if (!EVP_EncryptUpdate(ctx, buf, &len, buf, len)) {
            cerr << "Failed to encrypt string" << endl;
            return;
        }
    }

    // Cleanup the cipher when no longer needed
    EVP_CIPHER_CTX_free(ctx);
}
