                    cmd.Parameters.AddWithValue("@id", args[0]);
                    using (SqlDataReader reader = cmd.ExecuteReader()) {
                        if (reader.HasRows) {
                            while (reader.Read()) {
                                // Process the data retrieved from the database
                                Console.WriteLine(reader["mycolumn"].ToString());
                            }
                        } else {
                            Console.WriteLine("No rows found");
                        }
                    }
