    // Parse the version number and file type from the filename
    int version = 0;
    const char* filetype = "";
    sscanf(filename, "%d%s", &version, filetype);

    // Check if the version number is valid
    if (version <= 0) {
        return NULL;
    }

    // Construct a new filename with a timestamp and unique identifier
    char* new_filename = malloc(strlen(filename) + 16);
    snprintf(new_filename, strlen(filename) + 16, "%d%s-%lu", version, filetype, hashlib_hash(filename));

