        free(dns_resolve);
        return -1;
    }

    // Process the messages concurrently
    pthread_t* threads = (pthread_t*)malloc(sizeof(pthread_t) * message_count);
    if (!threads) {
        fprintf(stderr, "Failed to allocate memory for thread array\n");
        free(dns_resolve);
        return -1;
    }
    NAS_SUMMARY_REPORT_T* reports = (NAS_SUMMARY_REPORT_T*)malloc(sizeof(NAS_SUMMARY_REPORT_T) * message_count);
    if (!reports) {
        fprintf(stderr, "Failed to allocate memory for report array\n");
        free(threads);
        free(dns_resolve);
        return -1;
    }
    int thread_index = 0;
    for (int i = 0; i < message_count; i++) {
        NAS_MESSAGE_T* message = messages[i];
        pthread_create(&threads[thread_index], NULL, process_message, (void*)message);
        thread_index++;
    }

    // Wait for all threads to finish and collect the reports
    for (int i = 0; i < message_count; i++) {
        pthread_join(threads[i], NULL);
        NAS_SUMMARY_REPORT_T* report = (NAS_SUMMARY_REPORT_T*)malloc(sizeof(NAS_SUMMARY_REPORT_T));
        if (!report) {
            fprintf(stderr, "Failed to allocate memory for report\n");
            free(threads);
            free(reports);
            return -1;
        }
        reports[i] = *report;
    }

    // Clean up and return the reports
    pthread_mutex_destroy(&mutex);
    pthread_cond_destroy(&cond);
    free(threads);
    free(dns_resolve);
    return reports;
}

void* process_message(void* message) {
