class RandomValueGenerator {
public:
    RandomValueGenerator() : inclusive_range_(0), exclusive_range_(0) {}

    void setInclusiveRange(int min, int max) {
        if (min > max || min < 0) {
            std::cout << "Invalid range input for inclusive range. Using default values." << std::endl;
            return;
        }
        inclusive_range_ = min;
        exclusive_range_ = max;
    }

    void setExclusiveRange(int min, int max) {
        if (min > max || min < 0) {
            std::cout << "Invalid range input for exclusive range. Using default values." << std::endl;
            return;
        }
        inclusive_range_ = min;
        exclusive_range_ = max;
    }

    int generateRandomInt() {
        if (inclusive_range_ == 0 || exclusive_range_ == 0) {
            std::cout << "Invalid range input. Using default values." << std::endl;
            return 0;
        }
        return inclusive_range_ + rand() % (exclusive_range_ - inclusive_range_);
    }

    float generateRandomFloat() {
        if (inclusive_range_ == 0 || exclusive_range_ == 0) {
            std::cout << "Invalid range input. Using default values." << std::endl;
            return 0.0f;
        }
        return inclusive_range_ + static_cast<float>(rand()) / (static_cast<float>(RAND_MAX) / (exclusive_range_ - inclusive_range_));
    }

    void resetRange() {
        inclusive_range_ = 0;
        exclusive_range_ = 0;
    }

    std::string toString() const {
        return "Inclusive range: " + std::to_string(inclusive_range_) + ", Exclusive range: " + std::to_string(exclusive_range_);
    }

private:
    int inclusive_range_;
    int exclusive_range_;
};

std::string FileNameModifier(const std::string& filename) {
    RandomValueGenerator random;
    random.setInclusiveRange(1, 99);
    random.setExclusiveRange(100, 1000);

    int num_digits = std::to_string(random.generateRandomInt()).length();
    std::string new_filename = filename + "_" + std::to_string(random.generateRandomInt()) + ".";
    for (int i = 0; i < num_digits; ++i) {
        new_filename += random.generateRandomFloat() + ".";
    }
    return new_filename;
}
