// Custom class for generating dynamic suffixes
class DynamicSuffixGenerator {
public:
    // Constructor to set initial range values
    DynamicSuffixGenerator(int minInt, int maxInt, float minFloat, float maxFloat) {
        this->minInt = minInt;
        this->maxInt = maxInt;
        this->minFloat = minFloat;
        this->maxFloat = maxFloat;
    }

    // Method to generate random integer within range
    int getRandomInt() {
        return rand() % (this->maxInt - this->minInt + 1) + this->minInt;
    }

    // Method to generate random float within range
    float getRandomFloat() {
        return ((float)rand()) / RAND_MAX * (this->maxFloat - this->minFloat) + this->minFloat;
    }

    // Method to set new range values for integers and floats
    void setRange(int minInt, int maxInt, float minFloat, float maxFloat) {
        this->minInt = minInt;
        this->maxInt = maxInt;
        this->minFloat = minFloat;
        this->maxFloat = maxFloat;
    }

    // Method to display current range settings in human-readable format
    void printRange() {
        printf("Integer range: %d - %d\n", this->minInt, this->maxInt);
        printf("Float range: %.2f - %.2f\n", this->minFloat, this->maxFloat);
    }
};

// Function to modify a filename with a new extension and suffix
void FileNameModifier(char* fileName, char* newExtension) {
    // Initialize variables for file name manipulation
    int fileNameLen = strlen(fileName);
    int newFileNameLen = fileNameLen + 10; // Additional characters for new extension and suffix
    char* newFileName = (char*)malloc(newFileNameLen * sizeof(char));
    memset(newFileName, '\0', newFileNameLen);

    // Extract file name without extension
    int dotIndex = fileNameLen - 1;
    while (dotIndex >= 0 && fileName[dotIndex] != '.') {
        dotIndex--;
    }
    if (dotIndex == -1) {
        printf("Error: File name does not contain an extension.\n");
        return;
    }
    int baseNameLen = dotIndex + 1;
    char* baseName = (char*)malloc(baseNameLen * sizeof(char));
    memcpy(baseName, fileName, baseNameLen);

    // Generate suffix using DynamicSuffixGenerator class
    DynamicSuffixGenerator generator(0, 9999, 0.0, 1.0);
    int suffix = generator.getRandomInt();
    float suffixFloat = generator.getRandomFloat();

    // Construct new file name with modified extension and suffix
    sprintf(newFileName, "%s_%d_%.2f%s", baseName, suffix, suffixFloat, newExtension);

    // Free memory for temporary variables
    free(baseName);

    // Return modified file name
    return newFileName;
}

int main() {
    char* fileName = "example.txt";
    char* newExtension = ".pdf";
    char* modifiedFileName = FileNameModifier(fileName, newExtension);
    printf("Modified file name: %s\n", modifiedFileName);
    return 0;
}
