// Function to validate the filename and generate a default filename if necessary
std::string validateFilename(const std::string& filename, int maxLength) {
    // Check if the filename is valid (has a valid file extension and does not exceed the maximum length)
    if (!filename.empty() && filename.find_last_of('.') != std::string::npos && filename.length() <= maxLength) {
        return filename;
    } else {
        // Generate a default filename based on the current date and time, appending a unique identifier to avoid conflicts
        std::time_t t = std::time(nullptr);
        std::string defaultFilename = "data_" + std::to_string(t) + "_" + std::to_string(std::rand()) + ".txt";
        return defaultFilename;
    }
}

// Function to read the contents of a file and process it
void processFile(const std::string& filename, int threshold, std::vector<std::string>& processedData) {
    // Open the file in binary mode
    std::ifstream file(filename, std::ios::binary);
    if (!file.is_open()) {
        std::cerr << "Error: unable to open file '" << filename << "' for reading" << std::endl;
        return;
    }

    // Read the contents of the file into a vector of strings
    std::vector<std::string> data;
    while (file.good()) {
        std::string line;
        std::getline(file, line);
        if (!line.empty()) {
            data.push_back(line);
        }
    }

    // Close the file
    file.close();

    // Process the data and filter out lines with values less than the threshold
    std::vector<std::string> filteredData;
    for (const auto& line : data) {
        int value = std::stoi(line);
        if (value >= threshold) {
            filteredData.push_back(line);
        }
    }

    // Sort the filtered data alphabetically and apply a custom transformation to each string
    std::sort(filteredData.begin(), filteredData.end());
    for (auto& line : filteredData) {
        std::transform(line.begin(), line.end(), line.begin(), ::toupper);
        line = std::regex_replace(line, std::regex("[^a-zA-Z0-9]"), "_");
    }

    // Write the transformed data back to the file
    std::ofstream outfile(filename, std::ios::binary | std::ios::trunc);
    if (!outfile.is_open()) {
        std::cerr << "Error: unable to open file '" << filename << "' for writing" << std::endl;
        return;
    }
    for (const auto& line : filteredData) {
        outfile << line << "\n";
    }
    outfile.close();
}

// Function to parallelize the reading and processing of a file using threads
void processFileParallel(const std::string& filename, int threshold, std::vector<std::string>& processedData) {
    // Create a mutex for synchronizing access to the processed data vector
    std::mutex processedDataMutex;

    // Launch a thread to read the file and process it
    std::thread readerThread([&]() {
        processFile(filename, threshold, processedData);
    });

    // Launch a thread to sort and transform the data
    std::thread sorterThread([&]() {
        std::sort(processedData.begin(), processedData.end());
        for (auto& line : processedData) {
            std::transform(line.begin(), line.end(), line.begin(), ::toupper);
            line = std::regex_replace(line, std::regex("[^a-zA-Z0-9]"), "_");
        }
    });

    // Wait for the reader and sorter threads to finish
    readerThread.join();
    sorterThread.join();
}
