```csharp
using System;
using System.IO;
using System.Text;
using System.Collections.Generic;

public class Serializer {
    public static void Serialize<T>(T obj, string filename) {
        // Check if the object is null or not serializable
        if (obj == null || !typeof(T).IsSerializable) {
            throw new ArgumentException("Object must be non-null and serializable");
        }

        // Create a binary writer to write the data to the file
        using (var writer = new BinaryWriter(new FileStream(filename, FileMode.Create))) {
            // Serialize the object to a byte array
            var bytes = SerializeObject(obj);

            // Write the byte array to the file
            writer.Write(bytes);
        }
    }

    public static T Deserialize<T>(string filename) {
        // Check if the file exists and is readable
        if (!File.Exists(filename) || !File.CanRead(filename)) {
            throw new FileNotFoundException("File not found or cannot be read");
        }

        // Create a binary reader to read the data from the file
        using (var reader = new BinaryReader(new FileStream(filename, FileMode.Open))) {
            // Read the byte array from the file
            var bytes = reader.ReadBytes((int)reader.BaseStream.Length);

            // Deserialize the byte array to an object of type T
            return DeserializeObject<T>(bytes);
        }
    }

    private static byte[] SerializeObject(object obj) {
        // Create a memory stream to write the data to
        using (var stream = new MemoryStream()) {
            // Create a binary writer to write the data to the memory stream
            using (var writer = new BinaryWriter(stream)) {
                // Write the object to the memory stream
                writer.Write(obj);
            }

            // Return the byte array from the memory stream
            return stream.ToArray();
        }
    }

    private static T DeserializeObject<T>(byte[] bytes) {
        // Create a memory stream to read the data from
        using (var stream = new MemoryStream(bytes)) {
            // Create a binary reader to read the data from the memory stream
            using (var reader = new BinaryReader(stream)) {
                // Read the object from the memory stream
                return (T)reader.ReadObject();
            }
        }
    }
}
