NAS_SUMMARY_REPORT_T* resolve_and_decrypt_messages(const char* hostname, NAS_MESSAGE_T** messages, int message_count, size_t ip_size, int max_concurrent, double query_timeout, const char* log_file, const unsigned char* encryption_key, const unsigned char* iv, size_t key_size, size_t iv_size) {
