        free(reports);
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    // Initialize the message classification and reporting mechanism
    int message_type = 0;
    size_t message_size = 0;
    for (int i = 0; i < message_count; i++) {
        // Set the message type and size based on the opcode
        switch (messages[i]->opcode) {
            case 1:
                message_type = 1;
                message_size = sizeof(NAS_MESSAGE_T);
                break;
            case 2:
                message_type = 2;
                message_size = sizeof(NAS_MESSAGE_T) + messages[i]->data->length;
                break;
            default:
                // Unknown opcode, skip the message
                continue;
        }

        // Initialize the summary report for the current message type
        reports[message_type].count++;
        reports[message_type].average_size += message_size;
    }

    // Start the concurrent DNS query pool
    int query_index = 0;
    while (query_index < max_concurrent && query_index < message_count) {
        // Initialize the DNS query structure
        struct dns_query* query = &queries[query_index];
        memset(query, 0, sizeof(struct dns_query));

        // Set the DNS query parameters
        query->hostname = hostname;
        query->message_type = messages[query_index]->opcode;
        query->message_size = message_size;
        query->ip_address = (u_char*)malloc(ip_size);
