        // Set the DNS query IP address
        memcpy(query->ip_address, res->ai_addr, ip_size);

        // Increment the query index
        query_index++;
    }

    // Start the concurrent decryption pool
    int decrypt_index = 0;
    while (decrypt_index < max_concurrent && decrypt_index < message_count) {
        // Initialize the decryption structure
        struct dns_decrypt* decrypt = &queries[decrypt_index];
        memset(decrypt, 0, sizeof(struct dns_decrypt));

        // Set the decryption parameters
        decrypt->ctx = ctx;
        decrypt->message = messages[decrypt_index];
        decrypt->message_type = message_type;
        decrypt->message_size = message_size;
        decrypt->ip_address = (u_char*)malloc(ip_size);
        if (!decrypt->ip_address) {
            // Memory allocation failed, return error code
            printf("Error: Failed to allocate memory for IP address\n");
            free(reports);
            EVP_CIPHER_CTX_free(ctx);
            return NULL;
        }

        // Set the decryption IP address
        memcpy(decrypt->ip_address, queries[decrypt_index].ip_address, ip_size);

        // Increment the decrypt index
        decrypt_index++;
    }

    // Wait for all concurrent DNS queries and decryptions to complete
    while (query_index > 0 || decrypt_index > 0) {
        // Check if any DNS queries have completed
        for (int i = 0; i < query_index; i++) {
            struct dns_query* query = &queries[i];
            if (query->status == AI_FAILURE) {
                // DNS resolution failed, return error code
                printf("Error: Failed to resolve hostname %s\n", hostname);
                free(reports);
                EVP_CIPHER_CTX_free(ctx);
                return NULL;
            } else if (query->status == AI_SUCCESS) {
                // DNS resolution succeeded, start the decryption process
                struct dns_decrypt* decrypt = &queries[i];
                memcpy(decrypt->ip_address, query->ai_addr, ip_size);
                EVP_EncryptInit_ex(ctx, NULL, NULL, NULL, NULL);
                EVP_CIPHER_CTX_set_padding(ctx, 0);
                EVP_DecryptUpdate(ctx, decrypt->message->data, &decrypt->message_size, decrypt->message->data, decrypt->message_size);
                if (EVP_DecryptFinal_ex(ctx, NULL, NULL) <= 0) {
                    // Decryption failed, return error code
                    printf("Error: Failed to decrypt message\n");
                    free(reports);
                    EVP_CIPHER_CTX_free(ctx);
                    return NULL;
                }
                decrypt_index++;
            }
        }

        // Check if any decryptions have completed
        for (int i = 0; i < decrypt_index; i++) {
            struct dns_decrypt* decrypt = &queries[i];
            if (decrypt->status == AI_FAILURE) {
                // Decryption failed, return error code
                printf("Error: Failed to decrypt message\n");
                free(reports);
                EVP_CIPHER_CTX_free(ctx);
                return NULL;
            } else if (decrypt->status == AI_SUCCESS) {
                // Decryption succeeded, update the summary report
                reports[decrypt->message_type].count--;
                reports[decrypt->message_type].average_size -= decrypt->message_size;
            }
        }
    }

    // Free the DNS resolver and AES-CBC decryption context
    freeaddrinfo(res);
    EVP_CIPHER_CTX_free(ctx);

    // Return the summary report array
    return reports;
}
