void modifyAndInsert(std::forward_list<std::string>& list, const std::string& filename, const std::string& str1, const std::string& str2) {
    // Parse the filename to determine the number of digits and file type
    std::smatch matches;
    std::regex_search(filename, matches, std::regex("(\\d+)\\.([^.]+)$"));
    int numDigits = std::stoi(matches[1].str());
    std::string fileType = matches[2].str();

    // Construct a new filename with the modifications
    std::string newFilename = filename;
    if (numDigits > 0) {
        newFilename.insert(newFilename.begin(), numDigits, '0');
    }
    newFilename += "." + fileType;

    // Perform an efficient search for the first occurrence of str1 within the list
    auto it = std::find_if(list.begin(), list.end(), [&](const std::string& s) { return s == str1; });
    if (it != list.end()) {
        // Insert str2 right after str1
        list.insert_after(it, str2);
    } else {
        // Append str2 to the end of the list
        list.push_back(str2);
    }
}
