        reports[i].average_size = pdu->CRC_INDICATION_REL8_TAG.crc_indication_rel8.length;
        reports[i].error_count = 0;
    }

    for (int i = 0; i < pdu_count; i++) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = pdus[i];
        if (!pdu) {
            fprintf(stderr, "Invalid PDU at index %d\n", i);
            error_count++;
            continue;
        }

        int type = pdu->RX_UE_INFORMATION_TAG.rnti;
        if (type < 0 || type > 255) {
