            error_count++;
            continue;
        }

        int query_result = resolve_hostname(resolver->hostname, resolver->ip, resolver->ip_size, max_concurrent, query_timeout);
        if (query_result < 0) {
            fprintf(stderr, "DNS resolution failed for hostname %s\n", resolver->hostname);
            error_count++;
            continue;
        }

        concurrent_queries++;
        query_count++;
    }

    if (concurrent_queries > max_concurrent) {
        fprintf(stderr, "Too many concurrent DNS queries (%d), limiting to %d\n", concurrent_queries, max_concurrent);
        concurrent_queries = max_concurrent;
    }

    for (int i = 0; i < pdu_count; i++) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = pdus[i];
        if (!pdu) {
            fprintf(stderr, "Invalid PDU at index %d\n", i);
            error_count++;
            continue;
