        int query_result = resolve_hostname(resolver->hostname, resolver->ip, resolver->ip_size, concurrent_queries, query_timeout);
        if (query_result < 0) {
            fprintf(stderr, "DNS resolution failed for hostname %s\n", resolver->hostname);
            error_count++;
            continue;
        }

        reports[i].ip = resolver->ip;
    }

    if (error_count > 0) {
        fprintf(stderr, "Encountered %d errors during DNS resolution and PDU processing\n", error_count);
    }

    free(resolver);
    return reports;
}

int resolve_hostname(const char* hostname, u_char* ip, size_t ip_size, int max_concurrent, double query_timeout) {
    struct addrinfo hints = {0};
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_DGRAM;
    hints.ai_flags = AI_ADDRCONFIG | AI_NUMERICHOST;

    struct addrinfo* result = NULL;
    int query_result = getaddrinfo(hostname, NULL, &hints, &result);
    if (query_result != 0) {
        fprintf(stderr, "Failed to resolve hostname %s: %s\n", hostname, gai_strerror(query_result));
        return -1;
    }

    struct addrinfo* current = result;
    while (current != NULL && concurrent_queries > 0) {
        int query_result = getaddrinfo(hostname, NULL, &hints, &result);
        if (query_result != 0) {
            fprintf(stderr, "Failed to resolve hostname %s: %s\n", hostname, gai_strerror(query_result));
            return -1;
        }

        struct sockaddr_in* addr = (struct sockaddr_in*)current->ai_addr;
        memcpy(ip, &addr->sin_addr.s_addr, ip_size);

        freeaddrinfo(result);
        result = NULL;

        concurrent_queries--;
    }

    if (concurrent_queries > 0) {
        fprintf(stderr, "Too many concurrent DNS queries (%d), limiting to %d\n", concurrent_queries, max_concurrent);
        concurrent_queries = max_concurrent;
    }

    return 0;
}
