void securelyModifyAndEncrypt(vector<string>& input, const string& filename, const string& password, const string& additionalString1, const string& additionalString2) {
    // Initialize AES-256-CBC cipher with SHA-256 key derivation
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit(ctx, EVP_aes_256_cbc(), NULL, password.c_str());

    // Analyze filename to determine number of digits and file type
    int numDigits = 0;
    string fileType = "";
    for (int i = filename.size() - 1; i >= 0; i--) {
        if (isdigit(filename[i])) {
            numDigits++;
        } else {
            break;
        }
    }
    for (int i = filename.size() - 1; i >= 0; i--) {
        if (filename[i] == '.') {
            fileType = filename.substr(i + 1);
            break;
        }
    }

    // Construct new filename using sprintf and strcat
    string newFilename = "";
    for (int i = 0; i < numDigits; i++) {
        newFilename += "0";
    }
    newFilename += fileType;

    // Initialize dynamic array of NFAPI_CRC_INDICATION_PDU_T structures
    int numStructs = input.size();
    NFAPI_CRC_INDICATION_PDU_T* structArray = new NFAPI_CRC_INDICATION_PDU_T[numStructs];

    // Modify and encrypt forward list of strings
    for (int i = 0; i < numStructs; i++) {
        string& str = input[i];
        if (str.find(additionalString1) != string::npos) {
            str.replace(str.find(additionalString1), additionalString1.size(), additionalString2);
        } else {
            str += additionalString2;
        }
        EVP_EncryptUpdate(ctx, (unsigned char*)&structArray[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), (const unsigned char*)str.c_str(), str.size());
    }

    // Cleanup AES-256-CBC cipher and dynamic array of NFAPI_CRC_INDICATION_PDU_T structures
    EVP_EncryptFinal(ctx, NULL, 0);
    delete[] structArray;
}
