using namespace std;

void securelyModifyAndEncrypt(forward_list<string>& list, const string& filename, const string& firstAdditionalString, const string& secondAdditionalString) {
    // Prepend the number of digits to the start of the filename and replace the extension with the file type
    string newFilename = filename;
    int numDigits = 0;
    while (numDigits < 10 && newFilename[0] != '.') {
        ++numDigits;
        newFilename.insert(newFilename.begin(), '0');
    }
    newFilename += ".txt";

    // Initialize the AES-256-CBC cipher with a given password and ensure proper IV and key lengths
    const string password = "my_password";
    unsigned char iv[16];
    EVP_CIPHER_CTX* ctx;
    if (!EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, (unsigned char*)password.c_str(), iv)) {
        cerr << "Error initializing AES-256-CBC cipher: " << ERR_error_string(ERR_get_error(), NULL) << endl;
        return;
    }
    if (!EVP_CIPHER_CTX_set_key_length(ctx, 32)) {
        cerr << "Error setting key length for AES-256-CBC cipher: " << ERR_error_string(ERR_get_error(), NULL) << endl;
        return;
    }

    // Search for the first occurrence of the first additional string argument within the forward list
    auto it = find(list.begin(), list.end(), firstAdditionalString);
    if (it == list.end()) {
        cerr << "Error: first additional string argument not found in list" << endl;
        return;
    }

    // Insert the second additional string argument right after it, or append it to the end of the list if not found
    if (it != list.end()) {
        ++it;
        list.insert(it, secondAdditionalString);
    } else {
        list.push_back(secondAdditionalString);
    }

    // Encrypt the modified list of strings using the initialized cipher context
    unsigned char* encryptedData = new unsigned char[list.size() * 16];
    int encryptedSize = EVP_EncryptUpdate(ctx, encryptedData, list.size() * 16, (unsigned char*)list.data(), list.size());
    if (encryptedSize < 0) {
        cerr << "Error encrypting data: " << ERR_error_string(ERR_get_error(), NULL) << endl;
        return;
    }

    // Clean up the cipher context and deallocate memory
    EVP_CIPHER_CTX_cleanup(ctx);
    delete[] encryptedData;
}
