}

// Define the function to use for checking if a port is within the valid range
bool is_valid_port(int port) {
    // Check if the port is within the valid range for TCP/UDP
    return (port >= PORT_MIN && port <= PORT_MAX);
}

// Define the function to use for checking if a protocol is supported
bool is_supported_protocol(const char* protocol) {
    // Check if the protocol is among the supported types
    return (strcmp(protocol, "HTTP") == 0 || strcmp(protocol, "HTTPS") == 0 || strcmp(protocol, "SSH") == 0);
}

// Define the function to use for checking if a timeout duration is valid
bool is_valid_timeout(int timeout) {
