void securelyModifyAndEncrypt(vector<string>& input, const string& filename, const string& password, const string& additionalString1, const string& additionalString2) {
    // Initialize AES-256-CBC cipher with SHA-256 key derivation
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        cerr << "Error: Failed to initialize AES-256-CBC cipher" << endl;
        return;
    }

    // Generate key and initialization vector from password
    unsigned char key[32];
    unsigned char iv[16];
    SHA256_CTX sha256;
    SHA256_Init(&sha256);
    SHA256_Update(&sha256, password.c_str(), password.size());
    SHA256_Final(key, &sha256);
    RAND_bytes(iv, 16);

    // Encrypt input data using AES-256-CBC cipher
    int len = input.size();
    unsigned char* encryptedData = new unsigned char[len];
    EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv);
    EVP_EncryptUpdate(ctx, encryptedData, &len, input.data(), len);
    EVP_EncryptFinal_ex(ctx, encryptedData + len, &len);

    // Modify and encrypt additional string arguments
    int additionalString1Len = additionalString1.size();
    unsigned char* additionalString1Encrypted = new unsigned char[additionalString1Len];
    EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv);
    EVP_EncryptUpdate(ctx, additionalString1Encrypted, &additionalString1Len, additionalString1.data(), additionalString1Len);
    EVP_EncryptFinal_ex(ctx, additionalString1Encrypted + additionalString1Len, &additionalString1Len);

    int additionalString2Len = additionalString2.size();
    unsigned char* additionalString2Encrypted = new unsigned char[additionalString2Len];
    EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv);
    EVP_EncryptUpdate(ctx, additionalString2Encrypted, &additionalString2Len, additionalString2.data(), additionalString2Len);
    EVP_EncryptFinal_ex(ctx, additionalString2Encrypted + additionalString2Len, &additionalString2Len);

    // Modify input data and encrypt it in place
    for (int i = 0; i < len; ++i) {
        if (input[i] == additionalString1) {
            input[i] = additionalString2;
        } else if (input[i] == additionalString2) {
            input[i] = additionalString1;
        }
    }

    // Clean up AES-256-CBC cipher context and deallocate memory
    EVP_CIPHER_CTX_free(ctx);
    delete[] encryptedData;
    delete[] additionalString1Encrypted;
    delete[] additionalString2Encrypted;
}
