#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <openssl/ssl.h>
#include <openssl/err.h>

int execute_remote_command(const char *host, const char *username, const char *password, const char *command) {
    int sock = -1;
    SSL_CTX *ctx = NULL;
    SSL *ssl = NULL;
    BIO *bio = NULL;
    char buffer[4096];
    int ret = 0;

    // Establish a secure connection to the server using SSH
    sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
        perror("socket");
        goto cleanup;
    }

    ctx = SSL_CTX_new(TLSv1_client_method());
    if (!ctx) {
        ERR_print_errors_fp(stderr);
        goto cleanup;
    }

    ssl = SSL_new(ctx);
    if (!ssl) {
        ERR_print_errors_fp(stderr);
        goto cleanup;
    }

    bio = BIO_new_socket(sock, BIO_CLOSE);
    if (!bio) {
        perror("BIO_new_socket");
        goto cleanup;
    }

    SSL_set_fd(ssl, sock);
    if (SSL_connect(ssl) <= 0) {
        ERR_print_errors_fp(stderr);
        goto cleanup;
    }

    // Authenticate with the server using SSH
    char *auth_command = "ssh -l";
    strcat(auth_command, username);
    strcat(auth_command, " ");
    strcat(auth_command, host);
    if (SSL_write(ssl, auth_command, strlen(auth_command)) <= 0) {
        ERR_print_errors_fp(stderr);
        goto cleanup;
    }

    // Execute the command on the server using SSH
    char *exec_command = "ssh -l";
    strcat(exec_command, username);
    strcat(exec_command, " ");
    strcat(exec_command, host);
    strcat(exec_command, " \"");
    strcat(exec_command, command);
    strcat(exec_command, "\"");
    if (SSL_write(ssl, exec_command, strlen(exec_command)) <= 0) {
        ERR_print_errors_fp(stderr);
        goto cleanup;
    }

    // Read the output from the server using SSH
    while ((ret = SSL_read(ssl, buffer, sizeof(buffer))) > 0) {
        printf("%s", buffer);
    }

cleanup:
    if (bio) BIO_free_all(bio);
    if (ssl) SSL_free(ssl);
    if (ctx) SSL_CTX_free(ctx);
    if (sock >= 0) close(sock);
    return ret;
}
