        SSL_CTX_free(ctx);
        return -1;
    }
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
        fprintf(stderr, "Failed to create socket\n");
        SSL_free(ssl);
        SSL_CTX_free(ctx);
        return -1;
    }
    if (connect(sock, result->ai_addr, result->ai_addrlen) != 0) {
        fprintf(stderr, "Failed to connect to server\n");
        close(sock);
        SSL_free(ssl);
        SSL_CTX_free(ctx);
        return -1;
    }
    if (SSL_set_fd(ssl, sock) != 1) {
