        SSL_CTX_free(ctx);
        return -1;
    }

    // Execute the command on the server and process the PDU batch
    char* cmd = "command";
    if (SSL_write(ssl, cmd, strlen(cmd)) != strlen(cmd)) {
        fprintf(stderr, "Failed to send command\n");
        close(sock);
        SSL_free(ssl);
        SSL_CTX_free(ctx);
        return -1;
    }
    char* pdu_buf = malloc(ip_size * max_concurrent);
    if (!pdu_buf) {
        fprintf(stderr, "Failed to allocate memory for PDU buffer\n");
        close(sock);
        SSL_free(ssl);
        SSL_CTX_free(ctx);
        return -1;
    }
    int pdu_count = 0;
    while (pdu_count < pdu_count) {
        // Read the PDU from the server
        char* pdu = &pdu_buf[pdu_count * ip_size];
        if (SSL_read(ssl, pdu, ip_size) != ip_size) {
            fprintf(stderr, "Failed to read PDU\n");
            close(sock);
            SSL_free(ssl);
            SSL_CTX_free(ctx);
            return -1;
        }
        pdu_count++;
    }

    // Process the PDU batch and generate a summary report
    int error_count = 0;
    double average_size = 0;
    for (int i = 0; i < pdu_count; i++) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = &pdus[i];
        if (pdu->RX_UE_INFORMATION_TAG != 1 || pdu->RNTI == 0) {
            fprintf(stderr, "Invalid PDU received\n");
            error_count++;
            continue;
        }
        average_size += ip_size;
    }
    if (error_count > 0) {
        fprintf(stderr, "Error occurred while processing PDU batch\n");
    }
    PDU_SUMMARY_REPORT_T* report = malloc(sizeof(PDU_SUMMARY_REPORT_T));
