        close(sock);
        SSL_free(ssl);
        SSL_CTX_free(ctx);
        return -1;
    }
    report->count = pdu_count;
    report->average_size = average_size / pdu_count;
    report->error_count = error_count;

    // Clean up resources and return the summary report
    free(pdu_buf);
    SSL_free(ssl);
    SSL_CTX_free(ctx);
    close(sock);
    return report;
}
