#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <pthread.h>
#include <sys/time.h>
#include <arpa/inet.h>
#include <resolv.h>

#define MAX_HOSTNAMES 1000
#define DNS_TIMEOUT 5 // seconds
#define DNS_RETRIES 3
#define DNS_BACKOFF_MIN 100 // milliseconds
#define DNS_BACKOFF_MAX 1000 // milliseconds
#define DNS_CACHE_SIZE 1024
#define DNS_CACHE_EXPIRATION 3600 // seconds
#define RX_UE_INFORMATION_TAG "rx_ue_information"
#define RNTI "rnti"
#define CRCFLAG "crcflag"
#define CRC_INDICATION_REL8_TAG "crc_indication_rel8"

struct hostname_info {
    char *hostname;
    struct in_addr ip_address;
};

struct dns_cache {
    char *hostname;
    struct in_addr ip_address;
    time_t expiration;
};

struct thread_data {
    int thread_id;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    struct hostname_info *hostname_queue;
    int hostname_queue_size;
    int hostname_queue_head;
    int hostname_queue_tail;
};

struct dns_resolver {
    int thread_count;
    pthread_t *threads;
    struct thread_data *thread_data;
    struct dns_cache *dns_cache;
    int dns_cache_size;
    int dns_cache_expiration;
};

void *dns_resolver_thread(void *arg) {
    struct thread_data *thread_data = (struct thread_data *)arg;
    while (1) {
        pthread_mutex_lock(&thread_data->mutex);
        if (thread_data->hostname_queue_size == 0) {
            pthread_cond_wait(&thread_data->cond, &thread_data->mutex);
        }
        struct hostname_info *hostname = thread_data->hostname_queue[thread_data->hostname_queue_head];
        thread_data->hostname_queue_head = (thread_data->hostname_queue_head + 1) % MAX_HOSTNAMES;
        thread_data->hostname_queue_size--;
        pthread_mutex_unlock(&thread_data->mutex);

        struct hostent *host = gethostbyname(hostname->hostname);
        if (host == NULL) {
            printf("DNS resolution failed for %s\n", hostname->hostname);
            continue;
        }

        pthread_mutex_lock(&thread_data->mutex);
        thread_data->dns_cache[hostname->hostname].ip_address = *(struct in_addr *)host->h_addr_list[0];
        thread_data->dns_cache[hostname->hostname].expiration = time(NULL) + DNS_CACHE_EXPIRATION;
        pthread_mutex_unlock(&thread_data->mutex);
    }
}

int dns_resolver_init(struct dns_resolver *dns_resolver, int thread_count) {
    dns_resolver->thread_count = thread_count;
    dns_resolver->threads = (pthread_t *)malloc(sizeof(pthread_t) * thread_count);
    if (dns_resolver->threads == NULL) {
        return -1;
    }
    dns_resolver->thread_data = (struct thread_data *)malloc(sizeof(struct thread_data) * thread_count);
    if (dns_resolver->thread_data == NULL) {
        free(dns_resolver->threads);
        return -1;
    }
    dns_resolver->dns_cache = (struct dns_cache *)malloc(sizeof(struct dns_cache) * DNS_CACHE_SIZE);
    if (dns_resolver->dns_cache == NULL) {
        free(dns_resolver->threads);
        free(dns_resolver->thread_data);
        return -1;
    }
    dns_resolver->dns_cache_size = DNS_CACHE_SIZE;
    dns_resolver->dns_cache_expiration = DNS_CACHE_EXPIRATION;

    for (int i = 0; i < thread_count; i++) {
        struct thread_data *thread_data = &dns_resolver->thread_data[i];
        thread_data->thread_id = i;
        pthread_mutex_init(&thread_data->mutex, NULL);
        pthread_cond_init(&thread_data->cond, NULL);
        thread_data->hostname_queue = (struct hostname_info *)malloc(sizeof(struct hostname_info) * MAX_HOSTNAMES);
        if (thread_data->hostname_queue == NULL) {
            free(dns_resolver->threads);
            free(dns_resolver->thread_data);
            return -1;
        }
        thread_data->hostname_queue_size = 0;
        thread_data->hostname_queue_head = 0;
        thread_data->hostname_queue_tail = 0;
    }

    for (int i = 0; i < thread_count; i++) {
        struct thread_data *thread_data = &dns_resolver->thread_data[i];
        pthread_create(&dns_resolver->threads[i], NULL, dns_resolver_thread, (void *)thread_data);
    }

    return 0;
}

int dns_resolver_destroy(struct dns_resolver *dns_resolver) {
    for (int i = 0; i < dns_resolver->thread_count; i++) {
        pthread_join(dns_resolver->threads[i], NULL);
    }
    free(dns_resolver->threads);
    free(dns_resolver->thread_data);
    free(dns_resolver->dns_cache);
    return 0;
}

int dns_resolver_resolve(struct dns_resolver *dns_resolver, char *hostname) {
    struct hostent *host = gethostbyname(hostname);
    if (host == NULL) {
        printf("DNS resolution failed for %s\n", hostname);
        return -1;
    }

    pthread_mutex_lock(&dns_resolver->thread_data[0].mutex);
    struct dns_cache *cache = &dns_resolver->dns_cache[hostname];
    if (cache->expiration > time(NULL)) {
        cache->ip_address = *(struct in_addr *)host->h_addr_list[0];
        pthread_mutex_unlock(&dns_resolver->thread_data[0].mutex);
        return 0;
    }
    struct hostname_info *hostname_info = &dns_resolver->thread_data[0].hostname_queue[dns_resolver->thread_data[0].hostname_queue_tail];
    hostname_info->hostname = hostname;
    hostname_info->ip_address = *(struct in_addr *)host->h_addr_list[0];
    dns_resolver->thread_data[0].hostname_queue_tail = (dns_resolver->thread_data[0].hostname_queue_tail + 1) % MAX_HOSTNAMES;
    dns_resolver->thread_data[0].hostname_queue_size++;
    pthread_cond_signal(&dns_resolver->thread_data[0].cond);
    pthread_mutex_unlock(&dns_resolver->thread_data[0].mutex);

    return 0;
}
