void resolve_dns(struct dns_resolution_context *ctx, char *hostname) {
    struct addrinfo hints;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET; // IPv4 only for now
    hints.ai_socktype = SOCK_DGRAM;
    hints.ai_flags = AI_ADDRCONFIG | AI_V4MAPPED;
    struct addrinfo *result, *rp;
    int s;
    char host[1024];
    strcpy(host, hostname);
    if (getaddrinfo(host, NULL, &hints, &result) != 0) {
        return;
    }
    for (rp = result; rp != NULL; rp = rp->ai_next) {
        void *addr;
        char ip[1024];
        if (rp->ai_family == AF_INET) {
            struct sockaddr_in *ipv4 = (struct sockaddr_in *)rp->ai_addr;
            addr = &ipv4->sin_addr;
            inet_ntop(AF_INET, addr, ip, 1024);
        } else if (rp->ai_family == AF_INET6) {
            struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *)rp->ai_addr;
            addr = &ipv6->sin6_addr;
            inet_ntop(AF_INET6, addr, ip, 1024);
        } else {
            continue;
        }
        pthread_mutex_lock(&ctx->mutex);
        struct dns_record *dns_record = (struct dns_record *)malloc(sizeof(struct dns_record));
        memset(dns_record, 0, sizeof(struct dns_record));
        strcpy(dns_record->hostname, hostname);
        strcpy(dns_record->ip_address, ip);
        dns_record->ttl = time(NULL) + DNS_CACHE_TTL;
        ctx->dns_cache->dns_records[ctx->dns_cache->dns_records_count++] = dns_record;
        pthread_mutex_unlock(&ctx->mutex);
    }
    freeaddrinfo(result);
}

