#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <zlib.h>
#include <errno.h>

#define BUFFER_SIZE 4096
#define MAX_LINE_LENGTH 1024
#define MAX_WORD_COUNT 1024
#define MIN_BUFFER_SIZE 1024
#define MAX_BUFFER_SIZE 1048576

typedef struct {
    int line_count;
    int word_count;
    int char_count;
} metrics_t;

void print_usage(char *prog_name) {
    printf("Usage: %s [OPTIONS]...\n", prog_name);
    printf("\n");
    printf("Options:\n");
    printf("  -h, --help                   Display this help message and exit.\n");
    printf("  -m, --manpage                 Display comprehensive documentation and exit.\n");
    printf("  -c, --count-words            Count the number of words in each line of input.\n");
    printf("  -o, --output-file FILE       Redirect output to a specified file instead of the console.\n");
    printf("  -s, --summary               Print a summary at the end of processing.\n");
    printf("  -i, --input-source SOURCE   Specify an input source (default: stdin).\n");
    printf("\n");
}

void print_manpage(char *prog_name) {
    printf("Usage: %s [OPTIONS]...\n", prog_name);
    printf("\n");
    printf("Options:\n");
    printf("  -h, --help                   Display this help message and exit.\n");
    printf("  -m, --manpage                 Display comprehensive documentation and exit.\n");
    printf("  -c, --count-words            Count the number of words in each line of input.\n");
    printf("  -o, --output-file FILE       Redirect output to a specified file instead of the console.\n");
    printf("  -s, --summary               Print a summary at the end of processing.\n");
    printf("  -i, --input-source SOURCE   Specify an input source (default: stdin).\n");
    printf("\n");
}

int main(int argc, char **argv) {
    int c;
    metrics_t metrics = {0};
    FILE *output_file = NULL;
    char *input_source = NULL;
    while ((c = getopt(argc, argv, "hmco:i:s")) != -1) {
        switch (c) {
            case 'h':
                print_usage(argv[0]);
                return 0;
            case 'm':
                print_manpage(argv[0]);
                return 0;
            case 'c':
                metrics.word_count = 1;
                break;
            case 'o':
                output_file = fopen(optarg, "w");
                if (output_file == NULL) {
                    perror("fopen");
                    return 1;
                }
                break;
            case 'i':
                input_source = optarg;
                break;
            case 's':
                metrics.summary = 1;
                break;
        }
    }
    if (input_source == NULL) {
        input_source = "stdin";
    }
    FILE *input_stream = fopen(input_source, "r");
    if (input_stream == NULL) {
        perror("fopen");
        return 1;
    }
    char buffer[BUFFER_SIZE];
    while (fgets(buffer, BUFFER_SIZE, input_stream)) {
        metrics.line_count++;
        if (metrics.word_count) {
            int word_count = 0;
            char *token = strtok(buffer, " ");
            while (token != NULL) {
                word_count++;
                token = strtok(NULL, " ");
            }
            metrics.word_count += word_count;
        }
        if (output_file != NULL) {
            fprintf(output_file, "%s", buffer);
        } else {
            printf("%s", buffer);
        }
    }
    if (metrics.summary) {
        printf("Total lines: %d\n", metrics.line_count);
        if (metrics.word_count) {
            printf("Average words per line: %.2f\n", (double)metrics.word_count / metrics.line_count);
        }
    }
    fclose(input_stream);
    if (output_file != NULL) {
        fclose(output_file);
    }
    return 0;
}
