['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <resolv.h>
#include <pthread.h>
#include <stdbool.h>

#define MAX_HOSTNAMES 1000
#define DNS_TIMEOUT 5 // seconds
#define DNS_RETRY_COUNT 3
#define DNS_BACKOFF_FACTOR 2
#define DNS_CACHE_SIZE 1000
#define DNS_CACHE_EXPIRATION 60 // seconds
#define DNS_QUERY_TYPE A
#define DNS_QUERY_CLASS IN
#define DNS_SERVERS "8.8.8.8,8.8.4.4"

typedef struct {
    char *hostname;
    u_char ip[16];
} hostname_ip_pair_t;

typedef struct {
    hostname_ip_pair_t *pairs;
    size_t num_pairs;
} dns_cache_t;

dns_cache_t *dns_cache = NULL;
pthread_mutex_t dns_cache_lock = PTHREAD_MUTEX_INITIALIZER;

void init_dns_cache() {
    dns_cache = malloc(sizeof(dns_cache_t));
    dns_cache->pairs = malloc(DNS_CACHE_SIZE * sizeof(hostname_ip_pair_t));
    dns_cache->num_pairs = 0;
}

void destroy_dns_cache() {
    free(dns_cache->pairs);
    free(dns_cache);
}

bool is_dns_cache_expired(hostname_ip_pair_t *pair) {
    time_t now = time(NULL);
    return (now - pair->timestamp) > DNS_CACHE_EXPIRATION;
}

void update_dns_cache(const char *hostname, u_char *ip) {
    hostname_ip_pair_t *pair = NULL;
    for (size_t i = 0; i < dns_cache->num_pairs; i++) {
        if (!strcmp(dns_cache->pairs[i].hostname, hostname)) {
            pair = &dns_cache->pairs[i];
            break;
        }
    }
    if (pair == NULL) {
        // Add new entry to cache
        pair = &dns_cache->pairs[dns_cache->num_pairs++];
        pair->hostname = strdup(hostname);
    }
    memcpy(pair->ip, ip, 16);
    pair->timestamp = time(NULL);
}

u_char *get_cached_ip(const char *hostname) {
    hostname_ip_pair_t *pair = NULL;
    for (size_t i = 0; i < dns_cache->num_pairs; i++) {
        if (!strcmp(dns_cache->pairs[i].hostname, hostname)) {
            pair = &dns_cache->pairs[i];
            break;
        }
    }
    return (pair == NULL) ? NULL : pair->ip;
}

void dns_lookup(const char *hostname, u_char *ip) {
    // Check cache first
    if (get_cached_ip(hostname) != NULL) {
        memcpy(ip, get_cached_ip(hostname), 16);
        return;
    }

    // Perform DNS lookup
    struct addrinfo hints = {0};
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_DGRAM;
    hints.ai_protocol = IPPROTO_UDP;
    hints.ai_flags = AI_ADDRCONFIG | AI_V4MAPPED;

    struct addrinfo *result = NULL;
    int error = getaddrinfo(hostname, NULL, &hints, &result);
    if (error != 0) {
        fprintf(stderr, "getaddrinfo: %s\n", gai_strerror(error));
        return;
    }

    // Update cache and return IP address
    update_dns_cache(hostname, result->ai_addr);
    memcpy(ip, result->ai_addr, 16);
}

void dns_lookup_thread(const char *hostname) {
    u_char ip[16];
    dns_lookup(hostname, ip);
}

void dns_resolution_task(const char *hostnames[]) {
    // Initialize DNS cache
    init_dns_cache();

    // Perform DNS lookups in parallel
    pthread_t threads[MAX_HOSTNAMES];
    for (size_t i = 0; i < MAX_HOSTNAMES; i++) {
        if (hostnames[i] != NULL) {
            pthread_create(&threads[i], NULL, dns_lookup_thread, hostnames[i]);
        }
    }

    // Wait for all threads to complete
    for (size_t i = 0; i < MAX_HOSTNAMES; i++) {
        if (hostnames[i] != NULL) {
            pthread_join(threads[i], NULL);
        }
    }

    // Destroy DNS cache
    destroy_dns_cache();
}
