#include <stdio.h>
#include <string.h>
#include <stdlib.h>

// Define a struct to store the file extension and its corresponding type
typedef struct {
    char* extension;
    int type;
} FileType;

// Define an array of available file types
FileType fileTypes[] = {
    {"jpg", 0},
    {"png", 1},
    {"gif", 2},
    {"pdf", 3},
    {"txt", 4}
};

// Function to dynamically modify the file extension based on predefined rules
void modifyFileExtension(char* filename) {
    // Get the length of the filename
    int len = strlen(filename);

    // Check if the filename already has a numeric extension
    bool hasNumericExt = false;
    for (int i = 0; i < len - 1; i++) {
        if (isdigit(filename[i])) {
            hasNumericExt = true;
            break;
        }
    }

    // Determine the appropriate number of digits to append based on the filename's content
    int numDigits = 0;
    if (hasNumericExt) {
        // If the filename already has a numeric extension, determine the number of digits in the existing extension
        for (int i = len - 1; i >= 0; i--) {
            if (!isdigit(filename[i])) {
                break;
            }
            numDigits++;
        }
    } else {
        // If the filename does not have a numeric extension, determine the number of digits to append based on the file type
        int fileType = getFileType(filename);
        if (fileType != -1) {
            numDigits = strlen(fileTypes[fileType].extension);
        }
    }

    // Append the appropriate number of digits to the filename
    char* newFilename = malloc(len + numDigits + 1);
    memcpy(newFilename, filename, len - numDigits);
    for (int i = 0; i < numDigits; i++) {
        newFilename[len - numDigits + i] = '0' + i;
    }
    newFilename[len + numDigits] = '\0';

    // Set the modified filename as the return value
    strcpy(filename, newFilename);

    // Free the memory allocated for the new filename
    free(newFilename);
}

// Function to retrieve the file type of a given filename based on predefined rules
int getFileType(char* filename) {
    // Get the length of the filename
    int len = strlen(filename);

    // Check if the filename has an extension
    bool hasExt = false;
    for (int i = 0; i < len - 1; i++) {
        if (filename[i] == '.') {
            hasExt = true;
            break;
        }
    }

    // If the filename does not have an extension, return -1
    if (!hasExt) {
        return -1;
    }

    // Get the file extension and check if it is in the list of available file types
    char* ext = malloc(len + 1);
    memcpy(ext, filename + len - 1, len);
    ext[len] = '\0';
    for (int i = 0; i < sizeof(fileTypes) / sizeof(FileType); i++) {
        if (strcmp(ext, fileTypes[i].extension) == 0) {
            free(ext);
            return fileTypes[i].type;
        }
    }

    // If the file extension is not in the list of available file types, return -1
    free(ext);
    return -1;
}
