    LOGGING_MECHANISM_T *logger = (LOGGING_MECHANISM_T *)malloc(sizeof(LOGGING_MECHANISM_T));
    logger->file = fopen("log.txt", "w");
    logger->verbosity = 1;

    // Parse the XML document and extract the CRC indication data
    xmlDocPtr doc = xmlReadMemory(xml_document, strlen(xml_document), NULL, NULL, 0);
    if (doc == NULL) {
        printf("Error parsing XML document\n");
        return;
    }
    xmlNodePtr root = xmlDocGetRootElement(doc);
    if (root == NULL) {
        printf("Error getting root element of XML document\n");
        return;
    }
    xmlXPathContextPtr xpath_context = xmlXPathNewContext(doc);
    if (xpath_context == NULL) {
        printf("Error creating XPath context for XML document\n");
        return;
    }
    xmlXPathObjectPtr xpath_object = xmlXPathEvalExpression((const xmlChar *)"//CRC_INDICATION", xpath_context);
    if (xpath_object == NULL) {
        printf("Error evaluating XPath expression for XML document\n");
        return;
    }
    int num_crc_indications = xpath_object->nodesetval->nodeNr;
    xmlNodePtr *crc_indication_nodes = (xmlNodePtr *)malloc(sizeof(xmlNodePtr) * num_crc_indications);
    for (int i = 0; i < num_crc_indications; i++) {
        crc_indication_nodes[i] = xpath_object->nodesetval->nodeTab[i];
    }

    // Iterate over the CRC indication nodes and extract the data
    for (int i = 0; i < num_crc_indications; i++) {
        xmlNodePtr crc_indication_node = crc_indication_nodes[i];
        NFAPI_CRC_INDICATION_PDU_T *crc_indication = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        crc_indication->RX_UE_INFORMATION_TAG = xmlGetProp(crc_indication_node, (const xmlChar *)"RX_UE_INFORMATION_TAG");
        crc_indication->RNTI = xmlGetProp(crc_indication_node, (const xmlChar *)"RNTI");
        crc_indication->CRC_INDICATION_REL8_TAG = xmlGetProp(crc_indication_node, (const xmlChar *)"CRC_INDICATION_REL8_TAG");
        // Compute the MD5 hash of the CRC indication data and store it in the structure
        char *md5_hash = compute_md5_hash(crc_indication);
        crc_indication->MD5_HASH = md5_hash;
        // Add the CRC indication to the list
        add_crc_indication(list, crc_indication);
    }

    // Free the memory allocated for the XPath context and the XML document
    xmlXPathFreeContext(xpath_context);
    xmlFreeDoc(doc);
}

// Define the function for adding a CRC indication to the list
void add_crc_indication(NFAPI_CRC_INDICATION_LIST_T *list, NFAPI_CRC_INDICATION_PDU_T *crc_indication) {
    // Check if the list is full and needs to be resized
    if (list->size == 0) {
        list->data = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        list->size++;
    } else if (list->size == list->size) {
        NFAPI_CRC_INDICATION_PDU_T *new_data = (NFAPI_CRC_INDICATION_PDU_T *)realloc(list->data, sizeof(NFAPI_CRC_INDICATION_PDU_T) * 2);
        if (new_data == NULL) {
            printf("Error resizing memory for CRC indication list\n");
            return;
        }
        list->data = new_data;
        list->size++;
    }
    // Add the CRC indication to the list
    list->data[list->size - 1] = *crc_indication;
}

// Define the function for updating a CRC indication in the list
void update_crc_indication(NFAPI_CRC_INDICATION_LIST_T *list, int RNTI) {
    // Check if the RNTI is valid and exists in the list
    if (RNTI < 0 || RNTI > 65535) {
        printf("Error: Invalid RNTI value\n");
        return;
    }
    for (int i = 0; i < list->size; i++) {
        if (list->data[i].RNTI == RNTI) {
            // Update the CRC indication in the list
            list->data[i] = *crc_indication;
            return;
        }
    }
    printf("Error: RNTI not found in list\n");
}

// Define the function for removing a CRC indication from the list
void remove_crc_indication(NFAPI_CRC_INDICATION_LIST_T *list, int RNTI) {
    // Check if the RNTI is valid and exists in the list
    if (RNTI < 0 || RNTI > 65535) {
        printf("Error: Invalid RNTI value\n");
        return;
    }
    for (int i = 0; i < list->size; i++) {
        if (list->data[i].RNTI == RNTI) {
            // Remove the CRC indication from the list
            NFAPI_CRC_INDICATION_PDU_T *new_data = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * (list->size - 1));
            for (int j = 0; j < list->size; j++) {
                if (j == i) {
                    continue;
                } else {
                    new_data[j] = list->data[j];
                }
            }
            free(list->data);
            list->data = new_data;
            list->size--;
            return;
        }
    }
    printf("Error: RNTI not found in list\n");
}

// Define the function for computing the MD5 hash of a CRC indication structure
char *compute_md5_hash(NFAPI_CRC_INDICATION_PDU_T *crc_indication) {
    // Initialize the MD5 context
    MD5_CTX ctx;
    MD5Init(&ctx);

    // Compute the MD5 hash of the CRC indication data
    MD5Update(&ctx, (unsigned char *)&crc_indication->RX_UE_INFORMATION_TAG, sizeof(int));
    MD5Update(&ctx, (unsigned char *)&crc_indication->RNTI, sizeof(int));
    MD5Update(&ctx, (unsigned char *)&crc_indication->CRC_INDICATION_REL8_TAG, sizeof(int));

    // Finalize the MD5 hash and return it as a string
    unsigned char digest[16];
    MD5Final(digest, &ctx);
    char *md5_hash = (char *)malloc(sizeof(char) * 32);
    for (int i = 0; i < 16; i++) {
        sprintf(&md5_hash[i * 2], "%02x", digest[i]);
    }
    return md5_hash;
}
