    int keyLen = 32;
    int ivLen = 16;
    unsigned char key[keyLen];
    unsigned char iv[ivLen];
    SHA256(reinterpret_cast<const unsigned char*>(password), strlen(password), key);
    ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv);

    // Implement a cleanup function to disable the cipher
    auto cleanup = [&]() {
        EVP_CIPHER_CTX_free(ctx);
    };

    // Search for the first occurrence of the first additional string argument in the forward list, inserting the second string argument immediately after it if found; otherwise, append the second string to the end of the list
