#define DNS_CACHE_SIZE 10000
#define DNS_RETRY_COUNT 3
#define DNS_RETRY_DELAY 500 // milliseconds
#define DNS_MAX_QUERIES_PER_SECOND 10000
#define DNS_MIN_QUERY_TIMEOUT 100 // milliseconds
#define DNS_MAX_QUERY_TIMEOUT 1000 // milliseconds
#define DNS_RETRY_BACKOFF_FACTOR 2
#define DNS_CACHE_HIT_RATE_THRESHOLD 0.8
#define DNS_CACHE_MISS_RATE_THRESHOLD 0.2
