#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <resolv.h>
#include <pthread.h>
#include <stdbool.h>

#define MAX_HOSTNAMES 1000
#define MAX_THREADS 50
#define DNSSEC_VALIDATION true
#define DNS_RETRY_COUNT 3
#define DNS_RETRY_DELAY 1000 // in milliseconds
#define DNS_TIMEOUT 5000 // in milliseconds
#define DNS_SERVERS "8.8.8.8,8.8.4.4"

typedef struct {
    char *hostname;
    u_char ip[16];
} hostname_ip_pair_t;

typedef struct {
    pthread_mutex_t mutex;
    bool initialized;
    int cache_size;
    hostname_ip_pair_t *cache;
} dns_cache_t;

void init_dns_cache(dns_cache_t *cache) {
    cache->initialized = true;
    cache->cache_size = 0;
    cache->cache = malloc(sizeof(hostname_ip_pair_t) * MAX_HOSTNAMES);
}

void destroy_dns_cache(dns_cache_t *cache) {
    if (cache->initialized) {
        free(cache->cache);
        cache->initialized = false;
    }
}

bool dns_cache_lookup(dns_cache_t *cache, char *hostname, u_char ip[16]) {
    bool found = false;
    for (int i = 0; i < cache->cache_size; i++) {
        if (strcmp(cache->cache[i].hostname, hostname) == 0) {
            memcpy(ip, cache->cache[i].ip, 16);
            found = true;
            break;
        }
    }
    return found;
}

void dns_cache_insert(dns_cache_t *cache, char *hostname, u_char ip[16]) {
    if (cache->cache_size < MAX_HOSTNAMES) {
        cache->cache[cache->cache_size].hostname = hostname;
        memcpy(cache->cache[cache->cache_size].ip, ip, 16);
        cache->cache_size++;
    }
}

void dns_cache_evict(dns_cache_t *cache) {
    if (cache->cache_size > MAX_HOSTNAMES) {
        for (int i = 0; i < cache->cache_size - MAX_HOSTNAMES; i++) {
            free(cache->cache[i].hostname);
        }
        memmove(cache->cache, cache->cache + (cache->cache_size - MAX_HOSTNAMES), sizeof(hostname_ip_pair_t) * MAX_HOSTNAMES);
        cache->cache_size = MAX_HOSTNAMES;
    }
}

void dns_resolve(char *hostname, u_char ip[16]) {
    struct addrinfo hints, *res;
    int errcode;

    memset(&hints, 0, sizeof(struct addrinfo));
    hints.ai_family = AF_INET; // IPv4 only for now
    hints.ai_socktype = SOCK_DGRAM;

    if ((errcode = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo: %s\n", gai_strerror(errcode));
        return;
    }

    memcpy(ip, res->ai_addr, 16);
    freeaddrinfo(res);
}

void *dns_resolver_thread(void *arg) {
    dns_cache_t *cache = (dns_cache_t *)arg;
    pthread_mutex_lock(&cache->mutex);
    while (true) {
        char *hostname = NULL;
        u_char ip[16];
        bool found = false;

        // Lookup hostname in cache
        if (!found) {
            found = dns_cache_lookup(cache, hostname, ip);
        }

        // If not found, resolve DNS and insert into cache
        if (!found) {
            dns_resolve(hostname, ip);
            dns_cache_insert(cache, hostname, ip);
            dns_cache_evict(cache);
        }

        pthread_mutex_unlock(&cache->mutex);
    }
}

void *dns_resolver_load_balancer_thread(void *arg) {
    dns_cache_t *cache = (dns_cache_t *)arg;
    while (true) {
        pthread_mutex_lock(&cache->mutex);
        for (int i = 0; i < cache->cache_size; i++) {
            char *hostname = cache->cache[i].hostname;
            u_char ip[16];
            bool found = false;

            // Lookup hostname in cache
            if (!found) {
                found = dns_cache_lookup(cache, hostname, ip);
            }

            // If not found, resolve DNS and insert into cache
            if (!found) {
                dns_resolve(hostname, ip);
                dns_cache_insert(cache, hostname, ip);
                dns_cache_evict(cache);
            }
        }
        pthread_mutex_unlock(&cache->mutex);
    }
