    // Create a new task for DNS resolution
    task.hostname = hostname;
    task.thread_id = num_threads++;
    task.is_done = false;

    // Add the task to the list of tasks
    dns_tasks[task.thread_id] = &task;

    // Create a new thread for DNS resolution
    pthread_t thread;
    if (pthread_create(&thread, NULL, dns_resolver, (void *)&task) < 0) {
        perror("pthread_create");
        return;
