    // Check if the DNS resolution was successful
    if (!task.is_done) {
        printf("DNS resolution failed for %s\n", hostname);
        return;
    }

    // Add the result to the cache
    dns_results[num_hosts++] = &task.dns_results[task.thread_id];
}

// Function to perform DNS resolution for a list of hostnames
void dns_resolve_batch(char **hostnames, int num_hostnames) {
