} dns_resolver_t;

void *dns_resolver(void *args) {
    hostname_ip_map_t *hostname = (hostname_ip_map_t *)args;
    int sockfd, ret;
    struct addrinfo hints, *res;
    char ipstr[INET6_ADDRSTRLEN];

    // Create a new socket
    sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("socket");
        return NULL;
    }

    // Setup DNS resolver context
    dns_resolver_t *dns_ctx = malloc(sizeof(dns_resolver_t));
    dns_ctx->sockfd = sockfd;
    dns_ctx->ssl_ctx = SSL_CTX_new(SSLv23_client_method());
    dns_ctx->ssl = SSL_new(dns_ctx->ssl_ctx);

    // Setup DNSSEC validation context
#ifdef DNSSEC_VALIDATION
    SSL_set_verify(dns_ctx->ssl, SSL_VERIFY_PEER | SSL_VERIFY_FAIL_IF_NO_PEER_CERT, NULL);
#endif

    // Setup IPv6 support context
#ifdef IPV6_SUPPORT
    hints.ai_family = AF_INET6;
#else
    hints.ai_family = AF_INET;
#endif

    // Setup DNS-over-TLS (DoT) or DNS-over-HTTPS (DoH) support context
#ifdef DOH_SUPPORT
    SSL_set_fd(dns_ctx->ssl, sockfd);
#else
    hints.ai_socktype = SOCK_DGRAM;
#endif

    // Perform DNS resolution
    ret = getaddrinfo(hostname->hostname, NULL, &hints, &res);
    if (ret != 0) {
        perror("getaddrinfo");
        return NULL;
    }

    // Get IP address from DNS response
    struct in_addr *addr = &((struct sockaddr_in *)(res->ai_addr))->sin_addr;
    memcpy(&hostname->ip, addr, sizeof(hostname->ip));

    // Cleanup
    freeaddrinfo(res);
    SSL_free(dns_ctx->ssl);
    SSL_CTX_free(dns_ctx->ssl_ctx);
    close(sockfd);

    return NULL;
}

