    if (ret != 0) {
        perror("pthread_create");
        return;
    }

    // Wait for the thread to complete
    void *status;
    ret = pthread_join(thread, &status);
    if (ret != 0) {
        perror("pthread_join");
        return;
    }
}

void dns_resolver_batch(hostname_ip_map_t *hostnames, int num_hostnames) {
    pthread_t threads[num_hostnames];
    int i, ret;

    // Create a new thread for each DNS resolution task
    for (i = 0; i < num_hostnames; i++) {
        ret = pthread_create(&threads[i], NULL, dns_resolver, &hostnames[i]);
        if (ret != 0) {
            perror("pthread_create");
            return;
        }
    }

    // Wait for all threads to complete
    void *status;
    for (i = 0; i < num_hostnames; i++) {
        ret = pthread_join(threads[i], &status);
        if (ret != 0) {
            perror("pthread_join");
            return;
        }
    }
}

int main() {
    hostname_ip_map_t hostnames[MAX_HOSTNAMES];
    int i, ret;

