        perror("socket");
        return -1;
    }
    dns_ctx->ssl_ctx = SSL_CTX_new(SSLv23_client_method());
    dns_ctx->ssl = SSL_new(dns_ctx->ssl_ctx);

    // Perform DNS resolution for up to 1,000 hostnames simultaneously
    for (i = 0; i < MAX_HOSTNAMES; i++) {
        ret = getaddrinfo("example.com", NULL, &hints, &res);
        if (ret != 0) {
            perror("getaddrinfo");
            return -1;
        }

        // Get IP address from DNS response
        struct in_addr *addr = &((struct sockaddr_in *)(res->ai_addr))->sin_addr;
        memcpy(&hostnames[i].ip, addr, sizeof(hostnames[i].ip));

        // Cleanup
        freeaddrinfo(res);
    }

    // Distribute DNS resolution tasks across multiple worker threads to handle the load efficiently
    dns_resolver_batch(hostnames, MAX_HOSTNAMES);

    // Cleanup
    SSL_free(dns_ctx->ssl);
    SSL_CTX_free(dns_ctx->ssl_ctx);
    close(dns_ctx->sockfd);

    return 0;
}
