    memory_pool->memory = realloc(memory_pool->memory, memory_pool->size + sizeof(NFAPI_CRC_INDICATION_PDU_T));
    memcpy((char *)memory_pool->memory + memory_pool->used - sizeof(NFAPI_CRC_INDICATION_PDU_T), crc_indication, sizeof(NFAPI_CRC_INDICATION_PDU_T));

