// Function to securely modify and encrypt a forward list of strings based on specific criteria
void securelyModifyAndEncrypt(forward_list<string>& list, const string& filename, const string& firstAdditionalString, const string& secondAdditionalString) {
    // Analyze the filename to determine the number of digits to prepend and the file type to replace the existing extension
    int numDigits = 0;
    string newFilename = "";
    for (int i = 0; i < filename.size(); i++) {
        if (isdigit(filename[i])) {
            numDigits++;
        } else {
