    // Encrypt the modified list of strings in place and return nothing
    AES_ctr128_encrypt(&aesKey, &list, iv, 0);
}

// Function to handle concurrent read and write operations on a text file without data corruption
void readWriteFile(const string& filename) {
    // Open the file in binary mode for reading and writing
    ifstream file(filename, ios::binary | ios::in | ios::out);

    // Create a mutex to synchronize access to the file
    mutex mtx;

    // Create a condition variable to signal when a thread is waiting for data to be read from the file
    condition_variable cv;

    // Create a vector of threads to handle concurrent read and write operations
    vector<thread> threads;

    // Read the contents of the file in chunks using a buffered read/write strategy that minimizes memory usage while maintaining performance
    const int BUFFER_SIZE = 1024 * 1024; // 1 MB
    char* buffer = new char[BUFFER_SIZE];
    size_t fileSize = 0;
    while (file.read(buffer, BUFFER_SIZE)) {
        // Acquire the mutex to synchronize access to the file
        unique_lock<mutex> lock(mtx);

        // Write the contents of the buffer to the file
        file.write(buffer, BUFFER_SIZE);

        // Release the mutex and signal that a thread is waiting for data to be read from the file
        cv.notify_one();
    }

    // Wait for all threads to finish reading from the file before closing it
    while (threads.size() > 0) {
        unique_lock<mutex> lock(mtx);
        cv.wait(lock);
    }

    // Close the file and delete the buffer
    file.close();
    delete[] buffer;
}

