        // Parse downloaded resource and extract metadata
        Metadata metadata;
        metadata.url = url;
        metadata.title = parseTitle(resource.get());
        metadata.description = parseDescription(resource.get());
        metadata.keywords = parseKeywords(resource.get());

        // Validate metadata against configuration settings
