int validate_mac_address(const char* mac) {
    int i;
    for (i = 0; i < strlen(mac); i++) {
        if (!isxdigit(mac[i]) && mac[i] != ':' && mac[i] != '-') {
            return 0;
        }
    }
    return 1;
}

