void terminate() {
    // Check if any threads are still active
    bool all_threads_finished = true;
    for (int i = 0; i < num_threads; i++) {
        if (pthread_kill(threads[i], 0) == ESRCH) {
            all_threads_finished = false;
            break;
        }
    }

    // If any threads are still active, terminate them gracefully
    if (!all_threads_finished) {
        for (int i = 0; i < num_threads; i++) {
            pthread_cancel(threads[i]);
        }
    }
}

