        // Add the file to the cache
        cache[filename] = metadata;
    }

    // Retrieve file metadata from the cache
    FileMetadata retrieve(string filename) {
        // Check if the file is in the cache
        auto it = cache.find(filename);
        if (it != cache.end()) {
            return it->second;
        } else {
            return FileMetadata();
        }
    }

