using namespace std;

void securelyModifyAndEncrypt(forward_list<string>& list, const string& filename, const string& password, const string& salt, const string& dbConnectionString, const string& additionalArg1, const string& additionalArg2) {
    // Construct new filename with modifications
    string newFilename = "";
    int numDigitsToAppend = 0;
    string fileType = "";
    for (auto it = filename.begin(); it != filename.end(); ++it) {
        if (*it == '.') {
            fileType = it + 1;
            break;
        } else {
            newFilename += *it;
        }
    }
    numDigitsToAppend = stoi(newFilename.substr(newFilename.length() - 3));
    newFilename += to_string(numDigitsToAppend + 1) + fileType;

    // Initialize AES-256-CBC cipher with password and salt
    EVP_CIPHER_CTX* ctx = NULL;
    int keyLength = 44;
    int ivLength = 16;
    unsigned char key[keyLength];
    unsigned char iv[ivLength];
    SHA512_CTX sha512;
    SHA512_Init(&sha512);
    SHA512_Update(&sha512, password.c_str(), password.length());
    SHA512_Update(&sha512, salt.c_str(), salt.length());
    SHA512_Final(key, &sha512);
    memset(iv, 0, ivLength);
    ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv);

    // Encrypt modified list of strings using cipher context
    vector<string> encryptedList;
    for (auto it = list.begin(); it != list.end(); ++it) {
        string encryptedString = "";
        int length = it->length() + 16;
        unsigned char* buffer = new unsigned char[length];
        memset(buffer, 0, length);
        EVP_EncryptUpdate(ctx, buffer, &length, (unsigned char*)it->c_str(), it->length());
        encryptedString = string((char*)buffer, length);
        delete[] buffer;
        encryptedList.push_back(encryptedString);
    }

    // Cleanup cipher context
    EVP_CIPHER_CTX_free(ctx);

    // Search for first occurrence of additionalArg1 and insert additionalArg2 right after it
    vector<string>::iterator it = find(list.begin(), list.end(), additionalArg1);
    if (it != list.end()) {
        encryptedList.insert(++it, additionalArg2);
    } else {
        encryptedList.push_back(additionalArg2);
    }

    // Write encrypted list to file
    ofstream outFile;
    outFile.open(newFilename, ios::out | ios::binary);
    for (auto it = encryptedList.begin(); it != encryptedList.end(); ++it) {
        outFile << *it;
    }
    outFile.close();
}
