            string storedProcedureName = "usp_encryptData";
            byte[] dataToEncrypt = Encoding.UTF8.GetBytes("Hello, World!");

            // Establish secure connection to database server
            SqlConnection conn = new SqlConnection(dbConnectionString);
            conn.Open();

            // Execute stored procedure with appropriate parameters
            SqlCommand cmd = new SqlCommand(storedProcedureName, conn);
            cmd.Parameters.AddWithValue("@dataToEncrypt", dataToEncrypt);
            cmd.ExecuteNonQuery();

            // Retrieve result from database server and decrypt it
            DataTableReader reader = cmd.ExecuteReader();
            byte[] encryptedData = new byte[reader.GetBytes(0, 0, null, 0, int.MaxValue)];
            reader.GetBytes(0, 0, encryptedData, 0, encryptedData.Length);
            byte[] decryptedData = DecryptData(encryptedData, "mypassword", "mysalt");

            // Display decrypted data
            Console.WriteLine("Decrypted Data: {0}", Encoding.UTF8.GetString(decryptedData));
        }

        static byte[] DecryptData(byte[] encryptedData, string password, string salt) {
            // Initialize AES-256-CBC cipher with password and salt
            EVP_CIPHER_CTX* ctx = NULL;
            int keyLength = 44;
            int ivLength = 16;
            unsigned char key[keyLength];
            unsigned char iv[ivLength];
            SHA512_CTX sha512;
            SHA512_Init(&sha512);
            SHA512_Update(&sha512, password.c_str(), password.length());
            SHA512_Update(&sha512, salt.c_str(), salt.length());
            SHA512_Final(key, &sha512);
            memset(iv, 0, ivLength);
            ctx = EVP_CIPHER_CTX_new();
            EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv);

            // Decrypt data using cipher context
            int length = encryptedData.Length;
            unsigned char* buffer = new unsigned char[length];
            memset(buffer, 0, length);
            EVP_DecryptUpdate(ctx, buffer, &length, encryptedData, length);
            byte[] decryptedData = new byte[length];
            Array.Copy(buffer, decryptedData, length);
            delete[] buffer;

            // Cleanup cipher context
            EVP_CIPHER_CTX_free(ctx);

            return decryptedData;
        }
    }
}
