Here is a possible implementation of the `efficientlyModifyAndEncrypt` function in C++:
```cpp
#include <iostream>
#include <string>
#include <vector>
#include <openssl/aes.h>
#include <openssl/evp.h>
#include <openssl/sha.h>

using namespace std;

void efficientlyModifyAndEncrypt(forward_list<string>& list, const string& filename, const string& password, const string& salt, const string& dbConnectionString, const string& additionalArg1, const string& additionalArg2) {
    // Analyze the filename to determine the number of digits to append and the file type to replace the existing extension.
    int numDigits = 0;
    for (const auto& str : list) {
        if (str.find(filename) != string::npos) {
            numDigits = str.size() - filename.size();
            break;
        }
    }

    // Construct a new filename with the modifications.
    string newFilename = filename + to_string(numDigits) + ".enc";

    // Initialize an AES-256-CBC cipher with the given password and salt.
    EVP_CIPHER_CTX* ctx;
    int ivLength = 16;
    int keyLength = 44;
    unsigned char iv[ivLength];
    unsigned char key[keyLength];
    SHA512(password, salt, key);
    EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv);

    // Search for the first occurrence of the first additional string argument within the forward list.
    auto it = find(list.begin(), list.end(), additionalArg1);
    if (it != list.end()) {
        // Insert the second additional string argument right after it.
        list.insert_after(it, additionalArg2);
    } else {
        // Append the second additional string argument to the end of the list.
        list.push_back(additionalArg2);
    }

    // Encrypt the modified list of strings using the initialized cipher context.
    for (auto& str : list) {
        EVP_EncryptUpdate(ctx, str.data(), str.size());
    }
}
