using System;
using System.Data;
using System.Data.SqlClient;
using System.Security.Cryptography;

namespace MyApp {
    public class DatabaseHelper {
        private readonly string _connectionString;

        public DatabaseHelper(string connectionString) {
            _connectionString = connectionString;
        }

        public DataTableReader ExecuteStoredProcedure(byte[] inputData) {
            // Establish a secure connection to the database server.
            SqlConnection conn = new SqlConnection(_connectionString);
            try {
                conn.Open();
            } catch (SqlException ex) {
                Console.WriteLine("Error connecting to the database: " + ex.Message);
                return null;
            }

            // Execute a stored procedure with appropriate parameters.
            SqlCommand cmd = new SqlCommand("sp_MyStoredProcedure", conn);
            cmd.Parameters.AddWithValue("@inputData", inputData);
            try {
                cmd.ExecuteNonQuery();
            } catch (SqlException ex) {
                Console.WriteLine("Error executing the stored procedure: " + ex.Message);
                return null;
            }

            // Retrieve the result from the database in the form of a DataTableReader object.
            SqlDataAdapter adapter = new SqlDataAdapter(cmd);
            DataSet ds = new DataSet();
            try {
                adapter.Fill(ds);
            } catch (SqlException ex) {
                Console.WriteLine("Error retrieving data from the database: " + ex.Message);
                return null;
            }

            // Close the connection to the database.
            conn.Close();

            // Return the DataTableReader object.
            return ds.CreateDataReader();
        }
    }
}
