    public class EncryptionHelper {
        private readonly DatabaseHelper _databaseHelper;

        public EncryptionHelper(string connectionString) {
            _databaseHelper = new DatabaseHelper(connectionString);
        }

        public byte[] EncryptData(byte[] inputData, string password, string salt) {
            // Initialize an AES-256-CBC cipher with the given password and salt.
            EVP_CIPHER_CTX* ctx;
            int ivLength = 16;
            int keyLength = 44;
            unsigned char iv[ivLength];
            unsigned char key[keyLength];
            SHA512(password, salt, key);
            EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv);

            // Encrypt the input data using the initialized cipher context.
            byte[] encryptedData = new byte[inputData.Length];
            int encryptedSize = 0;
            for (int i = 0; i < inputData.Length; i += 16) {
                EVP_EncryptUpdate(ctx, encryptedData + i, &encryptedSize, inputData + i, 16);
            }

            // Return the encrypted data.
            return encryptedData;
        }

        public byte[] DecryptData(byte[] inputData, string password, string salt) {
            // Initialize an AES-256-CBC cipher with the given password and salt.
            EVP_CIPHER_CTX* ctx;
            int ivLength = 16;
            int keyLength = 44;
            unsigned char iv[ivLength];
            unsigned char key[keyLength];
            SHA512(password, salt, key);
            EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv);

            // Decrypt the input data using the initialized cipher context.
            byte[] decryptedData = new byte[inputData.Length];
            int decryptedSize = 0;
            for (int i = 0; i < inputData.Length; i += 16) {
                EVP_DecryptUpdate(ctx, decryptedData + i, &decryptedSize, inputData + i, 16);
            }

            // Return the decrypted data.
            return decryptedData;
        }
    }
