void retryConnection(const string& dbConnectionString, int numRetries = 5) {
    // Establish a secure connection to the database server using the provided connection string.
    SqlConnection conn = new SqlConnection(dbConnectionString);
    try {
        conn.Open();
    } catch (SqlException ex) {
        Console.WriteLine("Error connecting to the database: " + ex.Message);
        return;
    }

    // Retry the connection up to five times with exponential backoff.
    int retryCount = 0;
    while (retryCount < numRetries) {
        try {
            conn.Open();
            break;
        } catch (SqlException ex) {
            Console.WriteLine("Error connecting to the database: " + ex.Message);
            retryCount++;
            if (retryCount == numRetries) {
                return;
            }
            int backoff = 1 << retryCount; // Exponential backoff.
            Thread.Sleep(backoff * 1000); // Sleep for the specified amount of time before retrying.
        }
    }
}
