void parse_command_line(int argc, char** argv, input_source_t* sources, int* num_sources) {
    // Parse command line arguments and populate input source list
    *num_sources = 0;
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "--manpage") == 0) {
            // Display comprehensive documentation
            printf("Usage: %s [OPTIONS]... [INPUT_SOURCES]\n", argv[0]);
            printf("\n");
            printf("Options:\n");
            printf("  -cs\tCount words in each line and print summary at end.\n");
            printf("  -o OUTPUT_FILE\tRedirect output to specified file.\n");
            exit(0);
        } else if (strcmp(argv[i], "-cs") == 0) {
            // Count words in each line and print summary at end
            sources[*num_sources].filename = NULL;
            sources[*num_sources].fd = STDIN_FILENO;
            (*num_sources)++;
        } else if (strcmp(argv[i], "-o") == 0 && i + 1 < argc) {
            // Redirect output to specified file
            sources[*num_sources].filename = argv[++i];
            sources[*num_sources].fd = open(sources[*num_sources].filename, O_WRONLY | O_CREAT, 0644);
            (*num_sources)++;
        } else {
            // Add input source to list
            sources[*num_sources].filename = argv[i];
            sources[*num_sources].fd = open(sources[*num_sources].filename, O_RDONLY);
            (*num_sources)++;
        }
    }
}

void process_input_source(input_source_t source, metrics_t* metrics) {
    // Process input source line by line and update metrics
    char buffer[BUFFER_SIZE];
    int bytes_read;
    while ((bytes_read = read(source.fd, buffer, BUFFER_SIZE)) > 0) {
        for (int i = 0; i < bytes_read; i++) {
            if (buffer[i] == '\n') {
                metrics->total_lines++;
                metrics->total_words += strlen(buffer + i);
                metrics->total_chars += bytes_read - i;
            }
        }
    }
}

void process_input_sources(input_source_t* sources, int num_sources, metrics_t* metrics) {
    // Process each input source and update metrics
    for (int i = 0; i < num_sources; i++) {
        process_input_source(sources[i], metrics);
    }
}

void print_metrics(metrics_t* metrics) {
    // Print summary of processed input sources
    printf("Total lines: %d\n", metrics->total_lines);
    printf("Total words: %d\n", metrics->total_words);
    printf("Total chars: %d\n", metrics->total_chars);
}

int main(int argc, char** argv) {
    // Initialize input sources and metrics
    input_source_t* sources = malloc(sizeof(input_source_t) * (argc - 1));
    int num_sources;
    parse_command_line(argc, argv, sources, &num_sources);
    metrics_t metrics = {0};

    // Process input sources and update metrics
    process_input_sources(sources, num_sources, &metrics);

    // Print summary of processed input sources
    print_metrics(&metrics);

    // Clean up resources
    for (int i = 0; i < num_sources; i++) {
        close(sources[i].fd);
    }
    free(sources);

    return 0;
}
