#include <unistd.h>
#include <pthread.h>

// Define constants for command line options
#define OPT_MANPAGE 1
#define OPT_CS 2
#define OPT_OUTPUT 3

// Define structure to hold file information
struct file_info {
    char *filename;
    int fd;
};

// Define function prototypes
void parse_args(int argc, char **argv);
void process_file(char *filename);
void count_lines(char *line);
void print_usage();
void display_manpage();
void display_summary();
void log_error(const char *message);
void* thread_func(void *arg);

// Global variables
int num_threads = 1;
int line_count = 0;
int word_count = 0;
char *output_file = NULL;
struct file_info *files = NULL;
size_t num_files = 0;
pthread_mutex_t mutex;

int main(int argc, char **argv) {
    // Parse command line arguments
    parse_args(argc, argv);

    // Initialize mutex for thread synchronization
    pthread_mutex_init(&mutex, NULL);

    // Process each file in parallel using threads
    for (size_t i = 0; i < num_files; i++) {
        struct file_info *file = &files[i];
        pthread_create(&file->tid, NULL, thread_func, file);
    }

    // Join all threads and print summary
    for (size_t i = 0; i < num_files; i++) {
        struct file_info *file = &files[i];
        pthread_join(file->tid, NULL);
    }
    display_summary();

    // Clean up resources
    free(files);
    pthread_mutex_destroy(&mutex);

    return 0;
}

void parse_args(int argc, char **argv) {
    int c;
    while ((c = getopt(argc, argv, "cs:o:")) != -1) {
        switch (c) {
            case OPT_MANPAGE:
                display_manpage();
                break;
            case OPT_CS:
                // Enable word counting
                break;
            case OPT_OUTPUT:
                output_file = optarg;
                break;
            default:
                print_usage();
                exit(1);
        }
    }

    if (optind < argc) {
        // Parse input files
        num_files = argc - optind;
        files = malloc(num_files * sizeof(struct file_info));
        for (size_t i = 0; i < num_files; i++) {
            struct file_info *file = &files[i];
            file->filename = argv[optind + i];
            file->fd = open(file->filename, O_RDONLY);
            if (file->fd == -1) {
                log_error("Failed to open input file");
            }
        }
    } else {
        print_usage();
        exit(1);
    }
}

void process_file(char *filename) {
    // Open the file and read it line by line
    int fd = open(filename, O_RDONLY);
    if (fd == -1) {
        log_error("Failed to open input file");
    }

    char buffer[BUFSIZ];
    ssize_t bytes_read;
    while ((bytes_read = read(fd, buffer, BUFSIZ)) > 0) {
        // Count lines and words in the line
        for (char *line = buffer; line < buffer + bytes_read; line++) {
            if (*line == '\n') {
                count_lines(line);
            } else if (*line != ' ') {
                word_count++;
            }
        }
    }

    // Close the file and update the global line count
    close(fd);
    pthread_mutex_lock(&mutex);
    line_count += num_lines;
    pthread_mutex_unlock(&mutex);
}

void count_lines(char *line) {
    // Increment the global line count and print a progress indicator
    pthread_mutex_lock(&mutex);
    line_count++;
    printf("Processed %d lines (%.2f%%)\n", line_count, (float)line_count / num_lines * 100);
    fflush(stdout);
    pthread_mutex_unlock(&mutex);
}

void print_usage() {
    printf("Usage: %s [OPTIONS] FILE...\n", argv[0]);
    printf("\n");
    printf("Options:\n");
    printf("  -cs          Count the number of words in each line.\n");
    printf("  -o output_file Redirect output to a specified file.\n");
    printf("  --manpage    Display comprehensive documentation.\n");
}

void display_manpage() {
    // Display comprehensive documentation for the program
    printf("Usage: %s [OPTIONS] FILE...\n", argv[0]);
    printf("\n");
    printf("Options:\n");
    printf("  -cs          Count the number of words in each line.\n");
    printf("  -o output_file Redirect output to a specified file.\n");
    printf("  --manpage    Display comprehensive documentation.\n");
}

void display_summary() {
    // Print summary of processed lines and words
    if (output_file != NULL) {
        // Redirect output to a specified file
        FILE *out = fopen(output_file, "w");
        if (out == NULL) {
            log_error("Failed to open output file");
        }
        fprintf(out, "%d lines processed\n", line_count);
        if (word_count > 0) {
            fprintf(out, "%d words counted\n", word_count);
        }
        fclose(out);
    } else {
        // Print output to console
        printf("%d lines processed\n", line_count);
        if (word_count > 0) {
            printf("%d words counted\n", word_count);
        }
    }
}

void log_error(const char *message) {
    // Log error messages to stderr
    fprintf(stderr, "%s: %s\n", argv[0], message);
}

void* thread_func(void *arg) {
    struct file_info *file = (struct file_info *)arg;
    process_file(file->filename);
    return NULL;
}
