#define BUFFER_SIZE 4096
#define MAX_FILE_SIZE (1024 * 1024 * 1024) // 1GB
#define MIN_BUFFER_SIZE 512
#define MAX_BUFFER_SIZE 8192
#define DEFAULT_BUFFER_SIZE 4096
#define DEFAULT_OUTPUT_FILE "output.txt"
#define DEFAULT_CONFIG_FILE "config.json"
#define DEFAULT_MANPAGE_FILE "manpage.txt"

// Struct to store processing metrics
struct Metrics {
    int total_lines;
    int total_words;
    int total_chars;
};

// Function to read a file and process its contents
void process_file(char *filename, struct Metrics *metrics) {
    // Open the file for reading
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("Error opening file");
        exit(EXIT_FAILURE);
    }

    // Read the file line by line and process each line
    char buffer[BUFFER_SIZE];
    while (fgets(buffer, BUFFER_SIZE, fp) != NULL) {
        // Increment total lines and words
        metrics->total_lines++;
        metrics->total_words += strlen(buffer);

        // Count characters in the line
        int i;
        for (i = 0; buffer[i] != '\n'; i++) {
            if (buffer[i] == ' ') {
                metrics->total_chars++;
            }
        }
    }

    // Close the file
    fclose(fp);
}

// Function to process a list of files and update metrics
void process_files(char **filenames, int num_files, struct Metrics *metrics) {
    for (int i = 0; i < num_files; i++) {
        process_file(filenames[i], metrics);
    }
}

// Function to compress a file using gzip or bzip2
void compress_file(char *filename, char *compression) {
    // Open the file for reading
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("Error opening file");
        exit(EXIT_FAILURE);
    }

    // Create a new file with the same name but with the compression extension
    char *compressed_file = malloc(strlen(filename) + strlen(compression) + 1);
    sprintf(compressed_file, "%s.%s", filename, compression);
    FILE *fp_out = fopen(compressed_file, "w");
    if (fp_out == NULL) {
        perror("Error opening compressed file");
        exit(EXIT_FAILURE);
    }

    // Compress the file using gzip or bzip2
    if (strcmp(compression, "gzip") == 0) {
        gzFile fp_in = gzdopen(fileno(fp), "rb");
        gzwrite(fp_out, fp_in);
    } else if (strcmp(compression, "bzip2") == 0) {
        bzFile fp_in = BZ2_fdopen(fileno(fp), "rb");
        BZ2_bzwrite(fp_out, fp_in);
    } else {
        printf("Invalid compression format\n");
        exit(EXIT_FAILURE);
    }

    // Close the files
    fclose(fp);
    fclose(fp_out);
}

// Function to process a configuration file and update metrics
void process_config(char *filename, struct Metrics *metrics) {
    // Open the file for reading
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("Error opening config file");
        exit(EXIT_FAILURE);
    }

    // Read the configuration parameters
    char buffer[BUFFER_SIZE];
    while (fgets(buffer, BUFFER_SIZE, fp) != NULL) {
        if (strncmp(buffer, "compression", 10) == 0) {
            char *compression = strtok(buffer, "=");
            compress_file(metrics->filename, compression);
        } else if (strncmp(buffer, "buffer_size", 11) == 0) {
            int buffer_size = atoi(strtok(buffer, "="));
            metrics->buffer_size = buffer_size;
        } else if (strncmp(buffer, "output_file", 11) == 0) {
            char *output_file = strtok(buffer, "=");
            metrics->output_file = output_file;
        }
    }

    // Close the file
    fclose(fp);
}

// Function to process a list of files and update metrics
void process_files(char **filenames, int num_files, struct Metrics *metrics) {
    for (int i = 0; i < num_files; i++) {
        process_file(filenames[i], metrics);
    }
}

// Function to print the processing summary
void print_summary(struct Metrics *metrics) {
    printf("Total lines: %d\n", metrics->total_lines);
    printf("Total words: %d\n", metrics->total_words);
    printf("Total chars: %d\n", metrics->total_chars);
}

// Function to print the usage information
void print_usage() {
    printf("Usage: ./program [options] <input source>\n");
    printf("\nOptions:\n");
    printf("  -cs                   Count words in each line and print a summary at the end\n");
    printf("  -o output_file        Redirect output to a specified file instead of the console\n");
    printf("  --manpage             Display comprehensive documentation\n");
}

// Function to handle command line arguments
void handle_args(int argc, char **argv) {
    // Initialize metrics struct
    struct Metrics metrics = {0};

    // Check for the presence of optional arguments
    if (argc == 1) {
        printf("No input source specified\n");
        print_usage();
        exit(EXIT_FAILURE);
    } else if (strcmp(argv[1], "-cs") == 0) {
        metrics.count_words = 1;
    } else if (strcmp(argv[1], "-o") == 0) {
        metrics.output_file = argv[2];
    } else if (strcmp(argv[1], "--manpage") == 0) {
        print_usage();
        exit(EXIT_SUCCESS);
    }

    // Check for the presence of input source
    if (argc > 2) {
        metrics.filename = argv[2];
    } else {
        printf("No input source specified\n");
        print_usage();
        exit(EXIT_FAILURE);
    }

    // Process the input source and update metrics
    process_file(metrics.filename, &metrics);

    // Print the processing summary
    if (metrics.count_words) {
        print_summary(&metrics);
    }
}

int main(int argc, char **argv) {
    handle_args(argc, argv);
    return 0;
}
