#define DEFAULT_CACHE_SIZE 100000
#define DEFAULT_CACHE_TTL 3600 // seconds
#define DEFAULT_VERBOSITY 2
#define DEFAULT_FILTERING_CRITERIA "event_id"
#define DEFAULT_AGGREGATION_METRICS "throughput,packet_loss,delay"
#define DEFAULT_RECALCULATION_FREQUENCY 3600 // seconds
#define DEFAULT_MAX_RETRIES 5
#define DEFAULT_RETRY_DELAY 10 // seconds
#define DEFAULT_JSON_SERIALIZATION_OVERHEAD 20 // bytes

typedef struct {
    char event_id[EVENT_ID_LEN];
    time_t timestamp;
    char source_mac[SOURCE_MAC_LEN];
    char destination_mac[DESTINATION_MAC_LEN];
    int frame_size;
} NETWORK_EVENT_T;

typedef struct {
    char event_id[EVENT_ID_LEN];
    time_t timestamp;
    int frame_size;
} CACHED_NETWORK_EVENT_T;

typedef struct {
    NETWORK_EVENT_T *events;
    size_t num_events;
    size_t capacity;
    pthread_mutex_t mutex;
} EVENTS_LIST_T;

typedef struct {
    CACHED_NETWORK_EVENT_T *events;
    size_t num_events;
    size_t capacity;
    time_t last_processed_timestamp;
    pthread_mutex_t mutex;
} CACHE_T;

typedef struct {
    char log_filename[MAX_LOG_FILENAME_LEN];
    int log_filemode;
    size_t cache_size;
    time_t cache_ttl;
    int verbosity;
    char filtering_criteria[DEFAULT_FILTERING_CRITERIA];
    char aggregation_metrics[DEFAULT_AGGREGATION_METRICS];
    size_t recalculation_frequency;
    int max_retries;
    int retry_delay;
    int json_serialization_overhead;
} CONFIG_T;

void process_and_store_network_events(CONFIG_T *config) {
    // Initialize the events list and cache
    EVENTS_LIST_T *events_list = malloc(sizeof(EVENTS_LIST_T));
    CACHE_T *cache = malloc(sizeof(CACHE_T));
    events_list->num_events = 0;
    events_list->capacity = MAX_EVENTS;
    cache->num_events = 0;
    cache->capacity = DEFAULT_CACHE_SIZE;
    cache->last_processed_timestamp = time(NULL);

    // Open the log file and read its contents
    int log_file = open(config->log_filename, O_RDONLY);
    if (log_file < 0) {
        perror("Error opening log file");
        return;
    }
    char *line = NULL;
    size_t line_len = 0;
    ssize_t read;
    while ((read = getline(&line, &line_len, log_file)) != -1) {
        // Parse the line and extract the network event information
        NETWORK_EVENT_T *event = malloc(sizeof(NETWORK_EVENT_T));
