        if (token == NULL) {
            continue;
        }
        strncpy(event->event_id, token, EVENT_ID_LEN);
        token = strtok(NULL, " ");
        if (token == NULL) {
            continue;
        }
        event->timestamp = atol(token);
        token = strtok(NULL, " ");
        if (token == NULL) {
            continue;
        }
        strncpy(event->source_mac, token, SOURCE_MAC_LEN);
        token = strtok(NULL, " ");
        if (token == NULL) {
            continue;
        }
        strncpy(event->destination_mac, token, DESTINATION_MAC_LEN);
        token = strtok(NULL, " ");
        if (token == NULL) {
            continue;
        }
        event->frame_size = atoi(token);

        // Add the event to the events list and cache
        pthread_mutex_lock(&events_list->mutex);
        if (events_list->num_events < events_list->capacity) {
            events_list->events[events_list->num_events++] = *event;
        } else {
            free(event);
        }
        pthread_mutex_unlock(&events_list->mutex);
        pthread_mutex_lock(&cache->mutex);
        if (cache->num_events < cache->capacity) {
            CACHED_NETWORK_EVENT_T *cached_event = malloc(sizeof(CACHED_NETWORK_EVENT_T));
            strncpy(cached_event->event_id, event->event_id, EVENT_ID_LEN);
            cached_event->timestamp = event->timestamp;
            cached_event->frame_size = event->frame_size;
            cache->events[cache->num_events++] = *cached_event;
        } else {
            free(event);
        }
        pthread_mutex_unlock(&cache->mutex);
    }
    free(line);
    close(log_file);

    // Process the events list and cache
    process_events_list(events_list, config);
    process_cache(cache, config);

    // Free the memory allocated for the events list and cache
    pthread_mutex_destroy(&events_list->mutex);
    free(events_list);
    pthread_mutex_destroy(&cache->mutex);
    free(cache);
}

void process_events_list(EVENTS_LIST_T *events_list, CONFIG_T *config) {
    // Iterate over the events list and perform filtering and aggregation
    for (size_t i = 0; i < events_list->num_events; i++) {
        NETWORK_EVENT_T *event = &events_list->events[i];
        if (strcmp(config->filtering_criteria, "event_id") == 0) {
            // Filter based on event ID
            if (strncmp(event->event_id, config->aggregation_metrics, EVENT_ID_LEN) == 0) {
                process_event(event, config);
            }
        } else if (strcmp(config->filtering_criteria, "timestamp") == 0) {
            // Filter based on timestamp
            if (event->timestamp >= time(NULL) - config->cache_ttl) {
                process_event(event, config);
            }
        } else {
            // Filter based on both event ID and timestamp
            if (strncmp(event->event_id, config->aggregation_metrics, EVENT_ID_LEN) == 0 &&
                    event->timestamp >= time(NULL) - config->cache_ttl) {
                process_event(event, config);
            }
        }
    }
}

void process_cache(CACHE_T *cache, CONFIG_T *config) {
    // Iterate over the cache and perform aggregation
    for (size_t i = 0; i < cache->num_events; i++) {
        CACHED_NETWORK_EVENT_T *cached_event = &cache->events[i];
        if (strcmp(config->aggregation_metrics, "throughput") == 0) {
            // Aggregate throughput
            int total_frame_size = 0;
            for (size_t j = i; j < cache->num_events && cached_event->timestamp == cache->events[j].timestamp; j++) {
                total_frame_size += cache->events[j].frame_size;
            }
            printf("Throughput: %d\n", total_frame_size);
        } else if (strcmp(config->aggregation_metrics, "packet_loss") == 0) {
            // Aggregate packet loss
            int total_lost_frames = 0;
            for (size_t j = i; j < cache->num_events && cached_event->timestamp == cache->events[j].timestamp; j++) {
                if (cache->events[j].frame_size > 0) {
                    total_lost_frames++;
                }
            }
            printf("Packet loss: %d\n", total_lost_frames);
        } else if (strcmp(config->aggregation_metrics, "delay") == 0) {
            // Aggregate delay
            int total_delay = 0;
            for (size_t j = i; j < cache->num_events && cached_event->timestamp == cache->events[j].timestamp; j++) {
                if (cache->events[j].frame_size > 0) {
                    total_delay++;
                }
            }
            printf("Delay: %d\n", total_delay);
        } else {
            // Aggregate all metrics
            int total_frame_size = 0;
            int total_lost_frames = 0;
            int total_delay = 0;
            for (size_t j = i; j < cache->num_events && cached_event->timestamp == cache->events[j].timestamp; j++) {
                if (cache->events[j].frame_size > 0) {
                    total_lost_frames++;
                }
                total_delay++;
            }
            printf("Throughput: %d\n", total_frame_size);
            printf("Packet loss: %d\n", total_lost_frames);
            printf("Delay: %d\n", total_delay);
        }
    }
}

void process_event(NETWORK_EVENT_T *event, CONFIG_T *config) {
    // Perform filtering and aggregation on the event
    if (strcmp(config->aggregation_metrics, "throughput") == 0) {
        // Aggregate throughput
        int total_frame_size = 0;
        for (size_t i = 0; i < config->recalculation_frequency && event->timestamp >= time(NULL) - config->cache_ttl; i++) {
            total_frame_size += event->frame_size;
        }
        printf("Throughput: %d\n", total_frame_size);
    } else if (strcmp(config->aggregation_metrics, "packet_loss") == 0) {
        // Aggregate packet loss
        int total_lost_frames = 0;
        for (size_t i = 0; i < config->recalculation_frequency && event->timestamp >= time(NULL) - config->cache_ttl; i++) {
            if (event->frame_size > 0) {
                total_lost_frames++;
            }
        }
        printf("Packet loss: %d\n", total_lost_frames);
    } else if (strcmp(config->aggregation_metrics, "delay") == 0) {
        // Aggregate delay
        int total_delay = 0;
        for (size_t i = 0; i < config->recalculation_frequency && event->timestamp >= time(NULL) - config->cache_ttl; i++) {
            if (event->frame_size > 0) {
                total_delay++;
            }
        }
        printf("Delay: %d\n", total_delay);
    } else {
        // Aggregate all metrics
        int total_frame_size = 0;
        int total_lost_frames = 0;
        int total_delay = 0;
        for (size_t i = 0; i < config->recalculation_frequency && event->timestamp >= time(NULL) - config->cache_ttl; i++) {
            if (event->frame_size > 0) {
                total_lost_frames++;
            }
            total_delay++;
        }
        printf("Throughput: %d\n", total_frame_size);
        printf("Packet loss: %d\n", total_lost_frames);
        printf("Delay: %d\n", total_delay);
    }
}
