// Define the function to manage the list of CRC indication PDUs
void manage_crc_indication_list(NFAPI_CRC_INDICATION_LIST_T *list) {
    // Lock the list for thread-safe access
    pthread_mutex_lock(&list->mutex);

    // Check if the RNTI is valid and not a duplicate within the specified time window
    bool is_duplicate = false;
    struct timespec current_time;
    clock_gettime(CLOCK_REALTIME, &current_time);
    for (size_t i = 0; i < list->count; i++) {
        if (list->pdu[i].rnti == rnti) {
            // Check if the RNTI is within the specified time window
            struct timespec last_processed_time;
            clock_gettime(CLOCK_REALTIME, &last_processed_time);
            double time_diff = (current_time.tv_sec - last_processed_time.tv_sec) +
                               (current_time.tv_nsec - last_processed_time.tv_nsec) / 1e9;
            if (time_diff < 5) { // 5 seconds
                is_duplicate = true;
                break;
            }
        }
    }

    // Add the new CRC indication PDU to the list
    if (!is_duplicate) {
        NFAPI_CRC_INDICATION_PDU_T *new_pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        memcpy(new_pdu, &rx_ue_information_tag, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        list->pdu[list->count++] = new_pdu;
    }

    // Clean up old or unused entries based on the age threshold
    size_t cleanup_threshold = 10; // 10 seconds
    for (size_t i = 0; i < list->count; i++) {
        if (list->pdu[i].rnti == rnti) {
            free(list->pdu[i]);
            list->pdu[i] = NULL;
