#include <pthread.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>

#define BUFFER_SIZE 4096
#define MAX_FILENAME_LENGTH 256
#define DEFAULT_BATCH_SIZE 1024

typedef struct {
    char* filename;
    int fd;
} file_info_t;

void print_usage(char* progname) {
    printf("Usage: %s [OPTION]... [FILE]...\n", progname);
    printf("\n");
    printf("Options:\n");
    printf("  -c, --count       Count the number of words in each line.\n");
    printf("  -o, --output FILE Redirect output to a file instead of stdout.\n");
    printf("  -h, --help        Display this help message and exit.\n");
}

void process_file(char* filename) {
    int fd = open(filename, O_RDONLY);
    if (fd == -1) {
        perror("Error opening file");
        return;
    }

    char buffer[BUFFER_SIZE];
    size_t bytes_read = 0;
    int lines = 0;
    int words = 0;
    while ((bytes_read = read(fd, buffer, BUFFER_SIZE)) > 0) {
        for (int i = 0; i < bytes_read; i++) {
            if (buffer[i] == '\n') {
                lines++;
                words += strlen(buffer + i);
            }
        }
    }

    printf("File: %s\n", filename);
    printf("  Lines: %d\n", lines);
    printf("  Words: %d\n", words);

    close(fd);
}

void* process_file_thread(void* arg) {
    file_info_t* info = (file_info_t*)arg;
    process_file(info->filename);
    free(info);
    return NULL;
}

int main(int argc, char** argv) {
    int opt;
    while ((opt = getopt(argc, argv, "co:h")) != -1) {
        switch (opt) {
            case 'c':
                printf("Counting words in each line...\n");
                break;
            case 'o':
                printf("Redirecting output to %s...\n", optarg);
                break;
            case 'h':
                print_usage(argv[0]);
                return 0;
        }
    }

    if (optind >= argc) {
        print_usage(argv[0]);
        return 1;
    }

    int num_files = argc - optind;
    file_info_t* files = malloc(num_files * sizeof(file_info_t));
    for (int i = 0; i < num_files; i++) {
        char* filename = argv[optind + i];
        int fd = open(filename, O_RDONLY);
        if (fd == -1) {
            perror("Error opening file");
            return 1;
        }
        files[i].filename = filename;
        files[i].fd = fd;
    }

    int batch_size = DEFAULT_BATCH_SIZE;
    if (optind + num_files < argc) {
        char* optarg = argv[optind + num_files];
        if (strcmp(optarg, "-") == 0 || strcmp(optarg, "--") == 0) {
            batch_size = -1;
        } else {
            batch_size = atoi(optarg);
        }
    }

    pthread_t* threads = malloc(num_files * sizeof(pthread_t));
    for (int i = 0; i < num_files; i++) {
        file_info_t* info = &files[i];
        if (batch_size > 0) {
            int chunk_size = batch_size / num_files;
            if (chunk_size == 0) {
                chunk_size = 1;
            }
            for (int j = 0; j < info->fd; j += chunk_size) {
                pthread_create(&threads[i], NULL, process_file_thread, info);
            }
        } else {
            pthread_create(&threads[i], NULL, process_file_thread, info);
        }
    }

    for (int i = 0; i < num_files; i++) {
        pthread_join(threads[i], NULL);
    }

    free(files);
    free(threads);
    return 0;
}
