        if (list->count >= MAX_ELEMENTS) {
            printf("Error: maximum number of elements exceeded\n");
            return;
        }
        list->elements = realloc(list->elements, (list->count + 1) * sizeof(float));
        list->elements[list->count++] = number;
    }
}

// Define a function to print the average value of the numbers in the list
