// Custom memory pool for efficient memory allocation and deallocation
struct MemoryPool {
    void* buffer;
    size_t capacity;
    size_t used;
};

void initMemoryPool(struct MemoryPool* pool, size_t capacity) {
    pool->buffer = malloc(capacity);
    pool->capacity = capacity;
    pool->used = 0;
}

void* allocate(struct MemoryPool* pool, size_t size) {
    if (pool->used + size > pool->capacity) {
        return NULL;
    }
    void* ptr = pool->buffer + pool->used;
    pool->used += size;
    return ptr;
}

void deallocate(struct MemoryPool* pool, void* ptr) {
    // Not implemented yet
}

// Helper function to calculate the average value of a list of numbers
double average(double* numbers, int count) {
    double sum = 0.0;
    for (int i = 0; i < count; i++) {
        sum += numbers[i];
    }
    return sum / count;
}

// Main function to read input from standard input and calculate the average value
void main() {
    // Initialize memory pool with a capacity of 10 million elements
    struct MemoryPool pool;
    initMemoryPool(&pool, 10000000);

    // Read input from standard input
    double* numbers = NULL;
    int count = 0;
    while (fscanf(stdin, "%lf", &numbers[count]) == 1) {
        void* ptr = allocate(&pool, sizeof(double));
        if (!ptr) {
            printf("Error: Memory pool exhausted. Please enter fewer numbers.\n");
            break;
        }
        memcpy(ptr, &numbers[count], sizeof(double));
        count++;
    }

    // Calculate the average value of the input numbers
    double average = 0.0;
    if (count > 0) {
        average = average(numbers, count);
    } else {
        printf("Error: No valid numbers entered.\n");
    }

    // Print the average value to standard output
    printf("%lf\n", average);

    // Periodically flush the array to disk to prevent data loss in case of a crash
    FILE* fp = fopen("average.txt", "wb");
    if (fp) {
        fwrite(numbers, sizeof(double), count, fp);
        fclose(fp);
    }

    // Ensure that the data is correctly synchronized between threads
    #pragma omp critical
    {
        deallocate(&pool, numbers);
    }
}
