using namespace std;

void processAndEncryptList(const vector<string>& list, const string& filename, const string& password, const string& salt, const string& dbConnectionString, const string& additionalArg1, const string& additionalArg2) {
    // Analyze the filename to determine the number of digits to append and the file type to replace the existing extension.
    int numDigits = 0;
    string newFilename = "";
    if (filename.find(".") != string::npos) {
        numDigits = filename.size() - filename.find_last_of(".") - 1;
        newFilename = filename.substr(0, filename.find_last_of(".")) + "_" + to_string(numDigits) + ".enc";
    } else {
        newFilename = filename + ".enc";
    }

    // Initialize an AES-256-CBC cipher with the given password and salt.
    EVP_CIPHER_CTX* ctx;
    int keyLength = 44;
    int ivLength = 16;
    unsigned char key[keyLength];
    unsigned char iv[ivLength];
    SHA512(password.c_str(), password.size(), key);
    memcpy(key, salt.c_str(), salt.size());
    ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv);

    // Search for the first occurrence of the first additional string argument within the forward list.
    int index = -1;
    for (int i = 0; i < list.size(); i++) {
        if (list[i] == additionalArg1) {
            index = i;
            break;
        }
    }

    // Insert the second additional string argument right after it, or append it to the end of the list.
    vector<string> newList;
    if (index != -1) {
        for (int i = 0; i < index + 1; i++) {
            newList.push_back(list[i]);
        }
        newList.push_back(additionalArg2);
        for (int i = index + 1; i < list.size(); i++) {
            newList.push_back(list[i]);
        }
    } else {
        newList = list;
        newList.push_back(additionalArg2);
    }

    // Encrypt the modified list of strings using the initialized cipher context.
    vector<unsigned char> encryptedData;
    for (int i = 0; i < newList.size(); i++) {
        string data = newList[i];
        int length = data.size();
        unsigned char* buffer = new unsigned char[length];
        memcpy(buffer, data.c_str(), length);
        EVP_EncryptUpdate(ctx, buffer, &length, buffer, length);
        encryptedData.insert(encryptedData.end(), buffer, buffer + length);
        delete[] buffer;
    }

    // Write the encrypted data to a file with the new filename.
    ofstream outputFile(newFilename, ios::binary | ios::out);
    for (int i = 0; i < encryptedData.size(); i++) {
        outputFile << encryptedData[i];
    }
    outputFile.close();

    // Clean up the cipher context and return.
    EVP_CIPHER_CTX_free(ctx);
}
