// Define the structure for the CRC indication PDU
typedef struct {
    uint16_t rx_ue_information_tag;
    uint32_t rnti;
    uint8_t crc_indication_rel8_tag;
    bool crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the list of CRC indication PDUs
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pdu;
    size_t count;
} NFAPI_CRC_INDICATION_LIST_T;

// Define the function to add a new CRC indication PDU to the list
void nfapi_crc_indication_add(NFAPI_CRC_INDICATION_LIST_T *list, uint32_t rnti, bool crcflag) {
    // Check if the RNTI is valid
    if (rnti < 0 || rnti > 65535) {
        printf("Invalid RNTI value: %d\n", rnti);
        return;
    }

    // Allocate memory for the new PDU
    NFAPI_CRC_INDICATION_PDU_T *pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) {
        printf("Failed to allocate memory for CRC indication PDU\n");
        return;
    }

    // Initialize the new PDU
    pdu->rx_ue_information_tag = 0x1234;
    pdu->rnti = rnti;
    pdu->crc_indication_rel8_tag = 0x5678;
    pdu->crcflag = crcflag;

    // Add the new PDU to the list
    list->pdu = realloc(list->pdu, (list->count + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->pdu) {
        printf("Failed to allocate memory for CRC indication PDU\n");
        free(pdu);
        return;
    }
    list->pdu[list->count++] = *pdu;
}

// Define the function to update an existing CRC indication PDU in the list
void nfapi_crc_indication_update(NFAPI_CRC_INDICATION_LIST_T *list, uint32_t rnti, bool crcflag) {
    // Check if the RNTI is valid
    if (rnti < 0 || rnti > 65535) {
        printf("Invalid RNTI value: %d\n", rnti);
        return;
    }

    // Find the PDU with the matching RNTI
    for (size_t i = 0; i < list->count; i++) {
        if (list->pdu[i].rnti == rnti) {
            // Update the PDU
            list->pdu[i].crcflag = crcflag;
            return;
        }
    }

    // If no matching PDU was found, add a new one
    nfapi_crc_indication_add(list, rnti, crcflag);
}

// Define the function to remove an existing CRC indication PDU from the list
void nfapi_crc_indication_remove(NFAPI_CRC_INDICATION_LIST_T *list, uint32_t rnti) {
    // Check if the RNTI is valid
    if (rnti < 0 || rnti > 65535) {
        printf("Invalid RNTI value: %d\n", rnti);
        return;
    }

    // Find the PDU with the matching RNTI
    for (size_t i = 0; i < list->count; i++) {
        if (list->pdu[i].rnti == rnti) {
            // Remove the PDU from the list
            free(list->pdu[i]);
            memmove(&list->pdu[i], &list->pdu[i + 1], (list->count - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            list->count--;
            return;
        }
    }
}

// Define the function to process a bulk of CRC indication PDUs in parallel
void nfapi_crc_indication_process_bulk(NFAPI_CRC_INDICATION_LIST_T *list) {
    // Create a thread pool for processing the PDUs
    pthread_t threads[16];
    size_t thread_count = 0;

    // Process each PDU in parallel
    for (size_t i = 0; i < list->count; i++) {
        if (thread_count >= 16) {
            break;
        }

        pthread_create(&threads[thread_count], NULL, nfapi_crc_indication_process_pdu, &list->pdu[i]);
        thread_count++;
    }

    // Wait for all threads to complete
    for (size_t i = 0; i < thread_count; i++) {
        pthread_join(threads[i], NULL);
    }
}

