void nfapi_crc_indication_handle_data_loss(NFAPI_CRC_INDICATION_LIST_T *list) {
    // Check if any PDUs have been lost
    for (size_t i = 0; i < list->count; i++) {
        if (!list->pdu[i].crcflag) {
