// Define the function to add a new entry to the list
void add_new_entry(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    // Check if the list is full and needs to be resized
    if (list_size == MAX_LIST_SIZE) {
        resize_list();
    }
    // Add a new entry to the list with the new data
    list[list_size++] = *pdu;
}

// Define the function to resize the list when it is full
void resize_list() {
    // Create a new list with twice the size of the current list
    NFAPI_CRC_INDICATION_PDU_T *new_list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(2 * list_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    // Copy the data from the current list to the new list
    for (int i = 0; i < list_size; i++) {
        new_list[i] = list[i];
    }
    // Free the memory used by the current list
    free(list);
    // Set the new list as the current list
    list = new_list;
}

// Define the function to check if a RNTI value is valid and within the predefined range
bool is_rnti_valid(RNTI rnti) {
    // Check if the RNTI value is within the predefined range
    return (rnti >= MIN_RNTI && rnti <= MAX_RNTI);
}

// Define the function to track the last processed RNTIs and prevent duplicates within a specified time window
void track_last_processed_rnitis(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    // Check if the RNTI has already been processed in the current time window
    if (is_rnti_processed(pdu->rnti)) {
        // Skip processing the structure if it has already been processed within the current time window
        return;
    } else {
        // Add the RNTI to the list of last processed RNTIs and set its timestamp
        add_last_processed_rniti(pdu->rnti);
    }
}

// Define the function to check if an RNTI has already been processed in the current time window
bool is_rnti_processed(RNTI rnti) {
    // Iterate through the list of last processed RNTIs and check if there is an entry with the same RNTI value
    for (int i = 0; i < last_processed_rnitis.size(); i++) {
        if (last_processed_rnitis[i].rnti == rnti) {
            // Check if the timestamp of the entry is within the current time window
            return (time(NULL) - last_processed_rnitis[i].timestamp < TIME_WINDOW);
        }
    }
    return false;
}

// Define the function to add an RNTI to the list of last processed RNTIs and set its timestamp
void add_last_processed_rniti(RNTI rnti) {
    // Create a new entry in the list of last processed RNTIs with the current time stamp
    LAST_PROCESSED_RNTI new_entry = {rnti, time(NULL)};
    // Add the new entry to the list
    last_processed_rnitis.push_back(new_entry);
}

// Define the function to clean up old or unused entries in the list based on a configurable age threshold
void cleanup_list() {
    // Iterate through the list and check if there are any entries that are older than the configured age threshold
    for (int i = 0; i < list_size; i++) {
        if (time(NULL) - list[i].timestamp > AGE_THRESHOLD) {
            // Remove the entry from the list and free its memory
            free(list + i);
            list_size--;
            i--;
        }
    }
}

