pthread_cond_t cache_condition = PTHREAD_COND_INITIALIZER;
int cache_invalidation_period = CACHE_INVALIDATION_PERIOD;
int num_cache_entries = 0;
int num_cache_hits = 0;
int num_cache_misses = 0;
int num_requests_processed = 0;
int num_requests_failed = 0;
int num_requests_retried = 0;
int num_requests_backoff = 0;
int num_requests_successful = 0;
int num_requests_unsuccessful = 0;
int num_requests_timeout = 0;
int num_requests_server_unavailable = 0;
int num_requests_network_partition = 0;
int num_requests_ssl_error = 0;
int num_requests_unknown_error = 0;
int num_requests_processed_per_minute[60];
int num_requests_failed_per_minute[60];
int num_requests_retried_per_minute[60];
int num_requests_backoff_per_minute[60];
int num_requests_successful_per_minute[60];
int num_requests_unsuccessful_per_minute[60];
int num_requests_timeout_per_minute[60];
int num_requests_server_unavailable_per_minute[60];
int num_requests_network_partition_per_minute[60];
int num_requests_ssl_error_per_minute[60];
int num_requests_unknown_error_per_minute[60];

// Function declarations
void *process_request(void *arg);
void handle_connection(int sockfd);
void handle_data_source(char *data_source_id, char *metadata_version);
void handle_request(char *data_source_id, char *metadata_version, int status_code, long processing_time);
void handle_cache_invalidation();
void handle_backoff(int attempt);
void handle_ssl_error(int error);
void handle_unknown_error();
void log_request_status(char *data_source_id, char *metadata_version, int status_code, long processing_time);
void log_cache_statistics();
void log_system_statistics();

// Main function
int main() {
    // Initialize SSL library
    if (tls_enabled) {
        SSL_library_init();
        SSL_load_error_strings();
        ERR_load_BIO_strings();
        OpenSSL_add_all_algorithms();
    }

    // Create socket and bind to port
    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    struct sockaddr_in serv_addr;
    memset(&serv_addr, 0, sizeof(serv_addr));
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(8080);
    inet_pton(AF_INET, "127.0.0.1", &serv_addr.sin_addr);
    bind(sockfd, (struct sockaddr *)&serv_addr, sizeof(serv_addr));

    // Listen for incoming connections
    listen(sockfd, MAX_CONNECTIONS);

    // Initialize cache invalidation timer
    struct itimerval cache_invalidation_timer;
    memset(&cache_invalidation_timer, 0, sizeof(cache_invalidation_timer));
    cache_invalidation_timer.it_value.tv_sec = cache_invalidation_period;
    setitimer(ITIMER_REAL, &cache_invalidation_timer, NULL);

    // Initialize system statistics logging timer
    struct itimerval system_statistics_logging_timer;
    memset(&system_statistics_logging_timer, 0, sizeof(system_statistics_logging_timer));
    system_statistics_logging_timer.it_value.tv_sec = 60;
    setitimer(ITIMER_REAL, &system_statistics_logging_timer, NULL);

    // Initialize request processing threads
    pthread_t threads[MAX_CONNECTIONS];
    for (int i = 0; i < MAX_CONNECTIONS; i++) {
        pthread_create(&threads[i], NULL, process_request, NULL);
    }

    // Accept incoming connections and handle requests
    while (1) {
        int sockfd = accept(sockfd, NULL, NULL);
        if (sockfd < 0) {
            perror("accept");
            continue;
        }
        handle_connection(sockfd);
    }

    // Clean up and exit
    close(sockfd);
    return 0;
}

// Process request function
void *process_request(void *arg) {
    while (1) {
        pthread_mutex_lock(&cache_lock);
        if (num_requests_per_minute >= MAX_REQUESTS_PER_MINUTE) {
            pthread_cond_wait(&cache_condition, &cache_lock);
        }
        num_requests_per_minute++;
        pthread_mutex_unlock(&cache_lock);

        // Handle request
        handle_request(data_sources[num_connections].data_source_id, data_sources[num_connections].metadata_version, 0, 0);

        // Update statistics
        num_requests_processed++;
        num_requests_per_minute--;
        pthread_mutex_lock(&cache_lock);
        num_cache_hits++;
        pthread_cond_signal(&cache_condition);
        pthread_mutex_unlock(&cache_lock);
    }
}

// Handle connection function
void handle_connection(int sockfd) {
    // Read data source ID and metadata version from client
    char data_source_id[DATA_SOURCE_ID_SIZE];
    char metadata_version[METADATA_VERSION_SIZE];
    read(sockfd, data_source_id, DATA_SOURCE_ID_SIZE);
    read(sockfd, metadata_version, METADATA_VERSION_SIZE);

    // Handle data source and metadata version
    handle_data_source(data_source_id, metadata_version);

    // Read request status from client
    int status_code;
    long processing_time;
    read(sockfd, &status_code, sizeof(int));
    read(sockfd, &processing_time, sizeof(long));

    // Handle request status
    handle_request(data_source_id, metadata_version, status_code, processing_time);

    // Close connection
    close(sockfd);
}

// Handle data source function
void handle_data_source(char *data_source_id, char *metadata_version) {
    // Check if data source is already registered
    bool found = false;
    for (int i = 0; i < num_connections; i++) {
        if (!strcmp(data_sources[i].data_source_id, data_source_id)) {
            found = true;
            break;
        }
    }

    // Register new data source if not found
    if (!found) {
        strcpy(data_sources[num_connections].data_source_id, data_source_id);
        strcpy(data_sources[num_connections].metadata_version, metadata_version);
        num_connections++;
    }
}

// Handle request function
void handle_request(char *data_source_id, char *metadata_version, int status_code, long processing_time) {
    // Check if data source is registered
    bool found = false;
    for (int i = 0; i < num_connections; i++) {
        if (!strcmp(data_sources[i].data_source_id, data_source_id)) {
            found = true;
            break;
        }
    }

    // Handle request status
    if (found) {
        log_request_status(data_source_id, metadata_version, status_code, processing_time);
        handle_cache_invalidation();
        handle_backoff(0);
        handle_ssl_error(0);
        handle_unknown_error();
    } else {
        log_request_status(data_source_id, metadata_version, 404, 0);
        num_requests_failed++;
        num_requests_unsuccessful++;
    }
}

// Handle cache invalidation function
void handle_cache_invalidation() {
    // Invalidate cache entries older than CACHE_INVALIDATION_PERIOD seconds
    time_t current_time = time(NULL);
    for (int i = 0; i < num_cache_entries; i++) {
        if (current_time - request_statuses[i].processing_time > cache_invalidation_period) {
            request_statuses[i] = {0, 0};
            num_cache_hits--;
            num_cache_misses++;
        }
    }
}

// Handle backoff function
void handle_backoff(int attempt) {
    // Back off if maximum number of attempts is reached
    if (attempt >= max_backoff_attempts) {
        log_request_status(data_source_id, metadata_version, 503, 0);
        num_requests_failed++;
        num_requests_unsuccessful++;
        num_requests_backoff++;
    } else {
        // Sleep for backoff period
        sleep(backoff_period);
        attempt++;
        handle_backoff(attempt);
    }
}

// Handle SSL error function
void handle_ssl_error(int error) {
    // Log SSL error and retry request if possible
    log_request_status(data_source_id, metadata_version, 503, 0);
    num_requests_failed++;
    num_requests_unsuccessful++;
    num_requests_ssl_error++;
}

// Handle unknown error function
void handle_unknown_error() {
    // Log unknown error and retry request if possible
    log_request_status(data_source_id, metadata_version, 503, 0);
    num_requests_failed++;
    num_requests_unsuccessful++;
    num_requests_unknown_error++;
}

// Log request status function
void log_request_status(char *data_source_id, char *metadata_version, int status_code, long processing_time) {
    // Update statistics
    num_requests_processed++;
    if (status_code == 200) {
        num_requests_successful++;
    } else {
        num_requests_failed++;
        if (status_code == 404) {
            num_requests_unsuccessful++;
        } else if (status_code == 503) {
            num_requests_backoff++;
        } else if (status_code == 521) {
            num_requests_timeout++;
        } else if (status_code == 523) {
            num_requests_server_unavailable++;
        } else if (status_code == 524) {
            num_requests_network_partition++;
        } else if (status_code == 525) {
            num_requests_ssl_error++;
        } else {
            num_requests_unknown_error++;
        }
    }

    // Log request status
    printf("Request status: %s, %s, %d, %ld\n", data_source_id, metadata_version, status_code, processing_time);
}

// Log cache statistics function
void log_cache_statistics() {
    // Update statistics
    num_requests_per_minute = 0;
    for (int i = 0; i < num_connections; i++) {
        if (!strcmp(data_sources[i].data_source_id, data_source_id)) {
            num_requests_per_minute++;
        }
    }

    // Log cache statistics
    printf("Cache statistics: %d, %d, %d\n", num_cache_hits, num_cache_misses, num_connections);
}

// Log system statistics function
void log_system_statistics() {
    // Update statistics
    time_t current_time = time(NULL);
    struct tm *current_tm = localtime(&current_time);
    char current_date[10];
    strftime(current_date, 10, "%Y-%m-%d", current_tm);

    // Log system statistics
    printf("System statistics: %s, %d, %d, %d\n", current_date, num_requests_processed, num_requests_failed, num_connections);
