// Define the function for finding an existing NFAPI_CRC_INDICATION_PDU_T entry in the list
nfapi_crc_indication_pdu_t *find_nfapi_crc_indication_entry(nfapi_crc_indication_list_t *list, uint16_t rnti) {
    for (size_t i = 0; i < list->size; i++) {
        if (list->data[i].rnti == rnti) {
            return &list->data[i];
        }
    }
    return NULL;
}

// Define the function for removing an existing NFAPI_CRC_INDICATION_PDU_T entry from the list
void remove_nfapi_crc_indication_entry(nfapi_crc_indication_list_t *list, uint16_t rnti) {
    // Lock the list for thread-safe access
    pthread_mutex_lock(&list->mutex);

    // Find the entry to remove
    nfapi_crc_indication_pdu_t *entry = find_nfapi_crc_indication_entry(list, rnti);
    if (entry != NULL) {
        // Remove the entry from the list
        size_t index = entry - list->data;
        memmove(&list->data[index], &list->data[index + 1], (list->size - index - 1) * sizeof(nfapi_crc_indication_pdu_t));
        list->size--;
