ccch_message_t* ccch_messages = NULL;
size_t num_ccch_messages = 0;

void init_ccch_messages(int max_num_ccch_messages) {
    // Allocate memory for the dynamic array of CCCH messages
    ccch_messages = (ccch_message_t*)malloc(max_num_ccch_messages * sizeof(ccch_message_t));
    if (!ccch_messages) {
        printf("Error: Failed to allocate memory for CCCH messages\n");
        return;
    }
}

void populate_ccch_messages(int num_ccch_messages, int tci, char* bsr) {
    // Check if the dynamic array has been initialized
    if (!ccch_messages) {
        printf("Error: CCCH messages have not been initialized\n");
        return;
    }

    // Ensure that the number of CCCH messages does not exceed the maximum capacity
    if (num_ccch_messages > max_num_ccch_messages) {
        printf("Error: Number of CCCH messages exceeds maximum capacity\n");
        return;
    }

    // Dynamically allocate memory for each BSR message
    char* bsr_ptr = (char*)malloc(strlen(bsr) + 1);
    if (!bsr_ptr) {
        printf("Error: Failed to allocate memory for BSR message\n");
        return;
    }

    // Copy the BSR message into the allocated memory
    strcpy(bsr_ptr, bsr);

    // Add the CCCH message to the dynamic array
    ccch_messages[num_ccch_messages].tci = tci;
    ccch_messages[num_ccch_messages].bsr = bsr_ptr;
}

void free_ccch_messages() {
    // Free the memory allocated for each BSR message
    for (int i = 0; i < num_ccch_messages; i++) {
        if (ccch_messages[i].bsr) {
