        NFAPI_CRC_INDICATION_PDU_T pdu = new NFAPI_CRC_INDICATION_PDU_T(rxUeInformationTag, rnti, crcIndicationRel8Tag, crcflag);

        // Add the new entry to the list of NFAPI_CRC_INDICATION_PDU_T structures
        crcIndicationPduList.add(pdu);
