    public void updateCrcIndicationPdu(RX_UE_INFORMATION_TAG rxUeInformationTag, RNTI rnti, CRC_INDICATION_REL8_TAG crcIndicationRel8Tag) {
        // Find the existing entry in the list of NFAPI_CRC_INDICATION_PDU_T structures with the specified RX_UE_INFORMATION_TAG and RNTI
        NFAPI_CRC_INDICATION_PDU_T pdu = findCrcIndicationPdu(rxUeInformationTag, rnti);

