} NFAPI_CRC_INDICATION_LIST_T;

// Define the helper function to find the largest integer in an array
int largest_integer(int arr[], int n) {
    if (n == 0) return -1;
    else if (n == 1) return arr[0];
    else {
        int max = arr[0];
        for (int i = 1; i < n; i++) {
            if (arr[i] > max) max = arr[i];
        }
        return max;
    }
}

// Define the function to manage the dynamic list of NFAPI_CRC_INDICATION_PDU_T structures
void manage_crc_indication_list(NFAPI_CRC_INDICATION_LIST_T *list, int RNTI, int CRC_INDICATION_REL8_TAG) {
    // Check if the input RNTI is valid and within the range of the system
    if (RNTI < 0 || RNTI > 65535) return;

    // Create a new NFAPI_CRC_INDICATION_PDU_T structure with the given RNTI and CRC_INDICATION_REL8_TAG
    NFAPI_CRC_INDICATION_PDU_T *new_entry = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    new_entry->RX_UE_INFORMATION_TAG = RNTI;
    new_entry->RNTI = RNTI;
    new_entry->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;

    // Add the new entry to the list, if it is not a duplicate within the specified time window
    struct timespec current_time;
    clock_gettime(CLOCK_MONOTONIC, &current_time);
    long current_timestamp = (long)current_time.tv_sec * 1000 + (long)current_time.tv_nsec / 1000000;
    for (int i = 0; i < list->size; i++) {
        if (list->data[i].RNTI == RNTI && current_timestamp - list->data[i].CRC_INDICATION_REL8_TAG < 1000) {
            free(new_entry);
            return;
        }
    }
    list->data = (NFAPI_CRC_INDICATION_PDU_T *)realloc(list->data, (list->size + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->data[list->size++] = *new_entry;

    // Update the last processed RNTI to prevent duplicates within the specified time window
    list->last_processed_RNTI = RNTI;
}

