#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define data structures for MAC frames, preamble types, SRS configurations, and timing advance indicators
typedef struct {
    unsigned int rnti;
    PREAMBLE_TYPE preamble_type;
    SRS_CONFIG srs_config;
    TIMING_ADVANCE_INDICATOR timing_advance_indicator;
} MAC_FRAME_T;

typedef enum {
    PREAMBLE_TYPE_NONE,
    PREAMBLE_TYPE_SHORT,
    PREAMBLE_TYPE_LONG,
} PREAMBLE_TYPE;

typedef struct {
    unsigned int srs_bandwidth;
    unsigned int srs_cyclic_shift;
} SRS_CONFIG;

typedef enum {
    TIMING_ADVANCE_INDICATOR_NONE,
    TIMING_ADVANCE_INDICATOR_ENABLED,
} TIMING_ADVANCE_INDICATOR;

// Define data structure for network traffic statistics
typedef struct {
    unsigned int rnti;
    unsigned long long bytes_transmitted;
    unsigned long long bytes_received;
    unsigned long long packets_transmitted;
    unsigned long long packets_received;
} NETWORK_TRAFFIC_STATS;

// Define data structure for the list of MAC frames
typedef struct {
    MAC_FRAME_T *frames;
    size_t num_frames;
    pthread_mutex_t mutex;
} MAC_FRAME_LIST;

// Define helper function to compute average throughput
double compute_average_throughput(NETWORK_TRAFFIC_STATS *stats, unsigned int time_window) {
    // Compute the total number of bytes and packets transmitted/received within the specified time window
    unsigned long long total_bytes = 0;
    unsigned long long total_packets = 0;
    for (size_t i = 0; i < stats->num_frames; i++) {
        if (stats[i].time_stamp >= time_window) {
            total_bytes += stats[i].bytes_transmitted + stats[i].bytes_received;
            total_packets += stats[i].packets_transmitted + stats[i].packets_received;
        }
    }

    // Compute the average throughput in bits per second
    double average_throughput = 0.0;
    if (total_bytes > 0) {
        average_throughput = total_bytes * 8 / time_window;
    } else if (total_packets > 0) {
        average_throughput = total_packets * 125 / time_window; // Assuming a packet size of 125 bytes
    }

    return average_throughput;
}

// Define function to add/update/remove MAC frames in the list
void manage_mac_frames(MAC_FRAME_LIST *list, unsigned int rnti, PREAMBLE_TYPE preamble_type, SRS_CONFIG srs_config, TIMING_ADVANCE_INDICATOR timing_advance_indicator) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&list->mutex);

    // Check if the RNTI is valid and within the range of the system
    if (rnti < 0 || rnti > 65535) {
        printf("Invalid RNTI value: %d\n", rnti);
        pthread_mutex_unlock(&list->mutex);
        return;
    }

    // Check if the MAC frame already exists in the list and update it if necessary
    for (size_t i = 0; i < list->num_frames; i++) {
        if (list->frames[i].rnti == rnti) {
            list->frames[i].preamble_type = preamble_type;
            list->frames[i].srs_config = srs_config;
            list->frames[i].timing_advance_indicator = timing_advance_indicator;
            break;
        }
    }

    // Add the MAC frame to the list if it doesn't exist
    if (list->num_frames == 0 || i == list->num_frames) {
        list->frames = realloc(list->frames, (list->num_frames + 1) * sizeof(MAC_FRAME_T));
        list->frames[list->num_frames].rnti = rnti;
        list->frames[list->num_frames].preamble_type = preamble_type;
        list->frames[list->num_frames].srs_config = srs_config;
        list->frames[list->num_frames].timing_advance_indicator = timing_advance_indicator;
        list->num_frames++;
    }

    // Remove the MAC frame from the list if it has been processed within the specified time window
    for (size_t i = 0; i < list->num_frames; i++) {
        if (list->frames[i].rnti == rnti && list->frames[i].time_stamp >= time_window) {
            memmove(&list->frames[i], &list->frames[i + 1], (list->num_frames - i - 1) * sizeof(MAC_FRAME_T));
            list->num_frames--;
        }
    }

    // Unlock the mutex
    pthread_mutex_unlock(&list->mutex);
}

// Define function to read network traffic statistics from standard input and update the list of MAC frames
void read_network_traffic_stats(MAC_FRAME_LIST *list) {
    // Read the network traffic statistics from standard input
    NETWORK_TRAFFIC_STATS stats;
    while (fscanf(stdin, "%d %llu %llu %llu %llu", &stats.rnti, &stats.bytes_transmitted, &stats.bytes_received, &stats.packets_transmitted, &stats.packets_received) == 5) {
        // Check if the RNTI is valid and within the range of the system
        if (stats.rnti < 0 || stats.rnti > 65535) {
            printf("Invalid RNTI value: %d\n", stats.rnti);
            continue;
        }

        // Update the list of MAC frames with the new network traffic statistics
        manage_mac_frames(list, stats.rnti, PREAMBLE_TYPE_NONE, SRS_CONFIG_NONE, TIMING_ADVANCE_INDICATOR_NONE);
    }
}

// Define function to compute the average throughput for a given time window
double compute_average_throughput(MAC_FRAME_LIST *list, unsigned int time_window) {
    // Compute the total number of bytes and packets transmitted/received within the specified time window
    unsigned long long total_bytes = 0;
    unsigned long long total_packets = 0;
    for (size_t i = 0; i < list->num_frames; i++) {
        if (list->frames[i].time_stamp >= time_window) {
            total_bytes += list->frames[i].bytes_transmitted + list->frames[i].bytes_received;
            total_packets += list->frames[i].packets_transmitted + list->frames[i].packets_received;
        }
    }

    // Compute the average throughput in bits per second
    double average_throughput = 0.0;
    if (total_bytes > 0) {
        average_throughput = total_bytes * 8 / time_window;
    } else if (total_packets > 0) {
        average_throughput = total_packets * 125 / time_window; // Assuming a packet size of 125 bytes
    }

    return average_throughput;
}
