#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <assert.h>

// Define the structure for an HTTP request
typedef struct {
    int id;
    char *ip_address;
    void *header;
} http_request_t;

// Define a linked list data structure to store the requests
typedef struct http_request_list_node {
    http_request_t request;
    struct http_request_list_node *next;
} http_request_list_node_t;

// Function to dynamically allocate memory for a header structure
void *allocate_header(size_t size) {
    void *ptr = malloc(size);
    if (ptr == NULL) {
        // Handle memory allocation failure gracefully
        printf("Error: Failed to allocate memory for header\n");
        return NULL;
    }
    return ptr;
}

// Function to add a new request to the linked list
void add_request(http_request_list_node_t **head, int id, char *ip_address, void *header) {
    http_request_list_node_t *new_node = malloc(sizeof(http_request_list_node_t));
    if (new_node == NULL) {
        // Handle memory allocation failure gracefully
        printf("Error: Failed to allocate memory for new request\n");
        return;
    }
    new_node->request.id = id;
    new_node->request.ip_address = ip_address;
    new_node->request.header = header;
    new_node->next = *head;
    *head = new_node;
}

// Function to remove a request from the linked list
void remove_request(http_request_list_node_t **head, int id) {
    http_request_list_node_t *current = *head;
    http_request_list_node_t *previous = NULL;
    while (current != NULL && current->request.id != id) {
        previous = current;
        current = current->next;
    }
    if (current == NULL) {
        // Handle request not found gracefully
        printf("Error: Request with ID %d not found\n", id);
        return;
    }
    if (previous == NULL) {
        *head = current->next;
    } else {
        previous->next = current->next;
    }
    free(current);
}

// Function to handle a new HTTP request
void handle_request(http_request_list_node_t **head, int id, char *ip_address, void *header) {
    // Check if the request is already in the linked list
    http_request_list_node_t *current = *head;
    while (current != NULL && current->request.id != id) {
        current = current->next;
    }
    if (current == NULL) {
        // Add the request to the linked list
        add_request(head, id, ip_address, header);
    } else {
        // Update the existing request in the linked list
        current->request.ip_address = ip_address;
        current->request.header = header;
    }
}

// Function to handle a removed HTTP request
void handle_removed_request(http_request_list_node_t **head, int id) {
    // Check if the request is in the linked list
    http_request_list_node_t *current = *head;
    while (current != NULL && current->request.id != id) {
        current = current->next;
    }
    if (current == NULL) {
        // Handle request not found gracefully
        printf("Error: Request with ID %d not found\n", id);
        return;
    }
    remove_request(head, id);
}

// Function to handle a HTTP request with a unique identifier
void handle_unique_request(http_request_list_node_t **head, int id) {
    // Check if the request is in the linked list
    http_request_list_node_t *current = *head;
    while (current != NULL && current->request.id != id) {
        current = current->next;
    }
    if (current == NULL) {
        // Handle request not found gracefully
        printf("Error: Request with ID %d not found\n", id);
        return;
    }
    // Update the existing request in the linked list
    current->request.id = id;
}

// Function to handle a HTTP request with a client IP address
void handle_ip_address(http_request_list_node_t **head, char *ip_address) {
    // Check if the request is in the linked list
    http_request_list_node_t *current = *head;
    while (current != NULL && strcmp(current->request.ip_address, ip_address) != 0) {
        current = current->next;
    }
    if (current == NULL) {
