    // Update the existing request in the linked list
    current->request.ip_address = ip_address;
}

// Function to handle a HTTP request with a dynamically allocated header structure
void handle_header(http_request_list_node_t **head, void *header) {
    // Check if the request is in the linked list
    http_request_list_node_t *current = *head;
    while (current != NULL && current->request.header != header) {
        current = current->next;
    }
    if (current == NULL) {
        // Handle request not found gracefully
