    }
    // Update the existing request in the linked list
    current->request.header = header;
}

// Function to handle a HTTP request with a unique identifier and client IP address
void handle_unique_ip_address(http_request_list_node_t **head, int id, char *ip_address) {
    // Check if the request is in the linked list
    http_request_list_node_t *current = *head;
    while (current != NULL && current->request.id != id || strcmp(current->request.ip_address, ip_address) != 0) {
