    }
    // Update the existing request in the linked list
    current->request.id = id;
    current->request.ip_address = ip_address;
}

// Function to handle a HTTP request with a unique identifier and dynamically allocated header structure
void handle_unique_header(http_request_list_node_t **head, int id, void *header) {
    // Check if the request is in the linked list
    http_request_list_node_t *current = *head;
    while (current != NULL && current->request.id != id || current->request.header != header) {
        current = current->next;
    }
    if (current == NULL) {
        // Handle request not found gracefully
        printf("Error: Request with ID %d and header %p not found\n", id, header);
