// Define the maximum size of the list
#define MAX_LIST_SIZE 2048

// Define the structure for the NFAPI_L1_STATS_RECORD
typedef struct {
    int tx_power_level;
    int tx_antenna_selection;
    int channel_quality_indicator;
} NFAPI_L1_STATS_RECORD;

// Define the list of NFAPI_L1_STATS_RECORD structures
NFAPI_L1_STATS_RECORD* list = NULL;

// Define the mutex for thread safety
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to add a new entry to the list
void add_entry(int tx_power_level, int tx_antenna_selection, int channel_quality_indicator) {
    // Lock the mutex
    pthread_mutex_lock(&mutex);

    // Check if the list is full
    if (list == NULL || list->size >= MAX_LIST_SIZE) {
        // If the list is full, allocate a new list with twice the size
        NFAPI_L1_STATS_RECORD* new_list = realloc(list, 2 * sizeof(NFAPI_L1_STATS_RECORD));
        if (new_list == NULL) {
            // If memory allocation fails, handle the error gracefully and unlock the mutex
            printf("Memory allocation failed\n");
            pthread_mutex_unlock(&mutex);
            return;
        }
        list = new_list;
    }

    // Add a new entry to the list
    NFAPI_L1_STATS_RECORD* new_entry = &list[list->size];
    new_entry->tx_power_level = tx_power_level;
    new_entry->tx_antenna_selection = tx_antenna_selection;
    new_entry->channel_quality_indicator = channel_quality_indicator;
    list->size++;

    // Unlock the mutex
    pthread_mutex_unlock(&mutex);
}

// Function to update an existing entry in the list based on TX power level
void update_entry(int tx_power_level) {
    // Lock the mutex
    pthread_mutex_lock(&mutex);

    // Find the entry with the matching TX power level
    NFAPI_L1_STATS_RECORD* matching_entry = NULL;
    for (int i = 0; i < list->size; i++) {
        if (list[i].tx_power_level == tx_power_level) {
            matching_entry = &list[i];
            break;
        }
    }

    // If a matching entry is found, update it with the new TX antenna selection and channel quality indicator
    if (matching_entry != NULL) {
        matching_entry->tx_antenna_selection = tx_antenna_selection;
        matching_entry->channel_quality_indicator = channel_quality_indicator;
    } else {
        // If no matching entry is found, add a new entry with the given TX power level, antenna selection, and channel quality indicator
        add_entry(tx_power_level, tx_antenna_selection, channel_quality_indicator);
    }

    // Unlock the mutex
    pthread_mutex_unlock(&mutex);
}

// Function to retrieve a list of all entries with a channel quality above a certain threshold
NFAPI_L1_STATS_RECORD* get_entries_above_threshold(int threshold) {
    // Lock the mutex
    pthread_mutex_lock(&mutex);

    // Create an empty list to store the matching entries
    NFAPI_L1_STATS_RECORD* matching_list = NULL;

    // Iterate over all entries in the list and add those with a channel quality above the threshold to the matching list
    for (int i = 0; i < list->size; i++) {
        if (list[i].channel_quality_indicator > threshold) {
            NFAPI_L1_STATS_RECORD* new_entry = realloc(matching_list, (matching_list->size + 1) * sizeof(NFAPI_L1_STATS_RECORD));
            if (new_entry == NULL) {
                // If memory allocation fails, handle the error gracefully and unlock the mutex
                printf("Memory allocation failed\n");
                pthread_mutex_unlock(&mutex);
                return matching_list;
            }
            matching_list = new_entry;
            matching_list[matching_list->size].tx_power_level = list[i].tx_power_level;
            matching_list[matching_list->size].tx_antenna_selection = list[i].tx_antenna_selection;
            matching_list[matching_list->size].channel_quality_indicator = list[i].channel_quality_indicator;
            matching_list->size++;
        }
    }

    // Unlock the mutex
    pthread_mutex_unlock(&mutex);

    return matching_list;
}

// Function to clear the list when done
void clear_list() {
    // Lock the mutex
    pthread_mutex_lock(&mutex);

    // Free the memory allocated for the list
    free(list);
    list = NULL;

    // Unlock the mutex
    pthread_mutex_unlock(&mutex);
}
