#include <xml/xml.h>

void read_config(const char* filename) {
    // Load the XML file
    xmlDocPtr doc = xmlReadFile(filename, NULL, 0);
    if (doc == NULL) {
        printf("Error: unable to load configuration file\n");
        return;
    }

    // Get the root element of the document
    xmlNodePtr root = xmlDocGetRootElement(doc);
    if (root == NULL) {
        printf("Error: unable to get root element of configuration file\n");
        xmlFreeDoc(doc);
        return;
    }

    // Get the tile size from the XML file
    int tile_size = 0;
    xmlNodePtr tile_size_node = xmlGetProp(root, "tile-size");
    if (tile_size_node == NULL) {
        printf("Error: unable to get tile size from configuration file\n");
        xmlFreeDoc(doc);
        return;
    } else {
        sscanf(xmlNodeGetContent(tile_size_node), "%d", &tile_size);
    }

    // Get the world width and height from the XML file
    int world_width = 0, world_height = 0;
    xmlNodePtr world_dimensions_node = xmlGetProp(root, "world-dimensions");
    if (world_dimensions_node == NULL) {
        printf("Error: unable to get world dimensions from configuration file\n");
        xmlFreeDoc(doc);
        return;
    } else {
        sscanf(xmlNodeGetContent(world_dimensions_node), "%d %d", &world_width, &world_height);
    }

    // Get the camera speed from the XML file
    float camera_speed = 0.0;
    xmlNodePtr camera_speed_node = xmlGetProp(root, "camera-speed");
    if (camera_speed_node == NULL) {
        printf("Error: unable to get camera speed from configuration file\n");
        xmlFreeDoc(doc);
        return;
    } else {
        sscanf(xmlNodeGetContent(camera_speed_node), "%f", &camera_speed);
    }

    // Construct the new file name based on the tile size, world dimensions, and camera speed
    char* new_filename = (char*)malloc(sizeof(char) * 256);
    sprintf(new_filename, "output_%d_%dx%d_%.1f.png", tile_size, world_width, world_height, camera_speed);

    // Free the XML document and return the new file name
    xmlFreeDoc(doc);
    return new_filename;
}
