// Function to read configuration data from JSON file
game_config* read_configuration(const char* filename) {
    // Open the JSON file and check for errors
    json_object* root = json_object_from_file(filename);
    if (!root) {
        fprintf(stderr, "Error: failed to open configuration file '%s'\n", filename);
        return NULL;
    }

    // Allocate memory for the game configuration structure
    game_config* config = malloc(sizeof(game_config));
    if (!config) {
        fprintf(stderr, "Error: failed to allocate memory for game configuration\n");
        json_object_put(root);
        return NULL;
    }

    // Read the number of levels from the JSON file
    json_object* num_levels = json_object_object_get(root, "num_levels");
    if (!json_object_is_type(num_levels, json_type_int)) {
        fprintf(stderr, "Error: invalid type for 'num_levels' in configuration file\n");
        free(config);
        json_object_put(root);
        return NULL;
    }
    config->num_levels = json_object_get_int(num_levels);

    // Read the maximum player health from the JSON file
    json_object* max_player_health = json_object_object_get(root, "max_player_health");
    if (!json_object_is_type(max_player_health, json_type_int)) {
        fprintf(stderr, "Error: invalid type for 'max_player_health' in configuration file\n");
        free(config);
        json_object_put(root);
        return NULL;
    }
    config->max_player_health = json_object_get_int(max_player_health);

    // Read the initial player position from the JSON file
    json_object* initial_player_position = json_object_object_get(root, "initial_player_position");
    if (!json_object_is_type(initial_player_position, json_type_array)) {
        fprintf(stderr, "Error: invalid type for 'initial_player_position' in configuration file\n");
        free(config);
        json_object_put(root);
        return NULL;
    }
    config->initial_player_position[0] = json_object_get_int(json_object_array_get_idx(initial_player_position, 0));
    config->initial_player_position[1] = json_object_get_int(json_object_array_get_idx(initial_player_position, 1));

    // Read the dimensions of a game tile from the JSON file
    json_object* tile_dimensions = json_object_object_get(root, "tile_dimensions");
    if (!json_object_is_type(tile_dimensions, json_type_array)) {
        fprintf(stderr, "Error: invalid type for 'tile_dimensions' in configuration file\n");
        free(config);
        json_object_put(root);
        return NULL;
    }
    config->tile_dimensions[0] = json_object_get_int(json_object_array_get_idx(tile_dimensions, 0));
    config->tile_dimensions[1] = json_object_get_int(json_object_array_get_idx(tile_dimensions, 1));

    // Read the resolution of the game window from the JSON file
    json_object* window_resolution = json_object_object_get(root, "window_resolution");
    if (!json_object_is_type(window_resolution, json_type_array)) {
        fprintf(stderr, "Error: invalid type for 'window_resolution' in configuration file\n");
        free(config);
        json_object_put(root);
        return NULL;
    }
    config->window_resolution[0] = json_object_get_int(json_object_array_get_idx(window_resolution, 0));
    config->window_resolution[1] = json_object_get_int(json_object_array_get_idx(window_resolution, 1));

    // Read the frame rate limit from the JSON file
    json_object* frame_rate_limit = json_object_object_get(root, "frame_rate_limit");
    if (!json_object_is_type(frame_rate_limit, json_type_int)) {
        fprintf(stderr, "Error: invalid type for 'frame_rate_limit' in configuration file\n");
        free(config);
        json_object_put(root);
        return NULL;
    }
    config->frame_rate_limit = json_object_get_int(frame_rate_limit);

    // Validate that the specified dimensions and frame rate are within acceptable limits
    if (config->tile_dimensions[0] < 1 || config->tile_dimensions[1] < 1) {
        fprintf(stderr, "Error: invalid value for 'tile_dimensions' in configuration file\n");
        free(config);
        json_object_put(root);
        return NULL;
    }
    if (config->window_resolution[0] < 1 || config->window_resolution[1] < 1) {
        fprintf(stderr, "Error: invalid value for 'window_resolution' in configuration file\n");
        free(config);
        json_object_put(root);
        return NULL;
    }
    if (config->frame_rate_limit < 1) {
        fprintf(stderr, "Error: invalid value for 'frame_rate_limit' in configuration file\n");
        free(config);
        json_object_put(root);
        return NULL;
    }

    // Clean up and return the game configuration structure
    json_object_put(root);
    return config;
}
