#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// Define the structure for NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the structure for the dynamic list of NFAPI_CRC_INDICATION_PDU_T structures
typedef struct {
    int size;
    int capacity;
    NFAPI_CRC_INDICATION_PDU_T* entries;
} NFAPI_CRC_INDICATION_LIST_T;

// Define the function to manage the dynamic list of NFAPI_CRC_INDICATION_PDU_T structures
void manageNFAPI_CRC_INDICATION_LIST(NFAPI_CRC_INDICATION_LIST_T* list, int RNTI, bool CRCFLAG) {
    // Check if the RNTI is within the valid range
    if (RNTI < 0 || RNTI > 65535) {
        printf("Invalid RNTI value: %d\n", RNTI);
        return;
    }

    // Lock the list to prevent concurrent access
    pthread_mutex_lock(&list->mutex);

    // Check if the RNTI is already in the list
    for (int i = 0; i < list->size; i++) {
        if (list->entries[i].RNTI == RNTI) {
            // Update the CRCFLAG value if it has changed
            if (list->entries[i].CRCFLAG != CRCFLAG) {
                list->entries[i].CRCFLAG = CRCFLAG;
            }
            pthread_mutex_unlock(&list->mutex);
            return;
        }
    }

    // Add the new entry to the list if it is not already present
    if (list->size < list->capacity) {
        NFAPI_CRC_INDICATION_PDU_T* newEntry = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        newEntry->RX_UE_INFORMATION_TAG = 0;
        newEntry->RNTI = RNTI;
        newEntry->CRC_INDICATION_REL8_TAG = 0;
        newEntry->CRCFLAG = CRCFLAG;
        list->entries[list->size++] = *newEntry;
    } else {
        // Remove the oldest entry from the list if it is full
        NFAPI_CRC_INDICATION_PDU_T* oldestEntry = &list->entries[0];
        for (int i = 1; i < list->size; i++) {
            if (list->entries[i].RNTI < oldestEntry->RNTI) {
                oldestEntry = &list->entries[i];
            }
        }
        free(oldestEntry);
        memmove(&list->entries[0], &list->entries[1], sizeof(NFAPI_CRC_INDICATION_PDU_T) * (list->size - 1));
        list->size--;
    }

    // Unlock the list to allow concurrent access
    pthread_mutex_unlock(&list->mutex);
}

// Define the function to validate the RNTI values in the list
void validateRNTIs(NFAPI_CRC_INDICATION_LIST_T* list) {
    // Lock the list to prevent concurrent access
    pthread_mutex_lock(&list->mutex);

    // Iterate over the entries in the list and validate their RNTI values
    for (int i = 0; i < list->size; i++) {
        if (list->entries[i].RNTI < 0 || list->entries[i].RNTI > 65535) {
            printf("Invalid RNTI value: %d\n", list->entries[i].RNTI);
        }
    }

    // Unlock the list to allow concurrent access
    pthread_mutex_unlock(&list->mutex);
}

// Define the function to track the last processed RNTI and prevent duplicates within a specified time window
void trackLastProcessedRNTI(NFAPI_CRC_INDICATION_LIST_T* list, int RNTI) {
    // Lock the list to prevent concurrent access
    pthread_mutex_lock(&list->mutex);

    // Check if the RNTI is already in the list
    for (int i = 0; i < list->size; i++) {
        if (list->entries[i].RNTI == RNTI) {
            // Update the last processed time if it has changed
            if (list->entries[i].lastProcessedTime != time(NULL)) {
                list->entries[i].lastProcessedTime = time(NULL);
            }
            pthread_mutex_unlock(&list->mutex);
            return;
        }
    }

    // Add the new entry to the list if it is not already present
    if (list->size < list->capacity) {
        NFAPI_CRC_INDICATION_PDU_T* newEntry = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        newEntry->RX_UE_INFORMATION_TAG = 0;
        newEntry->RNTI = RNTI;
        newEntry->CRC_INDICATION_REL8_TAG = 0;
        newEntry->lastProcessedTime = time(NULL);
        list->entries[list->size++] = *newEntry;
    } else {
        // Remove the oldest entry from the list if it is full
        NFAPI_CRC_INDICATION_PDU_T* oldestEntry = &list->entries[0];
        for (int i = 1; i < list->size; i++) {
            if (list->entries[i].lastProcessedTime < oldestEntry->lastProcessedTime) {
                oldestEntry = &list->entries[i];
            }
        }
        free(oldestEntry);
        memmove(&list->entries[0], &list->entries[1], sizeof(NFAPI_CRC_INDICATION_PDU_T) * (list->size - 1));
        list->size--;
    }

    // Unlock the list to allow concurrent access
    pthread_mutex_unlock(&list->mutex);
}

// Define the function to clean up old or unused entries in the list based on a configurable age threshold
void cleanUpOldEntries(NFAPI_CRC_INDICATION_LIST_T* list, int ageThreshold) {
    // Lock the list to prevent concurrent access
    pthread_mutex_lock(&list->mutex);

    // Iterate over the entries in the list and remove any that are older than the specified age threshold
    for (int i = 0; i < list->size; i++) {
        if (list->entries[i].lastProcessedTime + ageThreshold <= time(NULL)) {
            free(&list->entries[i]);
            memmove(&list->entries[i], &list->entries[i+1], sizeof(NFAPI_CRC_INDICATION_PDU_T) * (list->size - i));
            list->size--;
        }
    }

    // Unlock the list to allow concurrent access
    pthread_mutex_unlock(&list->mutex);
}

// Define the function to handle incoming data in parallel to minimize latency and ensure data consistency
void handleIncomingData(NFAPI_CRC_INDICATION_LIST_T* list, int RNTI, bool CRCFLAG) {
    // Lock the list to prevent concurrent access
    pthread_mutex_lock(&list->mutex);

    // Add or update the entry in the list based on the incoming data
    manageNFAPI_CRC_INDICATION_LIST(list, RNTI, CRCFLAG);

    // Unlock the list to allow concurrent access
    pthread_mutex_unlock(&list->mutex);
}

// Define the function to handle memory allocation and deallocation efficiently to avoid leaks
void allocateMemory(NFAPI_CRC_INDICATION_LIST_T* list, int capacity) {
    // Lock the list to prevent concurrent access
    pthread_mutex_lock(&list->mutex);

    // Allocate memory for the new entries in the list
    NFAPI_CRC_INDICATION_PDU_T* newEntries = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * capacity);
    if (newEntries == NULL) {
        printf("Failed to allocate memory for the list\n");
        return;
    }

    // Copy the existing entries from the old list to the new list
    memcpy(newEntries, list->entries, sizeof(NFAPI_CRC_INDICATION_PDU_T) * list->size);

    // Free the memory for the old list
    free(list->entries);

    // Update the list with the new entries and capacity
    list->entries = newEntries;
    list->capacity = capacity;

    // Unlock the list to allow concurrent access
    pthread_mutex_unlock(&list->mutex);
}

// Define the function to handle memory deallocation efficiently to avoid leaks
void deallocateMemory(NFAPI_CRC_INDICATION_LIST_T* list) {
    // Lock the list to prevent concurrent access
    pthread_mutex_lock(&list->mutex);

    // Free the memory for the list entries
    free(list->entries);

    // Reset the list size and capacity
    list->size = 0;
    list->capacity = 0;

    // Unlock the list to allow concurrent access
    pthread_mutex_unlock(&list->mutex);
}
