void modifyAndInsert(std::forward_list<std::string>& fileNames, const std::string& filename, const std::string& searchString, const std::string& replacementString, const std::string& predefinedFileType) {
    // Determine the number of digits in the filename to append to each entry in the list
    int digitCount = 0;
    for (char c : filename) {
        if (std::isdigit(c)) {
            ++digitCount;
        }
    }

    // Replace the existing file extension with a predefined one
    size_t dotPos = filename.rfind('.');
    if (dotPos != std::string::npos) {
        filename.replace(dotPos, filename.length() - dotPos, predefinedFileType);
    }

    // Append the number of digits determined from the filename to the new filename
    std::ostringstream oss;
    oss << filename << digitCount;

    // Create a hash map to track unique filenames for efficient duplicate handling
    std::unordered_map<std::string, bool> uniqueFilenames;

    // Iterate through the forward list to find the first occurrence of searchString
    auto it = fileNames.before_begin();
    bool found = false;
    while (!found && it != fileNames.end()) {
        ++it;
        if (it != fileNames.end() && *it == searchString) {
            found = true;
        }
    }

    // Check for duplicates before inserting
    if (found) {
        if (uniqueFilenames.find(oss.str()) == uniqueFilenames.end()) {
            fileNames.insert_after(it, oss.str());
            uniqueFilenames[oss.str()] = true;
        }
    } else {
        if (uniqueFilenames.find(oss.str()) == uniqueFilenames.end()) {
            fileNames.push_back(oss.str());
            uniqueFilenames[oss.str()] = true;
        }
    }

