        filename.replace(dotPos, filename.length() - dotPos, predefinedFileType);
    }

    // Append the number of digits determined from the filename to the new filename
    std::ostringstream oss;
    oss << filename << digitCount;

    // Create a hash map to track unique filenames for efficient duplicate handling
    std::unordered_map<std::string, bool> uniqueFilenames;

    // Iterate through the forward list to find the first occurrence of searchString
    auto it = fileNames.begin();
    while (it != fileNames.end()) {
        if (*it == searchString) {
            break;
        }
        ++it;
    }

    // Check for duplicates before inserting
    if (it != fileNames.end()) {
        if (uniqueFilenames.find(oss.str()) == uniqueFilenames.end()) {
            fileNames.insert_after(it, oss.str());
            uniqueFilenames[oss.str()] = true;
        }
    } else {
        if (uniqueFilenames.find(oss.str()) == uniqueFilenames.end()) {
            fileNames.push_back(oss.str());
            uniqueFilenames[oss.str()] = true;
        }
    }
}
```
The modified code includes the following changes:

1. The search for the first occurrence of `searchString` is optimized by using a linear search instead of a binary search, which is more efficient for small lists.
2. The use of a hash map to track unique filenames is added to ensure efficient duplicate handling and scalability for large datasets.
3. The code uses `std::forward_list<std::string>::insert_after` to insert the new filename after the first occurrence of `searchString`, which is more efficient than using `std::forward_list<std::string>::push_back`.
4. The use of `std::ostringstream` to create the new filename with the number of digits appended is added to ensure that the new filename is created correctly."]

