        public DatabaseHelper(string connectionString) {
            _connectionString = connectionString;
        }

        public DataTableReader ExecuteStoredProcedure(byte[] inputData, string storedProcedureName, params object[] parameters) {
            // Establish a secure connection to the database server
            SqlConnection conn = new SqlConnection(_connectionString);
            try {
                conn.Open();
            } catch (SqlException ex) {
                Console.WriteLine("Error connecting to the database: " + ex.Message);
                return null;
            }

            // Execute the stored procedure with appropriate parameters
            SqlCommand cmd = new SqlCommand(storedProcedureName, conn);
            cmd.Parameters.AddRange(parameters);
            try {
                cmd.ExecuteNonQuery();
            } catch (SqlException ex) {
                Console.WriteLine("Error executing the stored procedure: " + ex.Message);
                return null;
            }

            // Retrieve the result from the database server
            SqlDataReader reader = cmd.ExecuteReader();
            DataTable dt = new DataTable();
            dt.Load(reader);
            reader.Close();

            // Return the result as a DataTableReader object
            return new DataTableReader(dt);
        }
    }
}
