// DNS resolution thread function
void *dns_resolution_thread(void *arg) {
    // Initialize variables
    int dns_socket = -1;
    struct sockaddr_in dns_server_address;
    char buffer[512];
    bool is_running = true;

    // Create socket for DNS resolution
    if ((dns_socket = socket(AF_INET, SOCK_DGRAM, 0)) < 0) {
        printf("Error creating DNS resolution socket\n");
        return NULL;
    }

    // Set up DNS server address
    memset(&dns_server_address, 0, sizeof(struct sockaddr_in));
    dns_server_address.sin_family = AF_INET;
    dns_server_address.sin_port = htons(53);
    inet_pton(AF_INET, dns_resolution_config.hostname, &dns_server_address.sin_addr);

    // Start DNS resolution loop
    while (is_running) {
        // Check if DNS resolution is enabled
        if (!is_dns_resolution_enabled) {
            break;
        }

        // Get next request from queue
        char *hostname = NULL;
        int port = 0;
        pthread_mutex_lock(&mutex);
        if (num_requests_per_second >= MAX_REQUESTS_PER_SECOND) {
            is_running = false;
        } else {
            num_requests_per_second++;
            hostname = "example.com"; // Replace with actual hostname from queue
            port = 80; // Replace with actual port from queue
        }
        pthread_mutex_unlock(&mutex);

        // Perform DNS resolution if enabled and request is available
        if (is_dns_resolution_enabled && hostname != NULL) {
            // Set up DNS query packet
            struct sockaddr_in client_address;
            memset(&client_address, 0, sizeof(struct sockaddr_in));
            client_address.sin_family = AF_INET;
            inet_pton(AF_INET, "127.0.0.1", &client_address.sin_addr);
            int client_port = 53;

            // Send DNS query packet to server
            if (sendto(dns_socket, buffer, strlen(buffer), 0, (struct sockaddr *)&dns_server_address, sizeof(struct sockaddr)) < 0) {
                printf("Error sending DNS resolution request\n");
                is_running = false;
            }

            // Receive DNS response packet from server
            struct sockaddr_in server_address;
            memset(&server_address, 0, sizeof(struct sockaddr_in));
            int server_port = 53;
            if (recvfrom(dns_socket, buffer, sizeof(buffer), 0, (struct sockaddr *)&server_address, &server_port) < 0) {
                printf("Error receiving DNS resolution response\n");
                is_running = false;
            }
        }
    }

    // Close socket for DNS resolution
    close(dns_socket);

    return NULL;
}

// CRC indication processing thread function
void *crc_indication_processing_thread(void *arg) {
    // Initialize variables
    int crc_indication_pdu_size = sizeof(crc_indication_pdu_t);
    bool is_running = true;

    // Start CRC indication processing loop
    while (is_running) {
        // Check if DNS resolution is enabled
        if (!is_dns_resolution_enabled) {
            break;
        }

        // Get next CRC indication PDU from queue
        crc_indication_pdu_t *crc_indication_pdu = NULL;
        pthread_mutex_lock(&mutex);
        if (num_concurrent_threads >= MAX_THREADS) {
            is_running = false;
        } else {
            num_concurrent_threads++;
            crc_indication_pdu = malloc(crc_indication_pdu_size);
            memset(crc_indication_pdu, 0, crc_indication_pdu_size);
        }
        pthread_mutex_unlock(&mutex);

        // Process CRC indication PDU if available
        if (crc_indication_pdu != NULL) {
            // Get IP address for hostname
            char *ip_address = get_ip_address(crc_indication_pdu->rx_ue_information, crc_indication_pdu->rnti);
            if (ip_address == NULL) {
                printf("Error getting IP address for hostname\n");
                is_running = false;
            } else {
                // Get CRC indication PDU for IP address and RNTI
                crc_indication_pdu_t *crc_indication_pdu = get_crc_indication_pdu(ip_address, crc_indication_pdu->rnti);
                if (crc_indication_pdu == NULL) {
                    printf("Error getting CRC indication PDU for IP address and RNTI\n");
                    is_running = false;
                } else {
                    // Process CRC indication PDU
                    if (crc_indication_pdu->crc_indication_rel8 == NULL) {
                        printf("Error processing CRC indication PDU\n");
                        is_running = false;
                    } else {
                        // Log event for CRC indication PDU
                        log_event("CRC indication received");

                        // Increment counters
                        num_crc_indications++;
                        if (strcmp(crc_indication_pdu->crc_indication_rel8, "correct") == 0) {
                            num_correct_crc_indications++;
                        } else {
                            num_incorrect_crc_indications++;
                        }
                    }
                }
            }
        }
    }

    // Free CRC indication PDU memory if available
    if (crc_indication_pdu != NULL) {
        free(crc_indication_pdu);
    }

    return NULL;
}

