#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <semaphore.h>

// Define the maximum number of entries in the list
#define MAX_ENTRIES 1024

// Define the maximum duration for which a RNTI is considered valid (in seconds)
#define VALID_RNTI_DURATION 5

// Define the age threshold for cleaning up old or unused entries (in seconds)
#define AGE_THRESHOLD 300

// Define the maximum CPU usage percentage for processing critical data
#define MAX_CPU_USAGE 70

// Define the memory usage limit for each entry (in bytes)
#define MEMORY_LIMIT 1024 * 1024

// Define the logging level for the function
#define LOGGING_LEVEL 3

// Define the fallback strategy for critical operations when resources are constrained
#define FALLBACK_STRATEGY 1

typedef struct {
    uint8_t valid;
    uint64_t rnti;
    uint8_t crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    uint64_t rx_ue_information_tag;
    uint64_t rnti;
    uint8_t crc_indication_rel8_tag;
} RX_UE_INFORMATION_TAG;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *entries[MAX_ENTRIES];
    int num_entries;
    pthread_mutex_t mutex;
    semaphore_t semaphore;
} CRC_INDICATION_LIST;

void init_crc_indication_list(CRC_INDICATION_LIST *list) {
    list->num_entries = 0;
    pthread_mutex_init(&list->mutex, NULL);
    semaphore_init(&list->semaphore, 1);
}

void add_crc_indication(CRC_INDICATION_LIST *list, RX_UE_INFORMATION_TAG *rx_ue_information) {
    pthread_mutex_lock(&list->mutex);
    semaphore_wait(&list->semaphore);
