// Structure to represent a transaction
typedef struct Transaction {
    int transactionID;
    float amount;
    char currency[3];
    time_t timestamp;
} Transaction;

// Function to populate the transaction list from a CSV file
void populateTransactionList(char *filePath) {
    // Open the CSV file for reading
    FILE *fp = fopen(filePath, "r");
    if (fp == NULL) {
        printf("Error: unable to open file %s\n", filePath);
        return;
    }

    // Create a hash table to store unique transaction IDs
    HashTable *transactionIDs = createHashTable();

    // Read each line of the CSV file and parse it into a Transaction structure
    char line[1024];
    while (fgets(line, sizeof(line), fp) != NULL) {
        // Skip empty lines or comments
        if (strlen(line) == 0 || line[0] == '#') continue;

        // Parse the transaction ID, amount, currency, and timestamp from the line
        int transactionID = atoi(strtok(line, ","));
        float amount = atof(strtok(NULL, ","));
        char *currency = strtok(NULL, ",");
        time_t timestamp = atol(strtok(NULL, ","));

        // Check if the transaction ID is already in the hash table
        if (hashTableContainsKey(transactionIDs, transactionID)) {
            // If it is, skip this transaction and move on to the next one
            continue;
        } else {
            // If not, add it to the hash table and create a new Transaction structure
            HashNode *node = createHashNode(transactionID);
            node->value = malloc(sizeof(Transaction));
            if (node->value == NULL) {
                printf("Error: unable to allocate memory for transaction %d\n", transactionID);
                continue;
            }
            Transaction *transaction = (Transaction *)node->value;
            transaction->transactionID = transactionID;
            transaction->amount = amount;
            strcpy(transaction->currency, currency);
            transaction->timestamp = timestamp;
            hashTableInsert(transactionIDs, node);
        }
    }

    // Close the CSV file and free the hash table
    fclose(fp);
    freeHashTable(transactionIDs);
}

// Function to iterate over the populated transactions without exposing internal implementation details
void iterateOverTransactions(void (*callback)(Transaction *)) {
    HashTableIterator iterator = createHashTableIterator();
    while (hashTableIteratorHasNext(&iterator)) {
        HashNode *node = hashTableIteratorGetNext(&iterator);
        Transaction *transaction = (Transaction *)node->value;
        callback(transaction);
    }
}
