// Define the structure to hold the thread-safe hash table
typedef struct {
    pthread_mutex_t mutex;
    int size;
    int count;
    RequestMetadata** entries;
} HashTable;

// Define the function to initialize the hash table
void initHashTable(HashTable* table) {
    // Initialize the mutex and set the size and count to 0
    pthread_mutex_init(&table->mutex, NULL);
    table->size = HASH_TABLE_SIZE;
    table->count = 0;

    // Allocate memory for the entries array
    table->entries = (RequestMetadata**)malloc(sizeof(RequestMetadata*) * table->size);
    memset(table->entries, 0, sizeof(RequestMetadata*) * table->size);
}

// Define the function to add an entry to the hash table
void addEntryToHashTable(HashTable* table, RequestMetadata* metadata) {
    // Acquire the mutex lock
    pthread_mutex_lock(&table->mutex);

    // Check if the hash table is full
    if (table->count == table->size) {
        // If so, double the size of the hash table
        table->size *= 2;
        RequestMetadata** newEntries = (RequestMetadata**)malloc(sizeof(RequestMetadata*) * table->size);
        memcpy(newEntries, table->entries, sizeof(RequestMetadata*) * table->count);
        free(table->entries);
        table->entries = newEntries;
    }

    // Add the entry to the hash table
    table->entries[table->count++] = metadata;

    // Release the mutex lock
    pthread_mutex_unlock(&table->mutex);
}

// Define the function to remove an entry from the hash table
void removeEntryFromHashTable(HashTable* table, RequestMetadata* metadata) {
    // Acquire the mutex lock
    pthread_mutex_lock(&table->mutex);

    // Find the index of the entry in the hash table
    int i;
    for (i = 0; i < table->count; i++) {
        if (table->entries[i] == metadata) {
            break;
        }
    }

    // If the entry was found, remove it from the hash table
    if (i < table->count) {
        table->count--;
        memmove(table->entries + i, table->entries + i + 1, sizeof(RequestMetadata*) * (table->count - i));
    }

    // Release the mutex lock
    pthread_mutex_unlock(&table->mutex);
}

