#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>

// Define the maximum size of the list
#define MAX_LIST_SIZE 1024

// Define the structure to store CRC indications
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T crc;
} CrcIndication;

// Define a linked list to store the CRC indications
struct LinkedList {
    CrcIndication *data;
    struct LinkedList *next;
};

// Define a mutex for thread safety
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Define a function to add a new CRC indication to the list
void addCrcIndication(NFAPI_CRC_INDICATION_PDU_T crc) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&mutex);

    // Check if the list is full
    if (listSize >= MAX_LIST_SIZE) {
        printf("List is full, cannot add new CRC indication\n");
        return;
    }

    // Create a new node for the CRC indication
    struct LinkedList *newNode = malloc(sizeof(struct LinkedList));
    newNode->data = malloc(sizeof(CrcIndication));
    newNode->next = NULL;

    // Set the data for the new node
    newNode->data->crc = crc;

    // Add the new node to the end of the list
    if (listHead == NULL) {
        listHead = newNode;
    } else {
        struct LinkedList *current = listHead;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = newNode;
    }

    // Increment the size of the list
    listSize++;

    // Unlock the mutex
    pthread_mutex_unlock(&mutex);
}

// Define a function to remove a CRC indication from the list
void removeCrcIndication(NFAPI_CRC_INDICATION_PDU_T crc) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&mutex);

    // Check if the list is empty
    if (listHead == NULL) {
        printf("List is empty, cannot remove CRC indication\n");
        return;
    }

    // Find the node containing the CRC indication to be removed
    struct LinkedList *current = listHead;
    while (current != NULL && current->data->crc != crc) {
        current = current->next;
    }

    // Check if the CRC indication was found
    if (current == NULL) {
        printf("CRC indication not found, cannot remove\n");
        return;
    }

    // Remove the node from the list
    struct LinkedList *previous = current->prev;
    previous->next = current->next;
    free(current);

    // Decrement the size of the list
    listSize--;

    // Unlock the mutex
    pthread_mutex_unlock(&mutex);
}

// Define a function to reset all CRC indications in the list
void resetCrcIndications() {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&mutex);

    // Check if the list is empty
    if (listHead == NULL) {
        printf("List is empty, cannot reset CRC indications\n");
        return;
    }

    // Free all nodes in the list
    struct LinkedList *current = listHead;
    while (current != NULL) {
        struct LinkedList *next = current->next;
        free(current);
        current = next;
    }

    // Reset the list size and head pointer
    listSize = 0;
    listHead = NULL;

    // Unlock the mutex
    pthread_mutex_unlock(&mutex);
}

// Define a function to query the total number of active CRC indications in the list
int getActiveCrcIndications() {
    int count = 0;

    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&mutex);

    // Check if the list is empty
    if (listHead == NULL) {
        printf("List is empty, cannot query active CRC indications\n");
        return count;
    }

    // Count the number of nodes in the list
    struct LinkedList *current = listHead;
    while (current != NULL) {
        count++;
        current = current->next;
    }

    // Unlock the mutex
    pthread_mutex_unlock(&mutex);

    return count;
}
