}

// Decrypt an encrypted message using AES-256-CBC and return the decrypted message
unsigned char *decrypt(const unsigned char *encrypted_message, int encrypted_message_len) {
    // Initialize the AES-256-CBC cipher context if it has not been initialized yet
    init_cipher_context();

    // Decrypt the encrypted message using AES-256-CBC
    EVP_DecryptInit_ex(cipher_context, EVP_aes_256_cbc(), NULL, key, iv);
    int decrypted_message_len = 0;
    unsigned char *decrypted_message = OPENSSL_malloc(encrypted_message_len + AES_BLOCK_SIZE);
    if (decrypted_message == NULL) {
        log_error("Failed to allocate memory for the decrypted message");
    }
    EVP_DecryptUpdate(cipher_context, decrypted_message, &decrypted_message_len, encrypted_message, encrypted_message_len);
    int final_decrypted_message_len = 0;
    EVP_DecryptFinal_ex(cipher_context, decrypted_message + decrypted_message_len, &final_decrypted_message_len);
    decrypted_message_len += final_decrypted_message_len;

    // Return the decrypted message
    return decrypted_message;
}

// Log an error message to the error log buffer
void log_error(const char *format, ...) {
    va_list args;
    va_start(args, format);
    vsnprintf(error_log_buffer, ERROR_LOG_BUFFER_SIZE, format, args);
    va_end(args);
}
