void add_config(node_t **head, const char *url, const char *format, const char *output_file) {
    // Allocate memory for the new node
    node_t *new_node = malloc(sizeof(node_t));
    if (!new_node) {
        fprintf(stderr, "Failed to allocate memory for new configuration setting\n");
        return;
    }

    // Initialize the new node with the given URL, format, and output file
    new_node->config = malloc(sizeof(config_t));
    if (!new_node->config) {
        fprintf(stderr, "Failed to allocate memory for configuration setting\n");
        free(new_node);
        return;
    }
    strcpy(new_node->config->url, url);
    strcpy(new_node->config->format, format);
    strcpy(new_node->config->output_file, output_file);

    // Add the new node to the linked list
    if (*head == NULL) {
        *head = new_node;
    } else {
        node_t *current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }
}

// Define the function to retrieve a configuration setting from the linked list
config_t* get_config(node_t *head, const char *url) {
    // Iterate through the linked list until we find the matching URL
    while (head != NULL) {
        if (strcmp(head->config->url, url) == 0) {
            return head->config;
        }
        head = head->next;
    }
    return NULL;
}

