    // Iterate through the linked list until we find the matching URL
    while (*head != NULL) {
        if (strcmp((*head)->config->url, url) == 0) {
            node_t *current = *head;
            *head = current->next;
            free(current);
            return;
        }
        head = &(*head)->next;
    }
}

