#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <pthread.h>

#define MAX_CHUNK_SIZE 1048576 // 1MB
#define MAX_LOG_SIZE 1048576 // 1MB

// Struct to hold information about a file chunk
struct file_chunk {
    char* data;
    size_t size;
};

// Struct to hold information about a line in the input file
struct line {
    char* data;
    size_t length;
};

// Function to read a file into chunks
void read_file(const char* filename, struct file_chunk** chunks) {
    int fd = open(filename, O_RDONLY);
    if (fd == -1) {
        perror("Error opening input file");
        exit(EXIT_FAILURE);
    }

    // Get the size of the file
    struct stat st;
    fstat(fd, &st);
    off_t filesize = st.st_size;

    // Read the file in chunks
    size_t chunk_size = MAX_CHUNK_SIZE;
    size_t num_chunks = (filesize + chunk_size - 1) / chunk_size;
    struct file_chunk* chunk = malloc(sizeof(struct file_chunk) * num_chunks);
    for (int i = 0; i < num_chunks; i++) {
        chunk[i].data = malloc(chunk_size);
        chunk[i].size = read(fd, chunk[i].data, chunk_size);
        if (chunk[i].size == -1) {
            perror("Error reading input file");
            exit(EXIT_FAILURE);
        }
    }

    // Close the file descriptor
    close(fd);

    *chunks = chunk;
}

// Function to process a line of text and count the number of words
void process_line(struct line* line, int* num_words) {
    char* data = line->data;
    size_t length = line->length;

    // Count the number of words in the line
    *num_words += 1;

    // Skip leading whitespace
    while (isspace(*data)) {
        data++;
        length--;
    }

    // Skip trailing whitespace
    while (length > 0 && isspace(data[length - 1])) {
        length--;
    }

    // Count the number of words in the line
    for (int i = 0; i < length; i++) {
        if (!isspace(data[i])) {
            while (i + 1 < length && !isspace(data[i + 1])) {
                i++;
            }
            *num_words += 1;
        }
    }
}

// Function to process a file chunk and count the number of words
void process_chunk(struct file_chunk* chunk, int* num_words) {
    char* data = chunk->data;
    size_t length = chunk->size;

    // Process each line in the chunk
    while (length > 0) {
        struct line line;
        line.data = data;
        line.length = length;
        process_line(&line, num_words);

        // Skip to the next line
        while (length > 0 && *data != '\n') {
            data++;
            length--;
        }
        if (length > 0) {
            data++;
            length--;
        }
    }
}

// Function to count the number of words in an input file
void count_words(const char* filename, int* num_words) {
    // Read the file into chunks
    struct file_chunk* chunks = NULL;
    read_file(filename, &chunks);

    // Process each chunk
    for (int i = 0; i < num_chunks; i++) {
        process_chunk(&chunks[i], num_words);
    }

    // Free the chunks
    free(chunks);
}

// Function to print a summary of the number of words in an input file
void print_summary(const char* filename, int num_words) {
    printf("File: %s\n", filename);
    printf("Number of words: %d\n", num_words);
}

// Function to handle command line arguments and call the appropriate functions
int main(int argc, char** argv) {
    // Check for invalid command line arguments
    if (argc < 2) {
        printf("Usage: %s [options] input_file\n", argv[0]);
        return EXIT_FAILURE;
    }

    // Parse the command line options
    int option_index = 1;
    while (option_index < argc && strcmp(argv[option_index], "--") != 0) {
        if (strcmp(argv[option_index], "-cs") == 0) {
            // Count the number of words in each line and print a summary at the end
            int num_words = 0;
            for (int i = 1; i < argc; i++) {
                count_words(argv[i], &num_words);
            }
            printf("Total number of words: %d\n", num_words);
        } else if (strcmp(argv[option_index], "-o") == 0) {
            // Redirect the output to a specified file
            if (argc - option_index < 2) {
                printf("Error: missing output file\n");
                return EXIT_FAILURE;
            }
            const char* output_file = argv[option_index + 1];
            FILE* out = fopen(output_file, "w");
            if (out == NULL) {
                perror("Error opening output file");
                return EXIT_FAILURE;
            }
            for (int i = 1; i < argc; i++) {
                count_words(argv[i], &num_words);
                fprintf(out, "File: %s\n", argv[i]);
                fprintf(out, "Number of words: %d\n", num_words);
            }
            fclose(out);
        } else {
            // Display comprehensive documentation
            printf("Usage: %s [options] input_file\n", argv[0]);
            printf("Options:\n");
            printf("  -cs      Count the number of words in each line and print a summary at the end.\n");
            printf("  -o output_file Redirect the output to a specified file instead of the console.\n");
        }
    }

    // Handle missing required options
    if (option_index == argc) {
        printf("Error: missing input file\n");
        return EXIT_FAILURE;
    }

    // Process each input file
    for (int i = option_index; i < argc; i++) {
        int num_words = 0;
        count_words(argv[i], &num_words);
        print_summary(argv[i], num_words);
    }

    return EXIT_SUCCESS;
}
