        } else if (strcmp(argv[i], "-cs") == 0 || strcmp(argv[i], "--count-words") == 0) {
            is_cs_requested = true;
        } else if (strcmp(argv[i], "-o") == 0 || strcmp(argv[i], "--output-file") == 0) {
