        handle_error("Error posting to semaphore");
    }
}

void handle_error(char* message) {
    perror(message);
    exit(EXIT_FAILURE);
}

void log_processing_details(char* details) {
    // Open the log file in append mode
    int log_file = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_file == -1) {
        handle_error("Error opening log file");
    }
    // Write the processing details to the log file
    write(log_file, details, strlen(details));
    // Close the log file
    close(log_file);
}

void cleanup() {
    if (input_filename != NULL) {
        free(input_filename);
    }
    if (output_filename != NULL) {
        free(output_filename);
    }
    if (semaphore != NULL) {
        sem_destroy(semaphore);
        free(semaphore);
