    pthread_mutex_lock(&crc_indication_mutex);

    // Allocate a new NFAPI_CRC_INDICATION_PDU_T structure from the memory pool
    NFAPI_CRC_INDICATION_PDU_T *new_crc = (NFAPI_CRC_INDICATION_PDU_T *) malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_crc) {
        // Handle out-of-memory condition
        pthread_mutex_unlock(&crc_indication_mutex);
        return;
    }

    // Initialize the new CRC indication structure
    new_crc->rx_ue_information_tag = rx_ue_information_tag;
    new_crc->rnti = rnti;
    new_crc->crcflag = crcflag;

    // Add the new CRC indication to the list of active CRCs
    num_active_crcs++;
    if (num_active_crcs > 1) {
        // Wake up any threads waiting on new CRC indications
        pthread_cond_broadcast(&new_crc_indication_cv);
    }

    // Unlock the mutex for protecting concurrent access to the list of CRC indications
    pthread_mutex_unlock(&crc_indication_mutex);
}

// Define the function to remove a CRC indication from the list
void remove_crc_indication(uint16_t rx_ue_information_tag, uint32_t rnti) {
    // Lock the mutex for protecting concurrent access to the list of CRC indications
    pthread_mutex_lock(&crc_indication_mutex);

    // Find the CRC indication with the specified RX UE information tag and RNTI
    NFAPI_CRC_INDICATION_PDU_T *crc = NULL;
    for (size_t i = 0; i < num_active_crcs; i++) {
        if (crc_indications[i].rx_ue_information_tag == rx_ue_information_tag && crc_indications[i].rnti == rnti) {
            crc = &crc_indications[i];
            break;
        }
    }

    // If the CRC indication was found, remove it from the list of active CRCs
    if (crc) {
        num_active_crcs--;
        if (num_active_crcs > 0) {
            // Move the last element in the list to the position of the removed CRC indication
            NFAPI_CRC_INDICATION_PDU_T *last_crc = &crc_indications[num_active_crcs - 1];
            memcpy(crc, last_crc, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        }
    }

    // Unlock the mutex for protecting concurrent access to the list of CRC indications
    pthread_mutex_unlock(&crc_indication_mutex);
}

// Define the function to reset all CRC indications in the list
void reset_crc_indications() {
    // Lock the mutex for protecting concurrent access to the list of CRC indications
    pthread_mutex_lock(&crc_indication_mutex);

    // Reset the number of active CRCs to 0
    num_active_crcs = 0;

    // Unlock the mutex for protecting concurrent access to the list of CRC indications
    pthread_mutex_unlock(&crc_indication_mutex);
}

