#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <semaphore.h>

// Define the maximum number of entries in the list
#define MAX_ENTRIES 1024

// Define the maximum duration for the last processed RNTI window (in seconds)
#define LAST_PROCESSED_RNTI_WINDOW 5

// Define the minimum age threshold for cleaning up old entries (in seconds)
#define MIN_AGE_THRESHOLD 300

// Define the maximum memory footprint for the list (in bytes)
#define MAX_MEMORY_FOOTPRINT 1048576

// Define the thread-safe mutex and semaphore for protecting the list
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
semaphore_t semaphore = SEMAPHORE_INITIALIZER;

// Define the structure to hold the NFAPI_CRC_INDICATION_PDU_T data
typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_information_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the list to hold the NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T *list = NULL;

// Define the function to add a new entry to the list
void add_entry(RX_UE_INFORMATION_TAG rx_ue_information_tag, RNTI rnti, CRC_INDICATION_REL8_TAG crc_indication_rel8_tag) {
    // Acquire the mutex to protect the list
    pthread_mutex_lock(&mutex);

    // Check if the list is full
    if (list == NULL || count >= MAX_ENTRIES) {
        // If the list is full, clean up old entries first
        cleanup_old_entries();
    }

    // Allocate memory for the new entry
    NFAPI_CRC_INDICATION_PDU_T *new_entry = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_entry == NULL) {
        // Log an error message and return if memory allocation fails
        printf("Error: Failed to allocate memory for new entry\n");
        pthread_mutex_unlock(&mutex);
        return;
    }

    // Initialize the new entry with the given data
    new_entry->rx_ue_information_tag = rx_ue_information_tag;
    new_entry->rnti = rnti;
    new_entry->crc_indication_rel8_tag = crc_indication_rel8_tag;

    // Add the new entry to the list
    if (list == NULL) {
        list = new_entry;
    } else {
        NFAPI_CRC_INDICATION_PDU_T *current = list;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_entry;
    }

    // Release the mutex and signal the semaphore to wake up any waiting threads
    pthread_mutex_unlock(&mutex);
    semaphore_post(&semaphore);
}

// Define the function to update an existing entry in the list
void update_entry(RX_UE_INFORMATION_TAG rx_ue_information_tag, RNTI rnti, CRC_INDICATION_REL8_TAG crc_indication_rel8_tag) {
    // Acquire the mutex to protect the list
    pthread_mutex_lock(&mutex);

    // Find the entry with the matching RNTI value
    NFAPI_CRC_INDICATION_PDU_T *current = list;
    while (current != NULL && current->rnti != rnti) {
        current = current->next;
    }

    // If the entry was found, update its data
    if (current != NULL) {
        current->rx_ue_information_tag = rx_ue_information_tag;
        current->crc_indication_rel8_tag = crc_indication_rel8_tag;
    } else {
        // Log an error message if the entry was not found
        printf("Error: Failed to find entry with RNTI value %d\n", rnti);
    }

    // Release the mutex and signal the semaphore to wake up any waiting threads
    pthread_mutex_unlock(&mutex);
    semaphore_post(&semaphore);
}

// Define the function to remove an entry from the list
void remove_entry(RNTI rnti) {
    // Acquire the mutex to protect the list
    pthread_mutex_lock(&mutex);

    // Find the entry with the matching RNTI value
    NFAPI_CRC_INDICATION_PDU_T *current = list;
    while (current != NULL && current->rnti != rnti) {
        current = current->next;
    }

    // If the entry was found, remove it from the list
    if (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T *previous = current->prev;
        if (previous == NULL) {
            list = current->next;
        } else {
            previous->next = current->next;
        }
        free(current);
    } else {
        // Log an error message if the entry was not found
        printf("Error: Failed to find entry with RNTI value %d\n", rnti);
    }

    // Release the mutex and signal the semaphore to wake up any waiting threads
    pthread_mutex_unlock(&mutex);
    semaphore_post(&semaphore);
}

// Define the function to clean up old entries in the list
void cleanup_old_entries() {
    // Acquire the mutex to protect the list
