    // If the oldest entry is older than the minimum age threshold, remove it from the list
    if (current != NULL && current->age > MIN_AGE_THRESHOLD) {
        NFAPI_CRC_INDICATION_PDU_T *previous = current->prev;
        if (previous == NULL) {
            list = current->next;
        } else {
            previous->next = current->next;
