// Custom memory pool for efficient memory allocation and deallocation
struct MemoryPool {
    void* buffer;
    size_t capacity;
    size_t used;
};

void initMemoryPool(struct MemoryPool* pool, size_t capacity) {
    pool->buffer = malloc(capacity);
    if (!pool->buffer) {
        fprintf(stderr, "Error: Failed to allocate memory for the memory pool\n");
        exit(EXIT_FAILURE);
    }
    pool->capacity = capacity;
    pool->used = 0;
}

void* allocMemory(struct MemoryPool* pool, size_t size) {
    if (pool->used + size > pool->capacity) {
        fprintf(stderr, "Error: Out of memory in the memory pool\n");
        exit(EXIT_FAILURE);
    }
    void* ptr = pool->buffer + pool->used;
    pool->used += size;
    return ptr;
}

void freeMemory(struct MemoryPool* pool, void* ptr) {
    // Do nothing for now
}

// Custom memory pool for efficient memory allocation and deallocation

// Function to process a potentially large text file containing a mix of integers and strings
int processFile(const char* filename) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        fprintf(stderr, "Error: Failed to open the file %s\n", filename);
        return EXIT_FAILURE;
    }

    // Initialize a memory pool for efficient memory allocation and deallocation
    struct MemoryPool pool;
    initMemoryPool(&pool, 1024 * 1024); // 1 MB

    // Array to store the valid integer values
    int* integers = NULL;
    size_t numIntegers = 0;

    char line[1024];
    while (fgets(line, sizeof(line), file)) {
        // Check if the line starts with an integer followed by whitespace
        if (sscanf(line, "%d%*s", &integers[numIntegers]) != 1) {
            fprintf(stderr, "Error: Invalid line %s\n", line);
            return EXIT_FAILURE;
        }
        numIntegers++;
    }

    // Calculate the product of the valid integer values using a helper function
    int product = calculateProduct(integers, numIntegers);

    // Print the product
    printf("The product is %d\n", product);

    // Save the processed integers to disk periodically to prevent data loss in case of a crash
    saveProcessedIntegersToDisk(&pool, integers, numIntegers);

    // Clean up memory
    free(integers);
    freeMemory(&pool, pool.buffer);
    fclose(file);

    return EXIT_SUCCESS;
}

// Helper function to calculate the product of a list of integers
int calculateProduct(const int* integers, size_t numIntegers) {
    int product = 1;
    for (size_t i = 0; i < numIntegers; i++) {
        if (integers[i] > INT_MAX || integers[i] < INT_MIN) {
            fprintf(stderr, "Error: Integer overflow during multiplication\n");
            return EXIT_FAILURE;
        }
        product *= integers[i];
    }
    return product;
}

// Function to save the processed integers to disk periodically to prevent data loss in case of a crash
void saveProcessedIntegersToDisk(struct MemoryPool* pool, const int* integers, size_t numIntegers) {
    FILE* file = fopen("processed_integers.bin", "wb");
    if (!file) {
        fprintf(stderr, "Error: Failed to open the file for writing\n");
        return;
    }

    // Write the number of integers to the file
    size_t numWritten = fwrite(&numIntegers, sizeof(size_t), 1, file);
    if (numWritten != 1) {
        fprintf(stderr, "Error: Failed to write the number of integers to the file\n");
        return;
    }

    // Write the integers to the file
    numWritten = fwrite(integers, sizeof(int), numIntegers, file);
    if (numWritten != numIntegers) {
        fprintf(stderr, "Error: Failed to write all the integers to the file\n");
        return;
    }

    // Close the file
    fclose(file);
}
