#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <unistd.h>
#include <errno.h>
#include <pthread.h>

#define MAX_DEVICES 10000
#define MAX_METRICS 100000
#define METRIC_BUFFER_SIZE 1024
#define LOG_BUFFER_SIZE 512
#define DEFAULT_SAMPLING_INTERVAL 1000 // in milliseconds
#define DEFAULT_AGGREGATION_INTERVAL 60 // in seconds
#define DEFAULT_BUFFER_SIZE 10000
#define DEFAULT_LOG_LEVEL 3
#define DEFAULT_LOG_DESTINATION "./network_stats.log"

typedef struct {
    int device_id;
    char* ip_address;
    unsigned short port;
} DeviceInfo;

typedef struct {
    int metric_id;
    char* metric_name;
    double value;
} Metric;

typedef struct {
    int device_count;
    DeviceInfo devices[MAX_DEVICES];
    int metric_count;
    Metric metrics[MAX_METRICS];
} NetworkStats;

void init_network_stats(NetworkStats* stats) {
    // Initialize the network statistics structure
    stats->device_count = 0;
    stats->metric_count = 0;
}

void add_device(NetworkStats* stats, int device_id, char* ip_address, unsigned short port) {
    // Add a new device to the network statistics structure
    if (stats->device_count < MAX_DEVICES) {
        stats->devices[stats->device_count].device_id = device_id;
        stats->devices[stats->device_count].ip_address = ip_address;
        stats->devices[stats->device_count].port = port;
        stats->device_count++;
    } else {
        printf("Maximum number of devices reached\n");
    }
}

void add_metric(NetworkStats* stats, int device_id, char* metric_name, double value) {
    // Add a new metric to the network statistics structure
    if (stats->device_count > 0 && stats->metric_count < MAX_METRICS) {
        for (int i = 0; i < stats->device_count; i++) {
            if (stats->devices[i].device_id == device_id) {
                stats->metrics[stats->metric_count].metric_id = stats->metric_count;
                stats->metrics[stats->metric_count].metric_name = metric_name;
                stats->metrics[stats->metric_count].value = value;
                stats->metric_count++;
                break;
            }
        }
    } else {
        printf("Maximum number of metrics reached\n");
    }
}

void update_network_stats(NetworkStats* stats) {
    // Update the network statistics structure with new data
    for (int i = 0; i < stats->device_count; i++) {
        DeviceInfo device = stats->devices[i];
        int sockfd = socket(AF_INET, SOCK_STREAM, 0);
        if (sockfd == -1) {
            printf("Socket creation failed\n");
            continue;
        }
        struct sockaddr_in serv_addr;
        memset(&serv_addr, '0', sizeof(serv_addr));
        serv_addr.sin_family = AF_INET;
        serv_addr.sin_port = htons(device.port);
        if (inet_pton(AF_INET, device.ip_address, &serv_addr.sin_addr) <= 0) {
            printf("Invalid address\n");
            close(sockfd);
            continue;
        }
        if (connect(sockfd, (struct sockaddr*)&serv_addr, sizeof(serv_addr)) < 0) {
            printf("Connection failed\n");
            close(sockfd);
            continue;
        }
        char buffer[METRIC_BUFFER_SIZE];
        memset(buffer, '0', METRIC_BUFFER_SIZE);
        int bytes_received = recv(sockfd, buffer, METRIC_BUFFER_SIZE, 0);
        if (bytes_received < 0) {
            printf("Recv failed\n");
            close(sockfd);
            continue;
        }
        char* token = strtok(buffer, " ");
        while (token != NULL) {
            add_metric(stats, device.device_id, token, atof(token));
            token = strtok(NULL, " ");
        }
        close(sockfd);
    }
}

void print_network_stats(NetworkStats* stats) {
    // Print the network statistics structure to the console
    for (int i = 0; i < stats->device_count; i++) {
        DeviceInfo device = stats->devices[i];
        printf("Device %d: %s:%hu\n", device.device_id, device.ip_address, device.port);
        for (int j = 0; j < stats->metric_count; j++) {
            Metric metric = stats->metrics[j];
            if (metric.device_id == device.device_id) {
                printf("\t%s: %f\n", metric.metric_name, metric.value);
            }
        }
    }
}

void log_network_stats(NetworkStats* stats, char* message) {
    // Log the network statistics structure to a file
    FILE* fp = fopen("./network_stats.log", "a");
    if (fp == NULL) {
        printf("Error opening log file\n");
        return;
    }
    for (int i = 0; i < stats->device_count; i++) {
        DeviceInfo device = stats->devices[i];
        fprintf(fp, "Device %d: %s:%hu\n", device.device_id, device.ip_address, device.port);
        for (int j = 0; j < stats->metric_count; j++) {
            Metric metric = stats->metrics[j];
            if (metric.device_id == device.device_id) {
                fprintf(fp, "\t%s: %f\n", metric.metric_name, metric.value);
            }
        }
    }
    fclose(fp);
}

void* network_stats_thread(void* args) {
    // Thread function for collecting and processing network statistics
    NetworkStats stats;
    init_network_stats(&stats);
    while (1) {
        update_network_stats(&stats);
        print_network_stats(&stats);
        log_network_stats(&stats, "Network Statistics");
        sleep(DEFAULT_SAMPLING_INTERVAL);
    }
}

int main() {
    // Main function for the network statistics module
    NetworkStats stats;
    init_network_stats(&stats);
    add_device(&stats, 1, "192.168.0.1", 5000);
    add_device(&stats, 2, "192.168.0.2", 5000);
    add_metric(&stats, 1, "byte_count", 1000);
    add_metric(&stats, 1, "packet_count", 10);
    add_metric(&stats, 2, "byte_count", 500);
    add_metric(&stats, 2, "packet_count", 5);
    pthread_t thread;
    pthread_create(&thread, NULL, network_stats_thread, &stats);
    return 0;
}
