static NFAPI_CRC_INDICATION_PDU_T *crc_indication_pool = NULL;

// Define the size of the memory pool
#define MEMORY_POOL_SIZE 1024 * 1024 * 16 // 16 MB

// Define the growth strategy for the memory pool
#define MEMORY_POOL_GROWTH_STRATEGY 2 // Double the size of the pool when it runs out of space

// Define the maximum capacity of the memory pool
#define MEMORY_POOL_MAX_CAPACITY 1024 * 1024 * 32 // 32 MB

// Define the mutex for protecting concurrent access to the list of CRC indications
static pthread_mutex_t crc_indication_list_mutex = PTHREAD_MUTEX_INITIALIZER;

// Define the condition variable for signaling when a new CRC indication is added or removed from the list
static pthread_cond_t crc_indication_list_cv = PTHREAD_COND_INITIALIZER;

// Define the function to add a new CRC indication to the list
void add_crc_indication(uint16_t rx_ue_information_tag, uint32_t rnti, bool crcflag) {
    // Acquire the mutex for protecting concurrent access to the list of CRC indications
    pthread_mutex_lock(&crc_indication_list_mutex);

    // Check if there is enough space in the memory pool for a new CRC indication structure
    if (num_active_crcs >= MEMORY_POOL_SIZE / sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        // If not, double the size of the memory pool and reallocate the list of CRC indications
        crc_indication_pool = realloc(crc_indication_pool, MEMORY_POOL_SIZE *= 2);
    }

    // Allocate a new CRC indication structure from the memory pool
    NFAPI_CRC_INDICATION_PDU_T *new_crc = crc_indication_pool + num_active_crcs;

    // Initialize the fields of the new CRC indication structure
    new_crc->rx_ue_information_tag = rx_ue_information_tag;
    new_crc->rnti = rnti;
    new_crc->crcflag = crcflag;

    // Add the new CRC indication to the list of active CRCs
    num_active_crcs++;

    // Signal any threads waiting for a new CRC indication to wake up and check the list of active CRCs
    pthread_cond_broadcast(&crc_indication_list_cv);

    // Release the mutex for protecting concurrent access to the list of CRC indications
    pthread_mutex_unlock(&crc_indication_list_mutex);
}

// Define the function to remove a CRC indication from the list
void remove_crc_indication(uint16_t rx_ue_information_tag, uint32_t rnti) {
    // Acquire the mutex for protecting concurrent access to the list of CRC indications
    pthread_mutex_lock(&crc_indication_list_mutex);

    // Find the index of the CRC indication with the specified RX UE information tag and RNTI in the list of active CRCs
    size_t i = 0;
    for (i = 0; i < num_active_crcs; i++) {
        if (crc_indications[i].rx_ue_information_tag == rx_ue_information_tag && crc_indications[i].rnti == rnti) {
            break;
        }
    }

    // If the CRC indication was found, remove it from the list of active CRCs and free its memory
    if (i < num_active_crcs) {
        NFAPI_CRC_INDICATION_PDU_T *removed_crc = crc_indications + i;
        memmove(removed_crc, removed_crc + 1, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (num_active_crcs - i));
        num_active_crcs--;
        free(removed_crc);
    }

    // Signal any threads waiting for a new CRC indication to wake up and check the list of active CRCs
    pthread_cond_broadcast(&crc_indication_list_cv);

    // Release the mutex for protecting concurrent access to the list of CRC indications
    pthread_mutex_unlock(&crc_indication_list_mutex);
}

