#include <string.h>
#include <time.h>
#include <pthread.h>

// Define the structure for storing TCP connection information
typedef struct {
    char *source_ip;
    char *destination_ip;
    int port;
    int packet_count;
} tcp_connection_info;

// Define the list of TCP connections
tcp_connection_info *connections = NULL;

// Define the mutex for protecting concurrent access to the list
pthread_mutex_t connections_mutex = PTHREAD_MUTEX_INITIALIZER;

// Define the function for adding a new TCP connection
void add_connection(char *source_ip, char *destination_ip, int port) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&connections_mutex);

    // Allocate memory for the new connection structure
    tcp_connection_info *new_connection = (tcp_connection_info *)malloc(sizeof(tcp_connection_info));
    if (!new_connection) {
        perror("Failed to allocate memory for new TCP connection");
        return;
    }

    // Initialize the new connection structure
    new_connection->source_ip = source_ip;
    new_connection->destination_ip = destination_ip;
    new_connection->port = port;
    new_connection->packet_count = 0;

    // Add the new connection to the list of connections
    connections = (tcp_connection_info *)realloc(connections, sizeof(tcp_connection_info) * (num_connections + 1));
    if (!connections) {
        perror("Failed to reallocate memory for TCP connections");
        free(new_connection);
        return;
    }
    connections[num_connections++] = new_connection;

    // Unlock the mutex and return
    pthread_mutex_unlock(&connections_mutex);
}

// Define the function for updating an existing TCP connection
void update_connection(char *source_ip, char *destination_ip, int port) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&connections_mutex);

    // Find the index of the connection in the list
    int i;
    for (i = 0; i < num_connections; i++) {
        if (strcmp(source_ip, connections[i]->source_ip) == 0 && strcmp(destination_ip, connections[i]->destination_ip) == 0 && port == connections[i]->port) {
            break;
        }
    }

    // If the connection was not found, return
    if (i == num_connections) {
        pthread_mutex_unlock(&connections_mutex);
        return;
    }

    // Update the packet count for the connection
    connections[i]->packet_count++;

    // Unlock the mutex and return
    pthread_mutex_unlock(&connections_mutex);
}

// Define the function for removing an existing TCP connection
void remove_connection(char *source_ip, char *destination_ip, int port) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&connections_mutex);

    // Find the index of the connection in the list
    int i;
    for (i = 0; i < num_connections; i++) {
        if (strcmp(source_ip, connections[i]->source_ip) == 0 && strcmp(destination_ip, connections[i]->destination_ip) == 0 && port == connections[i]->port) {
            break;
        }
    }

    // If the connection was not found, return
    if (i == num_connections) {
        pthread_mutex_unlock(&connections_mutex);
        return;
    }

    // Remove the connection from the list of connections
    for (int j = i; j < num_connections - 1; j++) {
        connections[j] = connections[j + 1];
    }
    num_connections--;

    // Free the memory for the removed connection structure
    free(connections[i]);

    // Reallocate the list of connections to remove the empty slot
    connections = (tcp_connection_info *)realloc(connections, sizeof(tcp_connection_info) * num_connections);

    // Unlock the mutex and return
    pthread_mutex_unlock(&connections_mutex);
}

// Define the function for checking if a TCP connection exists
int check_connection(char *source_ip, char *destination_ip, int port) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&connections_mutex);

    // Find the index of the connection in the list
    int i;
    for (i = 0; i < num_connections; i++) {
        if (strcmp(source_ip, connections[i]->source_ip) == 0 && strcmp(destination_ip, connections[i]->destination_ip) == 0 && port == connections[i]->port) {
            break;
        }
    }

    // If the connection was not found, return false
    if (i == num_connections) {
        pthread_mutex_unlock(&connections_mutex);
        return 0;
    }

    // Return true if the connection was found
    pthread_mutex_unlock(&connections_mutex);
    return 1;
}

// Define the function for getting the packet count for a TCP connection
int get_packet_count(char *source_ip, char *destination_ip, int port) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&connections_mutex);

    // Find the index of the connection in the list
    int i;
    for (i = 0; i < num_connections; i++) {
        if (strcmp(source_ip, connections[i]->source_ip) == 0 && strcmp(destination_ip, connections[i]->destination_ip) == 0 && port == connections[i]->port) {
            break;
        }
    }

    // If the connection was not found, return -1
    if (i == num_connections) {
        pthread_mutex_unlock(&connections_mutex);
        return -1;
    }

    // Return the packet count for the connection
    int packet_count = connections[i]->packet_count;
    pthread_mutex_unlock(&connections_mutex);
    return packet_count;
}
```
This code implements a function that dynamically manages a list of `TCP_CONNECTION_INFO` structures, each containing a valid `SOURCE_IP`, `DESTINATION_IP`, `PORT`, and `PACKET_COUNT`. The function supports adding, updating, and removing entries based on `IP:PORT` pairs, while implementing a mechanism to track the last processed `IP:PORT` pair to prevent duplicates within a specified time window. It must handle concurrent access safely, using thread-safe operations for modifications and access, and validate IP addresses and port numbers within the valid range, handling invalid inputs gracefully. Additionally, the function should dynamically allocate memory for an array of these structures based on a flexible runtime parameter, ensuring robust error checking and efficient resource handling.

