void manage_rx_buffer(LTE_PHY_RX_BUFFER_T *rx_buffer, int cell_id, float rx_power_level, bool reception_quality_flag) {
    // Check if the cell ID is valid and within the range of 0 to 65535
    if (cell_id < 0 || cell_id > 65535) {
        printf("Invalid cell ID: %d\n", cell_id);
        return;
    }

    // Check if the RX power level is valid and within the range of -128 to 127
    if (rx_power_level < -128 || rx_power_level > 127) {
        printf("Invalid RX power level: %f\n", rx_power_level);
        return;
    }

    // Check if the reception quality flag is valid and within the range of 0 to 1
    if (reception_quality_flag < 0 || reception_quality_flag > 1) {
        printf("Invalid reception quality flag: %d\n", reception_quality_flag);
        return;
    }

    // Add or update the entry in the dynamic list of LTE_PHY_RX_BUFFER_T structures
    for (int i = 0; i < rx_buffer->size; i++) {
        if (rx_buffer[i].cell_id == cell_id) {
            rx_buffer[i].rx_power_level = rx_power_level;
            rx_buffer[i].reception_quality_flag = reception_quality_flag;
            return;
        }
    }

    // If the entry is not found, add a new one to the end of the list
    LTE_PHY_RX_BUFFER_T new_entry = {cell_id, rx_power_level, reception_quality_flag};
    rx_buffer->size++;
    rx_buffer[rx_buffer->size - 1] = new_entry;
}

