} NFAPI_CRC_INDICATION_PDU_T;

// Define the structure for a connection metadata
typedef struct {
    uint32_t RNTI;
    uint64_t lastProcessedTime;
} CONNECTION_METADATA_T;

// Define the hash table for storing connections
static CONNECTION_METADATA_T *connections = NULL;

// Define the mutex for synchronizing access to the hash table
static pthread_mutex_t connectionsMutex = PTHREAD_MUTEX_INITIALIZER;

// Define the function for adding a new connection
void addConnection(uint32_t RNTI) {
    // Acquire the mutex to prevent concurrent access
    pthread_mutex_lock(&connectionsMutex);

    // Check if the connection already exists in the hash table
    if (connections == NULL || connections[RNTI] != NULL) {
        // If the connection does not exist, create a new entry for it
        connections = realloc(connections, sizeof(CONNECTION_METADATA_T) * (RNTI + 1));
        memset(&connections[RNTI], 0, sizeof(CONNECTION_METADATA_T));
    }

    // Set the last processed time for the connection to the current time
    connections[RNTI].lastProcessedTime = time(NULL);

    // Release the mutex and return
    pthread_mutex_unlock(&connectionsMutex);
}

// Define the function for updating a connection
void updateConnection(uint32_t RNTI) {
    // Acquire the mutex to prevent concurrent access
    pthread_mutex_lock(&connectionsMutex);

    // Check if the connection exists in the hash table
    if (connections == NULL || connections[RNTI] == NULL) {
        // If the connection does not exist, add it
        addConnection(RNTI);
    } else {
        // Set the last processed time for the connection to the current time
        connections[RNTI].lastProcessedTime = time(NULL);
    }

    // Release the mutex and return
    pthread_mutex_unlock(&connectionsMutex);
}

// Define the function for removing a connection
void removeConnection(uint32_t RNTI) {
    // Acquire the mutex to prevent concurrent access
    pthread_mutex_lock(&connectionsMutex);

    // Check if the connection exists in the hash table
    if (connections == NULL || connections[RNTI] == NULL) {
        // If the connection does not exist, do nothing
        return;
    } else {
        // Free the memory for the connection metadata
        free(connections[RNTI]);

        // Remove the connection from the hash table
        connections = realloc(connections, sizeof(CONNECTION_METADATA_T) * (RNTI - 1));
    }

    // Release the mutex and return
    pthread_mutex_unlock(&connectionsMutex);
}

// Define the function for processing a CRC indication PDU
void processCrcIndicationPdu(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    // Acquire the mutex to prevent concurrent access
    pthread_mutex_lock(&connectionsMutex);

    // Check if the connection exists in the hash table
    if (connections == NULL || connections[pdu->RNTI] == NULL) {
        // If the connection does not exist, add it
        addConnection(pdu->RNTI);
    } else {
        // Update the last processed time for the connection
        updateConnection(pdu->RNTI);
    }

    // Release the mutex and return
    pthread_mutex_unlock(&connectionsMutex);
}

// Define the function for periodically pruning inactive connections
void pruneInactiveConnections() {
    // Acquire the mutex to prevent concurrent access
    pthread_mutex_lock(&connectionsMutex);

    // Iterate over all connections and remove any that have not been processed within the specified time window
    for (int i = 0; i < connections->size(); i++) {
        if (connections[i] != NULL && connections[i].lastProcessedTime + TIME_WINDOW <= time(NULL)) {
            removeConnection(i);
        }
    }

    // Release the mutex and return
    pthread_mutex_unlock(&connectionsMutex);
}
