// Define the structure to store NFAPI_CRC_INDICATION_PDU_T data
typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the list to store the dynamic entries
static NFAPI_CRC_INDICATION_PDU_T *list = NULL;

// Define the mutex for thread-safe operations
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Define the function to add a new entry
void addEntry(uint32_t RNTI, uint8_t CRCFLAG) {
    // Lock the mutex before modifying the list
    pthread_mutex_lock(&mutex);

    // Create a new entry and set its values
    NFAPI_CRC_INDICATION_PDU_T *newEntry = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    newEntry->RX_UE_INFORMATION_TAG = 0;
    newEntry->RNTI = RNTI;
    newEntry->CRCFLAG = CRCFLAG;

    // Add the new entry to the list
    if (list == NULL) {
        list = newEntry;
    } else {
        NFAPI_CRC_INDICATION_PDU_T *current = list;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = newEntry;
    }

    // Unlock the mutex after modifying the list
    pthread_mutex_unlock(&mutex);
}

// Define the function to update an existing entry
void updateEntry(uint32_t RNTI, uint8_t CRCFLAG) {
    // Lock the mutex before modifying the list
    pthread_mutex_lock(&mutex);

    // Find the entry with the matching RNTI value
    NFAPI_CRC_INDICATION_PDU_T *current = list;
    while (current != NULL) {
        if (current->RNTI == RNTI) {
            current->CRCFLAG = CRCFLAG;
            break;
        }
        current = current->next;
    }

    // Unlock the mutex after modifying the list
    pthread_mutex_unlock(&mutex);
}

// Define the function to remove an existing entry
void removeEntry(uint32_t RNTI) {
    // Lock the mutex before modifying the list
    pthread_mutex_lock(&mutex);

    // Find the entry with the matching RNTI value
    NFAPI_CRC_INDICATION_PDU_T *current = list;
    while (current != NULL) {
        if (current->RNTI == RNTI) {
            // Remove the entry from the list
            if (current == list) {
                list = current->next;
            } else {
                NFAPI_CRC_INDICATION_PDU_T *previous = list;
                while (previous->next != current) {
                    previous = previous->next;
                }
                previous->next = current->next;
            }
            free(current);
            break;
        }
        current = current->next;
    }

    // Unlock the mutex after modifying the list
    pthread_mutex_unlock(&mutex);
}

// Define the function to check if an entry exists for a given RNTI value
bool entryExists(uint32_t RNTI) {
    // Lock the mutex before accessing the list
    pthread_mutex_lock(&mutex);

    // Find the entry with the matching RNTI value
    NFAPI_CRC_INDICATION_PDU_T *current = list;
    while (current != NULL) {
        if (current->RNTI == RNTI) {
            break;
        }
        current = current->next;
    }

    // Unlock the mutex after accessing the list
    pthread_mutex_unlock(&mutex);

    return current != NULL;
}

// Define the function to retrieve an entry for a given RNTI value
NFAPI_CRC_INDICATION_PDU_T *getEntry(uint32_t RNTI) {
    // Lock the mutex before accessing the list
    pthread_mutex_lock(&mutex);

    // Find the entry with the matching RNTI value
    NFAPI_CRC_INDICATION_PDU_T *current = list;
    while (current != NULL) {
        if (current->RNTI == RNTI) {
            break;
        }
        current = current->next;
    }

    // Unlock the mutex after accessing the list
    pthread_mutex_unlock(&mutex);

    return current;
}

// Define the function to periodically prune inactive connections
void pruneInactiveConnections() {
    // Lock the mutex before modifying the list
    pthread_mutex_lock(&mutex);

    // Find the entry with the oldest timestamp
    NFAPI_CRC_INDICATION_PDU_T *current = list;
    while (current != NULL) {
        if (current->next == NULL || current->timestamp < current->next->timestamp) {
            break;
        }
        current = current->next;
    }

    // Remove the entry from the list
    if (current == list) {
        list = current->next;
    } else {
        NFAPI_CRC_INDICATION_PDU_T *previous = list;
        while (previous->next != current) {
            previous = previous->next;
        }
        previous->next = current->next;
    }
    free(current);

    // Unlock the mutex after modifying the list
    pthread_mutex_unlock(&mutex);
}
