#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <openssl/sha.h>
#include <curl/curl.h>

// Define the maximum length of the filename
#define MAX_FILENAME_LENGTH 256

// Define the maximum length of the modified filename
#define MODIFIED_FILENAME_LENGTH 300

// Define the directory path separator character
#define DIRECTORY_SEPARATOR '/'

// Define the file type indicator characters
#define FILE_TYPE_INDICATOR "."

// Define the checksum algorithm to use
#define CHECKSUM_ALGORITHM SHA256

// Define the metadata service URL
#define METADATA_SERVICE_URL "https://metadata.example.com/file-type"

// Define the maximum number of retries for the metadata service
#define MAX_RETRIES 3

// Define the retry delay in seconds
#define RETRY_DELAY 10

// Define the error message for invalid file names
#define INVALID_FILENAME_ERROR "Invalid filename provided"

// Define the error message for file name too long
#define FILENAME_TOO_LONG_ERROR "Filename too long, maximum length is %d characters"

// Define the error message for metadata service error
#define METADATA_SERVICE_ERROR "Error retrieving file type information from metadata service"

// Function to generate a checksum for a given string
unsigned char* generateChecksum(const unsigned char* str) {
  // Initialize the SHA256 context
  SHA256_CTX ctx;
  SHA256_Init(&ctx);

  // Update the SHA256 context with the given string
  SHA256_Update(&ctx, str, strlen((const char*)str));

  // Finalize the SHA256 hash and return the result
  unsigned char* checksum = (unsigned char*)malloc(SHA256_DIGEST_LENGTH);
  SHA256_Final(checksum, &ctx);
  return checksum;
}

// Function to query the metadata service for file type information
int getFileTypeInfo(const unsigned char* filename, const unsigned char* directory_path) {
  // Initialize the CURL handle
  CURL* curl = curl_easy_init();

  // Set the URL and other options for the metadata service request
  curl_easy_setopt(curl, CURLOPT_URL, METADATA_SERVICE_URL);
  curl_easy_setopt(curl, CURLOPT_POSTFIELDS, filename);
  curl_easy_setopt(curl, CURLOPT_POSTFIELDSIZE, strlen((const char*)filename));
  curl_easy_setopt(curl, CURLOPT_TIMEOUT, RETRY_DELAY * MAX_RETRIES);
  curl_easy_setopt(curl, CURLOPT_CONNECTTIMEOUT, RETRY_DELAY);
  curl_easy_setopt(curl, CURLOPT_NOSIGNAL, 1);
  curl_easy_setopt(curl, CURLOPT_USERAGENT, "File Renamer");

  // Perform the metadata service request and check for errors
  CURLcode res = curl_easy_perform(curl);
  if (res != CURLE_OK) {
    fprintf(stderr, METADATA_SERVICE_ERROR);
    return -1;
  }

  // Extract the file type information from the response
  unsigned char* file_type = NULL;
  curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &file_type);
  if (file_type == NULL) {
    fprintf(stderr, METADATA_SERVICE_ERROR);
    return -1;
  }

  // Clean up the CURL handle and return the file type information
  curl_easy_cleanup(curl);
  return (int)file_type;
}

// Function to modify a filename based on the given configuration
unsigned char* modifyFilename(const unsigned char* filename, const unsigned char* directory_path, const unsigned char* config) {
  // Initialize the modified filename and checksum
  unsigned char* modified_filename = (unsigned char*)malloc(MODIFIED_FILENAME_LENGTH);
  unsigned char* checksum = generateChecksum(filename);

  // Extract the file type information from the metadata service
  int file_type = getFileTypeInfo(filename, directory_path);
  if (file_type == -1) {
    fprintf(stderr, METADATA_SERVICE_ERROR);
    return NULL;
  }

  // Generate the sequence of numbers for the modified filename
  unsigned char* sequence = (unsigned char*)malloc(MAX_FILENAME_LENGTH);
  sprintf((char*)sequence, "%016d", strlen((const char*)filename));

  // Append the sequence of numbers, checksum, and file type indicator to the modified filename
  int length = snprintf((char*)modified_filename, MODIFIED_FILENAME_LENGTH, "%s%s%s%s%s", directory_path, DIRECTORY_SEPARATOR, filename, sequence, FILE_TYPE_INDICATOR);
  if (length >= MODIFIED_FILENAME_LENGTH) {
    fprintf(stderr, FILENAME_TOO_LONG_ERROR, MAX_FILENAME_LENGTH);
    return NULL;
  }

  // Replace spaces in the modified filename with underscores
  for (int i = 0; i < length; i++) {
    if (modified_filename[i] == ' ') {
      modified_filename[i] = '_';
    }
  }

  // Free the memory allocated for the sequence and checksum
  free(sequence);
  free(checksum);

  return modified_filename;
}
