                config_exists = true;
                break;
            }
        }

        // If a web.config file does not exist for the current website, return a null pointer
        if (!config_exists) {
            printf("Website %s has no web.config file\n", domain_name);
            list->entries[i] = NULL;
            continue;
        }

        // Add the website to the list structure and update the cache
        NFAPI_CRC_INDICATION_PDU_T *entry = &list->entries[i];
        entry->rx_ue_information.rnti = i + 1;
        entry->crc_indication_rel8.crflag = rand() % 2;
        cache[i].domain_name = domain_name;
        cache[i].ssl_ctx = ssl_ctx;
        cache[i].last_accessed = time(NULL);
    }

    // Clean up the cache and return the list structure
    for (int i = 0; i < num_websites; i++) {
        if (cache[i].ssl_ctx != NULL) {
            SSL_CTX_free(cache[i].ssl_ctx);
        }
    }
    free(cache);
    return list;
}
