void modifyAndInsert(std::forward_list<std::string>& list, const std::string& filename, const std::string& searchStr1, const std::string& insertStr2) {
    // Get the number of digits to append at the end and the new file type to replace the existing extension
    int numDigits = 0;
    std::string newExt;
    size_t extPos = filename.find_last_of('.');
    if (extPos != std::string::npos) {
        numDigits = filename.size() - extPos - 1;
        newExt = filename.substr(extPos + 1);
    } else {
        // No extension found, use the default number of digits and file type
        numDigits = 3;
        newExt = "txt";
    }

    // Construct a new filename with the modifications
    std::string newFilename = filename.substr(0, extPos);
    newFilename += "." + newExt;
    for (int i = 0; i < numDigits; ++i) {
        newFilename += "0";
    }

    // Perform a case-insensitive search for the first occurrence of the first additional string argument within the forward list
    auto it = std::search(list.begin(), list.end(), searchStr1, [](const std::string& str) { return std::equal(str.begin(), str.end(), searchStr1.begin(), searchStr1.end(), [](char c1, char c2) { return std::tolower(c1) == std::tolower(c2); }); });
    if (it != list.end()) {
        // Insert the second additional string argument right after it
        list.insert_after(it, insertStr2);
    } else {
        // Append the second additional string argument to the end of the list
        list.push_back(insertStr2);
    }
}
