#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    uint16_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct CRC_INDICATION_LIST {
    pthread_mutex_t mutex;
    size_t count;
    NFAPI_CRC_INDICATION_PDU_T *elements;
} CRC_INDICATION_LIST;

void crc_indication_list_add(CRC_INDICATION_LIST *list, uint16_t RX_UE_INFORMATION_TAG, uint32_t RNTI, uint8_t CRCFLAG) {
    pthread_mutex_lock(&list->mutex);
    NFAPI_CRC_INDICATION_PDU_T *element = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    element->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    element->RNTI = RNTI;
    element->CRCFLAG = CRCFLAG;
    list->elements[list->count++] = element;
    pthread_mutex_unlock(&list->mutex);
}

void crc_indication_list_update(CRC_INDICATION_LIST *list, uint32_t RNTI) {
    pthread_mutex_lock(&list->mutex);
    for (size_t i = 0; i < list->count; i++) {
        if (list->elements[i]->RNTI == RNTI) {
            list->elements[i]->CRCFLAG ^= 1;
            break;
        }
    }
    pthread_mutex_unlock(&list->mutex);
}

void crc_indication_list_iterate(CRC_INDICATION_LIST *list, void (*callback)(NFAPI_CRC_INDICATION_PDU_T *)) {
    pthread_mutex_lock(&list->mutex);
    for (size_t i = 0; i < list->count; i++) {
        callback(list->elements[i]);
    }
    pthread_mutex_unlock(&list->mutex);
}

void crc_indication_list_free(CRC_INDICATION_LIST *list) {
    pthread_mutex_lock(&list->mutex);
    for (size_t i = 0; i < list->count; i++) {
        free(list->elements[i]);
    }
    free(list->elements);
    pthread_mutex_unlock(&list->mutex);
}
