} NFAPI_CRC_INDICATION_LIST;

// Define a function to add a new element to the list
bool nfapi_crc_indication_list_add(NFAPI_CRC_INDICATION_LIST *list, uint32_t validRXUEInformationTag, uint16_t rnti, uint8_t crcIndicationRel8Tag) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&list->mutex);

    // Allocate memory for a new element
    NFAPI_CRC_INDICATION_PDU_T *element = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!element) {
        pthread_mutex_unlock(&list->mutex);
        return false;
    }

    // Initialize the new element
    element->validRXUEInformationTag = validRXUEInformationTag;
    element->rnti = rnti;
    element->crcIndicationRel8Tag = crcIndicationRel8Tag;

    // Add the new element to the list
    list->elements[list->count++] = element;

    // Unlock the mutex and return success
    pthread_mutex_unlock(&list->mutex);
    return true;
}

// Define a function to update an existing element in the list based on RNTI
bool nfapi_crc_indication_list_update(NFAPI_CRC_INDICATION_LIST *list, uint16_t rnti, uint8_t crcIndicationRel8Tag) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&list->mutex);

    // Iterate over the list elements and find the one with the matching RNTI
    for (size_t i = 0; i < list->count; i++) {
        if (list->elements[i]->rnti == rnti) {
            // Update the element with the new CRC indication
            list->elements[i]->crcIndicationRel8Tag = crcIndicationRel8Tag;

            // Unlock the mutex and return success
            pthread_mutex_unlock(&list->mutex);
            return true;
        }
    }

    // If no matching element was found, unlock the mutex and return failure
    pthread_mutex_unlock(&list->mutex);
    return false;
}

