bool nfapi_crc_indication_list_process(NFAPI_CRC_INDICATION_LIST *list, void (*process_function)(NFAPI_CRC_INDICATION_PDU_T *)) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&list->mutex);

