int dns_resolve(const char *hostname, struct in_addr **addr) {
    int ret = 0;
    struct hostent *he;
    he = gethostbyname(hostname);
    if (he == NULL) {
        printf("DNS resolution failed for %s\n", hostname);
        return -1;
