int processAndHandleMessages(const char *hostname, int num_messages) {
    struct in_addr **addrs = NULL;
    int i, j;
    NAS_MESSAGE_T *nas_messages = NULL;
    pthread_t thread[num_messages];
    pthread_attr_t attr;
    void *status;

    // Allocate memory for the array of addresses and initialize it to NULL
    addrs = (struct in_addr **)malloc(sizeof(struct in_addr *) * num_messages);
    if (addrs == NULL) {
        printf("Memory allocation failed\n");
        return -1;
    }
    for (i = 0; i < num_messages; i++) {
        addrs[i] = NULL;
    }

    // Allocate memory for the array of NAS messages and initialize it to NULL
    nas_messages = (NAS_MESSAGE_T *)malloc(sizeof(NAS_MESSAGE_T) * num_messages);
    if (nas_messages == NULL) {
        printf("Memory allocation failed\n");
        return -1;
    }
    for (i = 0; i < num_messages; i++) {
        nas_messages[i].rx_ue_information.rnti = 0;
        nas_messages[i].crc_indication.crcflag = 0;
    }

    // Resolve the hostname and populate the array of addresses
    for (i = 0; i < num_messages; i++) {
        if (dns_resolve(hostname, &addrs[i]) != 0) {
            printf("DNS resolution failed for %s\n", hostname);
            return -1;
        }
    }

    // Create and start threads to handle the messages
    pthread_attr_init(&attr);
    pthread_attr_setdetachstate(&attr, PTHREAD_CREATE_JOINABLE);
    for (i = 0; i < num_messages; i++) {
        nas_messages[i].rx_ue_information.rnti = rand();
        nas_messages[i].crc_indication.crcflag = rand() % 2;
        if (pthread_create(&thread[i], &attr, handleMessage, (void *)&nas_messages[i]) != 0) {
            printf("Thread creation failed\n");
            return -1;
        }
    }

    // Wait for all threads to complete and free resources
    for (i = 0; i < num_messages; i++) {
        if (pthread_join(thread[i], &status) != 0) {
            printf("Thread join failed\n");
            return -1;
        }
    }
    pthread_attr_destroy(&attr);

    // Free memory for the array of addresses and the array of NAS messages
    free(addrs);
    free(nas_messages);

    return 0;
}

// Define the function to handle a single message
void *handleMessage(void *arg) {
    NAS_MESSAGE_T *nas_message = (NAS_MESSAGE_T *)arg;
    struct in_addr *addr = nas_message->rx_ue_information.rnti;
    int crcflag = nas_message->crc_indication.crcflag;

    // Handle the message and update the CRC flag if necessary
    if (crcflag == 1) {
        printf("Message received with CRC error\n");
        nas_message->crc_indication.crcflag = 0;
    } else {
        printf("Message received without CRC error\n");
    }

    // Free the memory for the address and return
    free(addr);
    pthread_exit(NULL);
}
