// Define the linked list node structure
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    struct Node *next;
} Node;

// Define the head pointer for the linked list
Node *head = NULL;

// Define the mutex for thread-safe access to the linked list
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to create and populate a linked list of NFAPI_CRC_INDICATION_PDU_T structures
void create_crc_indication_list(int num_nodes) {
    // Allocate memory for the linked list nodes
    Node *node = malloc(sizeof(Node));
    if (node == NULL) {
        printf("Memory allocation failed\n");
        return;
    }

    // Initialize the head pointer to the first node
    head = node;

    // Loop through each node in the linked list
    for (int i = 0; i < num_nodes; i++) {
        // Allocate memory for the NFAPI_CRC_INDICATION_PDU_T structure
        NFAPI_CRC_INDICATION_PDU_T *data = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (data == NULL) {
            printf("Memory allocation failed\n");
            return;
        }

        // Initialize the RX_UE_INFORMATION_TAG and RNTI values for each node
        data->rx_ue_information = malloc(sizeof(RX_UE_INFORMATION_TAG));
        if (data->rx_ue_information == NULL) {
            printf("Memory allocation failed\n");
            return;
        }
        data->rnti = rand() % 1000;

        // Set the CRC flag for each node based on predefined rules derived from the UE information and RNTI values
        if (data->rnti == 5) {
            data->crc_indication_rel8.CRCFlag = 1;
        } else {
            data->crc_indication_rel8.CRCFlag = 0;
        }

        // Add the node to the linked list
        node->data = data;
        node->next = malloc(sizeof(Node));
        if (node->next == NULL) {
            printf("Memory allocation failed\n");
            return;
        }
        node = node->next;
    }
}

// Function to traverse the linked list in both directions
void traverse_list() {
    // Lock the mutex to ensure thread-safe access to the linked list
    pthread_mutex_lock(&mutex);

    // Start at the head node and traverse the linked list in both directions
    Node *node = head;
    while (node != NULL) {
        printf("Node data: %d\n", node->data->rnti);
        node = node->next;
    }

    // Unlock the mutex to release access to the linked list
    pthread_mutex_unlock(&mutex);
}

// Function to clean up the linked list when it is no longer needed
void cleanup_list() {
    // Lock the mutex to ensure thread-safe access to the linked list
    pthread_mutex_lock(&mutex);

    // Start at the head node and traverse the linked list in both directions, freeing each node as we go
    Node *node = head;
    while (node != NULL) {
        Node *next = node->next;
        free(node->data);
        free(node);
        node = next;
    }

    // Unlock the mutex to release access to the linked list
    pthread_mutex_unlock(&mutex);
}
