// Define the function to create a new node in the linked list
PHY_CONTEXT_T* phy_context_create(int tx_streams, int rx_streams, int mcs) {
    // Allocate memory for the new node
    PHY_CONTEXT_T *node = malloc(sizeof(PHY_CONTEXT_T));
    if (node == NULL) {
        printf("Error: Failed to allocate memory for a new node in the linked list\n");
        return NULL;
    }

    // Initialize the fields of the new node
    node->tx_streams = tx_streams;
    node->rx_streams = rx_streams;
    node->mcs = mcs;
    node->next = NULL;
    node->prev = NULL;

    // Log the creation of the new node for debugging and auditing purposes
    printf("Created a new node in the linked list with TX streams: %d, RX streams: %d, MCS: %d\n", tx_streams, rx_streams, mcs);

    return node;
}

// Define the function to add a new node to the end of the linked list
void phy_context_add(PHY_CONTEXT_T *node) {
    // Check if the linked list is empty
    if (phy_context_head == NULL) {
        phy_context_head = node;
        return;
    }

    // Traverse the linked list to find the last node
    PHY_CONTEXT_T *current = phy_context_head;
    while (current->next != NULL) {
        current = current->next;
    }

    // Add the new node to the end of the linked list
    current->next = node;
    node->prev = current;
}

// Define the function to remove a node from the linked list
void phy_context_remove(PHY_CONTEXT_T *node) {
    // Check if the linked list is empty
    if (phy_context_head == NULL) {
        return;
    }

    // Traverse the linked list to find the node to be removed
    PHY_CONTEXT_T *current = phy_context_head;
    while (current != NULL && current->next != node) {
        current = current->next;
    }

    // Remove the node from the linked list
    if (current == NULL) {
        return;
    }
    current->prev->next = current->next;
    current->next->prev = current->prev;
}

// Define the function to traverse the linked list in both directions
void phy_context_traverse(PHY_CONTEXT_T *node) {
    // Check if the linked list is empty
    if (phy_context_head == NULL) {
        return;
    }

    // Traverse the linked list in both directions
    PHY_CONTEXT_T *current = phy_context_head;
    while (current != NULL) {
        printf("Node: TX streams: %d, RX streams: %d, MCS: %d\n", current->tx_streams, current->rx_streams, current->mcs);
        current = current->next;
    }
}

// Define the function to clean up the linked list when it is no longer needed
void phy_context_cleanup() {
    // Check if the linked list is empty
    if (phy_context_head == NULL) {
        return;
    }

    // Traverse the linked list and free each node
    PHY_CONTEXT_T *current = phy_context_head;
    while (current != NULL) {
        PHY_CONTEXT_T *next = current->next;
        free(current);
        current = next;
    }
}

// Define the function to handle dynamic changes to the stream configurations
void phy_context_update(int tx_streams, int rx_streams, int mcs) {
    // Check if the linked list is empty
    if (phy_context_head == NULL) {
        return;
    }

    // Traverse the linked list and update each node with the new stream configurations
    PHY_CONTEXT_T *current = phy_context_head;
    while (current != NULL) {
        current->tx_streams = tx_streams;
        current->rx_streams = rx_streams;
        current->mcs = mcs;
        current = current->next;
    }
}
