// Define the list of LTE packets
LTE_Packet* lte_packets = NULL;

// Define the maximum number of elements in the list
int max_elements = 0;

// Define the current number of elements in the list
int num_elements = 0;

// Define the mutex for synchronizing access to the list
pthread_mutex_t lte_packets_mutex = PTHREAD_MUTEX_INITIALIZER;

// Define the condition variable for signaling when a new element is added to the list
pthread_cond_t lte_packets_cv = PTHREAD_COND_INITIALIZER;

// Define the function for managing the creation, population, and serialization of the list of LTE packets
int manage_lte_packets(int max_elements) {
    // Check if the maximum number of elements is valid
    if (max_elements <= 0) {
        return -1;
    }

    // Allocate memory for the list of LTE packets
    lte_packets = malloc(sizeof(LTE_Packet) * max_elements);
    if (!lte_packets) {
        fprintf(stderr, "Failed to allocate memory for the list of LTE packets: %s\n", strerror(errno));
        return -1;
    }

    // Initialize the mutex and condition variable for synchronizing access to the list
    pthread_mutex_init(&lte_packets_mutex, NULL);
    pthread_cond_init(&lte_packets_cv, NULL);

    // Set the maximum number of elements in the list
    max_elements = max_elements;

    return 0;
}

// Define the function for adding a new LTE packet to the list
int add_lte_packet(LTE_Packet* lte_packet) {
    // Check if the list is full
    if (num_elements == max_elements) {
        return -1;
    }

    // Lock the mutex for synchronizing access to the list
    pthread_mutex_lock(&lte_packets_mutex);

    // Copy the new LTE packet into the list
    memcpy(lte_packets[num_elements], lte_packet, sizeof(LTE_Packet));

    // Increment the number of elements in the list
    num_elements++;

    // Signal the condition variable to wake up any threads waiting for a new element to be added to the list
    pthread_cond_signal(&lte_packets_cv);

    // Unlock the mutex
    pthread_mutex_unlock(&lte_packets_mutex);

    return 0;
}

// Define the function for serializing the list of LTE packets
int serialize_lte_packets(char* buffer, int size) {
    // Check if the buffer is large enough to hold all the LTE packets
    if (size < num_elements * sizeof(LTE_Packet)) {
        return -1;
    }

    // Lock the mutex for synchronizing access to the list
    pthread_mutex_lock(&lte_packets_mutex);

    // Serialize each LTE packet in the list into the buffer
    for (int i = 0; i < num_elements; i++) {
        memcpy(buffer + i * sizeof(LTE_Packet), lte_packets[i], sizeof(LTE_Packet));
    }

    // Unlock the mutex
    pthread_mutex_unlock(&lte_packets_mutex);

    return 0;
}

// Define the function for deserializing a list of LTE packets from a buffer
int deserialize_lte_packets(char* buffer, int size) {
    // Check if the buffer is large enough to hold all the LTE packets
    if (size < num_elements * sizeof(LTE_Packet)) {
        return -1;
    }

    // Lock the mutex for synchronizing access to the list
    pthread_mutex_lock(&lte_packets_mutex);

    // Deserialize each LTE packet in the buffer into the list
    for (int i = 0; i < num_elements; i++) {
        memcpy(lte_packets[i], buffer + i * sizeof(LTE_Packet), sizeof(LTE_Packet));
    }

    // Unlock the mutex
    pthread_mutex_unlock(&lte_packets_mutex);

    return 0;
}

// Define the function for handling a new incoming LTE packet
void handle_new_lte_packet(LTE_Packet* lte_packet) {
    // Add the new LTE packet to the list
    add_lte_packet(lte_packet);
}

// Define the function for handling a buffer of incoming LTE packets
void handle_buffer_of_lte_packets(char* buffer, int size) {
    // Deserialize the buffer into a list of LTE packets
    deserialize_lte_packets(buffer, size);

