        generate_checksum(updated_filename, &checksum_ctx);

        // Verify the checksum of the file
        int result = verify_checksum(updated_filename, &checksum_ctx);
        if (result == -1) {
            continue;
        }

        // Free the updated filename and checksum context
        free(updated_filename);
    }
}
