void processAndEnhance(std::vector<int>& vec, int target, const std::string& command) {
    // Parse the command string to determine the type of operation
    if (command == "find-and-replace") {
        // Search for the first occurrence of the target integer within the vector
        auto it = std::find(vec.begin(), vec.end(), target);
        if (it != vec.end()) {
            // Replace the found element with a new integer derived from the base integer and modifier
            int new_value = getNewValue(target, command);
            *it = new_value;
        } else {
            std::cout << "Target integer not found in vector" << std::endl;
        }
    } else if (command == "insert") {
        // Find the position where the target integer would fit in a sorted order of the vector using binary search
        auto it = std::lower_bound(vec.begin(), vec.end(), target);
        if (it != vec.end()) {
            // Insert the new integer at the found position
            int new_value = getNewValue(target, command);
            vec.insert(it, new_value);
        } else {
            std::cout << "Target integer not found in vector" << std::endl;
        }
    } else {
        std::cout << "Invalid command: " << command << std::endl;
    }
}

int getNewValue(int target, const std::string& command) {
    // Derive the new integer value from the base integer and modifier provided in the command string
    int base = std::stoi(command.substr(0, command.find('-')));
    int modifier = std::stoi(command.substr(command.find('-') + 1));
    return base * modifier;
}
