// Define the structure for storing node connection information
typedef struct {
    uint64_t macentityid;
    uint32_t preamble_seq;
    uint8_t tdd_config;
    uint16_t cell_id;
} NR_NODE_CONNECTION_INFO;

// Define the list data structure for storing node connection information
typedef struct {
    NR_NODE_CONNECTION_INFO *data;
    size_t size;
    size_t capacity;
} NR_NODE_CONNECTION_LIST;

// Initialize a new empty list
NR_NODE_CONNECTION_LIST* nr_node_connection_list_init() {
    NR_NODE_CONNECTION_LIST *list = malloc(sizeof(NR_NODE_CONNECTION_LIST));
    if (list == NULL) {
        return NULL;
    }
    list->data = NULL;
    list->size = 0;
    list->capacity = 0;
    return list;
}

// Add a new node connection information to the list
int nr_node_connection_list_add(NR_NODE_CONNECTION_LIST *list, uint64_t macentityid, uint32_t preamble_seq, uint8_t tdd_config) {
    // Check if the list is full
    if (list->size == list->capacity) {
        return -1;
    }

    // Allocate memory for the new node connection information
    NR_NODE_CONNECTION_INFO *node = malloc(sizeof(NR_NODE_CONNECTION_INFO));
    if (node == NULL) {
        return -2;
    }

    // Set the fields of the new node connection information
    node->macentityid = macentityid;
    node->preamble_seq = preamble_seq;
    node->tdd_config = tdd_config;
    node->cell_id = 0;

    // Add the new node connection information to the list
    list->data[list->size++] = *node;

    return 0;
}

// Update an existing node connection information in the list
int nr_node_connection_list_update(NR_NODE_CONNECTION_LIST *list, uint64_t macentityid, uint32_t preamble_seq, uint8_t tdd_config) {
    // Find the index of the node connection information in the list
    size_t i;
    for (i = 0; i < list->size; i++) {
        if (list->data[i].macentityid == macentityid) {
            break;
        }
    }

    // Check if the node connection information was found in the list
    if (i == list->size) {
        return -1;
    }

    // Update the fields of the existing node connection information
    list->data[i].preamble_seq = preamble_seq;
    list->data[i].tdd_config = tdd_config;

    return 0;
}

// Remove an existing node connection information from the list
int nr_node_connection_list_remove(NR_NODE_CONNECTION_LIST *list, uint64_t macentityid) {
    // Find the index of the node connection information in the list
    size_t i;
    for (i = 0; i < list->size; i++) {
        if (list->data[i].macentityid == macentityid) {
            break;
        }
    }

    // Check if the node connection information was found in the list
    if (i == list->size) {
        return -1;
    }

    // Remove the existing node connection information from the list
    list->data[i] = list->data[--list->size];

    return 0;
}

// Get the last processed MAC entity ID from the list
uint64_t nr_node_connection_list_get_last_processed(NR_NODE_CONNECTION_LIST *list) {
    // Check if the list is empty
    if (list->size == 0) {
        return 0;
    }

    // Return the last processed MAC entity ID from the list
    return list->data[list->size - 1].macentityid;
}

// Get the number of node connection information in the list
size_t nr_node_connection_list_get_size(NR_NODE_CONNECTION_LIST *list) {
    return list->size;
}

// Free the memory allocated for the list
void nr_node_connection_list_free(NR_NODE_CONNECTION_LIST *list) {
    free(list);
}
