#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the structure for an NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the structure for a list of NFAPI_CRC_INDICATION_PDU_T structures
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    int size;
} NFAPI_CRC_INDICATION_LIST_T;

// Define the helper class for generating random values within a specified range
class RandomValueHelper {
private:
    int minValue;
    int maxValue;
public:
    RandomValueHelper(int min, int max) {
        this->minValue = min;
        this->maxValue = max;
    }

    // Generate a random float value within the specified range
    float getRandomFloat() {
        return (float)(this->minValue + ((double)rand() / RAND_MAX) * (this->maxValue - this->minValue));
    }

    // Generate a random integer value within the specified range
    int getRandomInt() {
        return rand() % (this->maxValue - this->minValue + 1) + this->minValue;
    }

    // Override the ToString method to display the range of values
    string ToString() {
        return "[" + std::to_string(this->minValue) + ", " + std::to_string(this->maxValue) + "]";
    }
};

// Define the function for managing the dynamic list of NFAPI_CRC_INDICATION_PDU_T structures
void manageNFAPI_CRC_INDICATION_LIST(NFAPI_CRC_INDICATION_LIST_T *list, int RNTI) {
    // Synchronize access to the list and the helper class to prevent race conditions and ensure data integrity under concurrent modifications
    pthread_mutex_lock(&list->mutex);

    // Validate that the RNTI value falls within the valid range for the system
    if (RNTI < 0 || RNTI > 65535) {
        printf("Invalid RNTI value: %d\n", RNTI);
        pthread_mutex_unlock(&list->mutex);
        return;
    }

    // Check if the RNTI already exists in the list
    bool found = false;
    for (int i = 0; i < list->size; i++) {
        if (list->data[i].RNTI == RNTI) {
            found = true;
            break;
        }
    }

    // If the RNTI already exists, update its CRC_INDICATION_REL8_TAG with a new randomly set CRCFLAG value
    if (found) {
        list->data[i].CRC_INDICATION_REL8_TAG = RandomValueHelper(0, 1).getRandomInt();
    } else {
        // If the RNTI does not exist, add a new entry to the list with the specified RX_UE_INFORMATION_TAG and RNTI values
        NFAPI_CRC_INDICATION_PDU_T newEntry = {0};
        newEntry.RX_UE_INFORMATION_TAG = 1;
        newEntry.RNTI = RNTI;
        newEntry.CRC_INDICATION_REL8_TAG = RandomValueHelper(0, 1).getRandomInt();
        list->data[list->size++] = newEntry;
    }

    // Synchronize access to the list and the helper class to prevent race conditions and ensure data integrity under concurrent modifications
    pthread_mutex_unlock(&list->mutex);
}

// Define the function for tracking the last processed RNTI to ensure no duplicates are added within a specified time window
void trackLastProcessedRNTI(NFAPI_CRC_INDICATION_LIST_T *list, int RNTI) {
    // Synchronize access to the list and the helper class to prevent race conditions and ensure data integrity under concurrent modifications
    pthread_mutex_lock(&list->mutex);

    // Check if the RNTI has already been processed within the specified time window
    for (int i = 0; i < list->size; i++) {
        if (list->data[i].RNTI == RNTI) {
            printf("Duplicate RNTI value: %d\n", RNTI);
            pthread_mutex_unlock(&list->mutex);
            return;
        }
    }

    // If the RNTI has not been processed within the specified time window, add it to the list
    NFAPI_CRC_INDICATION_PDU_T newEntry = {0};
    newEntry.RX_UE_INFORMATION_TAG = 1;
    newEntry.RNTI = RNTI;
    newEntry.CRC_INDICATION_REL8_TAG = RandomValueHelper(0, 1).getRandomInt();
    list->data[list->size++] = newEntry;

    // Synchronize access to the list and the helper class to prevent race conditions and ensure data integrity under concurrent modifications
    pthread_mutex_unlock(&list->mutex);
}
