#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the structure for LTE_UPLINK NAS Transport PDUs
typedef struct {
    int NAS_MESSAGE_ID;
    char IMSI[15];
    int TRANSPORT_SEQ_NUMBER;
} LTE_UPLINK_NAS_TRANSPORT_PDU;

// Define the helper class for generating unique sequence numbers
class SequenceNumberHelper {
private:
    int currentSequenceNumber;

public:
    // Constructor to initialize the current sequence number
    SequenceNumberHelper() : currentSequenceNumber(0) {}

    // Method to return the next unique sequence number
    int getNextSequenceNumber() {
        return ++currentSequenceNumber;
    }

    // Method to reset the sequence number upon overflow
    void resetSequenceNumber() {
        currentSequenceNumber = 0;
    }
};

// Define the function for managing the dynamic list of LTE_UPLINK NAS Transport PDUs
void manageLTEUplinkNASTransportPDUs(LTE_UPLINK_NAS_TRANSPORT_PDU *pduList, int numEntries) {
    // Synchronize access to the list and the helper class
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&mutex);

    // Iterate through the list of LTE_UPLINK NAS Transport PDUs
    for (int i = 0; i < numEntries; i++) {
        // Check if the IMSI value falls within the valid range for the system
        if (!isValidIMSI(pduList[i].IMSI)) {
            printf("Invalid IMSI value: %s\n", pduList[i].IMSI);
            continue;
        }

        // Check if the current sequence number is within the specified time window
        if (isDuplicateSequenceNumber(pduList[i].TRANSPORT_SEQ_NUMBER)) {
            printf("Duplicate sequence number: %d\n", pduList[i].TRANSPORT_SEQ_NUMBER);
            continue;
        }

        // Update the last processed IMSI to prevent duplicates within the specified time window
        updateLastProcessedIMSI(pduList[i].IMSI);

        // Increment the sequence number for the current PDU
        pduList[i].TRANSPORT_SEQ_NUMBER = getNextSequenceNumber();
    }

    // Synchronize access to the list and the helper class
    pthread_mutex_unlock(&mutex);
}

// Define the function for adding new entries to the list of LTE_UPLINK NAS Transport PDUs
void addLTEUplinkNASTransportPDU(LTE_UPLINK_NAS_TRANSPORT_PDU *pdu) {
    // Synchronize access to the list and the helper class
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&mutex);

    // Check if the IMSI value falls within the valid range for the system
    if (!isValidIMSI(pdu.IMSI)) {
        printf("Invalid IMSI value: %s\n", pdu.IMSI);
        return;
    }

    // Check if the current sequence number is within the specified time window
    if (isDuplicateSequenceNumber(pdu.TRANSPORT_SEQ_NUMBER)) {
        printf("Duplicate sequence number: %d\n", pdu.TRANSPORT_SEQ_NUMBER);
        return;
    }

    // Update the last processed IMSI to prevent duplicates within the specified time window
    updateLastProcessedIMSI(pdu.IMSI);

    // Increment the sequence number for the current PDU
    pdu.TRANSPORT_SEQ_NUMBER = getNextSequenceNumber();

    // Add the new entry to the list of LTE_UPLINK NAS Transport PDUs
    pthread_mutex_unlock(&mutex);
}

// Define the function for updating existing entries in the list of LTE_UPLINK NAS Transport PDUs
void updateLTEUplinkNASTransportPDU(LTE_UPLINK_NAS_TRANSPORT_PDU *pdu) {
    // Synchronize access to the list and the helper class
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&mutex);

    // Check if the IMSI value falls within the valid range for the system
    if (!isValidIMSI(pdu.IMSI)) {
        printf("Invalid IMSI value: %s\n", pdu.IMSI);
        return;
    }

    // Check if the current sequence number is within the specified time window
    if (isDuplicateSequenceNumber(pdu.TRANSPORT_SEQ_NUMBER)) {
        printf("Duplicate sequence number: %d\n", pdu.TRANSPORT_SEQ_NUMBER);
        return;
    }

    // Update the last processed IMSI to prevent duplicates within the specified time window
    updateLastProcessedIMSI(pdu.IMSI);

    // Increment the sequence number for the current PDU
    pdu.TRANSPORT_SEQ_NUMBER = getNextSequenceNumber();

    // Update the entry in the list of LTE_UPLINK NAS Transport PDUs
    pthread_mutex_unlock(&mutex);
}

// Define the function for removing entries from the list of LTE_UPLINK NAS Transport PDUs based on IMSI
void removeLTEUplinkNASTransportPDU(char *imsi) {
    // Synchronize access to the list and the helper class
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&mutex);

    // Check if the IMSI value falls within the valid range for the system
    if (!isValidIMSI(imsi)) {
        printf("Invalid IMSI value: %s\n", imsi);
        return;
    }

    // Remove the entry from the list of LTE_UPLINK NAS Transport PDUs
    pthread_mutex_unlock(&mutex);
}

