    // Loop through each CCCH message and process it accordingly
    for (int i = 0; i < num_messages; i++) {
        // Check if the BSR message is null or has a size of zero
        if (!ccch_messages[i].bsr || ccch_messages[i].bsr->size == 0) {
            continue;
