        // Increment the total number of messages processed and the total size of all BSR messages
        num_processed++;
        total_bsr_size += ccch_messages[i].bsr->size;

        // Check if the total size of all BSR messages exceeds the maximum allowed size
        if (total_bsr_size > MAX_BSR_SIZE) {
            printf("Error: Total BSR size exceeds maximum allowed size\n");
            return;
        }

        // Process the CCCH message and its associated BSR message
