// Define a struct to represent a dynamic array of CCCH messages
typedef struct {
    ccch_message_t **messages; // Array of CCCH messages
    int num_messages; // Number of CCCH messages in the array
    size_t total_size; // Total allocated space for all BSR messages
} ccch_message_array_t;

// Initialize and populate a dynamic array of CCCH messages
ccch_message_array_t *init_ccch_messages(int num_messages) {
    // Allocate memory for the array of CCCH messages
    ccch_message_array_t *arr = malloc(sizeof(ccch_message_array_t));
    if (!arr) {
        fprintf(stderr, "Error: Failed to allocate memory for CCCH message array\n");
        return NULL;
    }

    // Initialize the number of messages and total allocated space
    arr->num_messages = num_messages;
    arr->total_size = 0;

    // Allocate memory for each CCCH message
    arr->messages = malloc(sizeof(ccch_message_t *) * num_messages);
    if (!arr->messages) {
        fprintf(stderr, "Error: Failed to allocate memory for CCCH messages\n");
        free(arr);
        return NULL;
    }

    // Initialize each CCCH message with a valid TCI and dynamically allocated BSR message
    for (int i = 0; i < num_messages; i++) {
        ccch_message_t *msg = malloc(sizeof(ccch_message_t));
        if (!msg) {
            fprintf(stderr, "Error: Failed to allocate memory for CCCH message %d\n", i);
            free(arr->messages);
            free(arr);
            return NULL;
        }

        // Set the TCI and dynamically allocate a BSR message
        msg->tci = i + 1;
        msg->bsr = malloc(sizeof(char) * (i + 1));
        if (!msg->bsr) {
            fprintf(stderr, "Error: Failed to allocate memory for BSR message %d\n", i);
            free(msg);
            continue;
        }

        // Set the priority level of the BSR message based on the TCI
        if (i % 2 == 0) {
            msg->priority = 1;
        } else {
            msg->priority = 2;
        }

        // Add the CCCH message to the array
        arr->messages[i] = msg;

        // Update the total allocated space for all BSR messages
        arr->total_size += sizeof(char) * (i + 1);
    }

    return arr;
}

// Free a dynamic array of CCCH messages
void free_ccch_messages(ccch_message_array_t *arr) {
    // Free each CCCH message in the array
    for (int i = 0; i < arr->num_messages; i++) {
        ccch_message_t *msg = arr->messages[i];
        free(msg->bsr);
        free(msg);
    }

    // Free the memory allocated for the array of CCCH messages
    free(arr->messages);
    free(arr);
}

