from threading import Lock

class CacheManager:
    def __init__(self, config):
        self.config = config
        self.lock = Lock()
        self.cache = deque(maxlen=10000)
        self.timestamp_map = {}
        self.source_module_map = {}
        self.event_id_map = {}
        self.priority_queue = []
        self.last_updated = time.time()

    def add(self, timestamp, event_id, source_module):
        with self.lock:
            if len(self.cache) == 10000:
                self.purge_least_recently_used()
            self.cache.append((timestamp, event_id, source_module))
            self.timestamp_map[timestamp] = event_id
            self.source_module_map[event_id] = source_module
            self.priority_queue.append(event_id)
            self.last_updated = time.time()

