#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define a struct to store authentication requests
typedef struct {
    char* session_id;
    char* user_credentials;
    int status; // 0: pending, 1: in progress, 2: completed
} auth_request_t;

// Define a linked list node to store the authentication requests
typedef struct {
    auth_request_t request;
    struct node* next;
} node_t;

// Define a function to allocate memory for an authentication request
auth_request_t* alloc_request(char* session_id, char* user_credentials) {
    auth_request_t* request = (auth_request_t*)malloc(sizeof(auth_request_t));
    if (!request) {
        return NULL;
    }
    request->session_id = strdup(session_id);
    request->user_credentials = strdup(user_credentials);
    request->status = 0; // pending
    return request;
}

// Define a function to deallocate memory for an authentication request
void free_request(auth_request_t* request) {
    if (request) {
        free(request->session_id);
        free(request->user_credentials);
        free(request);
    }
}

// Define a function to add an authentication request to the linked list
void add_request(node_t** head, auth_request_t* request) {
    node_t* new_node = (node_t*)malloc(sizeof(node_t));
    if (!new_node) {
        return;
    }
    new_node->request = *request;
    new_node->next = NULL;
    if (*head == NULL) {
        *head = new_node;
    } else {
        node_t* current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }
}

// Define a function to remove an authentication request from the linked list
void remove_request(node_t** head, char* session_id) {
    node_t* current = *head;
    if (current == NULL) {
        return;
    }
    if (strcmp(current->request.session_id, session_id) == 0) {
        *head = current->next;
        free_request(&current->request);
        free(current);
        return;
    }
    while (current->next != NULL) {
        if (strcmp(current->next->request.session_id, session_id) == 0) {
            node_t* temp = current->next;
            current->next = temp->next;
            free_request(&temp->request);
            free(temp);
            return;
        }
        current = current->next;
    }
}

// Define a function to process an authentication request
void process_request(node_t** head, char* session_id) {
    node_t* current = *head;
    if (current == NULL) {
        return;
    }
    while (current->next != NULL) {
        if (strcmp(current->next->request.session_id, session_id) == 0) {
            auth_request_t* request = &current->next->request;
            // Process the authentication request here
            current->next = current->next->next;
            free_request(request);
            return;
        }
        current = current->next;
    }
}

// Define a function to prioritize requests based on their creation timestamp
void prioritize_requests(node_t** head) {
    node_t* current = *head;
    if (current == NULL) {
        return;
    }
    while (current->next != NULL) {
        if (strcmp(current->request.session_id, current->next->request.session_id) > 0) {
            auth_request_t* request = &current->request;
            current->request = current->next->request;
            current->next->request = *request;
        }
        current = current->next;
    }
}

// Define a function to track the total number of requests processed and the average processing time over a specified time window
void track_requests(node_t** head, int* num_requests, double* avg_processing_time) {
    node_t* current = *head;
    if (current == NULL) {
        return;
    }
    while (current->next != NULL) {
        *num_requests += 1;
        *avg_processing_time += current->request.status == 2 ? 1 : 0; // completed requests only
        current = current->next;
    }
}

// Define a function to handle the efficient allocation and deallocation of memory for storing authentication requests
void manage_memory(node_t** head, int* num_requests) {
    node_t* current = *head;
    if (current == NULL) {
        return;
    }
    while (current->next != NULL) {
        if (*num_requests > 8192) { // 8KB
            auth_request_t* request = &current->next->request;
            current->next = current->next->next;
            free_request(request);
            *num_requests -= 1;
        } else {
            current = current->next;
        }
    }
}
