#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <time.h>
#include <errno.h>

// Define the structure for an audit record
typedef struct {
    int AUDIT_ID;
    char* FILE_PATH;
    time_t ACCESS_TIME;
    int STATUS_CODE;
} FILE_SYSTEM_AUDIT_RECORD_T;

// Define the maximum number of audit records to retain
#define MAX_AUDIT_RECORDS 10000

// Define the minimum and maximum values for STATUS_CODE
#define MIN_STATUS_CODE 0
#define MAX_STATUS_CODE 255

// Define the audit levels (critical, moderate, low)
#define AUDIT_LEVEL_CRITICAL 1
#define AUDIT_LEVEL_MODERATE 2
#define AUDIT_LEVEL_LOW 3

// Define the function to dynamically allocate memory for an array of audit records
FILE_SYSTEM_AUDIT_RECORD_T* allocate_audit_records(int num_records) {
    // Check if the number of records is valid
    if (num_records <= 0 || num_records > MAX_AUDIT_RECORDS) {
        return NULL;
    }

    // Allocate memory for the array of audit records
    FILE_SYSTEM_AUDIT_RECORD_T* records = (FILE_SYSTEM_AUDIT_RECORD_T*)malloc(num_records * sizeof(FILE_SYSTEM_AUDIT_RECORD_T));
    if (!records) {
        return NULL;
    }

    // Initialize the audit records
    for (int i = 0; i < num_records; i++) {
        records[i].AUDIT_ID = -1;
        records[i].FILE_PATH = NULL;
        records[i].ACCESS_TIME = 0;
        records[i].STATUS_CODE = -1;
    }

    return records;
}

// Define the function to add an audit record to the array of audit records
int add_audit_record(FILE_SYSTEM_AUDIT_RECORD_T* records, int num_records, FILE_SYSTEM_AUDIT_RECORD_T new_record) {
    // Check if the number of records is valid
    if (num_records <= 0 || num_records > MAX_AUDIT_RECORDS) {
        return -1;
    }

    // Check if the STATUS_CODE falls within the specified range
    if (new_record.STATUS_CODE < MIN_STATUS_CODE || new_record.STATUS_CODE > MAX_STATUS_CODE) {
        return -2;
    }

    // Check if the file path is valid
    if (!new_record.FILE_PATH) {
        return -3;
    }

    // Find an empty slot in the array of audit records
    int i = 0;
    while (i < num_records && records[i].AUDIT_ID != -1) {
        i++;
    }

    // Check if all slots are filled
    if (i == num_records) {
        return -4;
    }

    // Set the AUDIT_ID and FILE_PATH for the new record
    records[i].AUDIT_ID = i + 1;
    records[i].FILE_PATH = strdup(new_record.FILE_PATH);
    records[i].ACCESS_TIME = time(NULL);
    records[i].STATUS_CODE = new_record.STATUS_CODE;

    return i + 1;
}

// Define the function to retrieve an audit record from the array of audit records
FILE_SYSTEM_AUDIT_RECORD_T get_audit_record(FILE_SYSTEM_AUDIT_RECORD_T* records, int num_records, int AUDIT_ID) {
    // Check if the number of records is valid
    if (num_records <= 0 || num_records > MAX_AUDIT_RECORDS) {
        return NULL;
    }

    // Find the record with the specified AUDIT_ID
    for (int i = 0; i < num_records; i++) {
        if (records[i].AUDIT_ID == AUDIT_ID) {
            return records[i];
        }
    }

    // Return NULL if the record is not found
    return NULL;
}

// Define the function to free memory for an array of audit records
void free_audit_records(FILE_SYSTEM_AUDIT_RECORD_T* records, int num_records) {
    // Check if the number of records is valid
    if (num_records <= 0 || num_records > MAX_AUDIT_RECORDS) {
        return;
    }

    // Free memory for each record in the array
    for (int i = 0; i < num_records; i++) {
        free(records[i].FILE_PATH);
    }

    // Free memory for the array of audit records
    free(records);
}
