        printf("Error parsing JSON response\n");
        return false;
    }

    // Validate the access token field
    char* access_token = cJSON_GetObjectItemCaseSensitive(root, "access_token")->valuestring;
    if (!access_token) {
        printf("Missing access token in JSON response\n");
        return false;
    }

    // Validate the expires_in field
    int expires_in = cJSON_GetObjectItemCaseSensitive(root, "expires_in")->valueint;
    if (expires_in <= 0) {
        printf("Invalid expiration time in JSON response\n");
        return false;
    }

    // Clean up the memory allocated for the JSON object
    cJSON_Delete(root);

    return true;
}

