        return NULL;
    }

    // Allocate memory for the array of session states
    NETWORK_SESSION_STATE_T* session_states = malloc(sizeof(NETWORK_SESSION_STATE_T) * num_sessions);
    if (session_states == NULL) {
        return NULL;
    }

    // Initialize the session IDs and start times
    for (int i = 0; i < num_sessions; i++) {
        session_states[i].session_id = i + 1;
        session_states[i].start_time = time(NULL);
    }

    // Return the allocated memory
    return session_states;
}

// Define the function to verify the integrity of the status code before allocation
int verify_status_code(int status_code) {
    if (status_code < 0 || status_code > 999) {
        return -1;
    }
    return status_code;
}

