void track_sessions(NETWORK_SESSION_STATE_T* session_states, int num_sessions) {
    // Implement thread-safe access to the internal state of the function
    pthread_mutex_lock(&session_states->mutex);

    // Update the session states with new information
    for (int i = 0; i < num_sessions; i++) {
        session_states[i].status_code = verify_status_code(session_states[i].status_code);
