// Function to allocate memory for an array of LTE_PHY_TEST_FRAME_T structures
LTE_PHY_TEST_FRAME_T **allocate_frames(int num_frames, PHY_TEST_FRAME_TYPE type) {
    // Check if the number of frames is within the maximum allowed range
    assert(num_frames <= MAX_NUM_FRAMES);

    // Lock the mutex to prevent race conditions when accessing shared resources
    pthread_mutex_lock(&mutex);

    // Allocate memory for the array of frames
    LTE_PHY_TEST_FRAME_T **frames = malloc(num_frames * sizeof(LTE_PHY_TEST_FRAME_T));

    // Check if memory allocation failed
    if (frames == NULL) {
