        } else if (type == PHY_TEST_FRAME_TYPE_B) {
            strcpy(frames[i]->channel_quality_information, "B");
        } else if (type == PHY_TEST_FRAME_TYPE_C) {
            strcpy(frames[i]->channel_quality_information, "C");
        } else {
            printf("Error: Invalid frame type\n");
            pthread_mutex_unlock(&mutex);
            return NULL;
        }
    }

    // Increment the number of successfully allocated frames
    num_allocated_frames += num_frames;

    // Unlock the mutex to allow other threads to access shared resources
    pthread_mutex_unlock(&mutex);

    return frames;
}

// Function to free memory for an array of LTE_PHY_TEST_FRAME_T structures
void free_frames(LTE_PHY_TEST_FRAME_T **frames, int num_frames) {
    // Check if the number of frames is within the maximum allowed range
    assert(num_frames <= MAX_NUM_FRAMES);

    // Lock the mutex to prevent race conditions when accessing shared resources
    pthread_mutex_lock(&mutex);

    // Iterate over each frame and free its memory
