import re
import time
from concurrent.futures import ThreadPoolExecutor

def process_log_file(file_path):
    with open(file_path, "r") as f:
        lines = f.readlines()

    events = []
    for line in lines:
        match = re.search(r"^(\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}) (\w+) (\d+)", line)
        if match:
            timestamp, event_type, user_id = match.groups()
            events.append((timestamp, event_type, int(user_id)))

    filtered_events = []
    for event in events:
        if filter_event(event):
            filtered_events.append(event)

    summary = {}
    for event in filtered_events:
        timestamp, event_type, user_id = event
        if event_type not in summary:
            summary[event_type] = 0
        summary[event_type] += 1

    average_processing_time = 0
    for event in filtered_events:
        timestamp, event_type, user_id = event
        average_processing_time += time.time() - float(timestamp)

    return filtered_events, summary, average_processing_time / len(filtered_events)

def filter_event(event):
    timestamp, event_type, user_id = event
    if not (start_time <= timestamp < end_time):
        return False
    if event_type not in allowed_event_types:
        return False
    if user_id not in allowed_user_ids:
        return False
    return True

def main():
    file_paths = ["file1.log", "file2.log", ...]
    results = []
    with ThreadPoolExecutor(max_workers=len(file_paths)) as executor:
        futures = [executor.submit(process_log_file, file_path) for file_path in file_paths]
        for future in futures:
            results.append(future.result())
    return results
