int manage_file_descriptors(char *filename, int mode) {
    // Check if the file exists and is accessible
    struct stat buf;
    if (stat(filename, &buf) == -1) {
        perror("Error: File does not exist or is not accessible");
        return -1;
    }

    // Open the file in the specified mode
    int fd = open(filename, mode);
    if (fd == -1) {
        perror("Error: Failed to open file");
        return -1;
    }

    // Check if the number of file descriptors used by the process is within limits
    if (getdtablesize() >= MAX_FILE_DESCRIPTORS) {
        perror("Error: Too many file descriptors in use");
        close(fd);
        return -1;
    }

