#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/aes.h>
#include <openssl/evp.h>
#include <openssl/err.h>
#include <openssl/rand.h>
#include <openssl/hmac.h>
#include <openssl/pbkdf2.h>
#include <arpa/inet.h>

// Define error codes for the function
#define SUCCESS 0
#define FAILURE -1
#define DNS_FAILURE -2
#define AES_INIT_FAILURE -3
#define MEMORY_ALLOCATION_FAILURE -4

// Function to initialize an AES-256-CBC cipher using a given password and hostname
int init_aes_cbc(const char* password, const char* hostname) {
    // Declare variables for the key and IV
    unsigned char key[32];
    unsigned char iv[16];

    // Generate the encryption key and initialization vector using PBKDF2 with HMAC-SHA256
    if (PBKDF2_HMAC_SHA256(password, strlen(password), NULL, 0, 1000, key, sizeof(key)) == NULL) {
        printf("Error generating encryption key\n");
        return AES_INIT_FAILURE;
    }
    if (PBKDF2_HMAC_SHA256(password, strlen(password), NULL, 0, 1000, iv, sizeof(iv)) == NULL) {
        printf("Error generating initialization vector\n");
        return AES_INIT_FAILURE;
    }

    // Allocate memory for the cipher context
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) {
        printf("Error allocating memory for cipher context\n");
        return MEMORY_ALLOCATION_FAILURE;
    }

    // Initialize the cipher context with the encryption key and initialization vector
    if (!EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) {
        printf("Error initializing cipher context\n");
        return FAILURE;
    }

    // Perform DNS resolution for the given hostname using the standard library functions
    struct in_addr addr;
    if (inet_pton(AF_INET, hostname, &addr) != 1) {
        printf("Error resolving hostname\n");
        return DNS_FAILURE;
    }

    // Return the IP address in a u_char array
    u_char ip[4];
    memcpy(ip, &addr.s_addr, 4);
    return SUCCESS;
}

// Function to handle cleanup and disable the cipher
void cleanup_aes_cbc() {
    // Disable the cipher context
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) {
        printf("Error allocating memory for cipher context\n");
        return;
    }
    EVP_EncryptInit_ex(ctx, NULL, NULL, NULL, NULL);

    // Free all associated resources with the cipher context
    EVP_CIPHER_CTX_free(ctx);
}
