#include <stdlib.h>
#include <stdio.h>
#include <time.h>
#include <pthread.h>

// Define the maximum size of the list
#define MAX_LIST_SIZE 2048

// Define the structure for the NFAPI_L1_STATS_RECORD
typedef struct {
    int tx_power_level;
    int tx_antenna_selection;
    int channel_quality_indicator;
    time_t timestamp;
} nfapi_l1_stats_record_t;

// Define the list of NFAPI_L1_STATS_RECORD structures
static nfapi_l1_stats_record_t *list = NULL;

// Define the mutex for thread safety
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to add a new entry to the list
void add_entry(int tx_power_level, int tx_antenna_selection, int channel_quality_indicator) {
    // Lock the mutex
    pthread_mutex_lock(&mutex);

    // Check if the list is full
    if (list == NULL || list->size >= MAX_LIST_SIZE) {
        // If the list is full, remove the oldest entry
        nfapi_l1_stats_record_t *oldest = list;
        while (oldest->next != NULL) {
            oldest = oldest->next;
        }
        free(oldest);
    }

    // Create a new entry
    nfapi_l1_stats_record_t *new_entry = malloc(sizeof(nfapi_l1_stats_record_t));
    if (new_entry == NULL) {
        // If memory allocation fails, log the error and return
        printf("Memory allocation failed\n");
        pthread_mutex_unlock(&mutex);
        return;
    }

    // Set the fields of the new entry
    new_entry->tx_power_level = tx_power_level;
    new_entry->tx_antenna_selection = tx_antenna_selection;
    new_entry->channel_quality_indicator = channel_quality_indicator;
    new_entry->timestamp = time(NULL);

    // Add the new entry to the list
    if (list == NULL) {
        list = new_entry;
    } else {
        list->next = new_entry;
    }

    // Unlock the mutex
    pthread_mutex_unlock(&mutex);
}

// Function to update an existing entry in the list based on TX power level
void update_entry(int tx_power_level) {
    // Lock the mutex
    pthread_mutex_lock(&mutex);

    // Find the entry with the matching TX power level
    nfapi_l1_stats_record_t *current = list;
    while (current != NULL && current->tx_power_level != tx_power_level) {
        current = current->next;
    }

    // If an entry was found, update its timestamp and unlock the mutex
    if (current != NULL) {
        current->timestamp = time(NULL);
        pthread_mutex_unlock(&mutex);
    } else {
        // If no entry was found, log the error and return
        printf("Entry not found\n");
        pthread_mutex_unlock(&mutex);
    }
}

// Function to retrieve a list of all entries with a channel quality above a certain threshold
void retrieve_entries(int channel_quality_threshold) {
    // Lock the mutex
    pthread_mutex_lock(&mutex);

    // Create an empty list for the retrieved entries
    nfapi_l1_stats_record_t *retrieved_list = NULL;

    // Iterate through the list and add entries with a channel quality above the threshold to the retrieved list
    nfapi_l1_stats_record_t *current = list;
    while (current != NULL) {
        if (current->channel_quality_indicator > channel_quality_threshold) {
            // Create a new entry in the retrieved list
            nfapi_l1_stats_record_t *new_entry = malloc(sizeof(nfapi_l1_stats_record_t));
            if (new_entry == NULL) {
                printf("Memory allocation failed\n");
                pthread_mutex_unlock(&mutex);
                return;
            }

            // Set the fields of the new entry
            new_entry->tx_power_level = current->tx_power_level;
            new_entry->tx_antenna_selection = current->tx_antenna_selection;
            new_entry->channel_quality_indicator = current->channel_quality_indicator;
            new_entry->timestamp = current->timestamp;

            // Add the new entry to the retrieved list
            if (retrieved_list == NULL) {
                retrieved_list = new_entry;
            } else {
                retrieved_list->next = new_entry;
            }
        }

        current = current->next;
    }

    // Unlock the mutex and return the retrieved list
    pthread_mutex_unlock(&mutex);
}

// Function to handle memory allocation failures gracefully
void handle_memory_allocation_failure() {
    printf("Memory allocation failed\n");
}

// Function to handle overflow conditions gracefully
void handle_overflow_condition() {
    printf("List overflowed\n");
}

// Function to log the number of entries added, updated, and removed
void log_entries(int num_added, int num_updated, int num_removed) {
    // Lock the mutex
    pthread_mutex_lock(&mutex);

    // Log the number of entries added, updated, and removed
    printf("Number of entries added: %d\n", num_added);
    printf("Number of entries updated: %d\n", num_updated);
    printf("Number of entries removed: %d\n", num_removed);

    // Unlock the mutex
    pthread_mutex_unlock(&mutex);
}
