// Define the structure for a list of LTE PHY RX buffers
typedef struct {
    int num_entries;
    LTE_PHY_RX_BUFFER_T *entries;
} LTE_PHY_RX_BUFFERS_T;

// Define the structure for a list of PHY RX stats tags
typedef struct {
    int num_entries;
    PHY_RX_STATS_TAG *entries;
} PHY_RX_STATS_TAGS_T;

// Define the function to manage the dynamic list of LTE PHY RX buffers
void manage_lte_phy_rx_buffers(LTE_PHY_RX_BUFFERS_T *buffers) {
    // Check if the buffer is full and needs to be cleaned up
    if (buffers->num_entries >= MAX_ENTRIES) {
        // Clean up the oldest entry in the buffer
        LTE_PHY_RX_BUFFER_T *oldest_entry = buffers->entries[0];
        for (int i = 1; i < buffers->num_entries; i++) {
            if (buffers->entries[i]->cell_id > oldest_entry->cell_id) {
                oldest_entry = buffers->entries[i];
            }
        }
        // Remove the oldest entry from the buffer
        for (int i = 0; i < buffers->num_entries - 1; i++) {
            if (buffers->entries[i] == oldest_entry) {
                buffers->entries[i] = buffers->entries[i + 1];
            }
        }
        buffers->num_entries--;
    }
}

// Define the function to add a new entry to the list of LTE PHY RX buffers
void add_lte_phy_rx_buffer(LTE_PHY_RX_BUFFERS_T *buffers, int cell_id, float rx_power_level, char reception_quality_flag) {
    // Check if the buffer is full and needs to be cleaned up
    manage_lte_phy_rx_buffers(buffers);

    // Create a new entry in the buffer
    LTE_PHY_RX_BUFFER_T *new_entry = malloc(sizeof(LTE_PHY_RX_BUFFER_T));
    new_entry->cell_id = cell_id;
    new_entry->rx_power_level = rx_power_level;
    new_entry->reception_quality_flag = reception_quality_flag;

    // Add the new entry to the buffer
    buffers->entries[buffers->num_entries++] = new_entry;
}

// Define the function to update an existing entry in the list of LTE PHY RX buffers
void update_lte_phy_rx_buffer(LTE_PHY_RX_BUFFERS_T *buffers, int cell_id, float rx_power_level, char reception_quality_flag) {
    // Check if the buffer is full and needs to be cleaned up
    manage_lte_phy_rx_buffers(buffers);

    // Find the entry in the buffer with the specified cell ID
    LTE_PHY_RX_BUFFER_T *entry = NULL;
