        if (buffers->entries[i]->cell_id == cell_id) {
            entry = buffers->entries[i];
            break;
        }
    }

    // Update the entry with the new values
    if (entry != NULL) {
        entry->rx_power_level = rx_power_level;
        entry->reception_quality_flag = reception_quality_flag;
    } else {
        add_lte_phy_rx_buffer(buffers, cell_id, rx_power_level, reception_quality_flag);
    }
}

// Define the function to remove an existing entry from the list of LTE PHY RX buffers
void remove_lte_phy_rx_buffer(LTE_PHY_RX_BUFFERS_T *buffers, int cell_id) {
    // Find the entry in the buffer with the specified cell ID
    LTE_PHY_RX_BUFFER_T *entry = NULL;
    for (int i = 0; i < buffers->num_entries; i++) {
        if (buffers->entries[i]->cell_id == cell_id) {
            entry = buffers->entries[i];
            break;
        }
    }

    // Remove the entry from the buffer
    if (entry != NULL) {
        for (int i = 0; i < buffers->num_entries - 1; i++) {
            if (buffers->entries[i] == entry) {
                buffers->entries[i] = buffers->entries[i + 1];
            }
        }
        buffers->num_entries--;
    }
}

// Define the function to validate a PHY RX stats tag
int validate_phy_rx_stats_tag(PHY_RX_STATS_TAG *tag) {
    // Check if the CELL ID is within the valid range
    if (tag->cell_id < MIN_CELL_ID || tag->cell_id > MAX_CELL_ID) {
        return 0;
    }

    // Check if the RX power level is within the valid range
    if (tag->rx_power_level < MIN_RX_POWER_LEVEL || tag->rx_power_level > MAX_RX_POWER_LEVEL) {
        return 0;
    }

    // Check if the reception quality flag is within the valid range
    if (tag->reception_quality_flag < MIN_RECEPTION_QUALITY_FLAG || tag->reception_quality_flag > MAX_RECEPTION_QUALITY_FLAG) {
        return 0;
    }

    // Return success
    return 1;
}

// Define the function to populate a list of LTE PHY RX buffers using standard library functions
void populate_lte_phy_rx_buffers(LTE_PHY_RX_BUFFERS_T *buffers, int num_entries) {
