    for (int i = 0; i < num_entries; i++) {
        LTE_PHY_RX_BUFFER_T *new_entry = malloc(sizeof(LTE_PHY_RX_BUFFER_T));
        new_entry->cell_id = rand() % (MAX_CELL_ID - MIN_CELL_ID + 1) + MIN_CELL_ID;
        new_entry->rx_power_level = rand() % (MAX_RX_POWER_LEVEL - MIN_RX_POWER_LEVEL + 1) + MIN_RX_POWER_LEVEL;
        new_entry->reception_quality_flag = rand() % (MAX_RECEPTION_QUALITY_FLAG - MIN_RECEPTION_QUALITY_FLAG + 1) + MIN_RECEPTION_QUALITY_FLAG;
        buffers->entries[buffers->num_entries++] = new_entry;
    }
}

// Define the function to validate the integrity of a list of LTE PHY RX buffers
void validate_lte_phy_rx_buffers(LTE_PHY_RX_BUFFERS_T *buffers) {
