// Define the caching mechanism
class Cache {
 public:
  Cache(int size) : size_(size) {}

  void insert(const string& key, const vector<int>& value) {
    std::lock_guard<std::mutex> lock(mutex_);
    cache_.insert({key, value});
  }

  bool find(const string& key, vector<int>& value) {
    std::lock_guard<std::mutex> lock(mutex_);
    auto it = cache_.find(key);
    if (it != cache_.end()) {
      value = it->second;
      return true;
    } else {
      return false;
    }
  }

 private:
  int size_; // Size of the cache in MB
  unordered_map<string, vector<int>> cache_; // Cache map
  mutex mutex_; // Mutex for synchronizing access to the cache
};

// Define the connection pool
class ConnectionPool {
 public:
  ConnectionPool(int size) : size_(size) {}

  void addConnection(const string& host, const int port) {
    std::lock_guard<std::mutex> lock(mutex_);
    connections_.push_back({host, port});
  }

  bool getConnection(string& host, int& port) {
    std::lock_guard<std::mutex> lock(mutex_);
    if (connections_.empty()) {
      return false;
    } else {
      auto connection = connections_.front();
      connections_.pop_front();
      host = connection.first;
      port = connection.second;
      return true;
    }
  }

 private:
  int size_; // Size of the connection pool
  list<pair<string, int>> connections_; // Connection pool
  mutex mutex_; // Mutex for synchronizing access to the connection pool
};

// Define the retry mechanism
class Retry {
 public:
  Retry(int maxRetries) : maxRetries_(maxRetries) {}

  bool retry(const string& host, const int port, const int delay) {
    std::lock_guard<std::mutex> lock(mutex_);
    if (retries_.find(host + ":" + to_string(port)) == retries_.end()) {
      retries_.insert({host + ":" + to_string(port), 0});
    }
    auto it = retries_.find(host + ":" + to_string(port));
    if (it->second < maxRetries_) {
      it->second++;
      return true;
    } else {
      return false;
    }
  }

 private:
  int maxRetries_; // Maximum number of retries
  unordered_map<string, int> retries_; // Retry map
  mutex mutex_; // Mutex for synchronizing access to the retry map
};

