// Custom logging mechanism
void log_message(const char* message, const char* id, time_t timestamp) {
    printf("[%s] %s (%ld)\n", message, id, timestamp);
}

// Integration with an existing logging framework
#include <logging.h>

void decrypt_message(const unsigned char* key, const unsigned char* iv, const unsigned char* ciphertext, size_t length) {
    // Initialize AES cipher with the provided encryption key and initialization vector (IV)
    AES_KEY aes_key;
    AES_set_decrypt_key(key, 128, &aes_key);
    AES_cbc_encrypt(ciphertext, ciphertext, length, &aes_key, iv, AES_DECRYPT);

    // Calculate HMAC-SHA256 digest of the decrypted message
    unsigned char hmac[SHA256_DIGEST_LENGTH];
    SHA256(ciphertext, length, hmac, NULL);

    // Compare the calculated HMAC with the provided HMAC
    if (memcmp(hmac, ciphertext + length, SHA256_DIGEST_LENGTH) != 0) {
        log_message("Decryption failed", "Invalid HMAC", time(NULL));
        return;
    }

    // Decrypt the message using AES-CBC
    unsigned char plaintext[length];
    AES_cbc_encrypt(ciphertext, plaintext, length, &aes_key, iv, AES_DECRYPT);

    // Log successful decryption
    log_message("Decryption succeeded", "Message ID", time(NULL));
}
