typedef struct UEContext {
    int ue_id;
    char *active_sessions;
    time_t last_session_update;
} UEContext;

UEContext* init_ue_context(int ue_id) {
    UEContext *ctx = malloc(sizeof(UEContext));
    ctx->ue_id = ue_id;
    ctx->active_sessions = NULL;
    ctx->last_session_update = time(NULL);
    return ctx;
}

void add_session(UEContext *ctx, char *session) {
    if (ctx->active_sessions == NULL) {
        ctx->active_sessions = malloc(sizeof(char *) * 1);
    } else {
        int size = sizeof(char *) * (ctx->active_sessions_size + 1);
        ctx->active_sessions = realloc(ctx->active_sessions, size);
    }
    ctx->active_sessions[ctx->active_sessions_size++] = session;
}

void remove_expired_sessions(UEContext *ctx) {
    time_t current_time = time(NULL);
    for (int i = 0; i < ctx->active_sessions_size; i++) {
        if (difftime(current_time, ctx->last_session_update) > timeout) {
            free(ctx->active_sessions[i]);
            memmove(&ctx->active_sessions[i], &ctx->active_sessions[i + 1], sizeof(char *) * (ctx->active_sessions_size - i));
