#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define structure for session metadata
typedef struct {
    char *session_id;
    char *user_agent;
    time_t login_timestamp;
    time_t last_activity_timestamp;
} SessionMetadata;

// Define list data structure for storing sessions
typedef struct {
    SessionMetadata **sessions;
    int num_sessions;
} SessionList;

// Function to create a new session list
SessionList *create_session_list() {
    // Allocate memory for the list and initialize it
    SessionList *list = (SessionList *)malloc(sizeof(SessionList));
    list->num_sessions = 0;
    list->sessions = NULL;

    return list;
}

// Function to add a new session to the list
void add_session(SessionList *list, char *session_id, char *user_agent) {
    // Allocate memory for the new session metadata
    SessionMetadata *metadata = (SessionMetadata *)malloc(sizeof(SessionMetadata));
    metadata->session_id = strdup(session_id);
    metadata->user_agent = strdup(user_agent);
    metadata->login_timestamp = time(NULL);
    metadata->last_activity_timestamp = time(NULL);

    // Add the new session to the list
    list->sessions[list->num_sessions++] = metadata;
}

// Function to remove a session from the list
void remove_session(SessionList *list, char *session_id) {
    // Find the index of the session to be removed
    int i;
    for (i = 0; i < list->num_sessions; i++) {
        if (strcmp(list->sessions[i]->session_id, session_id) == 0) {
            break;
        }
    }

    // Remove the session from the list and free its memory
    SessionMetadata *metadata = list->sessions[i];
    free(metadata->session_id);
    free(metadata->user_agent);
    free(metadata);

    // Shift all subsequent sessions to fill the gap
    for (int j = i; j < list->num_sessions - 1; j++) {
        list->sessions[j] = list->sessions[j + 1];
    }

    // Decrement the number of sessions in the list
    list->num_sessions--;
}

// Function to update a session's last activity timestamp
void update_last_activity(SessionList *list, char *session_id) {
    // Find the index of the session to be updated
    int i;
    for (i = 0; i < list->num_sessions; i++) {
        if (strcmp(list->sessions[i]->session_id, session_id) == 0) {
            break;
        }
    }

    // Update the last activity timestamp and return
    list->sessions[i]->last_activity_timestamp = time(NULL);
}

// Function to verify that the list is correctly populated and contains no duplicate sessions based on their unique identifiers
void verify_list(SessionList *list) {
    // Iterate over all sessions in the list
    for (int i = 0; i < list->num_sessions; i++) {
        // Check if there are any duplicates of the current session ID
        for (int j = i + 1; j < list->num_sessions; j++) {
            if (strcmp(list->sessions[i]->session_id, list->sessions[j]->session_id) == 0) {
                // If a duplicate is found, remove the session from the list and free its memory
                SessionMetadata *metadata = list->sessions[j];
                free(metadata->session_id);
                free(metadata->user_agent);
                free(metadata);

                // Shift all subsequent sessions to fill the gap
                for (int k = j; k < list->num_sessions - 1; k++) {
                    list->sessions[k] = list->sessions[k + 1];
                }

                // Decrement the number of sessions in the list
                list->num_sessions--;
            }
        }
    }
}

// Function to log the creation process, including start and end timestamps, and the number of unique sessions in the list
void log_creation(SessionList *list) {
    // Get the current time as a timestamp
    time_t now = time(NULL);

    // Log the start of the creation process
    printf("Creating session list at %s\n", ctime(&now));

