    messages[messages->count++] = (RRC_MESSAGE) {
        .type = type,
        .sequence_number = sequence_number,
        .phy_feedback = phy_feedback
    };

    // Release the mutex and signal the semaphore to wake up any waiting threads
    pthread_mutex_unlock(&mutex);
    sem_post(&sem);

    return 0;
}

// Function to remove an RRC message from the array
int remove_message(uint32_t sequence_number) {
    // Acquire the mutex to ensure thread safety
    pthread_mutex_lock(&mutex);

    // Find the index of the RRC message with the specified sequence number
    int i = 0;
    while (i < messages->count && messages[i].sequence_number != sequence_number) {
        i++;
    }

    // If the message was found, remove it from the array and free its buffer data
    if (i < messages->count) {
        RRC_MESSAGE *message = &messages[i];
        free(message->phy_feedback.data);
        memmove(&messages[i], &messages[i + 1], sizeof(RRC_MESSAGE) * (messages->count - i));
        messages->count--;
    }

    // Release the mutex and signal the semaphore to wake up any waiting threads
    pthread_mutex_unlock(&mutex);
    sem_post(&sem);

    return 0;
}

// Function to retrieve an RRC message from the array
RRC_MESSAGE *get_message(uint32_t sequence_number) {
    // Acquire the mutex to ensure thread safety
    pthread_mutex_lock(&mutex);

    // Find the index of the RRC message with the specified sequence number
    int i = 0;
    while (i < messages->count && messages[i].sequence_number != sequence_number) {
        i++;
    }

    // If the message was found, return a copy of it
    if (i < messages->count) {
        RRC_MESSAGE *message = &messages[i];
        pthread_mutex_unlock(&mutex);
        return malloc(sizeof(RRC_MESSAGE));
    }

    // Release the mutex and signal the semaphore to wake up any waiting threads
    pthread_mutex_unlock(&mutex);
    sem_post(&sem);

    return NULL;
}

// Function to validate the buffer data before adding a new entry to the array
