#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <zlib.h>
#include <pthread.h>
#include <errno.h>

#define BUFFER_SIZE 4096
#define MAX_FILENAME_LEN 256
#define DEFAULT_BUFFER_SIZE 1024
#define DEFAULT_OUTPUT_FORMAT "wordcount"
#define DEFAULT_COMPRESSION_TYPE "gzip"
#define DEFAULT_THREAD_COUNT 8

typedef struct {
    char* filename;
    int fd;
} file_info_t;

typedef struct {
    long line_count;
    long word_count;
} processing_result_t;

void print_usage(char* progname) {
    printf("Usage: %s [options] [input]\n", progname);
    printf("\nOptions:\n");
    printf("  -h, --help                   Display this help message and exit\n");
    printf("  -i, --input <file>           Input file (default: stdin)\n");
    printf("  -o, --output <file>          Output file (default: stdout)\n");
    printf("  -c, --compression <type>     Compression type (default: gzip)\n");
    printf("  -t, --threads <count>        Number of threads for processing (default: 8)\n");
    printf("  -f, --format <format>        Output format (default: wordcount)\n");
    printf("\nInput:\n");
    printf("  Input can be a file or stdin\n");
}

void process_file(char* filename, int fd) {
    // Read buffer size is adjusted based on file characteristics to optimize performance
    long read_buffer_size = DEFAULT_BUFFER_SIZE;
    char* buffer = malloc(read_buffer_size);
    if (buffer == NULL) {
        perror("malloc");
        exit(1);
    }

    // Initialize processing result structure
    processing_result_t result = {0, 0};

    // Process file in chunks to handle large files without loading the entire file into memory
    while (read(fd, buffer, read_buffer_size) > 0) {
        // Count lines and words in buffer
        char* line = strtok(buffer, "\n");
        while (line != NULL) {
            result.line_count++;
            char* word = strtok(line, " ");
            while (word != NULL) {
                result.word_count++;
                word = strtok(NULL, " ");
            }
            line = strtok(NULL, "\n");
        }
    }

    // Write processing results to output file
    if (filename != NULL) {
        FILE* outfile = fopen(filename, "wb");
        if (outfile == NULL) {
            perror("fopen");
            exit(1);
        }
        fprintf(outfile, "%ld %ld\n", result.line_count, result.word_count);
        fclose(outfile);
    } else {
        printf("%ld %ld\n", result.line_count, result.word_count);
    }
}

void* process_chunk(void* args) {
    file_info_t* info = (file_info_t*)args;
    process_file(info->filename, info->fd);
    return NULL;
}

int main(int argc, char** argv) {
    // Parse command line arguments
    if (argc == 1) {
        print_usage(argv[0]);
        exit(1);
    }
    int opt;
    char* input = NULL;
    char* output = NULL;
    char* compression = DEFAULT_COMPRESSION_TYPE;
    int thread_count = DEFAULT_THREAD_COUNT;
    while ((opt = getopt(argc, argv, "hi:o:c:t:f:")) != -1) {
        switch (opt) {
            case 'h':
                print_usage(argv[0]);
                exit(0);
            case 'i':
                input = optarg;
                break;
            case 'o':
                output = optarg;
                break;
            case 'c':
                compression = optarg;
                break;
            case 't':
                thread_count = atoi(optarg);
                break;
            case 'f':
                if (strcmp(optarg, "wordcount") == 0) {
                    output_format = "wordcount";
                } else if (strcmp(optarg, "linecount") == 0) {
                    output_format = "linecount";
                } else {
                    printf("Invalid output format\n");
                    exit(1);
                }
                break;
            default:
                print_usage(argv[0]);
                exit(1);
        }
    }

    // Open input file or stdin
    int fd = 0;
    if (input != NULL) {
        fd = open(input, O_RDONLY);
        if (fd == -1) {
            perror("open");
            exit(1);
        }
    }

    // Open output file or stdout
    FILE* outfile = stdout;
    if (output != NULL) {
        outfile = fopen(output, "wb");
        if (outfile == NULL) {
            perror("fopen");
            exit(1);
        }
    }

    // Initialize processing result structure
    processing_result_t result = {0, 0};

    // Process input file in chunks using multiple threads
    pthread_t* threads = malloc(sizeof(pthread_t) * thread_count);
    if (threads == NULL) {
        perror("malloc");
        exit(1);
    }
    for (int i = 0; i < thread_count; i++) {
        file_info_t* info = malloc(sizeof(file_info_t));
        if (info == NULL) {
            perror("malloc");
            exit(1);
        }
        info->filename = input;
        info->fd = fd;
        pthread_create(&threads[i], NULL, process_chunk, (void*)info);
    }
    for (int i = 0; i < thread_count; i++) {
        pthread_join(threads[i], NULL);
    }

    // Combine intermediate results and write to output file
    if (input != NULL) {
        close(fd);
    }
    fprintf(outfile, "%ld %ld\n", result.line_count, result.word_count);
    fclose(outfile);

    // Clean up resources
    free(threads);
    return 0;
}
```']

