typedef struct {
    char client_identifier[256];
    char server_identifier[256];
    int sequence_number;
    unsigned short syn_flags;
} TCP_CONNECTION_REQUEST_PDU_T;

void generate_connection_requests(int num_connections, char* password) {
    // Initialize the encryption module with the given password
    EVP_CIPHER_CTX *ctx = NULL;
    if (!EVP_EncryptInit_ex(&ctx, EVP_aes_256_cbc(), NULL, password, NULL)) {
        printf("Error initializing AES-256-CBC cipher\n");
        return;
    }

    // Allocate memory for the connection requests array
    TCP_CONNECTION_REQUEST_PDU_T *requests = (TCP_CONNECTION_REQUEST_PDU_T*)malloc(num_connections * sizeof(TCP_CONNECTION_REQUEST_PDU_T));
    if (!requests) {
        printf("Error allocating memory for connection requests\n");
        return;
    }

    // Populate the connection requests array with valid data
    int i = 0;
    while (i < num_connections) {
        // Generate a random client and server identifier
        char client_identifier[256];
        char server_identifier[256];
        generate_random_string(client_identifier, 256);
        generate_random_string(server_identifier, 256);

        // Generate a random sequence number and SYN flags
        int sequence_number = rand() % 1000;
        unsigned short syn_flags = (rand() % 3) + 1;

        // Compute the SHA-256 hash of the IP address string
        char ip_address[256];
        generate_random_string(ip_address, 256);
        unsigned char sha256_hash[SHA256_DIGEST_LENGTH];
        SHA256_CTX ctx;
        SHA256_Init(&ctx);
        SHA256_Update(&ctx, ip_address, strlen(ip_address));
        SHA256_Final(sha256_hash, &ctx);

        // Encrypt the hash using AES-256-CBC
        unsigned char encrypted_hash[AES_BLOCK_SIZE];
        EVP_EncryptUpdate(&ctx, encrypted_hash, sizeof(encrypted_hash), sha256_hash, SHA256_DIGEST_LENGTH);

        // Store the connection request in the array
        requests[i].client_identifier = client_identifier;
        requests[i].server_identifier = server_identifier;
        requests[i].sequence_number = sequence_number;
        requests[i].syn_flags = syn_flags;
        i++;
    }

    // Free the encryption context
    EVP_CIPHER_CTX_free(ctx);

    // Return the connection requests array
    return requests;
}

void generate_random_string(char* buffer, int length) {
    for (int i = 0; i < length; i++) {
        buffer[i] = 'a' + rand() % 26;
    }
}
