        self.tag = tag
        self.rnti = rnti
        self.cqi = cqi
        self.rsrp = rsrp

# Define the list structure to hold the RX indication PDUs
class NFAPI_RX_INDICATION_LIST_T(object):
    def __init__(self, max_elements=1024):
        self.num_elements = 0
        self.max_elements = max_elements
        self.elements = []

# Define the function to create and populate a list of RX indication PDUs
