    if list.num_elements >= list.max_elements:
        logging.error("Error: Maximum number of elements reached")
        return -1

    pdu = NFAPI_RX_INDICATION_PDU_T(tag, rnti, cqi, rsrp)
    list.elements.append(pdu)
    list.num_elements += 1
    return 0

# Define the function to calculate the MD5 hash of a large file given its path
def md5sum(filepath):
    if not os.path.exists(filepath):
        logging.error("Error: File does not exist")
        return None

    with open(filepath, "rb") as f:
        hasher = hashlib.md5()
        while True:
            chunk = f.read(1024)
            if not chunk:
                break
            hasher.update(chunk)
        return hasher.hexdigest()

# Define the function to serialize the RX indication list to a binary format
def serialize_rx_indication_list(list, filename):
    with open(filename, "wb") as f:
        # Write the number of elements in the list to the file
        num_elements = struct.pack("Q", list.num_elements)
        f.write(num_elements)

        # Write each element in the list to the file
        for pdu in list.elements:
            data = struct.pack("BBHHH", pdu.tag, pdu.rnti, pdu.cqi, pdu.rsrp)
            f.write(data)

# Define the function to deserialize a binary RX indication list from a file
def deserialize_rx_indication_list(filename):
    with open(filename, "rb") as f:
        # Read the number of elements in the list from the file
        num_elements = struct.unpack("Q", f.read(8))[0]

        # Allocate memory for the list and its elements
        list = NFAPI_RX_INDICATION_LIST_T()
        list.num_elements = 0
        list.max_elements = num_elements
        list.elements = []

