# Define the function to calculate the MD5 hash of a large file
def md5_hash(file_path, chunk_size=1024):
    # Open the file and create an instance of the hash object
    with open(file_path, 'rb') as f:
        h = hashlib.md5()

        # Read the file in chunks and update the hash object for each chunk
        while True:
            data = f.read(chunk_size)
            if not data:
                break
            h.update(data)

    # Return the hexdigest of the hash object
    return h.hexdigest()
