    list->num_elements = 0;
    list->pdu_list = NULL;

    // Allocate memory for the array of RX indication PDUs
    list->pdu_list = malloc(max_num_elements * sizeof(NFAPI_RX_INDICATION_PDU_T));
    if (!list->pdu_list) {
