    if (!list || !num_elements) {
        return 0;
    }

    // Ensure that the number of elements in the list does not exceed the maximum capacity
    size_t num_available_elements = max_num_elements - list->num_elements;
    if (num_elements > num_available_elements) {
        fprintf(stderr, "Error: Attempted to populate more elements than the maximum capacity of the list\n");
        return -1;
    }

    // Copy the new data into the list
    for (size_t i = 0; i < num_elements; i++) {
        memcpy(&list->pdu_list[list->num_elements + i], &pdu_list[i], sizeof(NFAPI_RX_INDICATION_PDU_T));
