    // Serialize the list of RX indication PDUs to the buffer
    for (size_t i = 0; i < list->num_elements; i++) {
        memcpy(&buffer[i * sizeof(NFAPI_RX_INDICATION_PDU_T)], &list->pdu_list[i], sizeof(NFAPI_RX_INDICATION_PDU_T));
    }

