```python
import os
import struct
import logging

# Define a function to calculate the checksum of a binary file using the Adler-32 algorithm
def adler_checksum(filepath):
    # Open the file for reading in binary mode
    with open(filepath, "rb") as f:
        # Initialize the checksum variables
        a = 1
        b = 0

        # Iterate over the file contents and update the checksum
        while True:
            data = f.read(4)
            if not data:
                break
            for i in range(len(data)):
                a += ord(data[i])
                b += a

        # Return the final checksum value
        return (a, b)
