// Define the function to manage the dynamic list of TCP connection information
void manage_tcp_connection_list(TCP_CONNECTION_LIST *list) {
    // Check if the list is full and needs to be resized
    if (list->num_elements == list->max_elements) {
        // Resize the list by doubling its size
        list->max_elements *= 2;
        list->elements = realloc(list->elements, list->max_elements * sizeof(TCP_CONNECTION_INFO));
    }

