    memset(new_entry, 0, sizeof(NFAPI_CRC_INDICATION_PDU_T));
}

// Define the function to handle expired entries based on last access timestamps
void handle_expired_entries(TCP_CONNECTION_LIST *list) {
    // Get the current timestamp
    time_t now = time(NULL);

    // Iterate over the list of TCP connections and check for expired entries
    for (size_t i = 0; i < list->num_elements; ++i) {
        // Check if the entry has expired based on its last access timestamp
        if (now - list->elements[i].last_access > EXPIRATION_TIME) {
            // Remove the expired entry from the list
            memmove(&list->elements[i], &list->elements[i + 1], sizeof(TCP_CONNECTION_INFO));
            --list->num_elements;
        }
    }
}

// Define the function to handle duplicate RNTIs in the NFAPI CRC indication PDUs
void handle_duplicate_rntis(NFAPI_CRC_INDICATION_PDU_ARRAY *array) {
    // Create a hash table to store the RNTIs
    RNTI_HASH_TABLE rnti_table;
    rnti_table.num_elements = 0;
    rnti_table.max_elements = 16;
    rnti_table.elements = malloc(rnti_table.max_elements * sizeof(uint16_t));

    // Iterate over the array of NFAPI CRC indication PDUs and check for duplicate RNTIs
    for (size_t i = 0; i < array->num_entries; ++i) {
        // Check if the RNTI is already in the hash table
        uint16_t *rnti = &array->entries[i].rnti;
        if (find_in_hash_table(&rnti_table, rnti)) {
            // Remove the duplicate entry from the array
            memmove(&array->entries[i], &array->entries[i + 1], sizeof(NFAPI_CRC_INDICATION_PDU_T));
            --array->num_entries;
        } else {
            // Add the RNTI to the hash table
            add_to_hash_table(&rnti_table, rnti);
        }
    }
}

// Define the function to calculate the checksum of a binary file using the Adler-32 algorithm
void calculate_checksum(FILE *file) {
    // Initialize the Adler-32 checksum with a seed value
    uint32_t adler = 1;

    // Read the file in chunks and update the checksum for each chunk
    size_t chunk_size = 4096;
    char *chunk = malloc(chunk_size);
    while (fread(chunk, 1, chunk_size, file) == chunk_size) {
        // Update the Adler-32 checksum for each byte in the chunk
        for (size_t i = 0; i < chunk_size; ++i) {
            adler += chunk[i];
        }
    }

    // Free the memory allocated for the chunk
    free(chunk);
}
