  public void addSession(String userId, String deviceType) {
    // Generate a unique session ID for the user and device type
    String sessionId = generateUniqueSessionId(userId, deviceType);

    // Create a new session object and store it in the sessions map
    Session session = new Session(sessionId);
    sessions.put(sessionId, session);

    // Update the last processed RNTI for the device type
    lastProcessedRntiByDeviceType.put(deviceType, "");
  }

  public void updateSession(String userId, String deviceType) {
    // Get the current time in milliseconds
    long currentTime = System.currentTimeMillis();

    // Update the last activity timestamp for the session
    Session session = sessions.get(userId + "-" + deviceType);
    if (session != null) {
      session.setLastActivityTimestamp(currentTime);
    }
  }

  public void removeSession(String userId, String deviceType) {
    // Remove the session from the sessions map
    Session session = sessions.remove(userId + "-" + deviceType);

    // Update the last processed RNTI for the device type
    if (session != null) {
      lastProcessedRntiByDeviceType.put(deviceType, "");
    }
  }

