    long currentTime = System.currentTimeMillis();

    // Update the last activity timestamp for the session
    Session session = sessions.get(userId + "-" + deviceType);
    if (session != null) {
      session.setLastActivityTimestamp(currentTime);
    }

    // Add the CRC indication PDU to the list of PDUS for the user ID and device type
    List<NFAPI_CRC_INDICATION_PDU_T> pdus = crcIndicationPdusByUserId.get(userId + "-" + deviceType);
    if (pdus == null) {
      pdus = new ArrayList<>();
      crcIndicationPdusByUserId.put(userId + "-" + deviceType, pdus);
    }
    pdus.add(pdu);
  }

  public void removeCrcIndicationPdu(String userId, String deviceType, NFAPI_CRC_INDICATION_PDU_T pdu) {
    // Remove the CRC indication PDU from the list of PDUS for the user ID and device type
    List<NFAPI_CRC_INDICATION_PDU_T> pdus = crcIndicationPdusByUserId.get(userId + "-" + deviceType);
    if (pdus != null) {
      pdus.remove(pdu);
    }
  }

  public void sendUserAlerts(String userId, String deviceType) {
    // Get the current time in milliseconds
    long currentTime = System.currentTimeMillis();

    // Check if the user ID has been processed recently
    if (recentUserIds.contains(userId)) {
      return;
    }

    // Update the last processed RNTI for the device type
    String lastProcessedRnti = lastProcessedRntiByDeviceType.get(deviceType);
    if (lastProcessedRnti != null) {
      lastProcessedRntiByDeviceType.put(deviceType, "");
    }

    // Get the list of CRC indication PDUS for the user ID and device type
    List<NFAPI_CRC_INDICATION_PDU_T> pdus = crcIndicationPdusByUserId.get(userId + "-" + deviceType);
    if (pdus == null) {
      return;
    }

    // Iterate over the CRC indication PDUS and send alerts for each one
    for (NFAPI_CRC_INDICATION_PDU_T pdu : pdus) {
      // Check if the RNTI has been processed recently
      String rnti = pdu.getRNTI();
      if (recentUserIds.contains(rnti)) {
        continue;
      }

      // Update the last processed RNTI for the device type
      lastProcessedRntiByDeviceType.put(deviceType, rnti);

      // Send an alert for the CRC indication PDU
      sendAlert(userId, deviceType, pdu);
    }
  }

  private void sendAlert(String userId, String deviceType, NFAPI_CRC_INDICATION_PDU_T pdu) {
    // Generate an alert message for the CRC indication PDU
    String alertMessage = generateAlertMessage(pdu);

    // Send the alert message to the notification service API
    sendNotification(userId, deviceType, alertMessage);
  }

  private void sendNotification(String userId, String deviceType, String alertMessage) {
    // Get the notification channel for the user ID and device type
    String notificationChannel = getNotificationChannel(userId, deviceType);

    // Send the alert message to the notification service API using the specified channel
    NotificationServiceAPI.sendAlert(notificationChannel, alertMessage);
  }

  private String generateUniqueSessionId(String userId, String deviceType) {
    // Generate a unique session ID for the user and device type
    return SESSION_PREFIX + userId + "-" + deviceType;
  }

  private String getNotificationChannel(String userId, String deviceType) {
    // Get the notification channel for the user ID and device type
    return NOTIFICATION_CHANNELS[new Random().nextInt(NOTIFICATION_CHANNELS.length)];
  }

  private String generateAlertMessage(NFAPI_CRC_INDICATION_PDU_T pdu) {
    // Generate an alert message for the CRC indication PDU
    return "CRC indication received from UE with RNTI " + pdu.getRNTI() + " and CRCFlag " + pdu.getCRCFlag();
  }
}
