// Define the function to detect and handle packet loss during data transmission
void handle_packet_loss(int* num_retries, int max_retries) {
    // Check if any packets have been lost during data transmission
    if (*num_retries >= max_retries) {
        // If so, retry the transmission up to the maximum number of retries
        *num_retries = 0;
    } else {
        // Otherwise, increment the number of retries and wait for a random amount of time before retrying
        (*num_retries)++;
        int delay = rand() % 1000 + 500; // Generate a random value between 500 and 1500 milliseconds
        sleep(delay / 1000); // Sleep for the specified amount of time
    }
}
