// Function to compute the SHA-256 hash of a composite key derived from the UE ID, CELL ID, and current timestamp
uint8_t* compute_sha256_hash(uint32_t RX_UE_INFORMATION_TAG, uint16_t RNTI, time_t timestamp) {
    // Initialize the SHA-256 hash context
    SHA256_CTX ctx;
    SHA256_Init(&ctx);

    // Compute the composite key derived from the UE ID, CELL ID, and current timestamp
    uint8_t* composite_key = (uint8_t*)malloc(sizeof(uint32_t) + sizeof(uint16_t) + sizeof(time_t));
    memcpy(composite_key, &RX_UE_INFORMATION_TAG, sizeof(uint32_t));
    memcpy(composite_key + sizeof(uint32_t), &RNTI, sizeof(uint16_t));
    memcpy(composite_key + sizeof(uint32_t) + sizeof(uint16_t), &timestamp, sizeof(time_t));

    // Compute the SHA-256 hash of the composite key
    uint8_t* hash = (uint8_t*)malloc(sizeof(uint8_t) * HASH_LENGTH);
    SHA256_Update(&ctx, composite_key, sizeof(uint32_t) + sizeof(uint16_t) + sizeof(time_t));
    SHA256_Final(hash, &ctx);

    // Free the memory allocated for the composite key and hash context
    free(composite_key);
    SHA256_CTX_cleanup(&ctx);

    // Return the computed hash
    return hash;
}

