    }

    // Store the parsed fields in the output structure
    oauth2_response->access_token = json_string_value(access_token);
    oauth2_response->expires_in = expires_in_int;
    oauth2_response->token_type = token_type_str;
    if (refresh_token) {
        oauth2_response->refresh_token = json_string_value(refresh_token);
    } else {
        oauth2_response->refresh_token = NULL;
