    // Free the memory allocated for the JSON object
    json_decref(root);

    return true;
}

// Define the function to generate a composite key derived from the UE ID, CELL ID, and current timestamp
char *generate_composite_key(uint32_t ue_id, uint8_t crcflag) {
    // Initialize variables for generating the composite key
    char *composite_key = NULL;
    int len = 0;

    // Generate a string representation of the UE ID and CRC flag
    char *ue_id_str = malloc(sizeof(char) * 16);
    sprintf(ue_id_str, "%u", ue_id);
    int crcflag_len = strlen(crcflag);

    // Calculate the length of the composite key
    len += strlen(ue_id_str) + 1;
    len += crcflag_len + 1;

    // Allocate memory for the composite key
    composite_key = malloc(sizeof(char) * len);
    if (!composite_key) {
        return NULL;
    }

    // Generate the composite key
    strcpy(composite_key, ue_id_str);
    strcat(composite_key, ",");
    strncat(composite_key, crcflag, crcflag_len);

    // Free the memory allocated for the UE ID string
    free(ue_id_str);

    return composite_key;
}

