    // Initialize variables for calculating the SHA-256 hash
    unsigned char sha256_hash[SHA256_DIGEST_LENGTH];
    SHA256_CTX ctx;

    // Calculate the SHA-256 hash of the composite key
    SHA256_Init(&ctx);
    SHA256_Update(&ctx, composite_key, strlen(composite_key));
    SHA256_Final(sha256_hash, &ctx);

    return sha256_hash;
}

