        return -1;
    }

    // Set the padding mode for the AES cipher
    if (!EVP_CIPHER_CTX_set_padding(ctx, 0)) {
        log("Failed to set padding mode", LOG_LEVEL_ERROR);
        return -1;
    }

    // Decrypt the encrypted data using AES-CBC and HMAC-SHA256
    int decrypted_data_size = 0;
    unsigned char* decrypted_data = NULL;
    for (int i = 0; i < 3; i++) {
        // Decrypt the current part of the message
        if (!EVP_DecryptUpdate(ctx, decrypted_data, &decrypted_data_size, encrypted_data + i * AES_BLOCK_SIZE, data_size - i * AES_BLOCK_SIZE)) {
            log("Failed to decrypt current part of the message", LOG_LEVEL_ERROR);
            continue;
        }

        // Verify the HMAC-SHA256 digest for the current part of the message
        unsigned char* hmac = NULL;
        if (!HMAC(EVP_sha256(), key, key_size, encrypted_data + i * AES_BLOCK_SIZE, data_size - i * AES_BLOCK_SIZE, &hmac, NULL)) {
            log("Failed to generate HMAC-SHA256 digest", LOG_LEVEL_ERROR);
            continue;
        }

        // Compare the generated HMAC with the expected HMAC
        if (memcmp(hmac, encrypted_data + data_size - AES_BLOCK_SIZE, AES_BLOCK_SIZE) != 0) {
            log("HMAC-SHA256 digest does not match", LOG_LEVEL_WARNING);
            continue;
        }

        // If the HMAC verification is successful, break out of the loop
        break;
    }

    // Clean up the AES cipher context and return the decrypted data
    EVP_CIPHER_CTX_free(ctx);
    return decrypted_data_size;
}
