    // Allocate memory for the array of TCP connection statistics structures
    TCP_CONNECTION_STATS_T *stats = (TCP_CONNECTION_STATS_T *)malloc(num_connections * sizeof(TCP_CONNECTION_STATS_T));
    if (!stats) {
        // Log the error message and return NULL
        printf("Error: Failed to allocate memory for TCP connection statistics\n");
        return NULL;
    }

    // Initialize the connection statistics with zero bytes transmitted and received
    for (int i = 0; i < num_connections; i++) {
        stats[i].bytes_tx = 0;
        stats[i].bytes_rx = 0;
    }

    return stats;
}

