int validate_ip_port(char *ip, int port) {
    // Validate the IP address
    if (!inet_pton(AF_INET, ip, NULL)) {
        printf("Error: Invalid IP address\n");
        return 0;
    }

    // Validate the port number
    if (port < 1 || port > 65535) {
        printf("Error: Invalid port number\n");
        return 0;
    }

    return 1;
}

