    sprintf(composite_key, "%s:%d-%s:%d", src_ip, src_port, dest_ip, dest_port);

    // Calculate the MD5 hash of the composite key
    unsigned char md5_hash[MD5_DIGEST_LENGTH];
    MD5((unsigned char *)composite_key, strlen(composite_key), md5_hash);

    // Free the memory allocated for the composite key
    free(composite_key);

    return md5_hash;
}

// Define the function to update the TCP connection statistics
int update_tcp_connection_stats(TCP_CONNECTION_STATS_T *stats, char *src_ip, char *dest_ip, int src_port, int dest_port) {
    // Validate the IP addresses and ports
    if (!validate_ip_port(src_ip, src_port) || !validate_ip_port(dest_ip, dest_port)) {
