    new_stats->src_ip = src_ip;
    new_stats->dest_ip = dest_ip;
    new_stats->src_port = src_port;
    new_stats->dest_port = dest_port;
    new_stats->bytes_tx = 0;
    new_stats->bytes_rx = 0;

    // Add the new connection statistics to the array of TCP connection statistics structures
    stats[num_connections++] = *new_stats;

