    sprintf(filename, "connection_stats.log.%d-%02d-%02d", timeinfo->tm_year + 1900, timeinfo->tm_mon + 1, timeinfo->tm_mday);
    rename("connection_stats.log", filename);

    // Close the rotate file
    fclose(rotate_file);

    return 1;
}
