// Decryption function
char* decrypt_message(unsigned char* key, unsigned char* iv, unsigned char* ciphertext, int length) {
    AES_KEY aes_key;
    EVP_CIPHER_CTX *ctx;
    int outlen;
    unsigned char* plaintext = NULL;
    int retries = 0;

    // Initialize AES key and IV
    AES_set_decrypt_key(key, 128, &aes_key);
    AES_cbc_encrypt(iv, iv, length, &aes_key, NULL, NULL, 0);

    // Allocate memory for plaintext
    plaintext = (unsigned char*)malloc(length * sizeof(char));

    // Initialize EVP context
    ctx = EVP_CIPHER_CTX_new();

    // Set cipher and key
    EVP_EncryptInit_ex(ctx, EVP_aes_128_cbc(), NULL, key, iv, 0);

    // Decrypt message
    while (retries < 5) {
        if (EVP_DecryptUpdate(ctx, plaintext, &outlen, ciphertext, length)) {
            break;
        } else {
            retries++;
            log(LOG_WARNING, "Retrying decryption attempt %d", retries);
            // Reinitialize AES key and IV with new IV for each part of the message
            AES_set_decrypt_key(key, 128, &aes_key);
            AES_cbc_encrypt(iv, iv, length, &aes_key, NULL, NULL, 0);
        }
    }

    // Check HMAC integrity
    if (HMAC_verify(EVP_sha256(), plaintext, outlen, ciphertext + length, 32)) {
        log(LOG_INFO, "Decryption successful");
    } else {
        log(LOG_ERROR, "Decryption failed");
        return NULL;
    }

    // Free EVP context and plaintext buffer
    EVP_CIPHER_CTX_free(ctx);
    free(plaintext);

    return (char*)ciphertext;
}
