#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <semaphore.h>
#include <errno.h>

#define MAX_NFAPI_CRC_INDICATION_PDU 10000
#define MAX_RX_UE_INFORMATION_TAG 256
#define MAX_RNTI 65536
#define MAX_CRC_INDICATION_REL8_TAG 256

typedef struct {
    uint16_t rx_ue_information_tag;
    uint16_t rnti;
    uint16_t crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

void initialize_array(NFAPI_CRC_INDICATION_PDU_T *array, size_t size) {
    for (size_t i = 0; i < size; i++) {
        array[i].rx_ue_information_tag = rand() % MAX_RX_UE_INFORMATION_TAG;
        array[i].rnti = rand() % MAX_RNTI;
        array[i].crc_indication_rel8_tag = rand() % MAX_CRC_INDICATION_REL8_TAG;
    }
}

void populate_array(NFAPI_CRC_INDICATION_PDU_T *array, size_t size) {
    for (size_t i = 0; i < size; i++) {
        array[i].rx_ue_information_tag = rand() % MAX_RX_UE_INFORMATION_TAG;
        array[i].rnti = rand() % MAX_RNTI;
        array[i].crc_indication_rel8_tag = rand() % MAX_CRC_INDICATION_REL8_TAG;
    }
}

