#define LOG_FILE_PATH "/var/log/myapp.log"
#define LOG_FILE_MAX_SIZE 1024 * 1024 // 1 MB
#define LOG_FILE_ROTATE_INTERVAL 7 // days
#define LOG_SEVERITY_INFO 0
#define LOG_SEVERITY_WARNING 1
#define LOG_SEVERITY_ERROR 2
#define LOG_MODULE_MAX_LENGTH 32

typedef struct {
    char module[LOG_MODULE_MAX_LENGTH];
    int severity;
} LogMessage;

void log_message(const char *format, ...) {
    va_list args;
    va_start(args, format);

    // Allocate memory for the message
    size_t message_size = vsnprintf(NULL, 0, format, args) + 1;
    char *message = malloc(message_size);
    if (!message) {
        fprintf(stderr, "Failed to allocate memory for log message: %s\n", strerror(errno));
        return;
    }
    vsnprintf(message, message_size, format, args);

    // Write the message to the log file
    pthread_mutex_lock(&log_file_mutex);
    int fd = open(LOG_FILE_PATH, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (fd == -1) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        free(message);
        pthread_mutex_unlock(&log_file_mutex);
        return;
    }
    write(fd, message, message_size - 1); // -1 to exclude the null terminator
    close(fd);
    pthread_mutex_unlock(&log_file_mutex);

    free(message);
}

void log_rotate() {
    struct stat st;
    if (stat(LOG_FILE_PATH, &st) == -1) {
        fprintf(stderr, "Failed to get file size: %s\n", strerror(errno));
        return;
    }
    if (st.st_size > LOG_FILE_MAX_SIZE) {
        char new_file_path[256];
        snprintf(new_file_path, sizeof(new_file_path), "%s.%d", LOG_FILE_PATH, time(NULL));
        if (rename(LOG_FILE_PATH, new_file_path) == -1) {
            fprintf(stderr, "Failed to rotate log file: %s\n", strerror(errno));
            return;
        }
    }
}

void log_delete() {
    struct stat st;
    if (stat(LOG_FILE_PATH, &st) == -1) {
        fprintf(stderr, "Failed to get file size: %s\n", strerror(errno));
        return;
    }
    time_t now = time(NULL);
    if (now - st.st_mtime > LOG_FILE_ROTATE_INTERVAL * 24 * 60 * 60) {
        unlink(LOG_FILE_PATH);
    }
}

void log_message_async(const char *format, ...) {
    va_list args;
    va_start(args, format);

    // Allocate memory for the message
    size_t message_size = vsnprintf(NULL, 0, format, args) + 1;
    char *message = malloc(message_size);
    if (!message) {
        fprintf(stderr, "Failed to allocate memory for log message: %s\n", strerror(errno));
        return;
    }
    vsnprintf(message, message_size, format, args);

    // Write the message to a buffer
    pthread_mutex_lock(&log_buffer_mutex);
    if (log_buffer_size + message_size > LOG_BUFFER_MAX_SIZE) {
        log_flush();
    }
    memcpy(log_buffer + log_buffer_size, message, message_size - 1); // -1 to exclude the null terminator
    log_buffer_size += message_size;
    pthread_mutex_unlock(&log_buffer_mutex);

    free(message);
}

void log_flush() {
    if (log_buffer_size == 0) {
        return;
    }

    // Write the buffer to the log file
    pthread_mutex_lock(&log_file_mutex);
    int fd = open(LOG_FILE_PATH, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (fd == -1) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        pthread_mutex_unlock(&log_file_mutex);
        return;
    }
    write(fd, log_buffer, log_buffer_size);
    close(fd);
    pthread_mutex_unlock(&log_file_mutex);

    // Reset the buffer size
    log_buffer_size = 0;
}

void log_backpressure() {
    if (log_buffer_size > LOG_BUFFER_MAX_SIZE) {
        log_flush();
    }
}
