void log(int level, const char *format, ...) {
    // Check if the logging level is high enough to log this message
    if (level < log_level) return;

    // Get the current time
    time_t now = time(NULL);

    // Check if we need to rate limit the logs
    if (now - log_last_logged < 1) {
        return;
    }

    // Increment the number of logged messages
    log_last_logged++;

    // Format the message using va_start/va_end
    char buffer[4096];
    va_list args;
    va_start(args, format);
    vsnprintf(buffer, sizeof(buffer), format, args);
    va_end(args);

    // Log the message to the appropriate destination
#ifdef USE_SYSLOG
    syslog(level, "%s", buffer);
#else
    fprintf(log_file, "%s\n", buffer);
#endif
}

// Set the logging level (0-3)
void set_log_level(int level) {
    log_level = level;
}

// Set the rate limiting parameters
void set_log_rate_limit(int limit) {
    log_rate_limit = limit;
}
