    // Check if the input array is empty
    if (num_events == 0) {
        return NULL;
    }

    // Create an array to store the traffic events
    TrafficEvent* traffic_events = malloc(sizeof(TrafficEvent) * num_events);
    if (!traffic_events) {
        return NULL;
    }

    // Initialize the first event
    strcpy(traffic_events[0].event_type, events[0]);
    traffic_events[0].timestamp = atol(events[1]);
    traffic_events[0].vehicle_id = atoi(events[2]);

    // Calculate the duration between consecutive events
    for (size_t i = 1; i < num_events; ++i) {
        long current_timestamp = atol(events[i * 3 + 1]);
        long previous_timestamp = traffic_events[i - 1].timestamp;
        int duration = current_timestamp - previous_timestamp;
        traffic_events[i].duration = duration;
    }

    // Validate the event types against a predefined set of allowed types
    for (size_t i = 0; i < num_events; ++i) {
        const char* event_type = traffic_events[i].event_type;
        if (!strcmp(event_type, "entry") || !strcmp(event_type, "exit")) {
            continue;
        } else {
            free(traffic_events);
            return NULL;
        }
    }

    // Return the initialized traffic events array
    return traffic_events;
}
