// Define the NFAPI_CRC_INDICATION_PDU_T structure
typedef struct {
    uint16_t rx_ue_information_tag;
    uint32_t rnti;
    uint8_t crc_indication_rel8_tag;
    bool crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the custom hash table for RNTI validation and management
typedef struct {
    uint32_t *rnti_list;
    size_t rnti_count;
    pthread_mutex_t mutex;
} RNTI_HASH_TABLE_T;

// Function to create and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T *create_crc_indication_pdu_list(size_t n) {
    // Allocate memory for the list of PDUs
    NFAPI_CRC_INDICATION_PDU_T *pdu_list = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_list) {
        return NULL;
    }

    // Initialize the RNTI hash table
    RNTI_HASH_TABLE_T rnti_table = {NULL, 0};
    pthread_mutex_init(&rnti_table.mutex, NULL);

    // Populate the list of PDUs with random data
    for (size_t i = 0; i < n; i++) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = &pdu_list[i];

        // Generate a random RX_UE_INFORMATION_TAG and RNTI
        pdu->rx_ue_information_tag = rand() % 1000;
        pdu->rnti = rand() % 1000000;

        // Generate a random CRCFLAG for the CRC_INDICATION_REL8_TAG
        pdu->crc_indication_rel8_tag = rand() % 2;

        // Add the RNTI to the hash table if it is unique
        bool rnti_added = false;
        pthread_mutex_lock(&rnti_table.mutex);
        for (size_t j = 0; j < rnti_table.rnti_count; j++) {
            if (pdu->rnti == rnti_table.rnti_list[j]) {
                rnti_added = true;
                break;
            }
        }
        if (!rnti_added) {
            rnti_table.rnti_count++;
            rnti_table.rnti_list = realloc(rnti_table.rnti_list, rnti_table.rnti_count * sizeof(uint32_t));
            if (!rnti_table.rnti_list) {
                pthread_mutex_unlock(&rnti_table.mutex);
