// Define the function for initializing an AES-256-CBC cipher using a given password
void init_aes_cbc(const char* password, size_t password_len) {
    // Check if the cryptographic framework is available at runtime
    if (!EVP_get_cipherbyname("AES-256-CBC")) {
        printf("Error: Cryptographic framework not available. Please install OpenSSL.\n");
        exit(1);
    }

    // Generate a random initialization vector (IV) for the cipher
    unsigned char iv[16];
    RAND_bytes(iv, 16);

    // Derive an encryption key from the password using PBKDF2 and SHA-256
    EVP_PKEY_CTX* ctx = EVP_PKEY_CTX_new_id(EVP_PKEY_HMAC, NULL);
    EVP_PKEY_keygen(ctx, "SHA256", 8, password, password_len, NULL, NULL);
    unsigned char key[32];
    int key_len = 32;
    EVP_PKEY_derive(ctx, key, &key_len);
    EVP_PKEY_CTX_free(ctx);

    // Initialize the AES-256-CBC cipher using the derived key and IV
    AES_KEY aes_key;
    AES_set_encrypt_key(key, 256, &aes_key);
    AES_cbc_encrypt(iv, iv, 16, &aes_key, NULL, NULL);
}

