#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

// Environment variables for logging configuration
const char* LOG_DESTINATION = "LOG_DESTINATION";
const char* LOG_VERBOSITY = "LOG_VERBOSITY";
const char* LOG_RATE_LIMIT = "LOG_RATE_LIMIT";
const char* LOG_SUPPRESSION = "LOG_SUPPRESSION";

// Log levels
#define DEBUG 0
#define INFO 1
#define WARNING 2
#define ERROR 3

// Rate limiting constants
#define MAX_MESSAGES_PER_SECOND 50
#define MIN_LOGGING_INTERVAL 1000 // 1 second

// Thread-safe logging mutex
pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;

void log(int level, const char* message) {
    // Check if rate limiting is enabled
    if (getenv(LOG_RATE_LIMIT)) {
        // Acquire mutex to prevent data corruption
        pthread_mutex_lock(&log_mutex);

        // Get current time in milliseconds
        struct timespec ts;
        clock_gettime(CLOCK_MONOTONIC, &ts);
        long current_time = (long)ts.tv_sec * 1000 + (long)ts.tv_nsec / 1000000;

        // Check if logging interval has elapsed
        static long last_logged_at = 0;
        if (current_time - last_logged_at < MIN_LOGGING_INTERVAL) {
            pthread_mutex_unlock(&log_mutex);
            return;
        }

        // Update last logged time
        last_logged_at = current_time;

        // Release mutex
        pthread_mutex_unlock(&log_mutex);
    }

    // Check if logging is suppressed for this message
    if (getenv(LOG_SUPPRESSION)) {
        const char* suppression = getenv(LOG_SUPPRESSION);
        if (strstr(message, suppression) != NULL) {
            return;
        }
    }

    // Get logging destination and verbosity level from environment variables
    const char* log_destination = getenv(LOG_DESTINATION);
    int log_verbosity = atoi(getenv(LOG_VERBOSITY));

    // Log message based on verbosity level
    if (level <= log_verbosity) {
        switch (level) {
            case DEBUG:
                printf("[DEBUG] %s\n", message);
                break;
            case INFO:
                printf("[INFO] %s\n", message);
                break;
            case WARNING:
                printf("[WARNING] %s\n", message);
                break;
            case ERROR:
                printf("[ERROR] %s\n", message);
                break;
        }
    }
}
```
