    int index = -1;
    for (int i = 0; i < cache->num_crc_indications; i++) {
        if (cache->crc_indications[i].rnti == crc_indication->rnti) {
            index = i;
            break;
        }
    }

    // Update the CRC indication in the cache
    if (index != -1) {
        cache->crc_indications[index] = *crc_indication;
    } else {
        add_crc_indication(cache, crc_indication);
    }
}

// Function to retrieve a CRC indication from the cache
NFAPI_CRC_INDICATION_PDU_T *get_crc_indication(CACHE_STRUCT_T *cache, uint32_t rnti) {
    // Find the index of the CRC indication in the cache
