// Define the function for updating a cache store with a new entry, key-value pairs, and an expiration time for a given cache ID
void update_cache(CACHE_STRUCTURE* cache, size_t cache_id, NFAPI_CRC_INDICATION_PDU_T* element, uint32_t expiration_time) {
    // Check if the cache is full or if the cache ID is invalid
    if (cache->size == cache->capacity || cache_id >= cache->capacity) {
        return;
    }

    // Update the element in the cache with the new value and expiration time
    cache->elements[cache_id] = *element;
    cache->elements[cache_id].expiration_time = expiration_time;

    // Increment the size of the cache
    cache->size++;
}

// Define the function for managing the caching mechanism, including eviction and expiration
void manage_caching(CACHE_STRUCTURE* cache) {
    // Check if the cache is empty or if it has reached its maximum size
    if (cache->size == 0 || cache->size >= cache->capacity) {
        return;
    }

    // Evict elements from the cache based on the eviction policy and expiration time
    for (size_t i = 0; i < cache->size; i++) {
        if (cache->elements[i].expiration_time <= time(NULL)) {
            // Remove the element from the cache
            cache->elements[i] = cache->elements[cache->size - 1];
            cache->size--;
        }
